# ── Console HTTP enxuto ───────────────────────────────────
# /status e outras rotas de polling são consultadas constantemente pelo UI.
# Suprimir respostas HTTP 2xx/3xx evita peso e ruído no terminal sem esconder
# falhas úteis: requisições 4xx/5xx continuam aparecendo. Os logs funcionais
# do bot (scanner, Lumi, ordens, preflight e erros) não são afetados.
# Para depuração HTTP completa: SHOW_HTTP_ACCESS_LOGS=1 antes de iniciar.
class _ImportantHTTPLogFilter(logging.Filter):
    def filter(self, record: logging.LogRecord) -> bool:
        message = record.getMessage()
        match = re.search(r'"\s+(\d{3})\s', message)
        if match:
            try:
                return int(match.group(1)) >= 400
            except Exception:
                return True
        low = message.lower()
        if "development server" in low or "running on http" in low or "press ctrl+c" in low:
            return False
        return record.levelno >= logging.WARNING


def configure_http_console_logging() -> None:
    enabled = str(os.getenv("SHOW_HTTP_ACCESS_LOGS", "0") or "0").strip().lower() in {"1", "true", "yes", "on"}
    if enabled:
        return
    logger = logging.getLogger("werkzeug")
    if not any(isinstance(item, _ImportantHTTPLogFilter) for item in logger.filters):
        logger.addFilter(_ImportantHTTPLogFilter())
    logger.setLevel(logging.INFO)


configure_http_console_logging()


# ── Correção de encerramento ──────────────────────────────
# Algumas versões da iqoptionapi registram um logout automático no atexit.
# Quando o usuário encerra com CTRL+C, esse logout pode imprimir traceback
# "Exception ignored in atexit callback" mesmo sem quebrar o bot. Aqui
# tornamos o callback silencioso e seguro.
def patch_iqoption_logout_atexit() -> None:
    try:
        from iqoptionapi.http.logout import Logout  # type: ignore

        if getattr(Logout, "_nexcode_safe_patch", False):
            return

        def safe_logout_call(self):  # type: ignore
            try:
                return self._post()
            except BaseException:
                # Evita traceback no encerramento por CTRL+C, rede offline ou sessão já fechada.
                return None

        Logout.__call__ = safe_logout_call  # type: ignore
        Logout._nexcode_safe_patch = True  # type: ignore
    except Exception:
        pass


patch_iqoption_logout_atexit()


# Evita imprimir várias vezes quando o navegador continua consultando /status
# ou quando o terminal dispara SIGINT/SIGTERM mais de uma vez.
_shutdown_started = threading.Event()


def graceful_shutdown(*_args) -> None:
    """Para o loop do robô e encerra o servidor local uma única vez."""
    if _shutdown_started.is_set():
        return

    _shutdown_started.set()
    try:
        stop_event.set()
        with state_lock:
            state["running"] = False
            state["status_message"] = "Servidor local encerrando com segurança."
        try:
            _persist_payout_last_good_now()
        except Exception:
            pass
        print("\n[INFO] Encerrando servidor local com segurança...", flush=True)
    except Exception:
        pass

    # Como registramos nosso próprio handler, precisamos encerrar explicitamente;
    # se apenas retornarmos, o Flask continua ativo e o painel segue chamando /status.
    raise SystemExit(0)


try:
    signal.signal(signal.SIGINT, graceful_shutdown)
    signal.signal(signal.SIGTERM, graceful_shutdown)
except Exception:
    pass

