def _technical_score_levels(strategy: Optional[str] = None) -> List[int]:
    """Níveis realmente alcançáveis pelo score técnico da estratégia.

    ALL_STRATEGIES usa soma ponderada inteira / 33. O score exibido é truncado para
    inteiro; por isso cortes como 64% já significavam, na prática, 66%. Expor e
    ajustar o threshold na mesma grade elimina essa zona morta sem afrouxar risco.
    Para outras estratégias mantemos a escala inteira por compatibilidade.
    """
    st = str(strategy or (cfg_get("strategy", "combined") if "cfg_get" in globals() else "combined") or "combined").lower()
    if st == "all_strategies":
        # V108.8.0: o consenso continua sendo soma ponderada / 33, mas a confiança
        # exibida/avaliada passa a usar arredondamento percentual granular. Isso remove
        # zonas mortas artificiais (ex.: 60 -> 63) sem alterar os votos ou pesos.
        granular = True
        try:
            granular = bool(cfg_get("technical_granular_confidence_enabled", True)) if "cfg_get" in globals() else True
        except Exception:
            granular = True
        if granular:
            return list(range(0, 101))
        total = 33
        return sorted({int(i / total * 100) for i in range(total + 1)})
    return list(range(0, 101))


def technical_threshold_grid(value: Any, strategy: Optional[str] = None, mode: str = "ceil") -> int:
    """Alinha um corte à grade real do Technical Engine.

    `ceil` é usado em REAL/adaptive: nunca reduz a proteção efetiva. `floor` é útil
    apenas para descobrir o degrau imediatamente anterior para a faixa borderline.
    """
    try:
        target = max(0, min(100, int(round(float(value)))))
    except Exception:
        target = 0
    levels = _technical_score_levels(strategy)
    if not levels:
        return target
    if str(mode).lower() == "floor":
        candidates = [x for x in levels if x <= target]
        return max(candidates) if candidates else min(levels)
    candidates = [x for x in levels if x >= target]
    return min(candidates) if candidates else max(levels)


def technical_previous_level(value: Any, strategy: Optional[str] = None) -> int:
    current = technical_threshold_grid(value, strategy, "ceil")
    levels = _technical_score_levels(strategy)
    prev = [x for x in levels if x < current]
    return max(prev) if prev else current

