def normalize_market_mode(value: Any) -> str:
    """Normaliza o modo de mercado do scanner.

    Valores:
    - otc_only: usa apenas ativos OTC.
    - normal_only: usa Forex/Binárias normais e Cripto, sem OTC.
    - crypto_only: usa apenas Cripto, sem Forex tradicional e sem OTC.
    - auto: usa Forex/Binárias normais + Cripto quando existirem e também mantém OTC como complemento/fallback.
    """
    raw = str(value or "auto").strip().lower().replace("-", "_")
    aliases = {
        "otc": "otc_only",
        "somente_otc": "otc_only",
        "otc_only": "otc_only",
        "normal": "normal_only",
        "binary": "normal_only",
        "binarias": "normal_only",
        "binarias_normais": "normal_only",
        "normal_only": "normal_only",
        "forex": "normal_only",
        "forex_binarias": "normal_only",
        "forex_binary": "normal_only",
        "crypto": "crypto_only",
        "cripto": "crypto_only",
        "crypto_only": "crypto_only",
        "cripto_only": "crypto_only",
        "somente_crypto": "crypto_only",
        "somente_cripto": "crypto_only",
        "both": "auto",
        "ambos": "auto",
        "todos": "auto",
        "misto": "auto",
        "mixed": "auto",
        "forex_otc": "auto",
        "forex_crypto_otc": "auto",
        "forex_binarias_cripto_otc": "auto",
        "normal_crypto_otc": "auto",
        "normal_otc": "auto",
        "otc_binary": "auto",
        "otc_binarias": "auto",
        "otc_and_binary": "auto",
        "auto": "auto",
    }
    return aliases.get(raw, "auto")

def market_mode_label(mode: str) -> str:
    mode = normalize_market_mode(mode)
    if mode == "otc_only":
        return "Somente OTC"
    if mode == "normal_only":
        return "Forex/Binárias + Cripto"
    if mode == "crypto_only":
        return "Somente Cripto"
    return "Forex/Binárias + Cripto + OTC"



def normalize_risk_profile(value: Any) -> str:
    raw = str(value or "normal").strip().lower().replace("-", "_")
    aliases = {
        "conservador": "conservative",
        "conservative": "conservative",
        "normal": "normal",
        "agressivo": "aggressive",
        "aggressive": "aggressive",
    }
    return aliases.get(raw, "normal")

def risk_profile_label(profile: str) -> str:
    profile = normalize_risk_profile(profile)
    if profile == "conservative":
        return "Conservador"
    if profile == "aggressive":
        return "Flexível demo"
    return "Normal"

def risk_profile_min_tech(profile: str) -> int:
    profile = normalize_risk_profile(profile)
    if profile == "conservative":
        return 70
    if profile == "aggressive":
        return 52  # Wall Street: entra mais cedo em setups com edge
    return 60


def risk_profile_min_lumi(profile: str) -> int:
    profile = normalize_risk_profile(profile)
    if profile == "conservative":
        return 75
    if profile == "aggressive":
        return 55  # mais oportunidades, ainda exige confirmação Lumi
    return 65


def normalize_lumi_top_mode(value: Any) -> str:
    raw = str(value or "normal").strip().lower().replace("-", "_")
    aliases = {
        "economico": "ultra",
        "ultra_economico": "ultra",
        "ultra": "ultra",
        "normal": "normal",
        "dinamico": "dynamic",
        "dynamic": "dynamic",
        "oportunidade_forte": "dynamic",
        "forte": "dynamic",
    }
    return aliases.get(raw, "normal")


def lumi_top_mode_label(value: Any) -> str:
    mode = normalize_lumi_top_mode(value)
    if mode == "ultra":
        return "Ultra econômico"
    if mode == "dynamic":
        return "Oportunidade forte"
    return "Normal"


def clean_config_payload(data: Dict[str, Any]) -> Dict[str, Any]:
    """Normaliza dados do painel antes de salvar em config.json local."""
    cfg = dict(CONFIG_DEFAULTS)
    cfg["version"] = CONFIG_VERSION
    cfg["save_credentials"] = bool(data.get("save_credentials", cfg["save_credentials"]))
    cfg["email"] = str(data.get("email", cfg["email"])).strip() if cfg["save_credentials"] else ""
    cfg["password"] = str(data.get("password", cfg["password"])).strip() if cfg["save_credentials"] else ""
    account_type = str(data.get("account_type", cfg["account_type"])).upper()
    cfg["account_type"] = account_type if account_type in {"PRACTICE", "REAL"} else "PRACTICE"
    cfg["asset"] = str(data.get("asset", cfg["asset"])).strip().upper() or "EURUSD"
    cfg["timeframe"] = to_int(data.get("timeframe"), cfg["timeframe"], 60, 3600)
    if cfg["timeframe"] not in VALID_TIMEFRAMES:
        cfg["timeframe"] = 300
    cfg["amount"] = to_float(data.get("amount"), cfg["amount"], MIN_OPERATION_AMOUNT, 100.0)
    cfg["strategy"] = str(data.get("strategy", cfg["strategy"])).lower()
    if cfg["strategy"] not in VALID_STRATEGIES:
        cfg["strategy"] = "combined"
    cfg["martingale"] = bool(data.get("martingale", cfg["martingale"]))
    cfg["martingale_factor"] = to_float(data.get("martingale_factor"), cfg["martingale_factor"], 1.1, 2.5)
    cfg["martingale_max"] = to_int(data.get("martingale_max"), cfg["martingale_max"], 0, 2)
    cfg["intelligent_martingale_enabled"] = bool(data.get("intelligent_martingale_enabled", cfg.get("intelligent_martingale_enabled", False)))
    cfg["intelligent_martingale_factor"] = to_float(data.get("intelligent_martingale_factor"), cfg.get("intelligent_martingale_factor", 2.2), 1.1, 2.5)
    cfg["intelligent_martingale_max"] = to_int(data.get("intelligent_martingale_max"), cfg.get("intelligent_martingale_max", 1), 1, 2)
    cfg["intelligent_martingale_min_technical"] = to_int(data.get("intelligent_martingale_min_technical"), cfg.get("intelligent_martingale_min_technical", 70), 60, 95)
    cfg["intelligent_martingale_min_lumi"] = to_int(data.get("intelligent_martingale_min_lumi"), cfg.get("intelligent_martingale_min_lumi", 72), 60, 95)
