def load_saved_config() -> Dict[str, Any]:
    if not os.path.exists(CONFIG_FILE):
        return dict(CONFIG_DEFAULTS)
    try:
        with open(CONFIG_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            return dict(CONFIG_DEFAULTS)
        merged = dict(CONFIG_DEFAULTS)
        merged.update(data)
        return clean_config_payload(merged)
    except Exception:
        return dict(CONFIG_DEFAULTS)


_CONFIG_SAVE_LOCK = threading.RLock()

def save_config_file(data: Dict[str, Any]) -> Dict[str, Any]:
    """V109.2: persistência atômica serializada + retry contra WinError 5/antivírus.

    O V109.0 usava um único config.json.tmp; dois saves concorrentes podiam disputar
    o mesmo arquivo no Windows. Agora cada tentativa usa TMP único e um lock local.
    """
    cfg = clean_config_payload(data)
    tmp_file = f"{CONFIG_FILE}.{os.getpid()}.{threading.get_ident()}.tmp"
    last_exc = None
    with _CONFIG_SAVE_LOCK:
        try:
            for attempt in range(4):
                try:
                    with open(tmp_file, "w", encoding="utf-8") as f:
                        json.dump(cfg, f, ensure_ascii=False, indent=2)
                        f.flush()
                        try:
                            os.fsync(f.fileno())
                        except Exception:
                            pass
                    os.replace(tmp_file, CONFIG_FILE)
                    last_exc = None
                    break
                except (PermissionError, OSError) as exc:
                    last_exc = exc
                    try:
                        if os.path.exists(tmp_file):
                            os.remove(tmp_file)
                    except Exception:
                        pass
                    if attempt < 3:
                        time.sleep(0.08 * (attempt + 1))
            if last_exc is not None:
                # Último fallback: escrita direta serializada. Mantém o bot funcional
                # caso software de segurança bloqueie renomeação atômica por instantes.
                with open(CONFIG_FILE, "w", encoding="utf-8") as f:
                    json.dump(cfg, f, ensure_ascii=False, indent=2)
        finally:
            try:
                if os.path.exists(tmp_file):
                    os.remove(tmp_file)
            except Exception:
                pass
    try:
        run_auto_backup("config_saved")
    except Exception:
        pass
    return cfg


