def set_lumi_quota_status(status: str = "ok", reason: str = "", error: str = "") -> None:
    """Guarda o motivo real da indisponibilidade da Lumi para o painel não chamar tudo de sem cota."""
    try:
        with state_lock:
            state["lumi_quota_status"] = str(status or "ok")[:80]
            state["lumi_quota_reason"] = str(reason or status or "ok")[:220]
            if error:
                state["lumi_last_error"] = str(error)[:300]
    except Exception:
        pass


def short_lumi_error(err: Any) -> str:
    text = str(err or "").strip()
    low = text.lower()
    if "timed out" in low or "timeout" in low:
        return "timeout"
    if "handshake" in low or "_ssl" in low or "ssl" in low:
        return "timeout SSL"
    if "429" in low or "quota" in low or "resource_exhausted" in low:
        return "cota/429"
    if any(k in low for k in ["memory", "memória", "memoria", "out of memory", "insufficient memory"]):
        return "memória baixa no Ollama"
    if any(k in low for k in ["json", "resposta do modelo", "truncada", "truncado", "objeto não foi fechado"]):
        return "resposta IA inválida"
    if "urlopen" in low:
        return "falha de conexão"
    return text[:140] or "erro"


