class _TrackedRLock:
    """RLock compatível com telemetria de proprietário para diagnóstico de deadlock.

    Não altera a semântica do threading.RLock; apenas registra qual thread adquiriu
    o primeiro nível do lock e há quanto tempo. Isso permite ao watchdog apontar
    o provável responsável sem inspecionar/pausar as threads do trader.
    """
    def __init__(self, name: str = "lock") -> None:
        self._lock = threading.RLock()
        self._meta_lock = threading.Lock()
        self._name = str(name)
        self._owner_ident: Optional[int] = None
        self._owner_name = ""
        self._owner_site = ""
        self._acquired_ts = 0.0
        self._depth = 0

    def acquire(self, blocking: bool = True, timeout: float = -1) -> bool:
        if timeout is None:
            timeout = -1
        if timeout is not None and float(timeout) >= 0:
            ok = self._lock.acquire(blocking, float(timeout))
        else:
            ok = self._lock.acquire(blocking)
        if not ok:
            return False
        ident = threading.get_ident()
        name = threading.current_thread().name
        try:
            frame = sys._getframe(1)
            if frame.f_code.co_name == "__enter__" and frame.f_back is not None:
                frame = frame.f_back
            site = f"{frame.f_code.co_name}:{frame.f_lineno}"
        except Exception:
            site = "?"
        with self._meta_lock:
            if self._owner_ident == ident:
                self._depth += 1
            else:
                self._owner_ident = ident
                self._owner_name = name
                self._owner_site = site
                self._acquired_ts = time.time()
                self._depth = 1
        return True

    def release(self) -> None:
        ident = threading.get_ident()
        with self._meta_lock:
            if self._owner_ident == ident and self._depth > 0:
                self._depth -= 1
                if self._depth <= 0:
                    self._owner_ident = None
                    self._owner_name = ""
                    self._owner_site = ""
                    self._acquired_ts = 0.0
                    self._depth = 0
        self._lock.release()

    def __enter__(self):
        self.acquire()
        return self

    def __exit__(self, exc_type, exc, tb):
        self.release()
        return False

    def snapshot(self) -> Dict[str, Any]:
        with self._meta_lock:
            ts = float(self._acquired_ts or 0.0)
            return {
                "name": self._name,
                "locked": bool(self._owner_ident is not None),
                "owner_ident": self._owner_ident,
                "owner_thread": self._owner_name,
                "owner_site": self._owner_site,
                "depth": int(self._depth),
                "held_seconds": round(max(0.0, time.time() - ts), 2) if ts else 0.0,
            }


