def telegram_html_escape(value: Any) -> str:
    text = str(value if value is not None else "")
    return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


def telegram_plain_text(value: Any) -> str:
    """Remove tags simples de HTML para fallback quando o Telegram recusa parse_mode=HTML."""
    text = html.unescape(str(value if value is not None else ""))
    text = re.sub(r"<br\s*/?>", "\n", text, flags=re.I)
    text = re.sub(r"</p\s*>", "\n", text, flags=re.I)
    text = re.sub(r"<[^>]+>", "", text)
    return text


def telegram_token_preview(token: str) -> str:
    token = str(token or "").strip()
    if len(token) <= 10:
        return "vazio" if not token else "curto"
    return token[:6] + "..." + token[-4:]


def telegram_set_status(message: str) -> None:
    with state_lock:
        state["telegram_last_status"] = str(message)[:260]


def telegram_cfg() -> Dict[str, Any]:
    cfg = load_saved_config() if os.path.exists(CONFIG_FILE) else dict(CONFIG_DEFAULTS)
    try:
        with state_lock:
            # Estado tem prioridade quando o usuário acabou de salvar pelo painel.
            for key in [
                "telegram_enabled", "telegram_bot_token", "telegram_chat_id",
                "telegram_notify_start_stop", "telegram_notify_entries", "telegram_notify_results",
                "telegram_notify_lumi", "telegram_notify_errors", "telegram_notify_daily_summary", "telegram_commands_enabled", "telegram_polling_enabled",
            ]:
                if key in state:
                    cfg[key] = cfg_get(key)
    except Exception:
        pass
    token = os.environ.get("TELEGRAM_BOT_TOKEN") or str(cfg.get("telegram_bot_token", "")).strip()
    chat_id = os.environ.get("TELEGRAM_CHAT_ID") or str(cfg.get("telegram_chat_id", "")).strip()
    cfg["telegram_bot_token"] = token
    cfg["telegram_chat_id"] = chat_id
    return cfg


def telegram_notify(message: str, event: str = "info", silent: bool = False) -> bool:
    """Envia notificação Telegram sem travar o bot, com diagnóstico real do erro 400."""
    try:
        cfg = telegram_cfg()
        if not bool(cfg.get("telegram_enabled", False)):
            telegram_set_status("Telegram desativado")
            return False
        token = str(cfg.get("telegram_bot_token", "")).strip()
        chat_id = str(cfg.get("telegram_chat_id", "")).strip()
        if not token or not chat_id:
            telegram_set_status("Telegram não configurado: token/chat_id vazio")
            return False

        notify_map = {
            "start_stop": "telegram_notify_start_stop",
            "entries": "telegram_notify_entries",
            "results": "telegram_notify_results",
            "lumi": "telegram_notify_lumi",
            "errors": "telegram_notify_errors",
            "daily": "telegram_notify_daily_summary",
            "test": "telegram_enabled",
            "info": "telegram_enabled",
        }
        flag = notify_map.get(event, "telegram_enabled")
        if not bool(cfg.get(flag, True)):
            telegram_set_status(f"Telegram evento '{event}' desativado")
            return False

        def _post(payload: Dict[str, Any]) -> Tuple[bool, str]:
            data = json.dumps(payload, ensure_ascii=False).encode("utf-8")
            req = urllib.request.Request(
                f"https://api.telegram.org/bot{token}/sendMessage",
                data=data,
                headers={"Content-Type": "application/json"},
                method="POST",
            )
            try:
                with urllib.request.urlopen(req, timeout=8) as resp:
                    raw = resp.read().decode("utf-8", errors="replace")
                    status_code = int(getattr(resp, "status", 200))
                if 200 <= status_code < 300:
                    return True, f"OK {now_hms()}"
                return False, f"HTTP {status_code}: {raw[:220]}"
            except urllib.error.HTTPError as exc:
                try:
                    detail = exc.read().decode("utf-8", errors="replace")
                except Exception:
                    detail = str(exc)
                return False, f"HTTP {exc.code}: {detail[:260]}"
            except Exception as exc:
                return False, str(exc)[:260]

        text_html = str(message or "")[:3900]
        payload_html = {
            "chat_id": chat_id,
            "text": text_html,
            "parse_mode": "HTML",
            "disable_web_page_preview": True,
            "disable_notification": bool(silent),
        }
        ok, status_msg = _post(payload_html)
        if ok:
            telegram_set_status(status_msg)
            return True

        # Erro 400 pode ser tag HTML quebrada, &, <, > ou entidade inválida. Tenta texto puro.
        if "HTTP 400" in status_msg or "Bad Request" in status_msg or "can't parse" in status_msg.lower():
            plain = telegram_plain_text(message)[:3900]
            payload_plain = {
                "chat_id": chat_id,
                "text": plain,
                "disable_web_page_preview": True,
                "disable_notification": bool(silent),
            }
            ok2, status_plain = _post(payload_plain)
            if ok2:
                telegram_set_status(f"OK texto puro {now_hms()} | HTML recusado: {status_msg[:120]}")
                return True
            telegram_set_status(f"Falha Telegram: {status_msg[:140]} | fallback texto: {status_plain[:120]} | chat_id={chat_id[:4]}... token={telegram_token_preview(token)}")
            return False

        telegram_set_status(f"Falha Telegram: {status_msg} | chat_id={chat_id[:4]}... token={telegram_token_preview(token)}")
        return False
    except Exception as exc:
        telegram_set_status(f"Falha Telegram inesperada: {str(exc)[:220]}")
        return False

def telegram_notify_async(message: str, event: str = "info", silent: bool = False) -> None:
    try:
        threading.Thread(target=telegram_notify, args=(message, event, silent), daemon=True).start()
    except Exception:
        pass


def telegram_notify_lumi_unavailable(message: str, silent: bool = True, cooldown_seconds: int = 180) -> None:
    """Evita spam de Telegram quando a Lumi/Ollama entra em timeout repetido."""
    try:
        now = time.time()
        with state_lock:
            last = float(cfg_get("telegram_last_lumi_unavailable_ts", 0) or 0)
            if now - last < max(30, int(cooldown_seconds or 180)):
                return
            state["telegram_last_lumi_unavailable_ts"] = now
        telegram_notify_async(message, "lumi", silent=silent)
    except Exception:
        pass


