def telegram_handle_command(text_msg: str, chat_id: str = "") -> None:
    cmd = str(text_msg or "").strip().split()[0].lower()
    cfg = telegram_cfg()
    allowed_chat = str(cfg.get("telegram_chat_id", "")).strip()
    if allowed_chat and chat_id and str(chat_id) != allowed_chat:
        return
    if cmd in {"/start", "/help"}:
        telegram_notify("🤖 <b>IQ Bot Telegram ativo</b>\n\nUse /saldo para ver a carteira.\nUse /stop para parar as operações do bot.", "info")
    elif cmd in {"/saldo", "/status"}:
        telegram_notify(telegram_status_message(), "info")
    elif cmd == "/stop":
        stop_event.set()
        global BOT_RUN_TOKEN
        with bot_start_lock:
            BOT_RUN_TOKEN += 1
        with state_lock:
            was_running = bool(cfg_get("running"))
            state["running"] = False
            state["bot_run_token"] = BOT_RUN_TOKEN
            state["telegram_last_command"] = f"/stop {now_hms()}"
        try:
            run_auto_backup("telegram_stop")
        except Exception:
            pass
        try:
            _persist_payout_last_good_now()
        except Exception:
            pass
        log("Bot parado por comando Telegram /stop.", "warn")
        telegram_notify(f"🛑 <b>Bot parado pelo Telegram</b>\n\nStatus anterior: <b>{'rodando' if was_running else 'já estava parado'}</b>\n{telegram_summary_line()}", "start_stop")


def telegram_poll_loop() -> None:
    while True:
        try:
            cfg = telegram_cfg()
            if not bool(cfg.get("telegram_enabled", False)) or not bool(cfg.get("telegram_polling_enabled", True)) or not bool(cfg.get("telegram_commands_enabled", True)):
                time.sleep(3)
                continue
            token = str(cfg.get("telegram_bot_token", "")).strip()
            if not token:
                time.sleep(5)
                continue
            with state_lock:
                offset = int(cfg_get("telegram_last_update_id", 0) or 0) + 1
            url = f"https://api.telegram.org/bot{token}/getUpdates?timeout=3&offset={offset}"
            with urllib.request.urlopen(url, timeout=8) as resp:
                data = json.loads(resp.read().decode("utf-8", errors="replace") or "{}")
            if not data.get("ok"):
                time.sleep(2)
                continue
            for upd in data.get("result", []) or []:
                update_id = int(upd.get("update_id", 0) or 0)
                msg = upd.get("message") or upd.get("edited_message") or {}
                text_msg = str(msg.get("text") or "").strip()
                chat_id = str((msg.get("chat") or {}).get("id", "")).strip()
                with state_lock:
                    state["telegram_last_update_id"] = max(int(cfg_get("telegram_last_update_id", 0) or 0), update_id)
                if text_msg.startswith("/"):
                    telegram_handle_command(text_msg, chat_id)
        except urllib.error.HTTPError as exc:
            try:
                detail = exc.read().decode("utf-8", errors="replace")
            except Exception:
                detail = str(exc)
            telegram_set_status(f"Polling Telegram HTTP {exc.code}: {detail[:180]}")
            time.sleep(4)
        except Exception as exc:
            telegram_set_status(f"Polling Telegram: {str(exc)[:180]}")
            time.sleep(4)


def start_telegram_polling_once() -> None:
    try:
        if getattr(start_telegram_polling_once, "started", False):
            return
        start_telegram_polling_once.started = True
        threading.Thread(target=telegram_poll_loop, daemon=True).start()
    except Exception:
        pass


def safe_read_json(path: str, fallback: Any) -> Any:
    try:
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            return data if data is not None else fallback
    except Exception:
        pass
    return fallback


def _json_file_lock(path: str) -> threading.RLock:
    key = os.path.abspath(path)
    with JSON_FILE_LOCKS_GUARD:
        lock = JSON_FILE_LOCKS.get(key)
        if lock is None:
            lock = threading.RLock()
            JSON_FILE_LOCKS[key] = lock
        return lock


def safe_write_json(path: str, data: Any) -> None:
    """V108.8.0: gravação JSON atômica/thread-safe, inclusive no Windows.

    Cada writer usa arquivo temporário exclusivo; os retries curtos evitam WinError 32
    quando antivírus/indexador segura o destino por alguns milissegundos.
    """
    path = os.path.abspath(path)
    os.makedirs(os.path.dirname(path) or app.root_path, exist_ok=True)
    lock = _json_file_lock(path)
    with lock:
        tmp = f"{path}.tmp.{os.getpid()}.{threading.get_ident()}.{uuid.uuid4().hex[:8]}"
        try:
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
                f.flush()
                try:
                    os.fsync(f.fileno())
                except Exception:
                    pass
            last_exc = None
            for attempt in range(5):
                try:
                    os.replace(tmp, path)
                    last_exc = None
                    break
                except (PermissionError, OSError) as exc:
                    last_exc = exc
                    time.sleep(0.04 * (attempt + 1))
            if last_exc is not None:
                raise last_exc
        finally:
            try:
                if os.path.exists(tmp):
                    os.remove(tmp)
            except Exception:
                pass


