def _strategy_usage_store() -> Dict[str, Any]:
    """V108.8.0: ranking persistente de quais estratégias dominantes são mais usadas."""
    global STRATEGY_USAGE_CACHE
    with STRATEGY_USAGE_LOCK:
        if not isinstance(STRATEGY_USAGE_CACHE, dict):
            data = safe_read_json(STRATEGY_USAGE_FILE, {})
            if not isinstance(data, dict):
                data = {}
            data.setdefault("version", 1)
            data.setdefault("started_version", "V108.8.0")
            data.setdefault("strategies", {})
            STRATEGY_USAGE_CACHE = data
        return STRATEGY_USAGE_CACHE


def record_strategy_usage(signals: Optional[Dict[str, Any]], asset: str = "", direction: str = "", event: str = "analysis", *, force_save: bool = False) -> None:
    """Registra estratégia dominante por análise/sinal/entrada/resultado sem alterar a decisão."""
    global STRATEGY_USAGE_DIRTY
    sig = dict(signals or {})
    key = str(sig.get("primary_strategy_key") or sig.get("strategy_used_key") or "all_strategies").strip().lower() or "all_strategies"
    name = str(sig.get("primary_strategy_name") or sig.get("strategy_used") or key.replace("_", " ").title()).strip()
    ev = str(event or "analysis").strip().lower()
    now = time.time()
    with STRATEGY_USAGE_LOCK:
        store = _strategy_usage_store()
        strategies = store.setdefault("strategies", {})
        row = dict(strategies.get(key) or {})
        row.setdefault("key", key)
        row["name"] = name or row.get("name") or key
        row.setdefault("analyses", 0); row.setdefault("signals", 0); row.setdefault("entries", 0); row.setdefault("wins", 0); row.setdefault("losses", 0)
        if ev == "analysis":
            row["analyses"] = int(row.get("analyses", 0) or 0) + 1
            if normalize_lumi_action(direction) in VALID_DIRECTIONS:
                row["signals"] = int(row.get("signals", 0) or 0) + 1
        elif ev == "entry":
            row["entries"] = int(row.get("entries", 0) or 0) + 1
        elif ev == "win":
            row["wins"] = int(row.get("wins", 0) or 0) + 1
        elif ev == "loss":
            row["losses"] = int(row.get("losses", 0) or 0) + 1
        row["last_seen_ts"] = now
        row["last_seen"] = now_hms()
        if asset: row["last_asset"] = normalize_asset_name(asset)
        if direction: row["last_direction"] = normalize_lumi_action(direction)
        strategies[key] = row
        store["updated_at"] = now_hms()
        STRATEGY_USAGE_DIRTY += 1
        should_save = bool(force_save or STRATEGY_USAGE_DIRTY >= 20)
        if should_save:
            safe_write_json(STRATEGY_USAGE_FILE, store)
            STRATEGY_USAGE_DIRTY = 0


def strategy_usage_snapshot(limit: int = 6) -> List[Dict[str, Any]]:
    with STRATEGY_USAGE_LOCK:
        store = _strategy_usage_store()
        rows = [dict(v) for v in (store.get("strategies") or {}).values() if isinstance(v, dict)]
    rows.sort(key=lambda r: (int(r.get("analyses",0) or 0), int(r.get("signals",0) or 0), int(r.get("entries",0) or 0)), reverse=True)
    return rows[:max(1, int(limit or 6))]


def log_strategy_usage_summary(limit: int = 5) -> None:
    rows = strategy_usage_snapshot(limit)
    if not rows:
        return
    parts=[]
    for i,r in enumerate(rows,1):
        parts.append(
            f"#{i} {r.get('name','-')} A={int(r.get('analyses',0) or 0)} S={int(r.get('signals',0) or 0)} "
            f"E={int(r.get('entries',0) or 0)} W/L={int(r.get('wins',0) or 0)}/{int(r.get('losses',0) or 0)}"
        )
    log("📈 USO DAS ESTRATÉGIAS V108.8.0 | " + " · ".join(parts), "info")

_STRATEGY_PERF_CACHE: Dict[str, Any] = {"ts": 0.0, "rows": []}

def strategy_performance_snapshot(limit: int = 5, ttl: int = 45) -> List[Dict[str, Any]]:
    """V108.8.0: qualidade observada por estratégia no Signal Lab.

    É diagnóstico, não altera peso automaticamente. Shadow e REAL ficam separados
    para não transformar volume de simulação em falsa evidência de lucro REAL.
    """
    now = time.time()
    cached = list(_STRATEGY_PERF_CACHE.get("rows") or [])
    if cached and now - float(_STRATEGY_PERF_CACHE.get("ts", 0) or 0) < max(10, int(ttl)):
        return cached[:max(1, int(limit))]
    groups: Dict[str, Dict[str, Any]] = {}
    try:
        records = _signal_lab_resolved_records()
    except Exception:
        records = []
    for rec in records:
        if not isinstance(rec, dict): continue
        name = str(rec.get("strategy_used") or rec.get("strategy") or "ALL_STRATEGIES").strip() or "ALL_STRATEGIES"
        g = groups.setdefault(name, {"name":name,"shadow_wins":0,"shadow_losses":0,"real_wins":0,"real_losses":0,"real_pnl":0.0,"tech_sum":0.0,"tech_n":0,"lumi_sum":0.0,"lumi_n":0})
        result = str(rec.get("result") or "").upper()
        if result == "WIN": g["shadow_wins"] += 1
        elif result == "LOSS": g["shadow_losses"] += 1
        actual = str(rec.get("actual_result") or "").upper()
        if actual == "WIN": g["real_wins"] += 1
        elif actual == "LOSS": g["real_losses"] += 1
        if actual in {"WIN","LOSS"}:
            try: g["real_pnl"] += float(rec.get("actual_profit",0) or 0)
            except Exception: pass
        try:
            t=float(rec.get("technical_confidence",0) or 0)
            if t>0: g["tech_sum"]+=t; g["tech_n"]+=1
        except Exception: pass
        try:
            l=float(rec.get("lumi_confidence",0) or 0)
            if l>0: g["lumi_sum"]+=l; g["lumi_n"]+=1
        except Exception: pass
    rows=[]
    for g in groups.values():
        sn=g["shadow_wins"]+g["shadow_losses"]; rn=g["real_wins"]+g["real_losses"]
        g["shadow_samples"]=sn; g["shadow_wr"]=round(g["shadow_wins"]/sn*100.0,1) if sn else 0.0
        g["real_samples"]=rn; g["real_wr"]=round(g["real_wins"]/rn*100.0,1) if rn else 0.0
        g["real_pnl"]=round(g["real_pnl"],2)
        g["avg_technical"]=round(g["tech_sum"]/g["tech_n"],1) if g["tech_n"] else 0.0
        g["avg_lumi"]=round(g["lumi_sum"]/g["lumi_n"],1) if g["lumi_n"] else 0.0
        rows.append(g)
    rows.sort(key=lambda r:(int(r.get("real_samples",0)), int(r.get("shadow_samples",0)), float(r.get("shadow_wr",0))), reverse=True)
    _STRATEGY_PERF_CACHE["ts"]=now; _STRATEGY_PERF_CACHE["rows"]=rows
    return rows[:max(1,int(limit))]

def log_strategy_performance_summary(limit: int = 5) -> None:
    rows = strategy_performance_snapshot(limit)
    if not rows: return
    parts=[]
    for i,r in enumerate(rows,1):
        parts.append(f"#{i} {r.get('name','-')} Shadow={int(r.get('shadow_wins',0))}W/{int(r.get('shadow_losses',0))}L {float(r.get('shadow_wr',0)):.1f}% · REAL={int(r.get('real_wins',0))}W/{int(r.get('real_losses',0))}L P&L={float(r.get('real_pnl',0)):+.2f}")
    log("🏆 PERFORMANCE DAS ESTRATÉGIAS V108.8.0 | " + " · ".join(parts), "info")


def _payout_last_good_persist_snapshot() -> Dict[str, Any]:
    """Fotografia compacta do LKG para sobreviver a restart/falha intermitente.

    É usado SOMENTE em ranking/diagnóstico. O caminho REAL continua exigindo
    get_all_profit fresco imediatamente antes de api.buy.
    """
    with LUMI_CACHE_LOCK:
        items = {
            normalize_asset_name(asset): dict(info or {})
            for asset, info in PAYOUT_LAST_GOOD.items()
            if normalize_asset_name(asset) and int((info or {}).get("payout", 0) or 0) > 0
        }
    # Limite amplo, ordenado por mais recente, para não crescer indefinidamente.
    ordered = sorted(items.items(), key=lambda kv: float((kv[1] or {}).get("ts", 0) or 0), reverse=True)[:800]
    return {
        "version": 1,
        "updated_at": datetime.now().isoformat(timespec="seconds"),
        "items": dict(ordered),
    }


def _persist_payout_last_good_now() -> int:
    payload = _payout_last_good_persist_snapshot()
    safe_write_json(PAYOUT_LAST_GOOD_FILE, payload)
    return len(payload.get("items") or {})


def _payout_persist_worker() -> None:
    """Debounce de escrita: um snapshot por lote, nunca um arquivo por ativo."""
    global PAYOUT_PERSIST_DIRTY, PAYOUT_PERSIST_WORKER_ACTIVE
    try:
        while True:
            time.sleep(0.65)
            with PAYOUT_PERSIST_LOCK:
                PAYOUT_PERSIST_DIRTY = False
            try:
                _persist_payout_last_good_now()
            except Exception:
                pass
            with PAYOUT_PERSIST_LOCK:
                if not PAYOUT_PERSIST_DIRTY:
                    PAYOUT_PERSIST_WORKER_ACTIVE = False
                    return
    finally:
        with PAYOUT_PERSIST_LOCK:
            PAYOUT_PERSIST_WORKER_ACTIVE = False


def _schedule_payout_last_good_persist() -> None:
    global PAYOUT_PERSIST_DIRTY, PAYOUT_PERSIST_WORKER_ACTIVE
    with PAYOUT_PERSIST_LOCK:
        PAYOUT_PERSIST_DIRTY = True
        if PAYOUT_PERSIST_WORKER_ACTIVE:
            return
        PAYOUT_PERSIST_WORKER_ACTIVE = True
    try:
        threading.Thread(target=_payout_persist_worker, daemon=True, name="payout-lkg-v10877").start()
    except Exception:
        with PAYOUT_PERSIST_LOCK:
            PAYOUT_PERSIST_WORKER_ACTIVE = False


def _load_payout_last_good_persistent() -> int:
    raw = safe_read_json(PAYOUT_LAST_GOOD_FILE, {"version": 1, "items": {}})
    items = raw.get("items") if isinstance(raw, dict) else {}
    if not isinstance(items, dict):
        return 0
    loaded = 0
    with LUMI_CACHE_LOCK:
        for raw_asset, raw_info in items.items():
            asset = normalize_asset_name(raw_asset)
            info = dict(raw_info or {}) if isinstance(raw_info, dict) else {}
            try:
                payout = int(info.get("payout", 0) or 0)
                ts = float(info.get("ts", 0) or 0)
            except Exception:
                continue
            if not asset or payout <= 0 or ts <= 0:
                continue
            info["payout"] = payout
            info["ts"] = ts
            info.setdefault("source", "persistent_last_known_good")
            PAYOUT_LAST_GOOD[asset] = info
            loaded += 1
    return loaded


def _legacy_runtime_roots() -> List[str]:
    """Pastas prováveis de versões anteriores para migração automática de aprendizado."""
    roots = [os.path.abspath(app.root_path)]
    try:
        parent = os.path.dirname(os.path.abspath(app.root_path))
        for name in os.listdir(parent):
            path = os.path.join(parent, name)
            if not os.path.isdir(path) or os.path.abspath(path) == os.path.abspath(app.root_path):
                continue
            upper = str(name).upper()
            if "BOT IQ" in upper or "V108" in upper or "LUMI" in upper:
                roots.append(os.path.abspath(path))
    except Exception:
        pass
    return list(dict.fromkeys(roots))[:30]


def _migration_record_key(row: Dict[str, Any]) -> str:
    sid = str(row.get("signal_id") or row.get("id") or "").strip()
    if sid:
        return "sig:" + sid
    return "row:" + hashlib.sha1(json.dumps({
        "asset": row.get("asset"), "direction": row.get("direction"),
        "created": row.get("created_ts") or row.get("created_at"),
        "entry": row.get("entry_price"), "result": row.get("result"),
    }, sort_keys=True, ensure_ascii=False, default=str).encode("utf-8")).hexdigest()


def _migrate_signal_lab_from_legacy() -> int:
    target = safe_read_json(SIGNAL_LAB_FILE, {"version": 2, "records": [], "updated_at": ""})
    records = list(target.get("records") or []) if isinstance(target, dict) else []
    by_key = {_migration_record_key(r): r for r in records if isinstance(r, dict)}
    added = 0
    for root in _legacy_runtime_roots():
        src = os.path.join(root, "signal_lab.json")
        if not os.path.exists(src) or os.path.abspath(src) == os.path.abspath(SIGNAL_LAB_FILE):
            continue
        raw = safe_read_json(src, {})
        for row in list((raw or {}).get("records") or []):
            if not isinstance(row, dict):
                continue
            key = _migration_record_key(row)
            if key not in by_key:
                by_key[key] = dict(row); added += 1
            else:
                # Preserva a versão mais completa/resolvida do mesmo sinal.
                old = by_key[key]
                old_res = str(old.get("actual_result") or old.get("result") or "").upper()
                new_res = str(row.get("actual_result") or row.get("result") or "").upper()
                if old_res in {"", "PENDING"} and new_res not in {"", "PENDING"}:
                    by_key[key] = dict(row)
    merged = list(by_key.values())
    merged.sort(key=lambda r: float(r.get("actual_resolved_ts",0) or r.get("resolved_ts",0) or r.get("created_ts",0) or 0), reverse=True)
    safe_write_json(SIGNAL_LAB_FILE, {"version": 2, "records": merged[:SIGNAL_LAB_MAX_RECORDS], "updated_at": datetime.now().isoformat(timespec="seconds")})
    return added


def _migrate_trade_ledger_from_legacy() -> int:
    target = safe_read_json(REAL_TRADE_LEDGER_FILE, {"version": 1, "trades": [], "updated_at": ""})
    trades = list(target.get("trades") or []) if isinstance(target, dict) else []
    by_id = {str(t.get("order_id") or ""): dict(t) for t in trades if isinstance(t, dict) and str(t.get("order_id") or "")}
    added = 0
    for root in _legacy_runtime_roots():
        src = os.path.join(root, "real_trade_ledger.json")
        if not os.path.exists(src) or os.path.abspath(src) == os.path.abspath(REAL_TRADE_LEDGER_FILE):
            continue
        raw = safe_read_json(src,{})
        for row in list((raw or {}).get("trades") or []):
            if not isinstance(row,dict): continue
            oid=str(row.get("order_id") or "").strip()
            if not oid: continue
            if oid not in by_id:
                by_id[oid]=dict(row); added+=1
            else:
                current=by_id[oid]
                if str(current.get("status") or "").upper() not in {"WIN","LOSS"} and str(row.get("status") or row.get("result") or "").upper() in {"WIN","LOSS"}:
                    by_id[oid]=dict(row)
    merged=list(by_id.values())
    merged.sort(key=lambda r: float(r.get("closed_ts",0) or r.get("opened_ts",0) or 0), reverse=True)
    safe_write_json(REAL_TRADE_LEDGER_FILE,{"version":1,"trades":merged[:5000],"updated_at":datetime.now().isoformat(timespec="seconds")})
    return added


def _migrate_simple_runtime_files() -> int:
    copied=0
    names=("loss_memory.json","win_memory.json","ai_strategy_factory.json","adaptive_calibration.json","market_memory.json","payout_last_good.json")
    for name in names:
        target=os.path.join(PERSISTENT_DATA_DIR,name)
        if os.path.exists(target): continue
        candidates=[]
        for root in _legacy_runtime_roots():
            src=os.path.join(root,name)
            if os.path.exists(src):
                try: candidates.append((os.path.getmtime(src),src))
                except Exception: pass
        if candidates:
            src=max(candidates)[1]
            raw=safe_read_json(src,None)
            if raw is not None:
                safe_write_json(target,raw); copied+=1
    # Relatórios diários: copia apenas arquivos que ainda não existem na área persistente.
    os.makedirs(DAILY_REPORTS_DIR,exist_ok=True)
    for root in _legacy_runtime_roots():
        srcdir=os.path.join(root,"daily_reports")
        if not os.path.isdir(srcdir): continue
        try:
            for name in os.listdir(srcdir):
                if not name.endswith(".json"): continue
                dst=os.path.join(DAILY_REPORTS_DIR,name)
                if os.path.exists(dst): continue
                raw=safe_read_json(os.path.join(srcdir,name),None)
                if raw is not None:
                    safe_write_json(dst,raw); copied+=1
        except Exception: pass
    return copied


def initialize_persistent_runtime_data() -> Dict[str, Any]:
    """Inicializa área persistente e importa automaticamente dados de ZIPs anteriores."""
    global _signal_lab_cache, _adaptive_calibration_cache, _adaptive_calibration_dirty
    os.makedirs(PERSISTENT_DATA_DIR,exist_ok=True)
    os.makedirs(BACKUP_DIR,exist_ok=True)
    os.makedirs(DAILY_REPORTS_DIR,exist_ok=True)
    simple=_migrate_simple_runtime_files()
    ensure_memory_files()
    lab_added=_migrate_signal_lab_from_legacy()
    ledger_added=_migrate_trade_ledger_from_legacy()
    _signal_lab_cache=None
    _adaptive_calibration_cache=None
    _adaptive_calibration_dirty=True
    memory=safe_read_json(FAST_MARKET_MEMORY_FILE,{"version":1,"items":{},"updated_at":""})
    if isinstance(memory,dict):
        with state_lock:
            state["_fast_market_intelligence"] = dict(memory.get("items") or {})
    payout_lkg_loaded = _load_payout_last_good_persistent()
    win_backfill = {"imported": 0}
    reconciler = globals().get("reconcile_real_wins_into_win_memory")
    if callable(reconciler):
        try: win_backfill = dict(reconciler(False) or win_backfill)
        except Exception: pass
    return {"path":PERSISTENT_DATA_DIR,"lab_added":lab_added,"ledger_added":ledger_added,"files_copied":simple,"payout_lkg_loaded":payout_lkg_loaded,"win_backfill":win_backfill}


