# ── Indicadores técnicos ──────────────────────────────────
def calc_ema_series(values: List[float], period: int) -> List[float]:
    if not values:
        return []
    if len(values) < period:
        return [values[-1]]
    k = 2 / (period + 1)
    ema = sum(values[:period]) / period
    out = [ema]
    for v in values[period:]:
        ema = v * k + ema * (1 - k)
        out.append(ema)
    return out


def calc_ema(values: List[float], period: int) -> float:
    return calc_ema_series(values, period)[-1] if values else 0.0


def calc_rsi(closes: List[float], period: int = 14) -> float:
    if len(closes) < period + 1:
        return 50.0
    gains, losses = 0.0, 0.0
    window = closes[-(period + 1):]
    for prev, cur in zip(window, window[1:]):
        delta = cur - prev
        if delta > 0:
            gains += delta
        else:
            losses += abs(delta)
    if losses == 0:
        return 100.0
    rs = gains / losses
    return round(100 - (100 / (1 + rs)), 2)


def calc_macd(closes: List[float]) -> Tuple[float, float, float]:
    """MACD real: EMA12 - EMA26 e signal = EMA9 da série MACD."""
    if len(closes) < 35:
        return 0.0, 0.0, 0.0
    ema12_series = calc_ema_series(closes, 12)
    ema26_series = calc_ema_series(closes, 26)
    diff_len = min(len(ema12_series), len(ema26_series))
    macd_series = [a - b for a, b in zip(ema12_series[-diff_len:], ema26_series[-diff_len:])]
    signal_series = calc_ema_series(macd_series, 9)
    macd_line = macd_series[-1]
    signal = signal_series[-1]
    hist = macd_line - signal
    return round(macd_line, 6), round(signal, 6), round(hist, 6)


def calc_bb(closes: List[float], period: int = 20) -> Tuple[float, float, float, float, float]:
    if len(closes) < period:
        price = closes[-1] if closes else 0.0
        return price, price, price, 50.0, 0.0
    window = closes[-period:]
    mid = sum(window) / period
    std = (sum((x - mid) ** 2 for x in window) / period) ** 0.5
    upper = mid + 2 * std
    lower = mid - 2 * std
    width_pct = ((upper - lower) / mid * 100) if mid else 0.0
    pct_b = ((closes[-1] - lower) / (upper - lower) * 100) if upper != lower else 50.0
    return round(upper, 6), round(mid, 6), round(lower, 6), round(max(0, min(100, pct_b)), 2), round(width_pct, 4)



def calc_stochastic(closes: List[float], k_period: int = 5, d_period: int = 3) -> Tuple[float, float, float, float]:
    """Estocástico aproximado usando fechamentos.

    A API nem sempre entrega high/low/volume de forma uniforme para todos os ativos.
    Por isso usamos o intervalo dos fechamentos recentes como proxy. Não substitui
    uma leitura OHLC completa, mas mantém a estratégia funcional e transparente.
    """
    if len(closes) < max(k_period, d_period + 1):
        return 50.0, 50.0, 50.0, 50.0
    k_values: List[float] = []
    for i in range(max(0, len(closes) - d_period - 1), len(closes)):
        window = closes[max(0, i - k_period + 1): i + 1]
        lo, hi = min(window), max(window)
        k = ((closes[i] - lo) / (hi - lo) * 100.0) if hi != lo else 50.0
        k_values.append(max(0.0, min(100.0, k)))
    k_now = k_values[-1]
    k_prev = k_values[-2] if len(k_values) >= 2 else k_now
    d_now = sum(k_values[-d_period:]) / min(d_period, len(k_values))
    d_prev = sum(k_values[-d_period-1:-1]) / min(d_period, max(1, len(k_values)-1)) if len(k_values) > 1 else d_now
    return round(k_now, 2), round(d_now, 2), round(k_prev, 2), round(d_prev, 2)


def calc_avg_abs_delta(closes: List[float], period: int = 10) -> float:
    if len(closes) < 2:
        return 0.0
    deltas = [abs(closes[i] - closes[i - 1]) for i in range(max(1, len(closes) - period), len(closes))]
    return sum(deltas) / max(1, len(deltas))


def calc_ema_cross_vote(closes: List[float]) -> int:
    if len(closes) < 22:
        return 0
    ema9_now = calc_ema(closes, 9)
    ema21_now = calc_ema(closes, 21)
    ema9_prev = calc_ema(closes[:-1], 9)
    ema21_prev = calc_ema(closes[:-1], 21)
    if ema9_prev <= ema21_prev and ema9_now > ema21_now:
        return 1
    if ema9_prev >= ema21_prev and ema9_now < ema21_now:
        return -1
    # Depois do cruzamento, aceita alinhamento recente como continuação moderada.
    if ema9_now > ema21_now and closes[-1] > ema9_now:
        return 1
    if ema9_now < ema21_now and closes[-1] < ema9_now:
        return -1
    return 0


def calc_support_resistance_vote(closes: List[float]) -> Tuple[int, str]:
    if len(closes) < 18:
        return 0, "S/R aguardando histórico"
    price = closes[-1]
    history = closes[-30:-3] if len(closes) >= 33 else closes[:-3]
    support = min(history)
    resistance = max(history)
    span = max(resistance - support, abs(price) * 0.0005, 1e-9)
    tolerance = max(span * 0.12, abs(price) * 0.00018)
    last_move = closes[-1] - closes[-2]
    prev_move = closes[-2] - closes[-3]
    near_support = abs(price - support) <= tolerance
    near_resistance = abs(price - resistance) <= tolerance
    if near_support and last_move > 0 and prev_move <= 0:
        return 1, "S/R: reação em suporte"
    if near_resistance and last_move < 0 and prev_move >= 0:
        return -1, "S/R: rejeição em resistência"
    return 0, f"S/R: suporte={support:.6f} resistência={resistance:.6f}"


def calc_consolidation_breakout_vote(closes: List[float]) -> Tuple[int, str]:
    if len(closes) < 14:
        return 0, "Breakout: aguardando faixa"
    price = closes[-1]
    box = closes[-11:-1]
    box_high = max(box)
    box_low = min(box)
    box_mid = sum(box) / len(box)
    box_width_pct = ((box_high - box_low) / box_mid * 100.0) if box_mid else 0.0
    avg_delta = calc_avg_abs_delta(closes[:-1], 10)
    last_delta = closes[-1] - closes[-2]
    impulse_ok = abs(last_delta) >= max(avg_delta * 1.12, abs(price) * 0.00004)
    # Sem volume confiável em todos os ativos: impulso do candle é usado como proxy.
    if box_width_pct <= 0.12 and price > box_high and impulse_ok:
        return 1, "Breakout: rompeu topo da consolidação"
    if box_width_pct <= 0.12 and price < box_low and impulse_ok:
        return -1, "Breakout: rompeu fundo da consolidação"
    return 0, f"Breakout: faixa {box_width_pct:.3f}%"


def calc_macd_divergence_vote(closes: List[float], macd_hist: float) -> Tuple[int, str]:
    if len(closes) < 30:
        return 0, "Divergência: aguardando histórico"
    prev = closes[-18:-9]
    recent = closes[-9:]
    try:
        _, _, prev_hist = calc_macd(closes[:-4])
    except Exception:
        prev_hist = macd_hist
    price_higher_high = max(recent) > max(prev)
    price_lower_low = min(recent) < min(prev)
    macd_weaker_high = macd_hist < prev_hist
    macd_weaker_low = macd_hist > prev_hist
    if price_higher_high and macd_weaker_high and macd_hist <= 0:
        return -1, "Divergência MACD: alta perdendo força"
    if price_lower_low and macd_weaker_low and macd_hist >= 0:
        return 1, "Divergência MACD: queda perdendo força"
    return 0, "Divergência MACD: sem divergência clara"


def extract_candle(c: Dict[str, Any]) -> Tuple[int, float]:
    ts = int(c.get("from") or c.get("at") or c.get("id") or 0)
    close = float(c.get("close"))
    return ts, close


def get_closed_candles(candles: List[Dict[str, Any]], tf: int) -> List[Tuple[int, float]]:
    parsed = [extract_candle(c) for c in candles if c.get("close") is not None]
    parsed.sort(key=lambda x: x[0])
    # Evita usar vela em formação quando a API devolver candle atual.
    current_bucket = int(time.time() // tf) * tf
    closed = [(ts, close) for ts, close in parsed if ts < current_bucket]
    return closed if closed else parsed


@dataclass
class SignalDecision:
    direction: Optional[str]
    confidence: int
    reasons: List[str]
    signals: Dict[str, Any]



# ── Precision Engine V93 FAST: OHLC + Multi-timeframe + Entry Quality ─────────────
def _clamp_score(value: Any, low: int = 0, high: int = 100) -> int:
    try:
        return max(low, min(high, int(round(float(value)))))
    except Exception:
        return low


def _candle_ohlc(c: Dict[str, Any]) -> Optional[Dict[str, float]]:
    try:
        ts = int(c.get("from") or c.get("at") or c.get("id") or 0)
        close = float(c.get("close"))
        open_ = float(c.get("open", close) if c.get("open") is not None else close)
        high_raw = c.get("max") if c.get("max") is not None else c.get("high")
        low_raw = c.get("min") if c.get("min") is not None else c.get("low")
        high = float(high_raw if high_raw is not None else max(open_, close))
        low = float(low_raw if low_raw is not None else min(open_, close))
        if high < low:
            high, low = low, high
        return {"ts": ts, "open": open_, "high": high, "low": low, "close": close}
    except Exception:
        return None


def _expected_last_closed_ts(tf: int) -> int:
    tf = max(1, int(tf or 60))
    return int(time.time() // tf) * tf - tf


def _prune_analysis_cache() -> None:
    # Cache é in-memory e pequeno; remove candles antigos sem tocar em config/memórias.
    with LUMI_CACHE_LOCK:
        if len(ANALYSIS_CANDLE_CACHE) > 1400:
            oldest = sorted(ANALYSIS_CANDLE_CACHE.items(), key=lambda kv: float((kv[1] or {}).get("saved_at", 0)))[:350]
            for key, _ in oldest:
                ANALYSIS_CANDLE_CACHE.pop(key, None)
        if len(ANALYSIS_FEATURE_CACHE) > 1400:
            oldest = sorted(ANALYSIS_FEATURE_CACHE.items(), key=lambda kv: float((kv[1] or {}).get("saved_at", 0)))[:350]
            for key, _ in oldest:
                ANALYSIS_FEATURE_CACHE.pop(key, None)


def get_candle_bundle_cached(api: Any, asset: str, tf: int, count: int = 80, force: bool = False) -> Dict[str, Any]:
    """Retorna candles fechados/ohlc usando a vela esperada como chave de cache.

    Não precisa consultar a API só para descobrir se a vela mudou: o bucket temporal
    informa quando o cache deixa de ser válido. Isso reduz bastante chamadas repetidas.
    """
    asset = normalize_asset_name(asset)
    tf = max(1, int(tf or 60))
    expected = _expected_last_closed_ts(tf)
    key = f"{asset}|{tf}|{expected}|{int(count)}"
    use_cache = bool(cfg_get("precision_feature_cache_enabled", True)) and not force
    if use_cache:
        with LUMI_CACHE_LOCK:
            cached = ANALYSIS_CANDLE_CACHE.get(key)
            if cached:
                ANALYSIS_CACHE_STATS["candle_hits"] = int(ANALYSIS_CACHE_STATS.get("candle_hits", 0)) + 1
                out = dict(cached)
                out["cache_hit"] = True
                return out
    ANALYSIS_CACHE_STATS["candle_misses"] = int(ANALYSIS_CACHE_STATS.get("candle_misses", 0)) + 1

    # Cache incremental V94: ao virar apenas uma nova vela, reaproveita as 64 anteriores
    # e pede somente poucas velas recentes. Se a API não trouxer a vela esperada, faz
    # fallback para o carregamento completo para preservar precisão.
    prior: Optional[Dict[str, Any]] = None
    if use_cache:
        with LUMI_CACHE_LOCK:
            candidates = [
                dict(v) for v in ANALYSIS_CANDLE_CACHE.values()
                if isinstance(v, dict)
                and normalize_asset_name(v.get("asset", "")) == asset
                and int(v.get("tf", 0) or 0) == tf
                and len(v.get("closed") or []) >= min(50, int(count))
                and int(v.get("last_candle_ts", 0) or 0) < expected
            ]
        if candidates:
            candidates.sort(key=lambda x: int(x.get("last_candle_ts", 0) or 0), reverse=True)
            maybe = candidates[0]
            gap = expected - int(maybe.get("last_candle_ts", 0) or 0)
            if 0 < gap <= tf * 3:
                prior = maybe

    fetch_count = min(int(count), 4) if prior else int(count)
    candles = _timed_get_candles(api, asset, tf, fetch_count, time.time()) or []
    current_bucket = int(time.time() // tf) * tf
    fresh_ohlc: List[Dict[str, float]] = []
    for raw in candles:
        item = _candle_ohlc(raw) if isinstance(raw, dict) else None
        if item and int(item["ts"]) < current_bucket:
            fresh_ohlc.append(item)
    if not fresh_ohlc:
        for raw in candles:
            item = _candle_ohlc(raw) if isinstance(raw, dict) else None
            if item:
                fresh_ohlc.append(item)
    fresh_ohlc.sort(key=lambda x: int(x["ts"]))

    if prior:
        merged = {int(c.get("ts", 0)): dict(c) for c in list(prior.get("ohlc") or []) if isinstance(c, dict)}
        for item in fresh_ohlc:
            merged[int(item["ts"])] = item
        ohlc = [merged[k] for k in sorted(merged)][-int(count):]
        # Sem a vela fechada esperada, o delta incremental ficou incompleto: recarrega.
        if not ohlc or int(ohlc[-1].get("ts", 0) or 0) < expected:
            candles = _timed_get_candles(api, asset, tf, int(count), time.time()) or []
            ohlc = []
            for raw in candles:
                item = _candle_ohlc(raw) if isinstance(raw, dict) else None
                if item and int(item["ts"]) < current_bucket:
                    ohlc.append(item)
            if not ohlc:
                for raw in candles:
                    item = _candle_ohlc(raw) if isinstance(raw, dict) else None
                    if item:
                        ohlc.append(item)
            ohlc.sort(key=lambda x: int(x["ts"]))
    else:
        ohlc = fresh_ohlc
    closed = [(int(c["ts"]), float(c["close"])) for c in ohlc]
    result = {
        "asset": asset,
        "tf": tf,
        "expected_last_closed_ts": expected,
        "last_candle_ts": int(closed[-1][0]) if closed else 0,
        "closed": closed,
        "ohlc": ohlc,
        "saved_at": time.time(),
        "cache_hit": False,
    }
    if bool(cfg_get("precision_feature_cache_enabled", True)) and closed:
        with LUMI_CACHE_LOCK:
            ANALYSIS_CANDLE_CACHE[key] = dict(result)
        _prune_analysis_cache()
    return result


def _sign_word(value: int) -> str:
    return "bullish" if value > 0 else "bearish" if value < 0 else "neutral"


def _market_structure_from_ohlc(ohlc: List[Dict[str, float]]) -> Tuple[int, str]:
    recent = list(ohlc[-7:])
    if len(recent) < 4:
        return 0, "indefinida"
    hh = sum(1 for i in range(1, len(recent)) if recent[i]["high"] > recent[i-1]["high"])
    hl = sum(1 for i in range(1, len(recent)) if recent[i]["low"] > recent[i-1]["low"])
    lh = sum(1 for i in range(1, len(recent)) if recent[i]["high"] < recent[i-1]["high"])
    ll = sum(1 for i in range(1, len(recent)) if recent[i]["low"] < recent[i-1]["low"])
    threshold = max(2, (len(recent) - 1) // 2)
    if hh >= threshold and hl >= threshold:
        return 1, "higher_highs_higher_lows"
    if lh >= threshold and ll >= threshold:
        return -1, "lower_highs_lower_lows"
    return 0, "mista/lateral"


def _price_action_from_ohlc(ohlc: List[Dict[str, float]]) -> Tuple[int, str]:
    if len(ohlc) < 2:
        return 0, "indefinido"
    prev, last = ohlc[-2], ohlc[-1]
    po, pc = prev["open"], prev["close"]
    o, h, l, c = last["open"], last["high"], last["low"], last["close"]
    body = max(abs(c - o), max(abs(c), 1e-9) * 1e-7)
    upper = max(0.0, h - max(o, c))
    lower = max(0.0, min(o, c) - l)
    bullish_engulf = c > o and pc < po and c >= po and o <= pc
    bearish_engulf = c < o and pc > po and c <= po and o >= pc
    if bullish_engulf:
        return 1, "bullish_engulfing"
    if bearish_engulf:
        return -1, "bearish_engulfing"
    if lower >= body * 1.6 and c >= o:
        return 1, "bullish_rejection"
    if upper >= body * 1.6 and c <= o:
        return -1, "bearish_rejection"
    if c > o and pc > po:
        return 1, "bullish_continuation"
    if c < o and pc < po:
        return -1, "bearish_continuation"
    return 0, "neutral"


def _atr_percent(ohlc: List[Dict[str, float]], period: int = 14) -> float:
    if len(ohlc) < 2:
        return 0.0
    trs: List[float] = []
    start = max(1, len(ohlc) - max(2, int(period)))
    for i in range(start, len(ohlc)):
        cur, prev = ohlc[i], ohlc[i-1]
        tr = max(cur["high"] - cur["low"], abs(cur["high"] - prev["close"]), abs(cur["low"] - prev["close"]))
        trs.append(max(0.0, tr))
    close = max(abs(float(ohlc[-1]["close"])), 1e-9)
    return round((sum(trs) / max(1, len(trs))) / close * 100.0, 4)




def _ci_safe_float(value: Any, default: float = 0.0) -> float:
    try:
        v = float(value)
        if math.isnan(v) or math.isinf(v):
            return default
        return v
    except Exception:
        return default


def _ci_band(score: Any) -> str:
    n = _ci_safe_float(score, 50.0)
    if n < 35: return "muito_fraco"
    if n < 50: return "fraco"
    if n < 65: return "neutro"
    if n < 78: return "forte"
    return "elite"


def _ci_distance_band(value: Any) -> str:
    n = max(0.0, _ci_safe_float(value, 99.0))
    if n < 0.20: return "colado"
    if n < 0.50: return "perto"
    if n < 1.00: return "moderado"
    if n < 2.00: return "livre"
    return "distante"


def build_candle_intelligence(ohlc: List[Dict[str, float]], signals: Optional[Dict[str, Any]] = None, direction: Optional[str] = None) -> Dict[str, Any]:
    """V108: fotografia matemática do price action sem nova chamada à corretora.

    Usa apenas o OHLC já existente no rolling cache. O score mede qualidade do
    contexto para a direção indicada; não substitui o piso técnico nem a Lumi.
    """
    if not bool(cfg_get("candle_intelligence_enabled", True)):
        return {"enabled": False, "score": 50, "risk": 50, "label": "desativado", "guard_block": False}
    window = max(16, min(80, int(cfg_get("candle_intelligence_window", 30) or 30)))
    seq = [dict(c) for c in (ohlc or []) if isinstance(c, dict)][-max(window, 24):]
    if len(seq) < 12:
        return {"enabled": True, "score": 50, "risk": 50, "label": "dados_insuficientes", "guard_block": False, "samples": len(seq)}
    sig = signals or {}
    d = normalize_lumi_action(direction or "hold")
    dsign = 1 if d == "call" else -1 if d == "put" else 0
    last = seq[-1]; prev = seq[-2]
    close = _ci_safe_float(last.get("close"), 0.0)
    rng = max(1e-12, _ci_safe_float(last.get("high")) - _ci_safe_float(last.get("low")))
    body = abs(_ci_safe_float(last.get("close")) - _ci_safe_float(last.get("open")))
    upper = max(0.0, _ci_safe_float(last.get("high")) - max(_ci_safe_float(last.get("open")), _ci_safe_float(last.get("close"))))
    lower = max(0.0, min(_ci_safe_float(last.get("open")), _ci_safe_float(last.get("close"))) - _ci_safe_float(last.get("low")))
    body_ratio = body / rng
    upper_wick_ratio = upper / rng
    lower_wick_ratio = lower / rng
    close_position = (_ci_safe_float(last.get("close")) - _ci_safe_float(last.get("low"))) / rng

    # ATR absoluto e estrutura recente.
    trs=[]
    for i in range(max(1, len(seq)-14), len(seq)):
        cur, p = seq[i], seq[i-1]
        tr=max(_ci_safe_float(cur.get("high"))-_ci_safe_float(cur.get("low")), abs(_ci_safe_float(cur.get("high"))-_ci_safe_float(p.get("close"))), abs(_ci_safe_float(cur.get("low"))-_ci_safe_float(p.get("close"))))
        trs.append(max(0.0,tr))
    atr=sum(trs)/max(1,len(trs))
    atr_pct=(atr/max(abs(close),1e-9))*100.0
    last_range_atr=rng/max(atr,1e-12)
    body_atr=body/max(atr,1e-12)

    recent=seq[-8:]
    bullish=sum(1 for c in recent if _ci_safe_float(c.get("close")) > _ci_safe_float(c.get("open")))
    bearish=sum(1 for c in recent if _ci_safe_float(c.get("close")) < _ci_safe_float(c.get("open")))
    recent_closes=[_ci_safe_float(c.get("close")) for c in seq[-12:]]
    deltas=[recent_closes[i]-recent_closes[i-1] for i in range(1,len(recent_closes))]
    path=sum(abs(x) for x in deltas) or 1e-12
    net=recent_closes[-1]-recent_closes[0]
    efficiency=min(1.0,abs(net)/path)
    trend_sign=1 if net>0 else -1 if net<0 else 0
    structure_sign, structure=_market_structure_from_ohlc(seq)
    pa_sign, price_action=_price_action_from_ohlc(seq)

    impulse_raw=sum(deltas[-3:]) / max(atr,1e-12) if deltas else 0.0
    impulse=max(-3.0,min(3.0,impulse_raw))
    impulse_sign=1 if impulse>0.15 else -1 if impulse<-0.15 else 0

    zone=seq[-21:-1] if len(seq)>=21 else seq[:-1]
    if not zone: zone=seq[-12:-1]
    support=min(_ci_safe_float(c.get("low")) for c in zone)
    resistance=max(_ci_safe_float(c.get("high")) for c in zone)
    support_dist_atr=max(0.0,(close-support)/max(atr,1e-12))
    resistance_dist_atr=max(0.0,(resistance-close)/max(atr,1e-12))

    prev_close=_ci_safe_float(prev.get("close"))
    bull_break=close>resistance and prev_close<=resistance
    bear_break=close<support and prev_close>=support
    bull_wick_break=_ci_safe_float(last.get("high"))>resistance and close<=resistance
    bear_wick_break=_ci_safe_float(last.get("low"))<support and close>=support
    breakout="bullish" if bull_break else "bearish" if bear_break else "none"
    breakout_confirmed=bool((bull_break and body_ratio>=0.52 and close_position>=0.70 and impulse_sign>=0 and last_range_atr>=0.75) or (bear_break and body_ratio>=0.52 and close_position<=0.30 and impulse_sign<=0 and last_range_atr>=0.75))
    false_breakout_risk=0.0
    if bull_wick_break or bear_wick_break:
        false_breakout_risk=82.0
    elif (bull_break or bear_break) and not breakout_confirmed:
        false_breakout_risk=62.0
    elif body_ratio<0.25 and (upper_wick_ratio>0.45 or lower_wick_ratio>0.45):
        false_breakout_risk=48.0
    else:
        false_breakout_risk=18.0

    bullish_rejection=min(100.0, lower_wick_ratio*145.0 + (20 if close_position>0.65 else 0))
    bearish_rejection=min(100.0, upper_wick_ratio*145.0 + (20 if close_position<0.35 else 0))
    bb=_ci_safe_float(sig.get("bb_pct"),50.0)

    # V108.1: confiança específica de Price Action para a direção analisada.
    # É uma medida estrutural 0–100 e não substitui técnica/Lumi.
    pa_score=50.0
    if dsign:
        if pa_sign==dsign: pa_score+=22
        elif pa_sign==-dsign: pa_score-=22
        if impulse_sign==dsign: pa_score+=10
        elif impulse_sign==-dsign: pa_score-=10
        if trend_sign==dsign: pa_score+=6*max(0.35,efficiency)
        elif trend_sign==-dsign: pa_score-=6*max(0.35,efficiency)
        if 0.48<=body_ratio<=0.90: pa_score+=6
        if dsign>0 and bearish_rejection>=65: pa_score-=10
        if dsign<0 and bullish_rejection>=65: pa_score-=10
        if breakout_confirmed and ((dsign>0 and bull_break) or (dsign<0 and bear_break)): pa_score+=8
        if (dsign>0 and bull_wick_break) or (dsign<0 and bear_wick_break): pa_score-=12
    pa_score=max(0.0,min(100.0,pa_score))

    # Score direcional: começa neutro e só ganha pontos com confluência real.
    score=50.0
    reasons=[]; risks=[]
    if dsign:
        if trend_sign==dsign: score+=8*efficiency+4; reasons.append("tendência recente alinhada")
        elif trend_sign==-dsign: score-=10*max(0.35,efficiency); risks.append("tendência recente contrária")
        if structure_sign==dsign: score+=8; reasons.append("estrutura HH/HL ou LH/LL alinhada")
        elif structure_sign==-dsign: score-=9; risks.append("estrutura de preço contrária")
        if impulse_sign==dsign: score+=min(10.0,4+abs(impulse)*2.0); reasons.append("impulso alinhado")
        elif impulse_sign==-dsign: score-=min(12.0,5+abs(impulse)*2.0); risks.append("impulso contrário")
        if pa_sign==dsign: score+=7; reasons.append(price_action)
        elif pa_sign==-dsign: score-=9; risks.append("price action contrário")
        if breakout_confirmed and ((dsign>0 and bull_break) or (dsign<0 and bear_break)):
            score+=12; reasons.append("breakout confirmado")
        elif (dsign>0 and bull_wick_break) or (dsign<0 and bear_wick_break):
            score-=16; risks.append("falso rompimento/rejeição")
        barrier = resistance_dist_atr if dsign>0 else support_dist_atr
        near_limit=max(0.05,_ci_safe_float(cfg_get("candle_intelligence_near_barrier_atr",0.18),0.18))
        if barrier < near_limit and not breakout_confirmed:
            score-=18; risks.append(f"barreira contrária a {barrier:.2f} ATR")
        elif barrier < 0.50 and not breakout_confirmed:
            score-=9; risks.append(f"barreira próxima {barrier:.2f} ATR")
        elif barrier >= 1.0:
            score+=4; reasons.append("espaço livre até barreira")
        if dsign>0 and bearish_rejection>=65: score-=8; risks.append("rejeição vendedora forte")
        if dsign<0 and bullish_rejection>=65: score-=8; risks.append("rejeição compradora forte")
        if 0.48<=body_ratio<=0.90: score+=4; reasons.append("corpo de candle saudável")
        if dsign>0 and bb>=95 and not breakout_confirmed: score-=10; risks.append("CALL esticado no topo da Bollinger")
        if dsign<0 and bb<=5 and not breakout_confirmed: score-=10; risks.append("PUT esticado no fundo da Bollinger")
        score-=max(0.0,(false_breakout_risk-50.0)*0.18)
    score=max(0.0,min(100.0,score))
    risk=max(0.0,min(100.0,100.0-score + max(0.0,false_breakout_risk-45.0)*0.28))
    label="elite" if score>=78 else "forte" if score>=65 else "neutro" if score>=50 else "fraco" if score>=35 else "muito_fraco"
    barrier_atr = resistance_dist_atr if dsign>0 else support_dist_atr if dsign<0 else min(support_dist_atr,resistance_dist_atr)
    return {
        "enabled": True, "samples": len(seq), "direction": d, "score": int(round(score)), "risk": int(round(risk)), "label": label,
        "body_ratio": round(body_ratio,3), "upper_wick_ratio": round(upper_wick_ratio,3), "lower_wick_ratio": round(lower_wick_ratio,3), "close_position": round(close_position,3),
        "atr_pct": round(atr_pct,4), "last_range_atr": round(last_range_atr,3), "body_atr": round(body_atr,3),
        "bullish_8": bullish, "bearish_8": bearish, "trend_efficiency": round(efficiency,3), "trend_sign": trend_sign,
        "structure": structure, "structure_sign": structure_sign, "price_action": price_action, "price_action_sign": pa_sign, "price_action_score": int(round(pa_score)),
        "impulse_atr": round(impulse,3), "impulse_sign": impulse_sign,
        "support": round(support,8), "resistance": round(resistance,8), "support_distance_atr": round(support_dist_atr,3), "resistance_distance_atr": round(resistance_dist_atr,3), "barrier_distance_atr": round(barrier_atr,3),
        "breakout": breakout, "breakout_confirmed": breakout_confirmed, "false_breakout_risk": int(round(false_breakout_risk)),
        "bullish_rejection": int(round(bullish_rejection)), "bearish_rejection": int(round(bearish_rejection)),
        "reasons": reasons[:6], "risks": risks[:6], "last_ts": int(last.get("ts",0) or 0),
    }


def candle_intelligence_guard_reason(row: Dict[str, Any]) -> Tuple[bool, str]:
    ci=row.get("candle_intelligence") if isinstance(row.get("candle_intelligence"),dict) else {}
    if not ci or not ci.get("enabled") or normalize_lumi_action(row.get("direction") or "hold") not in VALID_DIRECTIONS:
        return False, "Candle Intelligence sem direção/dados suficientes"
    score=int(ci.get("score",50) or 50); fake=int(ci.get("false_breakout_risk",0) or 0)
    barrier=_ci_safe_float(ci.get("barrier_distance_atr"),99.0)
    min_score=int(cfg_get("candle_intelligence_real_min_score",42) or 42)
    max_fake=int(cfg_get("candle_intelligence_max_fakeout_risk",72) or 72)
    near=max(0.05,_ci_safe_float(cfg_get("candle_intelligence_near_barrier_atr",0.18),0.18))
    hard = score < min_score or fake >= max_fake or (barrier < near and not bool(ci.get("breakout_confirmed")))
    reason=f"Candle Score {score}% · risco {int(ci.get('risk',0) or 0)}% · fakeout {fake}% · barreira {barrier:.2f} ATR"
    if str(cfg_get("account_type","PRACTICE")).upper() == "REAL" and bool(cfg_get("candle_intelligence_real_guard_enabled",True)) and hard:
        return True, reason
    return False, reason


def timeframe_feature_summary(api: Any, asset: str, tf: int) -> Optional[Dict[str, Any]]:
    """Resume um timeframe em poucos campos. A Lumi recebe o resumo, não candles crus."""
    asset = normalize_asset_name(asset)
    tf = max(1, int(tf or 60))
    expected = _expected_last_closed_ts(tf)
    key = f"{asset}|{tf}|{expected}"
    if bool(cfg_get("precision_feature_cache_enabled", True)):
        with LUMI_CACHE_LOCK:
            cached = ANALYSIS_FEATURE_CACHE.get(key)
            if cached:
                ANALYSIS_CACHE_STATS["feature_hits"] = int(ANALYSIS_CACHE_STATS.get("feature_hits", 0)) + 1
                return dict(cached.get("value") or {})
    ANALYSIS_CACHE_STATS["feature_misses"] = int(ANALYSIS_CACHE_STATS.get("feature_misses", 0)) + 1
    bundle = get_candle_bundle_cached(api, asset, tf, 64)
    closed = list(bundle.get("closed") or [])
    ohlc = list(bundle.get("ohlc") or [])
    if len(closed) < 50 or len(ohlc) < 10:
        return None
    closes = [float(v) for _, v in closed]
    dec = analyze_closes(closes, "combined")
    s = dec.signals or {}
    structure_sign, structure = _market_structure_from_ohlc(ohlc)
    pa_sign, price_action = _price_action_from_ohlc(ohlc)
    trend_sign = int(s.get("trend_vote", 0) or 0)
    momentum_sign = int(s.get("momentum_vote", 0) or 0)
    breakout_sign = int(s.get("breakout_vote", 0) or s.get("breakout_consolidation_vote", 0) or 0)
    macd_sign = 1 if float(s.get("macd_hist", 0) or 0) > 0 else (-1 if float(s.get("macd_hist", 0) or 0) < 0 else 0)
    # Bias -1..+1. Estrutura/tendência pesam mais que osciladores.
    weighted = [(trend_sign, 3), (structure_sign, 3), (momentum_sign, 2), (macd_sign, 2), (pa_sign, 1), (breakout_sign, 1)]
    bias = sum(v * w for v, w in weighted) / max(1, sum(w for _v, w in weighted))
    recent_zone = ohlc[-21:-1] if len(ohlc) >= 21 else ohlc[:-1]
    if not recent_zone:
        recent_zone = ohlc[-20:]
    close_now = float(ohlc[-1]["close"])
    support = min(float(c["low"]) for c in recent_zone)
    resistance = max(float(c["high"]) for c in recent_zone)
    support_dist = max(0.0, (close_now - support) / max(abs(close_now), 1e-9) * 100.0)
    resistance_dist = max(0.0, (resistance - close_now) / max(abs(close_now), 1e-9) * 100.0)
    summary = {
        "tf": tf,
        "last_ts": int(closed[-1][0]),
        "trend": _sign_word(trend_sign),
        "structure": structure,
        "structure_sign": structure_sign,
        "momentum": _sign_word(momentum_sign),
        "price_action": price_action,
        "price_action_sign": pa_sign,
        "breakout": _sign_word(breakout_sign),
        "breakout_sign": breakout_sign,
        "bias": round(float(bias), 3),
        "rsi": round(float(s.get("rsi", 50) or 50), 1),
        "macd_hist": round(float(s.get("macd_hist", 0) or 0), 6),
        "bb_pct": round(float(s.get("bb_pct", 50) or 50), 1),
        "bb_width": round(float(s.get("bb_width", 0) or 0), 4),
        "atr_pct": _atr_percent(ohlc),
        "support_distance_pct": round(support_dist, 3),
        "resistance_distance_pct": round(resistance_dist, 3),
    }
    if bool(cfg_get("precision_feature_cache_enabled", True)):
        with LUMI_CACHE_LOCK:
            ANALYSIS_FEATURE_CACHE[key] = {"saved_at": time.time(), "value": dict(summary)}
        _prune_analysis_cache()
    return summary


def _direction_sign(direction: Any) -> int:
    d = normalize_lumi_action(direction)
    return 1 if d == "call" else -1 if d == "put" else 0


def enrich_row_precision(api: Any, row: Dict[str, Any]) -> Dict[str, Any]:
    """Acrescenta M1/M5/M15, Signal Score e Entry Score sem mudar o score técnico original."""
    if not bool(cfg_get("precision_engine_enabled", True)):
        row["signal_score"] = int(row.get("technical_confidence", 0) or 0)
        row["entry_score"] = int(row.get("technical_confidence", 0) or 0)
        row["precision_status"] = "disabled"
        return row
    asset = normalize_asset_name(row.get("asset", ""))
    dsign = _direction_sign(row.get("direction"))
    tech = _clamp_score(row.get("technical_confidence", 0))
    adaptive = _clamp_score(row.get("adaptive_score", tech))
    mtf: Dict[str, Any] = {}
    if bool(cfg_get("precision_multi_timeframe_enabled", True)):
        for label, tfv in (("m1", 60), ("m5", 300), ("m15", 900)):
            try:
                summary = timeframe_feature_summary(api, asset, tfv)
                if summary:
                    mtf[label] = summary
            except Exception:
                continue
    weights = {"m1": 0.25, "m5": 0.45, "m15": 0.30}
    align_sum = 0.0
    weight_sum = 0.0
    for label, weight in weights.items():
        info = mtf.get(label) or {}
        if info:
            bias = max(-1.0, min(1.0, float(info.get("bias", 0) or 0)))
            align = (1.0 + (dsign * bias)) * 50.0 if dsign else 50.0
            align_sum += align * weight
            weight_sum += weight
    mtf_alignment = round(align_sum / weight_sum, 1) if weight_sum else 50.0
    signal_score = _clamp_score((tech * 0.52) + (mtf_alignment * 0.33) + (adaptive * 0.15))

    # Entry Score mede o MOMENTO, separado da qualidade da direção.
    entry = 50.0
    for label, mult in (("m1", 16.0), ("m5", 13.0), ("m15", 7.0)):
        info = mtf.get(label) or {}
        if info:
            entry += dsign * float(info.get("bias", 0) or 0) * mult
    m5 = mtf.get("m5") or mtf.get("m1") or {}
    pa_sign = int(m5.get("price_action_sign", 0) or 0)
    breakout_sign = int(m5.get("breakout_sign", 0) or 0)
    if dsign and pa_sign == dsign:
        entry += 8
    elif dsign and pa_sign == -dsign:
        entry -= 11
    if dsign and breakout_sign == dsign:
        entry += 7
    elif dsign and breakout_sign == -dsign:
        entry -= 8
    # Extremos: direção pode estar correta, mas o ponto de entrada pode estar esticado.
    bb = float((row.get("signals") or {}).get("bb_pct", m5.get("bb_pct", 50)) or 50)
    if dsign > 0 and bb >= 97:
        entry += 4 if breakout_sign > 0 else -20
    elif dsign < 0 and bb <= 3:
        entry += 4 if breakout_sign < 0 else -20
    # Proximidade de barreira contrária reduz a qualidade da entrada.
    if dsign > 0 and m5 and float(m5.get("resistance_distance_pct", 99) or 99) < 0.08:
        entry -= 9
    if dsign < 0 and m5 and float(m5.get("support_distance_pct", 99) or 99) < 0.08:
        entry -= 9
    atr = float(m5.get("atr_pct", 0) or 0) if m5 else 0.0
    if atr and atr < 0.01:
        entry -= 8
    elif atr >= 0.02:
        entry += 3
    ci = row.get("candle_intelligence") if isinstance(row.get("candle_intelligence"), dict) else {}
    candle_score = int(ci.get("score", row.get("candle_score", 50)) or 50)
    ci_weight = max(0.05, min(0.40, float(cfg_get("candle_intelligence_weight", 0.24) or 0.24)))
    entry = entry * (1.0 - ci_weight) + candle_score * ci_weight
    entry_score = _clamp_score(entry)

    m5_bias = float((mtf.get("m5") or {}).get("bias", 0) or 0)
    m15_bias = float((mtf.get("m15") or {}).get("bias", 0) or 0)
    hard_conflict = bool(dsign and mtf.get("m5") and mtf.get("m15") and (dsign * m5_bias <= -0.25) and (dsign * m15_bias <= -0.25))
    payout = int(row.get("payout", 0) or 0)
    payout_quality = _clamp_score((payout - 60) * 2.5) if payout else 50
    priority = _clamp_score(signal_score * 0.50 + entry_score * 0.35 + adaptive * 0.10 + payout_quality * 0.05)

    row["mtf"] = mtf
    row["mtf_alignment"] = mtf_alignment
    row["signal_score"] = signal_score
    row["entry_score"] = entry_score
    row["decision_priority_score"] = priority
    row["precision_status"] = "ok" if mtf else "partial"
    row["mtf_hard_conflict"] = hard_conflict
    row["entry_quality_label"] = "forte" if entry_score >= 70 else "boa" if entry_score >= 58 else "limítrofe" if entry_score >= 45 else "ruim"
    # Recalibra usando os scores MTF/Entry recém-calculados. O ajuste anterior foi
    # produzido antes do Precision Engine e é substituído sem somar duas vezes o histórico.
    previous_calibration_adj = float((row.get("calibration") or {}).get("adjustment", 0) or 0)
    refined_calibration = adaptive_calibration_for_row(row)
    row["calibration"] = refined_calibration
    refined_delta = float(refined_calibration.get("adjustment", 0) or 0) - previous_calibration_adj
    row["adaptive_score"] = _clamp_score(float(row.get("adaptive_score", adaptive) or adaptive) + refined_delta)
    adaptive = _clamp_score(row.get("adaptive_score", adaptive))
    priority = _clamp_score(signal_score * 0.50 + entry_score * 0.35 + adaptive * 0.10 + payout_quality * 0.05)
    row["decision_priority_score"] = priority
    compute_opportunity_quality(row, row.get("lumi") if isinstance(row.get("lumi"), dict) else None)
    row["precision_summary"] = {
        "signal_score": signal_score,
        "entry_score": entry_score,
        "mtf_alignment": mtf_alignment,
        "candle_score": candle_score,
        "candle_intelligence": {k: ci.get(k) for k in ("score","risk","label","price_action","structure","impulse_atr","support_distance_atr","resistance_distance_atr","breakout","breakout_confirmed","false_breakout_risk")},
        "m1": {k: (mtf.get("m1") or {}).get(k) for k in ("last_ts", "trend", "structure", "momentum", "price_action", "breakout", "rsi", "bb_pct", "atr_pct")},
        "m5": {k: (mtf.get("m5") or {}).get(k) for k in ("last_ts", "trend", "structure", "momentum", "price_action", "breakout", "rsi", "bb_pct", "atr_pct", "support_distance_pct", "resistance_distance_pct")},
        "m15": {k: (mtf.get("m15") or {}).get(k) for k in ("last_ts", "trend", "structure", "momentum")},
    }
    return row


def precision_early_filter(row: Dict[str, Any], min_tech: int) -> Tuple[bool, str]:
    if not bool(cfg_get("precision_engine_enabled", True)):
        return True, "Precision Engine desativado"
    tech = int(row.get("technical_confidence", 0) or 0)
    entry = int(row.get("entry_score", tech) or tech)
    if bool(cfg_get("precision_hard_mtf_filter", True)) and bool(row.get("mtf_hard_conflict")):
        return False, f"MTF contrário: M5 e M15 conflitam com {str(row.get('direction') or '').upper()}"
    floor = int(cfg_get("precision_borderline_entry_floor", 55) or 55) if tech < int(min_tech) else int(cfg_get("precision_entry_score_floor", 40) or 40)
    if entry < floor:
        return False, f"Entry Score {entry}% < piso {floor}%"
    return True, f"Signal {int(row.get('signal_score',tech) or tech)}% · Entry {entry}% · MTF {float(row.get('mtf_alignment',50) or 50):.0f}%"


# ── Integração Lumi IA ────────────────────────────────────
def normalize_lumi_action(value: Any) -> str:
    text = str(value or "").strip().lower()
    mapping = {
        "call": "call", "compra": "call", "comprar": "call", "buy": "call", "alta": "call", "subir": "call",
        "put": "put", "venda": "put", "vender": "put", "sell": "put", "baixa": "put", "descer": "put",
        "hold": "hold", "aguardar": "hold", "neutro": "hold", "none": "hold", "esperar": "hold",
    }
    return mapping.get(text, "hold")


def compact_candles(closed: List[Tuple[int, float]], limit: int = 8) -> List[float]:
    """Mantém apenas os últimos fechamentos para a IA local responder rápido."""
    return [round(float(close), 6) for _ts, close in closed[-limit:]]


def _safe_float_dict(src: Dict[str, Any], key: str, default: float = 0.0, ndigits: int = 6) -> float:
    try:
        return round(float(src.get(key, default) or default), ndigits)
    except Exception:
        return round(float(default), ndigits)


def _safe_int_dict(src: Dict[str, Any], key: str, default: int = 0) -> int:
    try:
        return int(float(src.get(key, default) or default))
    except Exception:
        return int(default)


def _lumi_dir_code(value: Any) -> str:
    action = normalize_lumi_action(value)
    return "c" if action == "call" else "p" if action == "put" else "h"


def _lumi_sign_code(value: Any, deadband: float = 0.0) -> str:
    try:
        n = float(value or 0)
    except Exception:
        n = 0.0
    return "u" if n > deadband else "d" if n < -deadband else "n"


def _lumi_mtf_dir(info: Any) -> str:
    if not isinstance(info, dict):
        return "n"
    for key in ("trend", "structure", "momentum", "price_action", "breakout"):
        text = str(info.get(key) or "").strip().lower()
        if any(x in text for x in ("bull", "alta", "up")):
            return "u"
        if any(x in text for x in ("bear", "baixa", "down")):
            return "d"
    try:
        bias = float(info.get("bias", 0) or 0)
        return "u" if bias > 0.12 else "d" if bias < -0.12 else "n"
    except Exception:
        return "n"


def build_lumi_prompt(asset: str, timeframe: int, closed: List[Tuple[int, float]], technical: Dict[str, Any]) -> str:
    """V108.3: contexto Ultra-Fast mínimo para reduzir prompt_eval e geração.

    A Lumi recebe somente os fatores que mudam a decisão. As regras permanentes,
    o protocolo compacto e os códigos de saída vivem no Modelfile.
    """
    tech = _safe_int_dict(technical, "confidence", 0)
    mtf = technical.get("mtf_compact") if isinstance(technical.get("mtf_compact"), dict) else {}
    m5 = mtf.get("m5") if isinstance(mtf.get("m5"), dict) else {}
    m15 = mtf.get("m15") if isinstance(mtf.get("m15"), dict) else {}
    breakout_state = str(technical.get("breakout_state") or technical.get("candle_breakout") or "").strip().lower()
    if not breakout_state:
        ci = technical.get("candle_intelligence") if isinstance(technical.get("candle_intelligence"), dict) else {}
        breakout_state = str(ci.get("breakout") or "none").strip().lower()
    breakout_code = "u" if "bull" in breakout_state else "d" if "bear" in breakout_state else "n"
    if not bool(technical.get("breakout_confirmed", False)):
        breakout_code = "n"

    calibration = technical.get("calibration_compact") if isinstance(technical.get("calibration_compact"), dict) else {}
    payload = {
        "v": 1,
        "a": str(asset)[:24],
        "tf": max(1, int((timeframe or 300) // 60)),
        "q": _lumi_dir_code(technical.get("direction") or technical.get("signal") or technical.get("action")),
        "t": tech,
        "cs": _safe_int_dict(technical, "candle_score", 50),
        "pa": _safe_int_dict(technical, "price_action_score", 50),
        "mt": int(round(_safe_float_dict(technical, "mtf_alignment", 50, 1))),
        "fo": _safe_int_dict(technical, "false_breakout_risk", 0),
        "ba": _safe_float_dict(technical, "barrier_distance_atr", 0, 2),
        "bo": breakout_code,
        "rsi": int(round(_safe_float_dict(technical, "rsi", 50, 1))),
        "mc": _lumi_sign_code(technical.get("macd_hist", 0), 0.0),
        "mo": _lumi_sign_code(technical.get("momentum_vote", 0), 0.0),
        "m5": _lumi_mtf_dir(m5),
        "m15": _lumi_mtf_dir(m15),
        "po": _safe_int_dict(technical, "payout", int(cfg_get("payout", 0) or 0)),
        "en": _safe_int_dict(technical, "entry_score", tech),
        "sg": _safe_int_dict(technical, "signal_score", tech),
    }
    # Apenas dois números de memória: edge e amostra. O REAL continua protegido
    # por guardrails fora da IA, portanto não enviamos o dataset inteiro.
    try:
        if calibration:
            payload["ed"] = round(float(calibration.get("edge", calibration.get("edge_pp", 0)) or 0), 1)
            payload["n"] = int(calibration.get("n", 0) or 0)
    except Exception:
        pass
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":"))


def extract_json_object_from_text(text: str) -> Optional[Dict[str, Any]]:
    """Extrai o primeiro objeto JSON de uma resposta textual da IA.

    A api_lumi_iq.php pode devolver {tipo:texto,resposta:"..."} quando o
    Gemini coloca explicação antes/depois do JSON. Esta rotina evita perder
    uma análise boa só por causa de markdown ou texto extra.
    """
    cleaned = (text or "").strip().replace("```json", "").replace("```js", "").replace("```", "").strip()
    if not cleaned:
        return None
    try:
        obj = json.loads(cleaned)
        return obj if isinstance(obj, dict) else None
    except Exception:
        pass

    start = cleaned.find("{")
    while start != -1:
        depth = 0
        in_string = False
        escape = False
        for i in range(start, len(cleaned)):
            ch = cleaned[i]
            if escape:
                escape = False
                continue
            if ch == "\\":
                escape = True
                continue
            if ch == '"':
                in_string = not in_string
                continue
            if in_string:
                continue
            if ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    candidate = cleaned[start:i+1]
                    try:
                        obj = json.loads(candidate)
                        if isinstance(obj, dict):
                            return obj
                    except Exception:
                        break
        start = cleaned.find("{", start + 1)
    return None


def infer_lumi_from_text(text: str) -> Optional[Dict[str, Any]]:
    """Fallback de leitura quando a IA responde em texto em vez de JSON.

    Só aprova CALL/PUT se a palavra aparecer de forma clara. Caso contrário,
    devolve HOLD, mantendo o bot conservador.
    """
    t = (text or "").strip()
    low = t.lower()
    if not low:
        return None

    action = "hold"
    if any(k in low for k in ["call", "compra", "comprar", "alta", "subida", "buy"]):
        action = "call"
    if any(k in low for k in ["put", "venda", "vender", "baixa", "queda", "sell"]):
        # Se texto citar compra e venda ao mesmo tempo, segura em HOLD.
        if action == "call":
            action = "hold"
        else:
            action = "put"

    # Tenta capturar confiança escrita como 70% ou confidence:70.
    confidence = 0
    import re
    m = re.search(r"(?:confian[cç]a|confidence)\D{0,12}(\d{1,3})", low) or re.search(r"(\d{1,3})\s*%", low)
    if m:
        confidence = max(0, min(100, int(m.group(1))))
    elif action in {"call", "put"}:
        confidence = 55

    return {
        "action": action,
        "confidence": confidence,
        "confidence_exact": round(float(confidence_exact), 2),
        "reason": t[:220],
        "market_condition": "texto_livre",
    }


_LUMI_PLACEHOLDER_REASONS = {
    "motivo técnico concreto",
    "motivo tecnico concreto",
    "bloquear com motivo técnico concreto",
    "bloquear com motivo tecnico concreto",
    "motivo concreto",
    "razão técnica concreta",
    "razao tecnica concreta",
    "motivo curto e agressivo",
    "motivo do ajuste ou manter configuração",
    "motivo do ajuste ou manter configuracao",
    "manter configuração atual",
    "manter configuracao atual",
    "sem motivo informado",
}

def _normalize_reason_key(value: Any) -> str:
    value = str(value or "").strip().lower()
    value = re.sub(r"^[\s\-–—:;]+|[\s\-–—:;.!?]+$", "", value)
    value = re.sub(r"\s+", " ", value)
    return value

def is_lumi_placeholder_reason(value: Any) -> bool:
    key = _normalize_reason_key(value)
    if not key:
        return True
    if key in _LUMI_PLACEHOLDER_REASONS:
        return True
    if re.fullmatch(r"(?:bloquear\s+com\s+)?motivo(?:\s+t[eé]cnico)?(?:\s+concreto)?", key):
        return True
    if re.fullmatch(r"resumo operacional(?: estilo wall street)?(?:\s*\(\s*1(?:\s*[-–]\s*2)?\s*frases?\s*\))?", key):
        return True
    if re.fullmatch(r"resumo do racioc[ií]nio operacional(?: em at[eé] \d+ caracteres)?", key):
        return True
    return False

def _extract_lumi_reason_value(value: Any) -> str:
    """Extrai somente o campo reason, mesmo quando o modelo o devolve como JSON aninhado/string."""
    if isinstance(value, dict):
        nested = value.get("reason") or value.get("motivo") or value.get("justificativa")
        if nested is not None and nested is not value:
            return _extract_lumi_reason_value(nested)
        return ""
    if isinstance(value, (list, tuple)):
        return " ".join(str(x) for x in value if str(x).strip())
    text = str(value or "").strip()
    if not text:
        return ""
    text = re.sub(r"^```(?:json)?\s*|\s*```$", "", text, flags=re.I | re.S).strip()
    # Se o próprio reason veio contendo o JSON inteiro, extrai o campo interno.
    if "{" in text and "}" in text:
        obj = extract_json_object_from_text(text)
        if isinstance(obj, dict):
            nested = obj.get("reason") or obj.get("motivo") or obj.get("justificativa")
            if nested is not None and str(nested).strip() != text:
                return _extract_lumi_reason_value(nested)
    # V100: também trata JSON truncado/incompleto. O Qwen pode encerrar a geração
    # depois do reason e antes de fechar a chave; não mostramos o JSON bruto no painel.
    if "{" in text or re.search(r'"(?:reason|motivo|justificativa)"\s*:', text, flags=re.I):
        m = re.search(r'"(?:reason|motivo|justificativa)"\s*:\s*"((?:\\.|[^"\r\n])*)', text, flags=re.I)
        if m:
            candidate = m.group(1).replace('\\"', '"').replace('\\n', ' ').strip()
            if candidate:
                return candidate
        # Nunca deixa um objeto JSON bruto virar reason.
        return ""
    return text

def clean_lumi_reason(value: Any, action: str = "hold", focus: Optional[List[str]] = None, condition: str = "") -> str:
    reason = _extract_lumi_reason_value(value).strip()
    # Remove prefixos do prompt que às vezes vazam na resposta, preservando o conteúdo técnico real.
    reason = re.sub(r"^(?:motivo\s+agressivo|motivo\s+t[eé]cnico|motivo)\s*:\s*", "", reason, flags=re.I).strip()
    if reason and not is_lumi_placeholder_reason(reason):
        return reason[:220]

    factors = [str(x).strip() for x in (focus or []) if str(x).strip()]
    factors = [x for x in factors if not is_lumi_placeholder_reason(x)][:4]
    action_txt = normalize_lumi_action(action).upper()
    if factors:
        return f"{action_txt}: fatores objetivos observados: {', '.join(factors)}."[:220]
    if condition and str(condition).strip().lower() not in {"indefinido", "analisado", "texto_livre"}:
        return f"{action_txt}: condição de mercado {str(condition).strip()}."[:220]
    return f"{action_txt}: a IA não retornou justificativa técnica específica; decisão mantida de forma preventiva."[:220]


LUMI_REASON_CODES = {
    "bd": "Breakout bearish confirmado com confluência estrutural.",
    "bu": "Breakout bullish confirmado com confluência estrutural.",
    "td": "Tendência M5/M15 bearish alinhada com o setup.",
    "tu": "Tendência M5/M15 bullish alinhada com o setup.",
    "mo": "Momentum e estrutura confirmam a direção candidata.",
    "cf": "Conflito técnico relevante entre os sinais principais.",
    "wk": "Setup sem confluência suficiente para entrada.",
    "fo": "Risco de falso rompimento elevado; melhor aguardar.",
    "ba": "Barreira técnica próxima reduz a qualidade da entrada.",
    "ex": "Preço esticado; timing de entrada desfavorável.",
    "lr": "Evidência estatística/laboratório insuficiente para assumir risco.",
    "mx": "Sinais mistos; não há direção limpa para entrada.",
    "ok": "Confluência técnica suficiente para a direção selecionada.",
}

LUMI_RISK_CODES = {"l": "baixo", "m": "medio", "h": "alto"}
LUMI_ACTION_CODES = {"c": "call", "p": "put", "h": "hold"}

# V108.7.40 · auditoria de log mostrou casos reais de {"a":"p", "x":"bu"} — ação PUT
# com motivo "breakout bullish". Com num_predict=32 num modelo 4B, esse tipo de
# inconsistência interna acontece e passava direto para a UI/Telegram sem checagem,
# inclusive em operações REAIS. Este mapa deixa explícito qual direção cada código
# de motivo sugere, para validar coerência antes de confiar na decisão.
LUMI_REASON_DIRECTION_HINT = {
    "bu": "call", "tu": "call",
    "bd": "put", "td": "put",
}

# V108.7.40 · rastreio leve de viés direcional persistente. Serve para diferenciar
# "mercado realmente em tendência de um lado só" de "bug no pipeline de candles/prompt
# empurrando toda decisão para o mesmo lado" — ver auditoria de log 2026-08-31 (42/42
# decisões PUT na sessão inteira, incluindo ativos sem correlação entre si).
LUMI_DIRECTION_BIAS_FILE = os.path.join(PERSISTENT_DATA_DIR, "lumi_direction_bias.json")
LUMI_DIRECTION_BIAS_WINDOW = 40
LUMI_DIRECTION_BIAS_MIN_SAMPLES = 20
LUMI_DIRECTION_BIAS_ALERT_RATIO = 0.90
LUMI_DIRECTION_BIAS_ALERT_COOLDOWN = 1800
_lumi_direction_bias_last_alert_ts = 0.0


def _lumi_reason_from_code(code: Any, action: str = "hold") -> str:
    key = str(code or "").strip().lower()
    reason = LUMI_REASON_CODES.get(key)
    if reason:
        return reason
    return "Confluência avaliada pela Lumi." if action in {"call", "put"} else "Sinais insuficientes; aguardar melhor oportunidade."


def _lumi_hold_from_reason(code: Any) -> int:
    # O modelo não gasta tokens decidindo hold_candles. O backend aplica uma
    # política curta e previsível conforme a causa do HOLD.
    key = str(code or "").strip().lower()
    return 2 if key in {"fo", "ba", "ex"} else 1


def _lumi_direction_bias_store() -> Dict[str, Any]:
    return safe_read_json(LUMI_DIRECTION_BIAS_FILE, {"history": [], "events": [], "conflicts": 0, "updated_at": ""})


def _lumi_direction_bias_save(store: Dict[str, Any]) -> None:
    store["updated_at"] = now_hms()
    safe_write_json(LUMI_DIRECTION_BIAS_FILE, store)


def _lumi_track_reason_conflict(action: str, reason_code: str, hinted_direction: str) -> None:
    """Conta quantas vezes o motivo (x) contradisse a ação (a). Não bloqueia o fluxo."""
    try:
        store = _lumi_direction_bias_store()
        store["conflicts"] = int(store.get("conflicts", 0) or 0) + 1
        store["last_conflict"] = {
            "action": action, "reason_code": reason_code, "hinted_direction": hinted_direction, "time": now_hms(),
        }
        _lumi_direction_bias_save(store)
    except Exception:
        pass


def _lumi_track_direction_bias(action: str) -> None:
    """V108.8.0: mede viés direcional recente das decisões CALL/PUT da Lumi.

    Mantém eventos com timestamp para que uma sequência antiga não contamine a sessão
    indefinidamente. O histórico simples continua salvo apenas para compatibilidade.
    """
    if action not in {"call", "put"}:
        return
    global _lumi_direction_bias_last_alert_ts
    try:
        store = _lumi_direction_bias_store()
        now_ts = time.time()
        max_age_s = max(1800, int(cfg_get("lumi_direction_bias_guard_history_max_age_minutes", 180) or 180) * 60)
        events = []
        for event in list(store.get("events") or []):
            if not isinstance(event, dict):
                continue
            event_action = str(event.get("action") or "").lower()
            try:
                event_ts = float(event.get("ts", 0) or 0)
            except Exception:
                event_ts = 0.0
            if event_action in {"call", "put"} and event_ts > 0 and (now_ts - event_ts) <= max_age_s:
                events.append({"action": event_action, "ts": event_ts})
        events.append({"action": action, "ts": now_ts})
        events = events[-LUMI_DIRECTION_BIAS_WINDOW:]
        store["events"] = events
        store["history"] = [str(x.get("action") or "") for x in events]
        _lumi_direction_bias_save(store)
        actions = [x["action"] for x in events]
        min_samples = int(cfg_get("lumi_direction_bias_guard_min_samples", LUMI_DIRECTION_BIAS_MIN_SAMPLES) or LUMI_DIRECTION_BIAS_MIN_SAMPLES)
        alert_ratio = float(cfg_get("lumi_direction_bias_guard_ratio", LUMI_DIRECTION_BIAS_ALERT_RATIO) or LUMI_DIRECTION_BIAS_ALERT_RATIO)
        if len(actions) >= min_samples:
            calls = actions.count("call")
            puts = actions.count("put")
            total = calls + puts
            dominant = max(calls, puts)
            ratio = (dominant / total) if total else 0.0
            if ratio >= alert_ratio and (now_ts - _lumi_direction_bias_last_alert_ts) > LUMI_DIRECTION_BIAS_ALERT_COOLDOWN:
                _lumi_direction_bias_last_alert_ts = now_ts
                side = "PUT" if puts > calls else "CALL"
                log(
                    f"🚨 VIÉS DIRECIONAL LUMI V108.8.0 | {dominant}/{total} decisões recentes foram {side} ({ratio*100:.0f}%) · "
                    f"o Bias Guard comparará essa concentração com o DEEP técnico antes de aceitar a direção dominante em REAL.",
                    "warn",
                )
    except Exception:
        pass

def _lumi_direction_bias_snapshot() -> Dict[str, Any]:
    """Retorna somente eventos direcionais recentes da V42; histórico legado não aciona guard."""
    try:
        store = _lumi_direction_bias_store()
        now_ts = time.time()
        max_age_s = max(1800, int(cfg_get("lumi_direction_bias_guard_history_max_age_minutes", 180) or 180) * 60)
        actions: List[str] = []
        for event in list(store.get("events") or []):
            if not isinstance(event, dict):
                continue
            action = str(event.get("action") or "").lower()
            try:
                event_ts = float(event.get("ts", 0) or 0)
            except Exception:
                event_ts = 0.0
            if action in {"call", "put"} and event_ts > 0 and (now_ts - event_ts) <= max_age_s:
                actions.append(action)
        actions = actions[-LUMI_DIRECTION_BIAS_WINDOW:]
        calls = actions.count("call")
        puts = actions.count("put")
        total = calls + puts
        dominant = "put" if puts > calls else "call" if calls > puts else ""
        dominant_count = max(calls, puts) if total else 0
        ratio = (dominant_count / total) if total else 0.0
        return {
            "samples": total, "calls": calls, "puts": puts, "dominant": dominant,
            "ratio": ratio, "conflicts": int(store.get("conflicts", 0) or 0),
            "max_age_minutes": int(max_age_s // 60),
        }
    except Exception:
        return {"samples": 0, "calls": 0, "puts": 0, "dominant": "", "ratio": 0.0, "conflicts": 0}

def _technical_direction_distribution(rows: Any) -> Dict[str, Any]:
    """Resume a direção técnica do DEEP atual para diferenciar regime real de viés da IA."""
    calls = puts = 0
    weighted_call = weighted_put = 0.0
    try:
        for item in list(rows or []):
            if not isinstance(item, dict):
                continue
            direction = normalize_lumi_action(item.get("direction") or "hold")
            if direction not in {"call", "put"}:
                continue
            tech = max(0, min(100, int(item.get("technical_confidence", 0) or 0)))
            # Confianças extremamente baixas não descrevem regime útil; acima de 40 entram com peso crescente.
            if tech < 40:
                continue
            weight = max(1.0, tech / 50.0)
            if direction == "call":
                calls += 1
                weighted_call += weight
            else:
                puts += 1
                weighted_put += weight
    except Exception:
        pass
    total = calls + puts
    weighted_total = weighted_call + weighted_put
    dominant = "put" if weighted_put > weighted_call else "call" if weighted_call > weighted_put else ""
    dominant_weight = max(weighted_call, weighted_put) if weighted_total else 0.0
    ratio = (dominant_weight / weighted_total) if weighted_total else 0.0
    return {
        "samples": total, "calls": calls, "puts": puts, "dominant": dominant, "ratio": ratio,
        "weighted_call": round(weighted_call, 3), "weighted_put": round(weighted_put, 3),
    }


def _lumi_hard_veto(lumi: Any) -> bool:
    return bool(isinstance(lumi, dict) and lumi.get("hard_veto"))


def apply_lumi_direction_bias_guard(lumi: Dict[str, Any], row: Dict[str, Any], technical_rows: Any, min_tech: int) -> Dict[str, Any]:
    """V108.8.0: valida viés da Lumi contra a distribuição técnica DEEP da rodada.

    Em REAL, uma concentração histórica extrema só vira proteção quando o DEEP atual
    não confirma a mesma direção. Nessa situação a direção dominante da IA não pode
    ser usada como simples confirmação; exige confluência técnica excepcional ou vira
    HARD VETO para a oportunidade corrente. A minoria direcional nunca é penalizada.
    """
    if not isinstance(lumi, dict) or not bool(lumi.get("ok")):
        return lumi
    if not bool(cfg_get("lumi_direction_bias_guard_enabled", True)):
        return lumi
    if str(cfg_get("account_type", "PRACTICE")).upper() != "REAL":
        return lumi
    action = normalize_lumi_action(lumi.get("action") or "hold")
    if action not in {"call", "put"} or _lumi_hard_veto(lumi):
        return lumi

    bias = _lumi_direction_bias_snapshot()
    min_samples = int(cfg_get("lumi_direction_bias_guard_min_samples", 20) or 20)
    bias_ratio_req = float(cfg_get("lumi_direction_bias_guard_ratio", 0.90) or 0.90)
    if int(bias.get("samples", 0) or 0) < min_samples or float(bias.get("ratio", 0) or 0) < bias_ratio_req:
        return lumi
    dominant = str(bias.get("dominant") or "")
    if action != dominant:
        # Uma decisão na direção minoritária é evidência contra o próprio viés; não penaliza.
        return lumi

    market = _technical_direction_distribution(technical_rows)
    market_min = int(cfg_get("lumi_direction_bias_guard_technical_min_samples", 6) or 6)
    if int(market.get("samples", 0) or 0) < market_min:
        lumi["direction_bias_guard"] = {"status": "insufficient_market_sample", "bias": bias, "market": market}
        return lumi

    alignment_req = float(cfg_get("lumi_direction_bias_guard_market_alignment_ratio", 0.70) or 0.70)
    market_confirms = str(market.get("dominant") or "") == dominant and float(market.get("ratio", 0) or 0) >= alignment_req
    if market_confirms:
        lumi["direction_bias_guard"] = {"status": "market_confirmed", "bias": bias, "market": market}
        return lumi

    ci = row.get("candle_intelligence") if isinstance(row.get("candle_intelligence"), dict) else {}
    tech = int(row.get("technical_confidence", 0) or 0)
    mtf = float(row.get("mtf_alignment", 50) or 50)
    candle = int(row.get("candle_score", ci.get("score", 50)) or 50)
    pa = int(ci.get("price_action_score", 50) or 50)
    quality = int((row.get("opportunity_quality") or {}).get("score", 0) or 0)
    tech_req = max(int(min_tech or 0) + 2, int(cfg_get("lumi_direction_bias_guard_exceptional_tech", 70) or 70))
    mtf_req = int(cfg_get("lumi_direction_bias_guard_exceptional_mtf", 75) or 75)
    candle_req = int(cfg_get("lumi_direction_bias_guard_exceptional_candle", 80) or 80)
    pa_req = int(cfg_get("lumi_direction_bias_guard_exceptional_price_action", 80) or 80)
    quality_req = int(cfg_get("lumi_direction_bias_guard_exceptional_quality", 78) or 78)
    exceptional = (
        normalize_lumi_action(row.get("direction") or "hold") == action
        and tech >= tech_req and mtf >= mtf_req and candle >= candle_req and pa >= pa_req and quality >= quality_req
    )
    guard_meta = {
        "bias": bias, "market": market, "exceptional": exceptional,
        "requirements": {"tech": tech_req, "mtf": mtf_req, "candle": candle_req, "price_action": pa_req, "quality": quality_req},
        "observed": {"tech": tech, "mtf": round(mtf, 1), "candle": candle, "price_action": pa, "quality": quality},
    }
    if exceptional:
        penalty = int(cfg_get("lumi_direction_bias_guard_confidence_penalty", 10) or 10)
        before = int(lumi.get("confidence", 0) or 0)
        lumi["confidence"] = max(0, before - penalty)
        guard_meta["status"] = "exceptional_pass_with_penalty"
        guard_meta["confidence_before"] = before
        guard_meta["confidence_after"] = int(lumi.get("confidence", 0) or 0)
        lumi["direction_bias_guard"] = guard_meta
        log(
            f"🟠 LUMI BIAS GUARD | {row.get('asset')} {action.upper()} · IA {int(bias.get('calls',0))}C/{int(bias.get('puts',0))}P "
            f"({float(bias.get('ratio',0))*100:.0f}% {dominant.upper()}) x DEEP {int(market.get('calls',0))}C/{int(market.get('puts',0))}P "
            f"· confluência excepcional confirmou; confiança {before}%→{int(lumi.get('confidence',0))}%.",
            "warn",
        )
        return lumi

    original_action = action
    original_conf = int(lumi.get("confidence", 0) or 0)
    lumi["original_action"] = original_action
    lumi["original_confidence"] = original_conf
    lumi["action"] = "hold"
    lumi["confidence"] = min(original_conf, 40)
    lumi["hard_veto"] = True
    lumi["hard_veto_code"] = "directional_bias_guard"
    guard_meta["status"] = "hard_veto"
    lumi["direction_bias_guard"] = guard_meta
    lumi["reason"] = (
        f"[HARD VETO viés direcional] Lumi {int(bias.get('calls',0))}C/{int(bias.get('puts',0))}P "
        f"({float(bias.get('ratio',0))*100:.0f}% {dominant.upper()}) não confirmado pelo DEEP "
        f"{int(market.get('calls',0))}C/{int(market.get('puts',0))}P; confluência excepcional insuficiente."
    )
    log(
        f"🛑 LUMI BIAS HARD VETO | {row.get('asset')} {original_action.upper()} · histórico Lumi "
        f"{int(bias.get('calls',0))}C/{int(bias.get('puts',0))}P x DEEP {int(market.get('calls',0))}C/{int(market.get('puts',0))}P · "
        f"mercado técnico não confirmou concentração e setup não atingiu confluência excepcional.",
        "warn",
    )
    return lumi


def parse_lumi_payload(api_response: Any) -> Dict[str, Any]:
    """Aceita JSON direto, envelope da api_lumi_iq.php ou texto livre da IA."""
    raw = api_response

    if isinstance(api_response, dict) and api_response.get("error"):
        raise ValueError(str(api_response.get("error")))

    if isinstance(api_response, dict) and "resposta" in api_response:
        raw = api_response.get("resposta")

    original_raw = raw
    if isinstance(raw, str):
        raw = extract_json_object_from_text(raw) or infer_lumi_from_text(raw)

    if not isinstance(raw, dict):
        raise ValueError("Resposta da Lumi não veio em JSON/texto interpretável")

    # Alguns modelos devolvem {resposta:{...}} mesmo dentro do texto.
    if "resposta" in raw and isinstance(raw.get("resposta"), (dict, str)):
        return parse_lumi_payload(raw)

    compact_action = str(raw.get("a") or "").strip().lower()
    action = LUMI_ACTION_CODES.get(compact_action) or normalize_lumi_action(
        raw.get("action") or raw.get("acao") or raw.get("ação") or raw.get("sinal") or raw.get("operacao") or raw.get("operação")
    )
    confidence = to_int(raw.get("c") if raw.get("c") is not None else (raw.get("confidence") or raw.get("confianca") or raw.get("confiança") or raw.get("probabilidade")), 0, 0, 100)
    condition = str(raw.get("market_condition") or raw.get("condicao_mercado") or raw.get("condição_mercado") or raw.get("condicao") or "indefinido")[:60]

    focus_raw = raw.get("focus") or raw.get("foco") or []
    focus = [str(x)[:48] for x in focus_raw[:6] if str(x).strip()] if isinstance(focus_raw, list) else []
    reason_code = str(raw.get("x") or raw.get("reason_code") or "").strip().lower()

    # V108.7.40 · valida coerência entre o motivo (x) e a ação (a) antes de confiar
    # na decisão. Ex.: {"a":"p","x":"bu"} = PUT com motivo "breakout bullish" —
    # contraditório. Em vez de deixar passar (como acontecia antes), rebaixa para
    # HOLD e reduz a confiança; nunca promove a ação, só protege contra ela.
    reason_action_conflict = False
    hinted_direction = LUMI_REASON_DIRECTION_HINT.get(reason_code)
    conflict_original_action = ""
    if hinted_direction and action in {"call", "put"} and hinted_direction != action:
        reason_action_conflict = True
        conflict_original_action = action
        _lumi_track_reason_conflict(action, reason_code, hinted_direction)
        log(
            f"⚠️ Lumi INCONSISTÊNCIA | ação={action.upper()} mas motivo x={reason_code} aponta {hinted_direction.upper()} · rebaixado para HOLD por segurança.",
            "warn",
        )
        action = "hold"
        confidence = min(confidence, 40)

    raw_reason = raw.get("reason") or raw.get("motivo") or raw.get("justificativa")
    if reason_code:
        reason = _lumi_reason_from_code(reason_code, action)
    else:
        reason = clean_lumi_reason(raw_reason or "Sem motivo informado", action=action, focus=focus, condition=condition)
    if reason_action_conflict:
        reason = f"[Anomalia motivo×ação corrigida p/ HOLD] {reason}"
    raw_summary = str(raw.get("analysis_summary") or raw.get("resumo_analise") or "").strip()
    analysis_summary = (raw_summary if raw_summary and not is_lumi_placeholder_reason(raw_summary) else reason)[:320]
    thinking = str(raw.get("thinking") or raw.get("raciocinio") or raw.get("pensamento") or raw.get("chain_of_thought") or "")[:1200]
    agent_action = raw.get("agent_action") or raw.get("acao_agente") or {}
    if not isinstance(agent_action, dict):
        agent_action = {}

    raw_hold_candles = to_int(raw.get("hold_candles"), 0, 0, 10)
    if action in {"call", "put"}:
        safe_hold_candles = 0
    elif reason_code:
        safe_hold_candles = _lumi_hold_from_reason(reason_code)
    else:
        safe_hold_candles = max(1, min(3, raw_hold_candles or 1))

    risk_raw = str(raw.get("r") if raw.get("r") is not None else (raw.get("risk") or raw.get("risco") or "medio")).strip().lower()
    risk_value = LUMI_RISK_CODES.get(risk_raw, risk_raw)
    if risk_value not in {"baixo", "medio", "alto"}:
        risk_value = "medio"

    # V108.7.40 · alimenta o rastreio de viés direcional com a ação final (já pós-conflito).
    _lumi_track_direction_bias(action)

    return {
        "ok": True,
        "action": action,
        "confidence": confidence,
        "reason": reason,
        "market_condition": condition,
        "analysis_summary": analysis_summary,
        "thinking": thinking,
        "raciocinio": thinking,
        "focus": focus,
        "agent_action": agent_action,
        "risk": risk_value,
        "reason_code": reason_code,
        "reason_action_conflict": reason_action_conflict,
        "hard_veto": bool(reason_action_conflict and cfg_get("lumi_coherence_hard_veto_enabled", True)),
        "hard_veto_code": "reason_action_conflict" if reason_action_conflict and cfg_get("lumi_coherence_hard_veto_enabled", True) else "",
        "original_action": conflict_original_action if reason_action_conflict else "",
        "hinted_direction": hinted_direction if reason_action_conflict else "",
        "decision": str(raw.get("decision") or raw.get("decisao") or raw.get("decisão") or "")[:40],
        "hold_candles": safe_hold_candles,
        "source": "lumi",
        "error": "",
        "raw": original_raw if isinstance(original_raw, str) else raw,
    }


def today_key() -> str:
    return datetime.now().strftime("%Y-%m-%d")

def make_lumi_cache_key(asset: str, timeframe: int, closed: List[Tuple[int, float]], technical: Dict[str, Any]) -> str:
    last_ts = closed[-1][0] if closed else 0
    price = closed[-1][1] if closed else 0
    base = json.dumps({
        "asset": asset,
        "tf": timeframe,
        "last_ts": last_ts,
        "price": round(float(price), 6),
        "dir_hint": technical.get("score"),
        "conf": technical.get("confidence"),
        "signal_score": technical.get("signal_score"),
        "entry_score": technical.get("entry_score"),
        "mtf_alignment": technical.get("mtf_alignment"),
        "mtf": technical.get("mtf_compact") or {},
        "calibration": technical.get("calibration_compact") or adaptive_calibration_compact(technical.get("calibration")),
    }, sort_keys=True)
    return hashlib.sha1(base.encode("utf-8")).hexdigest()

def lumi_quota_state(reason: str, error: str = "", status: str = "cooldown") -> Dict[str, Any]:
    remaining = max(0, int(float(cfg_get("lumi_cooldown_until", 0)) - time.time()))
    set_lumi_quota_status(status, reason, error)
    return {
        "ok": False,
        "action": "hold",
        "confidence": 0,
        "reason": reason,
        "source": "lumi_quota_protection",
        "quota_status": status,
        "error": error,
        "cooldown_remaining": remaining,
        "raw": None,
    }


def is_lumi_quota_or_cooldown(lumi: Dict[str, Any]) -> bool:
    """True quando a Lumi não pôde ser usada e o fallback técnico deve entrar."""
    if not isinstance(lumi, dict):
        return True
    if lumi.get("ok") is False and not lumi.get("action"):
        return True
    text = f"{lumi.get('source','')} {lumi.get('reason','')} {lumi.get('error','')} {lumi.get('quota_status','')}".lower()
    keys = [
        "429", "quota", "cota", "cooldown", "rate-limit", "resource_exhausted", "limite",
        "timeout", "timed out", "indisponível", "indisponivel", "memória", "memoria", "memory",
        "out of memory", "connection", "conex", "refused", "recusou", "unreachable",
        "erro_conexao", "http", "ssl", "fallback_tecnico", "gateway", "ollama",
        "economia", "intervalo",
    ]
    return any(k in text for k in keys)


def lumi_unavailable_label(lumi: Dict[str, Any]) -> str:
    """Nome curto e claro para o motivo de a Lumi não ter sido usada."""
    status = str(lumi.get("quota_status") or cfg_get("lumi_quota_status") or "").lower()
    reason = str(lumi.get("reason") or cfg_get("lumi_quota_reason") or lumi.get("error") or "").lower()
    text = f"{status} {reason}"
    if "429" in text or "resource_exhausted" in text or "quota" in text or "cota" in text or "limite_diario" in text:
        return "Lumi sem cota"
    if "memória" in text or "memoria" in text or "memory" in text or "out of memory" in text:
        return "Ollama com memória baixa"
    if "timeout" in text or "timed out" in text:
        return "Ollama/Lumi em timeout"
    if "ssl" in text or "handshake" in text:
        return "Lumi com erro SSL"
    if "intervalo" in text or "rate" in text:
        return "Lumi em intervalo anti-rate-limit"
    if "cooldown" in text:
        return "Lumi em cooldown"
    if "economia" in text or "técnica" in text:
        return "Lumi economizada"
    if "resposta_invalida" in text or "resposta ia inválida" in text or "json" in text:
        return "Lumi online · resposta IA inválida"
    return "Lumi indisponível"


def adaptive_premium_override_decision(
    row: Dict[str, Any], lumi: Dict[str, Any], min_tech: int, min_payout: int, min_lumi_conf: int
) -> Tuple[bool, str, List[Dict[str, Any]]]:
    """V108.8.0: permite REAL 60..(corte-1) apenas quando o gap é pequeno e a
    confluência é excepcional. Payout melhora a viabilidade econômica, mas nunca
    compensa sozinho uma leitura técnica fraca. Abaixo de 60% é bloqueio absoluto.
    """
    is_real = str(cfg_get("account_type", "PRACTICE")).upper() == "REAL"
    if _lumi_hard_veto(lumi):
        return False, f"Lumi HARD VETO: {str((lumi or {}).get('hard_veto_code') or 'coerência')}", [make_step("Lumi HARD VETO", False, str((lumi or {}).get("reason") or "inconsistência interna"))]
    context_floor = int(row.get("context_tech_floor", min_tech) or min_tech)
    if bool(row.get("adaptive_loss_context_blocked")) or int(row.get("technical_confidence",0) or 0) < context_floor:
        ctx = row.get("adaptive_loss_context") or {}
        return False, f"Adaptive Loss Intelligence recusou override: técnica contextual exige {context_floor}% · edge {float(ctx.get('edge_pp',0) or 0):+.1f}pp", [make_step("Adaptive Loss Intelligence", False, str(ctx.get("reason") or "contexto REAL negativo"))]
    if not is_real or not bool(cfg_get("adaptive_premium_override_enabled", True)):
        return False, "Adaptive Premium Override indisponível", []

    tech = int(row.get("technical_confidence", 0) or 0)
    payout = int(row.get("payout", 0) or 0)
    strategy_now = str(cfg_get("strategy", "combined") or "combined")
    effective_cut = technical_threshold_grid(max(int(min_tech), REAL_HARD_TECH_FLOOR), strategy_now, "ceil")
    tech_floor = max(60, int(cfg_get("adaptive_premium_override_tech_floor", 60) or 60))
    max_gap = max(1, min(4, int(cfg_get("adaptive_premium_override_max_gap_pp", 4) or 4)))
    gap = max(0, int(effective_cut) - tech)
    tech_band_ok = tech_floor <= tech < int(effective_cut) and 1 <= gap <= max_gap

    direction = normalize_lumi_action(row.get("direction") or "hold")
    lumi_action = normalize_lumi_action((lumi or {}).get("action") or "hold")
    lumi_conf = int((lumi or {}).get("confidence", 0) or 0)
    source = str((lumi or {}).get("source") or "").lower()
    real_lumi = bool((lumi or {}).get("ok")) and source not in {
        "technical_demo_fallback", "technical_fallback", "technical_fallback_after_lumi_hold",
        "fallback_tecnico", "lumi_economy", "lumi_economy_hold", "asset_cooldown", "off", "erro",
    }
    aligned = direction in VALID_DIRECTIONS and lumi_action == direction

    calibration = adaptive_calibration_for_row(row, lumi)
    calibration_penalty = adaptive_calibration_lumi_penalty(calibration)
    required_lumi = max(
        int(min_lumi_conf or 0),
        int(cfg_get("adaptive_premium_override_min_lumi", 82) or 82),
    ) + calibration_penalty
    lumi_ok = real_lumi and aligned and lumi_conf >= required_lumi

    required_payout = max(int(min_payout), int(cfg_get("adaptive_premium_override_min_payout", 80) or 80))
    payout_ok = payout > 0 and payout >= required_payout

    ci = row.get("candle_intelligence") if isinstance(row.get("candle_intelligence"), dict) else {}
    mtf_alignment = float(row.get("mtf_alignment", 50) or 50)
    candle_score = int(row.get("candle_score", ci.get("score", 50)) or 50)
    price_action_score = int(ci.get("price_action_score", 50) or 50)
    quality = compute_opportunity_quality(row, lumi)
    quality_score = int(quality.get("score", 0) or 0)
    mtf_min = int(cfg_get("adaptive_premium_override_min_mtf", 70) or 70)
    candle_min = int(cfg_get("adaptive_premium_override_min_candle", 75) or 75)
    pa_min = int(cfg_get("adaptive_premium_override_min_price_action", 75) or 75)
    quality_min = int(cfg_get("adaptive_premium_override_min_quality", 75) or 75)
    mtf_ok = mtf_alignment >= mtf_min
    candle_ok = candle_score >= candle_min
    pa_ok = price_action_score >= pa_min
    quality_ok = quality_score >= quality_min

    loss_memory_ok = not bool(row.get("loss_memory_rejected"))
    si = row.get("shadow_intelligence") if isinstance(row.get("shadow_intelligence"), dict) else shadow_intelligence_for_row(row)
    row["shadow_intelligence"] = si
    si_samples = int(si.get("samples", 0) or 0)
    si_edge = float(si.get("edge_pp", 0) or 0)
    shadow_veto_n = int(cfg_get("adaptive_premium_override_shadow_veto_min_samples", 30) or 30)
    shadow_veto_edge = float(cfg_get("adaptive_premium_override_shadow_veto_edge_pp", -2.0) or -2.0)
    shadow_ok = si_samples < shadow_veto_n or si_edge >= shadow_veto_edge

    calibration_hard_negative = adaptive_calibration_strong_negative(calibration)
    if bool(cfg_get("wallstreet_ev_real_requires_both_samples", True)):
        calibration_hard_negative = calibration_hard_negative and int(calibration.get("actual_samples", 0) or 0) >= int(cfg_get("wallstreet_ev_min_real_samples", 6) or 6)
    ev_gate = wallstreet_row_risk_gate(row, lumi)
    ev_ok = not bool(ev_gate.get("block")) and not calibration_hard_negative

    # Mesmo no Override, não compra/vende exaustão extrema sem breakout alinhado.
    sig = row.get("signals") or {}
    bb_pct = float(sig.get("bb_pct", 50) or 50)
    breakout_vote = int(sig.get("breakout_vote", 0) or 0)
    momentum_vote = int(sig.get("momentum_vote", 0) or 0)
    macd_hist = float(sig.get("macd_hist", 0) or 0)
    extreme_pct = float(cfg_get("lumi_borderline_bb_extreme_pct", 98) or 98)
    bb_extreme = (direction == "call" and bb_pct >= extreme_pct) or (direction == "put" and bb_pct <= (100.0 - extreme_pct))
    breakout_confirmed = True
    if bb_extreme:
        if direction == "call":
            breakout_confirmed = breakout_vote > 0 and momentum_vote > 0 and macd_hist > 0
        elif direction == "put":
            breakout_confirmed = breakout_vote < 0 and momentum_vote < 0 and macd_hist < 0

    steps = [
        make_step("Adaptive Premium · faixa técnica", tech_band_ok, f"{tech}% / corte {effective_cut}% · gap {gap}pp · piso {tech_floor}% · máx {max_gap}pp"),
        make_step("Adaptive Premium · Lumi", lumi_ok, f"{lumi_action.upper()} {lumi_conf}% / mínimo {required_lumi}% · fonte {source or 'desconhecida'}"),
        make_step("Adaptive Premium · payout", payout_ok, f"{payout or '—'}% / mínimo {required_payout}%"),
        make_step("Adaptive Premium · Quality", quality_ok, f"{quality_score}% / mínimo {quality_min}%"),
        make_step("Adaptive Premium · MTF", mtf_ok, f"{mtf_alignment:.0f}% / mínimo {mtf_min}%"),
        make_step("Adaptive Premium · Candle/PA", candle_ok and pa_ok, f"Candle {candle_score}%/{candle_min}% · PA {price_action_score}%/{pa_min}%"),
        make_step("Adaptive Premium · Loss Memory", loss_memory_ok, "sem veto ativo" if loss_memory_ok else str(row.get("loss_memory_reason") or "padrão de LOSS semelhante bloqueado")),
        make_step("Adaptive Premium · Shadow", shadow_ok, f"edge {si_edge:+.1f}pp · n={si_samples} · veto se n≥{shadow_veto_n} e edge<{shadow_veto_edge:+.1f}pp"),
        make_step("Adaptive Premium · EV", ev_ok, str(ev_gate.get("reason") or calibration.get("risk") or "sem veto histórico")),
        make_step("Adaptive Premium · Anti-Chase", (not bb_extreme) or breakout_confirmed, f"BB {bb_pct:.1f}%" + (" · breakout confirmado" if bb_extreme and breakout_confirmed else "")),
    ]

    checks = [tech_band_ok, lumi_ok, payout_ok, quality_ok, mtf_ok, candle_ok, pa_ok, loss_memory_ok, shadow_ok, ev_ok, (not bb_extreme) or breakout_confirmed]
    approved = all(checks)
    meta = {
        "approved": approved, "tech": tech, "cut": int(effective_cut), "gap_pp": gap, "tech_floor": tech_floor,
        "required_lumi": required_lumi, "required_payout": required_payout, "quality": quality_score,
        "required_quality": quality_min, "mtf": mtf_alignment, "required_mtf": mtf_min,
        "candle": candle_score, "required_candle": candle_min, "price_action": price_action_score,
        "required_price_action": pa_min,
    }
    row["adaptive_premium_override"] = meta
    if approved:
        return True, (
            f"ADAPTIVE PREMIUM OVERRIDE aprovado: técnica {tech}%/{effective_cut}% (gap {gap}pp) + "
            f"Lumi {lumi_conf}% {direction.upper()} + payout {payout}% + Quality {quality_score}% + "
            f"MTF {mtf_alignment:.0f}% + Candle/PA {candle_score}%/{price_action_score}%"
        ), steps

    failed = [str(x.get("label") or "") for x in steps if not bool(x.get("ok"))]
    return False, "Adaptive Premium Override recusado: " + (", ".join(failed[:4]) if failed else "confluência insuficiente"), steps


def lumi_borderline_promotion_decision(
    row: Dict[str, Any], lumi: Dict[str, Any], min_tech: int, min_payout: int, min_lumi_conf: int
) -> Tuple[bool, str, List[Dict[str, Any]]]:
    """Avalia promoção técnica limítrofe sem transformar Lumi em atalho de risco.

    Em PRACTICE preserva a faixa histórica configurável. Em REAL, o Adaptive Premium
    Override pode avaliar 60%+ com gap máximo de 4pp; fora dessa faixa permanece a
    promoção legada mais estreita. Timeout, cooldown, HOLD e resposta sintética nunca promovem.
    """
    if _lumi_hard_veto(lumi):
        return False, f"Lumi HARD VETO: {str((lumi or {}).get('hard_veto_code') or 'coerência')}", [make_step("Lumi HARD VETO", False, str((lumi or {}).get("reason") or "inconsistência interna"))]
    if not bool(cfg_get("lumi_borderline_promotion_enabled", True)):
        return False, "promoção limítrofe desativada", []
    is_real = str(cfg_get("account_type", "PRACTICE")).upper() == "REAL"
    tech = int(row.get("technical_confidence", 0) or 0)
    if is_real and bool(cfg_get("adaptive_premium_override_enabled", True)):
        strategy_now_apo = str(cfg_get("strategy", "combined") or "combined")
        cut_apo = technical_threshold_grid(max(int(min_tech), REAL_HARD_TECH_FLOOR), strategy_now_apo, "ceil")
        floor_apo = max(60, int(cfg_get("adaptive_premium_override_tech_floor", 60) or 60))
        gap_apo = max(0, int(cut_apo) - tech)
        max_gap_apo = max(1, min(4, int(cfg_get("adaptive_premium_override_max_gap_pp", 4) or 4)))
        if floor_apo <= tech < int(cut_apo) and 1 <= gap_apo <= max_gap_apo:
            return adaptive_premium_override_decision(row, lumi, min_tech, min_payout, min_lumi_conf)
    if is_real and not bool(cfg_get("real_borderline_promotion_enabled", True)):
        return False, "promoção limítrofe REAL desativada", []
    payout = int(row.get("payout", 0) or 0)
    direction = normalize_lumi_action(row.get("direction") or "hold")
    lumi_action = normalize_lumi_action((lumi or {}).get("action") or "hold")
    lumi_conf = int((lumi or {}).get("confidence", 0) or 0)
    source = str((lumi or {}).get("source") or "").lower()
    strategy_now = str(cfg_get("strategy", "combined") or "combined")
    effective_grid = technical_threshold_grid(min_tech, strategy_now, "ceil")
    previous_grid = technical_previous_level(effective_grid, strategy_now)
    if is_real:
        # V108.8.0: caminho NORMAL continua no piso REAL (>=62). A faixa Premium
        # é uma exceção isolada de no máximo 2pp abaixo do corte e exige confluência
        # completa + Opportunity Quality alta; nunca é usada por fallback/timeout.
        configured_floor = int(cfg_get("real_borderline_tech_floor", 60) or 60)
        floor = max(configured_floor, int(effective_grid) - 2)
    else:
        floor = int(cfg_get("lumi_borderline_tech_floor", 50) or 50)
    calibration = adaptive_calibration_for_row(row, lumi)
    calibration_penalty = adaptive_calibration_lumi_penalty(calibration)
    required_lumi = max(
        int(cfg_get("real_borderline_min_lumi_confidence", 85) or 85) if is_real else int(cfg_get("lumi_borderline_min_confidence", 72) or 72),
        int(min_lumi_conf or 0) + (10 if is_real else 0),
    ) + calibration_penalty

    real_lumi = bool((lumi or {}).get("ok")) and source not in {
        "technical_demo_fallback", "technical_fallback", "technical_fallback_after_lumi_hold",
        "fallback_tecnico", "lumi_economy", "lumi_economy_hold", "asset_cooldown", "off", "erro",
    }
    tech_in_band = (floor <= tech < int(effective_grid)) if is_real else (floor <= tech < int(min_tech))
    payout_required = max(int(min_payout), int(min_payout) + int(cfg_get("real_borderline_min_payout_margin", 8) or 8)) if is_real else int(min_payout)
    payout_ok = payout > 0 and payout >= payout_required
    aligned = direction in VALID_DIRECTIONS and lumi_action == direction
    confidence_ok = lumi_conf >= required_lumi

    # Promoção 50–54% recebe proteção extra contra comprar/vender no extremo da banda.
    # Em extremo, só aceitamos continuação se o próprio motor técnico detectar breakout
    # alinhado (breakout + momentum + MACD na mesma direção).
    sig = row.get("signals") or {}
    bb_pct = float(sig.get("bb_pct", 50) or 50)
    breakout_vote = int(sig.get("breakout_vote", 0) or 0)
    momentum_vote = int(sig.get("momentum_vote", 0) or 0)
    macd_hist = float(sig.get("macd_hist", 0) or 0)
    extreme_pct = float(cfg_get("lumi_borderline_bb_extreme_pct", 98) or 98)
    bb_guard_enabled = bool(cfg_get("lumi_borderline_bb_guard_enabled", True))
    bb_extreme = (direction == "call" and bb_pct >= extreme_pct) or (direction == "put" and bb_pct <= (100.0 - extreme_pct))
    breakout_confirmed = True
    extreme_quality_ok = True
    if bb_guard_enabled and bb_extreme:
        if direction == "call":
            breakout_confirmed = breakout_vote > 0 and momentum_vote > 0 and macd_hist > 0
        elif direction == "put":
            breakout_confirmed = breakout_vote < 0 and momentum_vote < 0 and macd_hist < 0
        # V101: promoção 50–54% em BB extremo exige qualidade excepcional de entrada/MTF
        # e espaço mínimo até a barreira contrária. Não basta a Lumi declarar 90–95%.
        entry_score = int(row.get("entry_score", tech) or tech)
        mtf_alignment = float(row.get("mtf_alignment", 50) or 50)
        m5 = ((row.get("precision_summary") or {}).get("m5") or {}) if isinstance(row.get("precision_summary"), dict) else {}
        barrier_dist = float(m5.get("resistance_distance_pct", 99) if direction == "call" else m5.get("support_distance_pct", 99) or 99)
        extreme_quality_ok = entry_score >= 70 and mtf_alignment >= 65 and barrier_dist >= 0.08

    ci = row.get("candle_intelligence") if isinstance(row.get("candle_intelligence"), dict) else {}
    entry_score = int(row.get("entry_score", tech) or tech)
    mtf_alignment = float(row.get("mtf_alignment", 50) or 50)
    candle_score = int(row.get("candle_score", ci.get("score", 50)) or 50)
    price_action_score = int(ci.get("price_action_score", 50) or 50)
    si = row.get("shadow_intelligence") if isinstance(row.get("shadow_intelligence"), dict) else shadow_intelligence_for_row(row)
    row["shadow_intelligence"] = si
    si_samples = int(si.get("samples", 0) or 0)
    si_edge = float(si.get("edge_pp", 0) or 0)
    quality = compute_opportunity_quality(row, lumi)
    quality_score = int(quality.get("score", 0) or 0)
    if is_real:
        entry_ok = entry_score >= int(cfg_get("real_borderline_min_entry_score", 62) or 62)
        mtf_ok = mtf_alignment >= float(cfg_get("real_borderline_min_mtf_alignment", 60) or 60)
        candle_ok = candle_score >= int(cfg_get("real_borderline_min_candle_score", 60) or 60)
        pa_ok = price_action_score >= int(cfg_get("real_borderline_min_price_action_score", 75) or 75)
        quality_ok = quality_score >= int(cfg_get("real_borderline_min_quality_score", 75) or 75)
        shadow_veto_n = int(cfg_get("real_borderline_shadow_veto_min_samples", 30) or 30)
        shadow_min_edge = float(cfg_get("real_borderline_min_shadow_edge_pp", 2.0) or 2.0)
        # Shadow com pouca amostra não impede uma oportunidade premium; com amostra
        # robusta passa a funcionar como veto quando claramente abaixo da referência.
        shadow_ok = si_samples < shadow_veto_n or si_edge >= shadow_min_edge
    else:
        entry_ok = mtf_ok = candle_ok = pa_ok = shadow_ok = quality_ok = True

    band_text = (f"{tech}% · faixa Premium {floor}–{max(floor, effective_grid-1)}% abaixo do corte normal {effective_grid}%" if is_real else f"{tech}% · faixa {floor}–{max(floor, int(min_tech)-1)}%")
    steps = [
        make_step("Faixa técnica promovível", tech_in_band, band_text),
        make_step("Payout promoção", payout_ok, f"{payout or '—'}% / mínimo {payout_required}%"),
        make_step("Lumi real", real_lumi, f"fonte {source or 'desconhecida'}"),
        make_step("Direção Lumi", aligned, f"técnica {direction.upper()} x Lumi {lumi_action.upper()}"),
        make_step("Confiança Lumi promoção", confidence_ok, f"{lumi_conf}% / mínimo {required_lumi}%"),
        make_step("Calibração persistente", not (adaptive_calibration_strong_negative(calibration) and (not is_real or not bool(cfg_get("wallstreet_ev_real_requires_both_samples", True)) or int(calibration.get("actual_samples",0) or 0) >= int(cfg_get("wallstreet_ev_min_real_samples",6) or 6))), f"{calibration.get('risk')} · ajuste {float(calibration.get('adjustment',0)):+.1f} · WR {float(calibration.get('winrate',0)):.1f}% · n {float(calibration.get('effective_samples',0)):.1f} · REAL {int(calibration.get('actual_samples',0) or 0)}"),
        make_step("Entry Score REAL borderline", entry_ok, f"{entry_score}% / mínimo {int(cfg_get('real_borderline_min_entry_score',62) or 62)}%" if is_real else "não exigido em DEMO"),
        make_step("MTF REAL borderline", mtf_ok, f"{mtf_alignment:.0f}% / mínimo {int(cfg_get('real_borderline_min_mtf_alignment',60) or 60)}%" if is_real else "não exigido em DEMO"),
        make_step("Candle Intelligence borderline", candle_ok and pa_ok, f"Candle {candle_score}% / {int(cfg_get('real_borderline_min_candle_score',60) or 60)}% · PA {price_action_score}% / {int(cfg_get('real_borderline_min_price_action_score',75) or 75)}%" if is_real else "não exigido em DEMO"),
        make_step("Shadow Intelligence borderline", shadow_ok, f"edge {si_edge:+.1f}pp · n={si_samples} · veto só com n>={int(cfg_get('real_borderline_shadow_veto_min_samples',30) or 30)}" if is_real else "não exigido em DEMO"),
        make_step("Opportunity Quality", quality_ok, f"{quality_score}% / mínimo {int(cfg_get('real_borderline_min_quality_score',75) or 75)}%" if is_real else f"{quality_score}%"),
        make_step(
            "Extremo Bollinger / breakout",
            (not bb_extreme) or (breakout_confirmed and extreme_quality_ok) or not bb_guard_enabled,
            (f"BB {bb_pct:.1f}% · breakout {breakout_vote:+d} · momentum {momentum_vote:+d} · MACD {macd_hist:+.6f}" if bb_extreme else f"BB {bb_pct:.1f}% fora do extremo de promoção"),
        ),
    ]
    if not tech_in_band:
        return False, (f"REAL borderline Premium exige técnica {floor}–{max(floor, effective_grid-1)}% abaixo do corte normal {effective_grid}%" if is_real else f"técnica {tech}% fora da faixa promovível {floor}–{max(floor, int(min_tech)-1)}%"), steps
    if not payout_ok:
        return False, f"payout {payout or '—'}% abaixo do mínimo borderline {payout_required}%", steps
    if not real_lumi:
        return False, "promoção exige resposta real da Lumi; fallback/cooldown/timeout não promove", steps
    if not aligned:
        return False, f"Lumi não confirmou a direção técnica ({direction.upper()} x {lumi_action.upper()})", steps
    if not confidence_ok:
        return False, f"confiança Lumi {lumi_conf}% < {required_lumi}% para promover setup limítrofe", steps
    calibration_hard_negative = adaptive_calibration_strong_negative(calibration)
    if is_real and bool(cfg_get("wallstreet_ev_real_requires_both_samples", True)):
        calibration_hard_negative = calibration_hard_negative and int(calibration.get("actual_samples", 0) or 0) >= int(cfg_get("wallstreet_ev_min_real_samples", 6) or 6)
    if calibration_hard_negative:
        return False, f"promoção recusada pela calibração persistente: padrão histórico em {calibration.get('risk')} ({float(calibration.get('adjustment',0)):+.1f})", steps
    if is_real and not entry_ok:
        return False, f"REAL borderline recusado: Entry Score {entry_score}% abaixo do mínimo", steps
    if is_real and not mtf_ok:
        return False, f"REAL borderline recusado: MTF {mtf_alignment:.0f}% sem alinhamento suficiente", steps
    if is_real and not (candle_ok and pa_ok):
        return False, f"REAL borderline recusado: Candle/Price Action insuficientes ({candle_score}%/{price_action_score}%)", steps
    if is_real and not quality_ok:
        return False, f"REAL borderline recusado: Opportunity Quality {quality_score}% abaixo do mínimo", steps
    if is_real and not shadow_ok:
        return False, f"REAL borderline recusado: Shadow robusto desfavorável ({si_edge:+.1f}pp · n={si_samples})", steps
    if bb_guard_enabled and bb_extreme and (not breakout_confirmed or not extreme_quality_ok):
        side = "superior" if direction == "call" else "inferior"
        if not breakout_confirmed:
            return False, f"promoção recusada: BB {bb_pct:.1f}% em extremo {side} sem breakout técnico confirmado", steps
        return False, f"promoção recusada: BB {bb_pct:.1f}% extremo exige Entry>=70, MTF>=65 e espaço de barreira", steps
    return True, (f"REAL borderline Premium aprovado: técnica {tech}% + Quality {quality_score}% + Lumi {lumi_conf}% {direction.upper()} + payout {payout}% + MTF/Candle/Shadow" if is_real else f"Lumi promoveu setup limítrofe: técnica {tech}% + Lumi {lumi_conf}% {direction.upper()} + payout {payout}%"), steps


def technical_fallback_decision(row: Dict[str, Any], min_payout: int) -> Tuple[bool, str, List[Dict[str, Any]]]:
    """Fallback técnico quando a Lumi está offline/timeout/sem cota.

    Em modo agente full / aggressive, libera com técnica + payout bons.
    Continua bloqueando extremos claros contra a direção.
    """
    if not cfg_get("technical_fallback_enabled", True):
        return False, "fallback técnico desativado", []
    is_real = cfg_get("account_type") == "REAL"
    # Agente full: fallback REAL liberado por padrão (só amount/stops ficam travados)
    allow_real = bool(cfg_get("technical_fallback_allow_real", True))
    if is_real and not allow_real:
        return False, "fallback técnico REAL desativado por segurança", []

    max_session = int(cfg_get(
        "technical_fallback_max_session_real" if is_real else "technical_fallback_max_session_demo",
        cfg_get("technical_fallback_max_session", 1000000),
    ) or 0)
    if max_session <= 0:
        max_session = 1000000
    if int(cfg_get("technical_fallback_count", 0) or 0) >= max_session:
        return False, f"limite de fallback técnico na sessão atingido ({max_session})", []

    direction = str(row.get("direction") or "").lower()
    conf = int(row.get("technical_confidence", 0) or 0)
    payout = int(row.get("payout", 0) or 0)
    risk = normalize_risk_profile(cfg_get("risk_profile", "aggressive"))

    min_pay_key = "technical_fallback_min_payout_real" if is_real else "technical_fallback_min_payout_demo"
    default_min_pay = 70 if risk == "aggressive" else 75

    # v90: fallback técnico usa o MESMO corte técnico normal da oportunidade.
    # Nunca deixa anti-stall/override transformar 50–54% em fallback: essa faixa
    # só pode ser promovida por uma resposta REAL da Lumi alinhada e >=72%.
    try:
        row_required = int(float(row.get("technical_required", 0) or 0))
    except Exception:
        row_required = 0
    try:
        effective_required = int(lumi_agent_effective_metrics().get("min_technical_confidence", cfg_get("min_technical_confidence", 55)) or 55)
    except Exception:
        effective_required = int(cfg_get("min_technical_confidence", 55) or 55)
    configured_required = int(cfg_get("min_technical_confidence", 55) or 55)
    professional_floor = max(REAL_HARD_TECH_FLOOR, int(cfg_get("wallstreet_real_min_technical_floor", REAL_HARD_TECH_FLOOR) or REAL_HARD_TECH_FLOOR)) if is_real and bool(cfg_get("wallstreet_adaptive_enabled", True)) else 55
    # Fallback sem IA exige margem adicional no REAL.
    fallback_real_floor = int(cfg_get("technical_fallback_min_confidence_real", 62) or 62) if is_real else 55
    min_conf = max(55, professional_floor, fallback_real_floor, configured_required, effective_required, row_required)
    min_conf = technical_threshold_grid(min_conf, cfg_get("strategy", "combined"), "ceil")
    quality_score = int(compute_opportunity_quality(row, None).get("score", 0) or 0)
    fallback_quality_min = int(cfg_get("technical_fallback_real_min_quality_score", 72) or 72) if is_real else 0

    raw_min_pay = int(cfg_get(min_pay_key, cfg_get("technical_fallback_min_payout", default_min_pay)) or 0)
    min_pay_cfg = raw_min_pay if raw_min_pay > 0 else default_min_pay
    min_pay = max(min_pay_cfg, int(min_payout or 0) if int(min_payout or 0) > 0 else 0)

    sig = row.get("signals") or {}
    rsi = float(sig.get("rsi", 50) or 50)
    bb = float(sig.get("bb_pct", 50) or 50)
    macd_hist = float(sig.get("macd_hist", 0) or 0)
    ema9 = float(sig.get("ema9", 0) or 0)
    ema21 = float(sig.get("ema21", 0) or 0)

    calibration = row.get("calibration") if isinstance(row.get("calibration"), dict) else adaptive_calibration_for_row(row)
    row["calibration"] = calibration
    calibration_negative = adaptive_calibration_strong_negative(calibration)
    if is_real and bool(cfg_get("wallstreet_ev_real_requires_both_samples", True)):
        calibration_negative = calibration_negative and int(calibration.get("actual_samples", 0) or 0) >= int(cfg_get("wallstreet_ev_min_real_samples", 6) or 6)
    ws_gate = wallstreet_row_risk_gate(row)
    steps = [
        make_step("Fallback técnico", True, "Lumi offline/timeout; agente opera por técnica"),
        make_step("Calibração persistente", not calibration_negative, f"{calibration.get('risk')} · ajuste {float(calibration.get('adjustment',0)):+.1f} · WR {float(calibration.get('winrate',0)):.1f}% · n {float(calibration.get('effective_samples',0)):.1f}"),
        make_step("Wall Street EV", not bool(ws_gate.get("block")), str(ws_gate.get("reason") or "histórico")),
        make_step("Conta", True, "REAL com fallback forte" if is_real else "DEMO liberado"),
        make_step("Técnica mínima fallback", conf >= min_conf, f"{conf}% / mínimo {min_conf}%"),
        make_step("Opportunity Quality fallback", (quality_score >= fallback_quality_min) if is_real else True, f"{quality_score}% / mínimo {fallback_quality_min}%" if is_real else f"{quality_score}%"),
        make_step("Payout fallback", (payout > 0 and payout >= min_pay), f"{payout or '—'}% / mínimo {min_pay}%"),
        make_step("Limite fallback sessão", int(cfg_get("technical_fallback_count", 0) or 0) < max_session, f"{cfg_get('technical_fallback_count', 0)} / {max_session}"),
    ]
    if direction not in VALID_DIRECTIONS:
        return False, "fallback bloqueado: direção técnica ausente", steps
    if calibration_negative or ws_gate.get("block"):
        return False, f"fallback bloqueado pelo histórico/EV: {ws_gate.get('reason') or calibration.get('risk')}", steps
    if conf < min_conf:
        return False, f"fallback bloqueado: técnica {conf}% < {min_conf}%", steps
    if is_real and quality_score < fallback_quality_min:
        return False, f"fallback bloqueado: qualidade {quality_score}% < {fallback_quality_min}%", steps
    if payout <= 0 or payout < min_pay:
        return False, f"fallback bloqueado: payout {payout or '—'}% < {min_pay}%", steps

    # Anti-extremo apenas. A direção já veio da análise técnica (60%+):
    # com Lumi offline o agente confia na técnica + payout, sem exigir EMA+MACD juntos.
    if direction == "call":
        if rsi >= 82 or bb >= 97:
            steps.append(make_step("Extremo contra entrada", False, f"CALL com RSI {rsi:.1f} / Bollinger {bb:.1f}%"))
            return False, f"fallback bloqueado: CALL em extremo superior (RSI {rsi:.1f}, BB {bb:.1f}%)", steps
        if risk == "conservative" and not (ema9 > ema21 and macd_hist > 0):
            steps.append(make_step("Tendência/momentum", False, "conservador exige EMA+MACD para CALL"))
            return False, f"fallback bloqueado: tendência/momentum fracos para CALL (EMA9 {ema9:.6f} ≤ EMA21 {ema21:.6f} ou MACD {macd_hist:+.6f} ≤ 0)", steps
        steps.append(make_step(
            "Tendência/momentum", True,
            f"CALL pela técnica {conf}% · EMA9{' >' if ema9 > ema21 else ' ≤'}EMA21 · MACD {macd_hist:+.5f}"
        ))
    if direction == "put":
        if rsi <= 18 or bb <= 3:
            steps.append(make_step("Extremo contra entrada", False, f"PUT com RSI {rsi:.1f} / Bollinger {bb:.1f}%"))
            return False, f"fallback bloqueado: PUT em extremo inferior (RSI {rsi:.1f}, BB {bb:.1f}%)", steps
        if risk == "conservative" and not (ema9 < ema21 and macd_hist < 0):
            steps.append(make_step("Tendência/momentum", False, "conservador exige EMA+MACD para PUT"))
            return False, f"fallback bloqueado: tendência/momentum fracos para PUT (EMA9 {ema9:.6f} ≥ EMA21 {ema21:.6f} ou MACD {macd_hist:+.6f} ≥ 0)", steps
        steps.append(make_step(
            "Tendência/momentum", True,
            f"PUT pela técnica {conf}% · EMA9{' <' if ema9 < ema21 else ' ≥'}EMA21 · MACD {macd_hist:+.5f}"
        ))

    steps.append(make_step("Fallback aprovado", True, f"técnica {conf}% + payout {payout}% · Lumi offline — agente opera"))
    return True, (
        "fallback técnico REAL aprovado: Lumi indisponível — agente opera por técnica"
        if is_real else
        "fallback técnico DEMO aprovado porque a Lumi está indisponível"
    ), steps


def _lumi_asset_cooldown_key(asset: str) -> str:
    return normalize_asset_name(asset or "").upper()


def lumi_asset_cooldown_remaining(asset: str) -> int:
    """Cooldown apenas do candidato que causou timeout/pressão local no Ollama."""
    key = _lumi_asset_cooldown_key(asset)
    if not key:
        return 0
    now_ts = time.time()
    with state_lock:
        pool = state.setdefault("lumi_asset_cooldowns", {})
        item = pool.get(key) if isinstance(pool, dict) else None
        if not isinstance(item, dict):
            return 0
        until = float(item.get("until", 0) or 0)
        if until <= now_ts:
            pool.pop(key, None)
            return 0
    return max(0, int(until - now_ts))


def set_lumi_asset_cooldown(asset: str, seconds: int, reason: str = "") -> int:
    key = _lumi_asset_cooldown_key(asset)
    seconds = max(0, int(seconds or 0))
    if not key or seconds <= 0:
        return 0
    until = time.time() + seconds
    with state_lock:
        pool = state.setdefault("lumi_asset_cooldowns", {})
        if not isinstance(pool, dict):
            pool = {}
            state["lumi_asset_cooldowns"] = pool
        pool[key] = {"until": until, "reason": str(reason or "")[:220]}
    return seconds


def clear_lumi_asset_cooldown(asset: str) -> None:
    key = _lumi_asset_cooldown_key(asset)
    if not key:
        return
    with state_lock:
        pool = state.setdefault("lumi_asset_cooldowns", {})
        if isinstance(pool, dict):
            pool.pop(key, None)


# ── Lumi Health Engine: circuit breaker de latência ─────────────────────────
def lumi_health_snapshot() -> Dict[str, Any]:
    """Estado operacional da Lumi para o caminho crítico da entrada.

    Dois timeouts consecutivos colocam a IA em modo degradado por 5 minutos.
    Nesse período 50–54% não consome IA; sinais >= corte técnico usam fallback
    imediatamente, sem esperar o timeout novamente.
    """
    now = time.time()
    with state_lock:
        until = float(cfg_get("_lumi_health_degraded_until", 0) or 0)
        consecutive = int(cfg_get("_lumi_health_consecutive_timeouts", 0) or 0)
        if until and now >= until:
            state["_lumi_health_degraded_until"] = 0.0
            state["_lumi_health_consecutive_timeouts"] = 0
            state["_lumi_health_reason"] = "janela degradada encerrada; nova tentativa permitida"
            until = 0.0
            consecutive = 0
        return {
            "degraded": bool(until > now),
            "remaining": max(0, int(until - now)),
            "consecutive_timeouts": consecutive,
            "reason": str(cfg_get("_lumi_health_reason") or "saudável"),
            "last_latency_ms": int(cfg_get("_lumi_health_last_latency_ms", 0) or 0),
        }


def record_lumi_health_result(result: Dict[str, Any], latency_ms: int) -> Dict[str, Any]:
    """Atualiza saúde da Lumi sem transformar falhas de um ativo em cooldown global."""
    result = result if isinstance(result, dict) else {}
    text = " ".join([
        str(result.get("quota_status") or ""),
        str(result.get("error") or ""),
        str(result.get("reason") or ""),
    ]).lower()
    timed_out = ("timeout" in text or "timed out" in text or "excedeu o orçamento" in text) and not bool(result.get("ok"))
    now = time.time()
    became_degraded = False
    with state_lock:
        state["_lumi_health_last_latency_ms"] = max(0, int(latency_ms or 0))
        if bool(result.get("ok")):
            state["_lumi_health_consecutive_timeouts"] = 0
            state["_lumi_health_reason"] = "Lumi respondeu dentro do orçamento"
        elif timed_out:
            count = int(cfg_get("_lumi_health_consecutive_timeouts", 0) or 0) + 1
            state["_lumi_health_consecutive_timeouts"] = count
            state["_lumi_health_reason"] = f"{count} timeout(s) consecutivo(s)"
            if count >= 2:
                old_until = float(cfg_get("_lumi_health_degraded_until", 0) or 0)
                new_until = max(old_until, now + 300)
                state["_lumi_health_degraded_until"] = new_until
                state["_lumi_health_reason"] = "2+ timeouts consecutivos; circuit breaker FAST por 5min"
                became_degraded = old_until <= now
    snap = lumi_health_snapshot()
    if became_degraded:
        log("⚡ Lumi Health: 2 timeouts consecutivos · modo degradado por 5min. Faixa 50–54% será descartada sem IA; >=55% seguirá direto para fallback técnico.", "warn")
    return snap


def lumi_hold_key(asset: str, timeframe: int) -> str:
    return f"{normalize_asset_name(asset)}:{int(timeframe)}"


def is_lumi_hold_blocked(asset: str, timeframe: int) -> int:
    key = lumi_hold_key(asset, timeframe)
    now_ts = time.time()
    with LUMI_CACHE_LOCK:
        until = float(LUMI_HOLD_BLOCKS.get(key, 0) or 0)
        if until <= now_ts:
            LUMI_HOLD_BLOCKS.pop(key, None)
            return 0
        return int(until - now_ts)


def lumi_hold_block_until_hms(asset: str, timeframe: int) -> str:
    """Retorna o horário local até quando o ativo ficará bloqueado após HOLD/divergência."""
    key = lumi_hold_key(asset, timeframe)
    with LUMI_CACHE_LOCK:
        until = float(LUMI_HOLD_BLOCKS.get(key, 0) or 0)
    if until <= time.time():
        return ""
    return datetime.fromtimestamp(until).strftime("%H:%M:%S")


def block_after_lumi_hold(asset: str, timeframe: int, reason: str = "HOLD") -> None:
    candles = effective_lumi_hold_candles()
    seconds = max(int(timeframe), 60) * max(candles, 1)
    key = lumi_hold_key(asset, timeframe)
    with LUMI_CACHE_LOCK:
        LUMI_HOLD_BLOCKS[key] = time.time() + seconds
    log(f"Lumi {reason}: {asset} bloqueado por {candles} vela(s) para economizar IA.", "info")



def _ollama_url_normalized(url: Optional[str] = None) -> str:
    """Retorna a URL real do Ollama. Migra silenciosamente URLs legadas do gateway :5002."""
    value = str(url or cfg_get("ollama_url") or OLLAMA_DEFAULT_URL).strip() or OLLAMA_DEFAULT_URL
    if "/api/analisar-sinal" in value or ":5002" in value:
        value = OLLAMA_DEFAULT_URL
        with state_lock:
            state["ollama_url"] = value
            state["ollama_mode"] = "direct"
    if "/api/" not in value:
        value = value.rstrip("/") + "/api/chat"
    return value


def _ollama_api_url(path: str, base_url: Optional[str] = None) -> str:
    chat_url = _ollama_url_normalized(base_url)
    base = chat_url.split("/api/", 1)[0].rstrip("/")
    return base + "/api/" + str(path or "chat").lstrip("/")


def _ollama_post_json(url: str, payload: Dict[str, Any], timeout: float) -> Dict[str, Any]:
    body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    req = urllib.request.Request(url, data=body, headers={"Content-Type": "application/json"}, method="POST")
    with urllib.request.urlopen(req, timeout=max(1.0, float(timeout))) as resp:
        text = resp.read().decode("utf-8", errors="replace")
    try:
        parsed = json.loads(text)
    except Exception:
        parsed = {"response": text}
    if isinstance(parsed, dict) and parsed.get("error"):
        raise ValueError(str(parsed.get("error")))
    return parsed if isinstance(parsed, dict) else {"response": str(parsed)}


def _ollama_response_text(payload: Dict[str, Any]) -> str:
    if not isinstance(payload, dict):
        return str(payload or "")
    if isinstance(payload.get("message"), dict):
        return str((payload.get("message") or {}).get("content") or "")
    if payload.get("response") is not None:
        return str(payload.get("response") or "")
    if payload.get("resposta") is not None:
        value = payload.get("resposta")
        return json.dumps(value, ensure_ascii=False) if isinstance(value, (dict, list)) else str(value or "")
    return json.dumps(payload, ensure_ascii=False)


def _integrated_lumi_progress_worker(stop_evt: threading.Event, request_id: str, contexto: Dict[str, Any]) -> None:
    """Atualiza o Agent Manager no mesmo processo, sem polling HTTP interno."""
    asset = normalize_asset_name(contexto.get("ativo") or contexto.get("asset") or "-")
    direction = normalize_lumi_action(contexto.get("direcao") or contexto.get("direcao_tecnica") or contexto.get("direction"))
    try:
        tech = int(float(contexto.get("tecnica", contexto.get("confianca_tecnica", 0)) or 0))
    except Exception:
        tech = 0
    try:
        payout = int(float(contexto.get("payout", 0) or 0))
    except Exception:
        payout = 0
    stages = [
        ("context", f"📡 Tape lido: {asset} {direction.upper()} · técnica {tech}% · payout {payout or '—'}%.", ["sinal técnico", "payout"]),
        ("indicators", "⚡ Lumi integrada lendo EMA, MACD, RSI, Bollinger e momentum.", ["tendência", "momentum", "osciladores"]),
        ("regime", "🔥 Conferindo regime, volatilidade e memória operacional.", ["regime", "volatilidade", "histórico"]),
    ]
    started = time.time()
    for phase, message, focus in stages:
        if stop_evt.is_set():
            return
        publish_lumi_agent_status(
            phase, message, asset, direction, focus=focus,
            thinking=message, request_id=request_id,
            elapsed_ms=int((time.time() - started) * 1000), action_status="analisando",
        )
        if stop_evt.wait(0.70):
            return
    while not stop_evt.wait(1.5):
        publish_lumi_agent_status(
            "thinking", f"⚡ {asset} {direction.upper()} · Trader 4B processando decisão...",
            asset, direction, focus=["decisão", "risco", "edge"],
            thinking=f"Processando {asset} {direction.upper()} no Ollama integrado.",
            request_id=request_id, elapsed_ms=int((time.time() - started) * 1000),
            action_status="analisando",
        )


def _notify_gateway_agent_action_result(asset: str, direction: str, effective: Dict[str, Any]) -> None:
    """Compatibilidade do código antigo: a telemetria agora é local, sem chamada para :5002."""
    with state_lock:
        agent = dict(cfg_get("lumi_agent") or {})
    publish_lumi_agent_status(
        "action_applied" if str(agent.get("action_status") or "") == "aplicado" else "monitoring",
        str(agent.get("status") or "Lumi integrada · métricas processadas."),
        asset, direction,
        last_action=str(agent.get("last_action") or "Métricas mantidas."),
        action_status=str(agent.get("action_status") or "mantido"),
    )


def _ollama_trader_schema() -> Dict[str, Any]:
    # V108.3: protocolo mínimo. Exemplo: {"a":"p","c":85,"r":"m","x":"bd"}
    return {
        "type": "object",
        "properties": {
            "a": {"type": "string", "enum": ["c", "p", "h"]},
            "c": {"type": "integer", "minimum": 0, "maximum": 100},
            "r": {"type": "string", "enum": ["l", "m", "h"]},
            "x": {"type": "string", "enum": ["bd", "bu", "td", "tu", "mo", "cf", "wk", "fo", "ba", "ex", "lr", "mx", "ok"]},
        },
        "required": ["a", "c", "r", "x"],
        "additionalProperties": False,
    }


def _call_ollama_text(model: str, system_prompt: str, user_prompt: str, timeout: int, *, json_mode: bool = False, keep_alive: str = "5m", num_predict: int = 420) -> str:
    payload: Dict[str, Any] = {
        "model": str(model or LUMI_ANALYST_MODEL),
        "stream": False,
        "think": False,
        "keep_alive": keep_alive,
        "messages": [
            {"role": "system", "content": str(system_prompt or "")},
            {"role": "user", "content": str(user_prompt or "")},
        ],
        "options": {"temperature": 0.15, "top_p": 0.8, "num_ctx": 4096, "num_predict": int(num_predict)},
    }
    if json_mode:
        payload["format"] = "json"
    response = _ollama_post_json(_ollama_url_normalized(), payload, timeout)
    return _ollama_response_text(response)


def call_ollama_lumi(prompt: str, timeout_seconds: float) -> Dict[str, Any]:
    """Decisão FAST diretamente no Ollama :11434, sem segundo Flask/gateway."""
    ollama_url = _ollama_url_normalized()
    ollama_model = str(cfg_get("ollama_model") or OLLAMA_DEFAULT_MODEL).strip() or OLLAMA_DEFAULT_MODEL
    with state_lock:
        state["ollama_mode"] = "direct"
        state["ollama_url"] = ollama_url

    try:
        contexto = json.loads(prompt)
        if not isinstance(contexto, dict):
            contexto = {}
    except Exception:
        contexto = {}

    request_id = uuid.uuid4().hex[:12]
    started = time.time()
    stop_progress = threading.Event()
    progress_thread = threading.Thread(
        target=_integrated_lumi_progress_worker,
        args=(stop_progress, request_id, contexto), daemon=True,
    )
    progress_thread.start()

    # O Modelfile já contém as regras permanentes. Mantemos apenas uma instrução mínima
    # para modelos-base usados como fallback, sem repetir o prompt grande a cada trade.
    system_fast = (
        'LUMI ULTRA FAST. Responda SOMENTE {"a":"c|p|h","c":0-100,"r":"l|m|h","x":"codigo"}. '
        'q é hipótese: c=CALL,p=PUT,h=HOLD. Códigos x: bd,bu,td,tu,mo,cf,wk,fo,ba,ex,lr,mx,ok.'
    )
    messages = [{"role": "user", "content": prompt}]
    if str(ollama_model).lower() != LUMI_CUSTOM_MODEL.lower():
        messages.insert(0, {"role": "system", "content": system_fast})

    payload: Dict[str, Any] = {
        "model": ollama_model,
        "stream": False,
        "think": False,
        "keep_alive": "30m",
        "format": _ollama_trader_schema(),
        "messages": messages,
        "options": {
            "temperature": 0.03,
            "top_p": 0.60,
            "num_ctx": int(cfg_get("lumi_fast_num_ctx", 768) or 768) if bool(cfg_get("lumi_fast_runtime_enabled", True)) else 1024,
            "num_predict": int(cfg_get("lumi_fast_num_predict", 32) or 32) if bool(cfg_get("lumi_fast_runtime_enabled", True)) else 32,
        },
    }

    effective_timeout = max(5.0, min(float(timeout_seconds or 12.5), 120.0))
    # O modelo recebe um orçamento interno curto; sobra margem para o fluxo externo
    # cair em fallback antes de consumir toda a janela da vela.
    effective_timeout = min(effective_timeout, OLLAMA_TRADER_INTERNAL_TIMEOUT)
    if bool(cfg_get("lumi_fast_runtime_enabled", True)):
        effective_timeout = min(effective_timeout, max(3.5, float(cfg_get("lumi_fast_timeout_seconds", 4.5) or 4.5)))

    try:
        try:
            api_response = _ollama_post_json(ollama_url, payload, effective_timeout)
        except urllib.error.HTTPError as exc:
            # Compatibilidade Ollama: o caminho principal usa think=false + JSON Schema.
            # Se uma versão local antiga rejeitar um desses campos, fazemos UM retry
            # compatível sem relaxar o parser/guardrails da operação.
            detail = ""
            try:
                detail = exc.read().decode("utf-8", errors="replace")[:600]
            except Exception:
                detail = str(exc)
            detail_lower = detail.lower()

            if exc.code == 400 and any(k in detail_lower for k in ["think", "thinking"]):
                compat_payload = dict(payload)
                compat_payload.pop("think", None)
                api_response = _ollama_post_json(ollama_url, compat_payload, effective_timeout)
                payload = compat_payload
            elif exc.code == 400 and any(k in detail_lower for k in ["schema", "format", "structured"]):
                compat_payload = dict(payload)
                compat_payload["format"] = "json"
                api_response = _ollama_post_json(ollama_url, compat_payload, effective_timeout)
                payload = compat_payload
            elif exc.code in {400, 404} and ollama_model.lower() == LUMI_CUSTOM_MODEL.lower() and any(k in detail_lower for k in ["model", "not found", "pull"]):
                fallback_model = LUMI_BASE_MODEL
                log(f"Lumi: {LUMI_CUSTOM_MODEL} não encontrado; fallback local para {fallback_model}.", "info")
                payload["model"] = fallback_model
                payload["messages"] = [
                    {"role": "system", "content": system_fast},
                    {"role": "user", "content": prompt},
                ]
                api_response = _ollama_post_json(ollama_url, payload, effective_timeout)
                ollama_model = fallback_model
            else:
                raise

        content = _ollama_response_text(api_response)
        try:
            parsed = parse_lumi_payload(content or api_response)
        except Exception:
            # Um único retry ultracurto para JSON malformado, sem segundo servidor.
            retry_payload = dict(payload)
            retry_payload["options"] = dict(payload.get("options") or {})
            retry_payload["options"]["num_predict"] = 32
            retry_payload["messages"] = [
                {"role": "system", "content": system_fast},
                {"role": "user", "content": prompt},
            ]
            retry_response = _ollama_post_json(ollama_url, retry_payload, min(5, effective_timeout))
            api_response = retry_response
            content = _ollama_response_text(retry_response)
            parsed = parse_lumi_payload(content or retry_response)

        parsed["source"] = "ollama_integrado"
        parsed["model"] = ollama_model
        raw_lumi_json = " ".join(str(content or "").strip().split())
        parsed["raw_json"] = raw_lumi_json[:500]
        if isinstance(api_response, dict):
            parsed["ollama_total_ms"] = int(float(api_response.get("total_duration", 0) or 0) / 1_000_000)
            parsed["ollama_prompt_ms"] = int(float(api_response.get("prompt_eval_duration", 0) or 0) / 1_000_000)
            parsed["ollama_generation_ms"] = int(float(api_response.get("eval_duration", 0) or 0) / 1_000_000)
            parsed["ollama_tokens_out"] = int(api_response.get("eval_count", 0) or 0)
        elapsed_ms = int((time.time() - started) * 1000)
        if raw_lumi_json:
            lumi_asset = normalize_asset_name(contexto.get("ativo") or contexto.get("asset") or contexto.get("a") or "-")
            log(
                f"🧠 LUMI JSON | {lumi_asset} | {raw_lumi_json[:320]} · "
                f"total={int(parsed.get('ollama_total_ms', elapsed_ms) or elapsed_ms)}ms · "
                f"prompt={int(parsed.get('ollama_prompt_ms',0) or 0)}ms · geração={int(parsed.get('ollama_generation_ms',0) or 0)}ms · tokens={int(parsed.get('ollama_tokens_out',0) or 0)}",
                "info",
            )
        publish_lumi_agent_status(
            "decision",
            f"⚡ Lumi integrada: {_lumi_decision_label(parsed)} · {str(parsed.get('reason') or '')[:180]}",
            contexto.get("ativo") or contexto.get("asset") or "-",
            contexto.get("direcao") or contexto.get("direction") or parsed.get("action"),
            focus=["decisão", "risco", "edge"],
            analysis_summary=str(parsed.get("reason") or "")[:320],
            thinking=f"Decisão FAST concluída localmente em {elapsed_ms} ms.",
            last_decision=_lumi_decision_label(parsed),
            request_id=request_id, elapsed_ms=elapsed_ms, action_status="decidido",
        )
        return parsed
    finally:
        stop_progress.set()
        progress_thread.join(timeout=0.15)


def _warmup_integrated_lumi() -> None:
    """Pré-aquece só o Trader 4B; o Analyst 14B permanece fora do caminho crítico."""
    time.sleep(0.35)
    model = str(cfg_get("ollama_model") or OLLAMA_DEFAULT_MODEL).strip() or OLLAMA_DEFAULT_MODEL
    generate_url = _ollama_api_url("generate")
    try:
        print(f"[LUMI] Pré-aquecendo {model} diretamente no Ollama...", flush=True)
        payload = {"model": model, "prompt": "", "stream": False, "keep_alive": "30m", "options": {"num_predict": 1}}
        try:
            _ollama_post_json(generate_url, payload, 120)
        except urllib.error.HTTPError as exc:
            if exc.code in {400, 404} and model.lower() == LUMI_CUSTOM_MODEL.lower():
                payload["model"] = LUMI_BASE_MODEL
                _ollama_post_json(generate_url, payload, 120)
                print(f"[LUMI] {LUMI_CUSTOM_MODEL} não encontrado; fallback {LUMI_BASE_MODEL} aquecido.", flush=True)
                return
            raise
        print(f"[LUMI] {model} aquecido · servidor Lumi integrado ao :5001.", flush=True)
    except Exception as exc:
        print(f"[LUMI] Ollama não pôde ser pré-aquecido: {short_lumi_error(exc)}", flush=True)


def call_lumi(asset: str, timeframe: int, closed: List[Tuple[int, float]], technical: Dict[str, Any], rotation_bypass: bool = False) -> Dict[str, Any]:
    if not cfg_get("lumi_enabled"):
        return {"ok": False, "action": "hold", "confidence": 0, "reason": "Lumi desativada", "source": "off", "error": "", "raw": None}

    now_ts = time.time()
    # Economia: só chama a Lumi quando a técnica já tem força mínima.
    min_tech_to_call = int(lumi_agent_effective_metrics().get("lumi_min_technical_to_call", cfg_get("lumi_min_technical_to_call", cfg_get("min_technical_confidence", 60))) or 0)
    try:
        tech_conf_now = int(float(technical.get("confidence", 0) or 0))
    except Exception:
        tech_conf_now = 0
    # Promoção 50–54%: garante que a faixa limítrofe chegue à Lumi mesmo se
    # o limite econômico antigo estiver configurado acima de 50. Abaixo do piso, economiza.
    try:
        technical_required_now = int(float(technical.get("technical_required", cfg_get("min_technical_confidence", 60)) or 60))
    except Exception:
        technical_required_now = int(cfg_get("min_technical_confidence", 60) or 60)
    if bool(cfg_get("lumi_borderline_promotion_enabled", True)) and tech_conf_now < technical_required_now:
        min_tech_to_call = min(min_tech_to_call, int(cfg_get("lumi_borderline_tech_floor", 50) or 50))
    if min_tech_to_call > 0 and tech_conf_now < min_tech_to_call:
        set_lumi_quota_status("economia", f"Lumi economizada: técnica {tech_conf_now}% < {min_tech_to_call}%")
        return {
            "ok": False,
            "action": "hold",
            "confidence": 0,
            "reason": f"Lumi economizada: técnica {tech_conf_now}% < {min_tech_to_call}%",
            "source": "lumi_economy",
            "quota_status": "economia",
            "error": "",
            "raw": None,
        }

    tech_direction_now = normalize_lumi_action(technical.get("direction") or technical.get("signal") or technical.get("action") or technical.get("sinal"))
    if tech_direction_now not in VALID_DIRECTIONS:
        set_lumi_quota_status("economia", "Lumi economizada: técnica sem direção CALL/PUT")
        return {
            "ok": False,
            "action": "hold",
            "confidence": 0,
            "reason": "Lumi economizada: técnica sem direção CALL/PUT",
            "source": "lumi_economy_hold",
            "quota_status": "economia",
            "error": "",
            "raw": None,
        }

    provider = str(cfg_get("lumi_provider") or "ollama").strip().lower()
    if provider not in VALID_LUMI_PROVIDERS:
        provider = "ollama"

    # Timeout/memória local do Ollama é cooldown POR ATIVO, não global.
    # Assim a rotação pode testar o próximo candidato imediatamente.
    if provider == "ollama":
        asset_rest = lumi_asset_cooldown_remaining(asset)
        if asset_rest > 0:
            return {
                "ok": False, "action": "hold", "confidence": 0,
                "reason": f"Lumi em cooldown somente para {normalize_asset_name(asset)}. Tentará este ativo novamente em {asset_rest}s.",
                "source": "asset_cooldown", "quota_status": "asset_cooldown",
                "cooldown_remaining": asset_rest, "error": "", "raw": None,
            }

    # Global fica reservado para quota/429 e proteções realmente globais.
    cooldown_until = float(cfg_get("lumi_cooldown_until", 0) or 0)
    if now_ts < cooldown_until:
        rest = int(cooldown_until - now_ts)
        return lumi_quota_state(f"Lumi em cooldown global. Tentará novamente em {rest}s.", status="cooldown_global")

    today = today_key()
    if cfg_get("_lumi_day") != today:
        with state_lock:
            state["_lumi_day"] = today
            state["lumi_calls_today"] = 0
            state["lumi_quota_status"] = "ok"
            state["lumi_quota_reason"] = "novo dia"

    daily_limit = int(cfg_get("lumi_daily_call_limit", 200) or 200)
    if int(cfg_get("lumi_calls_today", 0) or 0) >= daily_limit:
        with state_lock:
            state["lumi_last_error"] = "limite diário local atingido"
        return lumi_quota_state(f"Limite diário local da Lumi atingido ({daily_limit} chamadas).", status="limite_diario")

    cache_ttl = int(cfg_get("lumi_cache_ttl_seconds", 300) or 300)
    cache_key = make_lumi_cache_key(asset, timeframe, closed, technical)
    with LUMI_CACHE_LOCK:
        cached = LUMI_CACHE.get(cache_key)
        if cached and now_ts - float(cached.get("ts", 0)) <= cache_ttl:
            result = dict(cached.get("value", {}))
            result["source"] = "lumi_cache"
            return result

    min_interval = int(cfg_get("lumi_min_interval_seconds", 45) or 45)
    elapsed = now_ts - float(cfg_get("lumi_last_call_ts", 0) or 0)
    # Na rotação da MESMA rodada, o Ollama/gateway local pode seguir para o próximo
    # candidato sem esperar o intervalo global. Endpoint externo continua protegido.
    local_rotation = bool(rotation_bypass and provider == "ollama")
    if elapsed < min_interval and not local_rotation:
        rest = int(min_interval - elapsed)
        return lumi_quota_state(f"Proteção anti-rate-limit ativa. Próxima chamada Lumi em {rest}s.", status="intervalo")

    endpoint = str(cfg_get("lumi_endpoint") or LUMI_DEFAULT_ENDPOINT).strip()
    if provider == "endpoint" and not endpoint.startswith("http"):
        return {"ok": False, "action": "hold", "confidence": 0, "reason": "Endpoint Lumi inválido", "source": "erro", "error": "endpoint inválido", "raw": None}

    prompt = build_lumi_prompt(asset, timeframe, closed, technical)
    publish_lumi_agent_status(
        "sending",
        f"Enviando {asset} {tech_direction_now.upper()} para a Lumi Agente · técnica {tech_conf_now}%.",
        asset, tech_direction_now,
        focus=["técnica", "tendência", "momentum", "volatilidade", "regime", "risco"],
        analysis_summary="Contexto FAST enviado ao Ollama; aguardando somente CALL/PUT/HOLD e confiança.",
        action_status="analisando",
    )

    with state_lock:
        state["lumi_last_call_ts"] = time.time()
        state["lumi_calls_today"] = int(cfg_get("lumi_calls_today", 0) or 0) + 1

    try:
        timeout_seconds = float(cfg_get("lumi_timeout_seconds") or 12.5)
        timeout_seconds = max(5.0, min(timeout_seconds, 120.0))
        if provider == "ollama":
            timeout_seconds = float(cfg_get("ollama_timeout_seconds") or timeout_seconds)
            timeout_seconds = max(5.0, min(timeout_seconds, 120.0))
            parsed = call_ollama_lumi(prompt, timeout_seconds)
        else:
            body = json.dumps({"mensagem": prompt}, ensure_ascii=False).encode("utf-8")
            req = urllib.request.Request(endpoint, data=body, headers={"Content-Type": "application/json"}, method="POST")
            with urllib.request.urlopen(req, timeout=timeout_seconds) as resp:
                text = resp.read().decode("utf-8", errors="replace")
            try:
                api_response = json.loads(text)
            except Exception:
                api_response = {"tipo": "texto", "resposta": text}
            parsed = parse_lumi_payload(api_response)
            parsed["source"] = "endpoint"
        with LUMI_CACHE_LOCK:
            LUMI_CACHE[cache_key] = {"ts": time.time(), "value": parsed}
            # Limpeza simples para não crescer sem limite.
            if len(LUMI_CACHE) > 500:
                oldest = sorted(LUMI_CACHE.items(), key=lambda kv: kv[1].get("ts", 0))[:120]
                for k, _ in oldest:
                    LUMI_CACHE.pop(k, None)
        clear_lumi_asset_cooldown(asset)
        with state_lock:
            state["lumi_last_error"] = ""
            state["lumi_quota_status"] = "ok"
            state["lumi_quota_reason"] = "Lumi respondeu normalmente via " + str(cfg_get("lumi_provider") or "endpoint")
        agent_effective = apply_lumi_agent_action(parsed, asset, tech_direction_now)
        _notify_gateway_agent_action_result(asset, tech_direction_now, agent_effective)
        return parsed
    except urllib.error.HTTPError as e:
        try:
            detail = e.read().decode("utf-8", errors="replace")[:500]
        except Exception:
            detail = str(e)
        error_text = f"HTTP {e.code}: {detail}"[:520]
        if e.code == 429 or "RESOURCE_EXHAUSTED" in detail or "quota" in detail.lower():
            cooldown = int(cfg_get("lumi_cooldown_on_429_seconds", 600) or 600)
            with state_lock:
                state["lumi_cooldown_until"] = time.time() + cooldown
                state["lumi_last_error"] = error_text
            return lumi_quota_state(f"Cota/limite da IA excedido. Chamadas pausadas por {cooldown}s.", error_text, status="cota_429")
        detail_low = detail.lower()
        if e.code == 502 and any(k in detail_low for k in ["json", "resposta do modelo", "truncad", "resposta ia"]):
            set_lumi_quota_status("resposta_invalida", "Lumi online · resposta IA inválida; usando HOLD/fallback.", error_text)
            publish_lumi_agent_status(
                "degraded",
                "Lumi online · resposta IA inválida. HOLD preventivo/fallback até a próxima análise.",
                asset, tech_direction_now,
                focus=["json", "retry", "fallback"],
                analysis_summary="O gateway respondeu, mas o conteúdo da IA não pôde ser validado.",
                action_status="degraded",
            )
            return {
                "ok": False,
                "action": "hold",
                "confidence": 0,
                "reason": "Lumi online · resposta IA inválida; HOLD/fallback nesta varredura.",
                "source": "fallback_tecnico",
                "quota_status": "resposta_invalida",
                "error": error_text,
                "raw": None,
            }
        # Gateway local pode encapsular ReadTimeout do Ollama como HTTP 502/504.
        # Isso NÃO é erro de endpoint/chave: classifica como latência e cai cedo no fallback técnico.
        timeout_http = e.code in {502, 504} and any(k in detail_low for k in [
            "timed out", "timeout", "read timeout", "read timed", "httpconnectionpool", "ollama excedeu",
        ])
        if timeout_http:
            cooldown = int(cfg_get("ollama_unavailable_cooldown_seconds", 45) or 0)
            if cooldown > 0:
                set_lumi_asset_cooldown(asset, cooldown, error_text)
            reason_timeout = (
                f"Ollama/Lumi excedeu o orçamento de latência em {normalize_asset_name(asset)}; "
                "cooldown aplicado somente neste ativo e rotação liberada para os demais."
            )
            set_lumi_quota_status("timeout", reason_timeout, error_text)
            publish_lumi_agent_status(
                "degraded", reason_timeout, asset, tech_direction_now,
                focus=["latência", "timeout", "fallback"],
                analysis_summary="O gateway está acessível; o modelo local apenas não respondeu dentro do prazo operacional.",
                action_status="degraded",
            )
            return {
                "ok": False, "action": "hold", "confidence": 0,
                "reason": reason_timeout, "source": "fallback_tecnico",
                "quota_status": "timeout", "error": error_text, "raw": None,
            }

        provider_now = str(cfg_get("lumi_provider") or "ollama").strip().lower()
        generic_reason = (
            "Gateway Lumi/Ollama retornou erro HTTP; verifique o processo local e o detalhe técnico."
            if provider_now == "ollama"
            else "Lumi HTTP falhou; verifique o endpoint e a autenticação configurados."
        )
        set_lumi_quota_status("http_error", generic_reason, error_text)
        return {
            "ok": False,
            "action": "hold",
            "confidence": 0,
            "reason": generic_reason,
            "source": "fallback_tecnico",
            "error": error_text,
            "raw": None,
        }
    except Exception as e:
        error_text = short_lumi_error(e)
        raw_error = str(e)[:300]
        provider_now = str(cfg_get("lumi_provider") or "ollama").strip().lower()
        if any(k in error_text.lower() for k in ["memória", "memoria", "memory"]):
            status = "memoria_baixa"
        elif "timeout" in error_text.lower():
            status = "timeout"
        elif any(k in error_text.lower() for k in ["resposta ia inválida", "json", "truncad"]):
            status = "resposta_invalida"
        else:
            status = "erro_conexao"
        # Timeout/memória baixa no Ollama não deve travar a rotação inteira.
        # Local Ollama => cooldown só do ativo; endpoint externo => proteção global curta.
        if status in {"timeout", "memoria_baixa"}:
            if provider_now == "ollama":
                cooldown = int(cfg_get("ollama_unavailable_cooldown_seconds", 45) or 0)
                if cooldown > 0:
                    set_lumi_asset_cooldown(asset, cooldown, raw_error or error_text)
            else:
                cooldown = min(int(cfg_get("lumi_cooldown_on_429_seconds", 300) or 300), 180)
                if cooldown > 0:
                    with state_lock:
                        state["lumi_cooldown_until"] = time.time() + cooldown
        if status == "resposta_invalida":
            status_reason = f"Lumi online · resposta IA inválida: {error_text}"
            publish_lumi_agent_status(
                "degraded", status_reason, asset, tech_direction_now,
                focus=["json", "retry", "fallback"],
                analysis_summary="Ollama/gateway acessível; somente a resposta estruturada falhou.",
                action_status="degraded",
            )
        else:
            status_reason = f"Lumi indisponível: {error_text}"
        set_lumi_quota_status(status, status_reason, raw_error)
        return {
            "ok": False,
            "action": "hold",
            "confidence": 0,
            "reason": status_reason,
            "source": "fallback_tecnico",
            "quota_status": status,
            "error": raw_error,
            "raw": None,
        }


_TECHNICAL_WEIGHT_CACHE: Dict[str, Any] = {"ts": 0.0, "multipliers": {}}


def _technical_strategy_performance_multipliers() -> Dict[str, float]:
    """V108.8.0: peso adaptativo suave, com shrinkage para não supervalorizar amostra pequena."""
    if not bool(cfg_get("technical_dynamic_strategy_weighting_enabled", True)):
        return {}
    now = time.time()
    cached = dict(_TECHNICAL_WEIGHT_CACHE.get("multipliers") or {})
    if cached and now - float(_TECHNICAL_WEIGHT_CACHE.get("ts", 0) or 0) < 45:
        return cached
    label_to_key = {
        "momentum": "momentum", "tendência": "trend", "tendencia": "trend",
        "ema 9/21": "ema_cross", "ema": "ema", "macd": "macd",
        "price action": "price_action", "volatilidade": "volatility",
        "suporte/resistência": "support_resistance", "suporte/resistencia": "support_resistance",
        "rsi+bollinger": "rsi_bollinger", "rsi": "rsi", "bollinger": "bollinger",
        "pullback": "pullback", "breakout": "breakout", "breakout consolidação": "breakout_consolidation",
        "breakout consolidacao": "breakout_consolidation", "divergência macd": "macd_divergence",
        "divergencia macd": "macd_divergence", "reversal": "reversal", "estocástico": "stochastic",
        "estocastico": "stochastic",
    }
    lo = float(cfg_get("technical_dynamic_weight_min", 0.88) or 0.88)
    hi = float(cfg_get("technical_dynamic_weight_max", 1.12) or 1.12)
    mults: Dict[str, float] = {}
    try:
        rows = strategy_performance_snapshot(100, ttl=45)
    except Exception:
        rows = []
    for r in rows:
        label = str(r.get("name") or "").strip().lower()
        key = label_to_key.get(label)
        if not key:
            continue
        sw = float(r.get("shadow_wins", 0) or 0); sl = float(r.get("shadow_losses", 0) or 0)
        rw = float(r.get("real_wins", 0) or 0); rl = float(r.get("real_losses", 0) or 0)
        # Priors 50/50: Shadow precisa de volume; REAL ganha influência com menos amostras.
        shadow_wr = (sw + 15.0) / max(1.0, sw + sl + 30.0)
        real_wr = (rw + 5.0) / max(1.0, rw + rl + 10.0)
        shadow_delta = shadow_wr - 0.50
        real_delta = real_wr - 0.50
        m = 1.0 + shadow_delta * 0.45 + real_delta * 0.80
        mults[key] = round(max(lo, min(hi, m)), 4)
    _TECHNICAL_WEIGHT_CACHE["ts"] = now
    _TECHNICAL_WEIGHT_CACHE["multipliers"] = dict(mults)
    return mults


def _technical_consensus_v2(model_rows: List[Tuple[str, int, str]], base_weights: List[int], score: float, legacy_confidence: float) -> Dict[str, Any]:
    """Converte votos ativos em confiança por famílias independentes.

    Neutros/HOLD deixam de diluir o denominador, porém uma única família nunca pode
    fabricar confiança REAL forte. O boost é limitado e o caminho normal permanece
    sujeito aos mesmos gates 62/Lumi/payout/EV/preflight.
    """
    if not bool(cfg_get("technical_consensus_v2_enabled", True)):
        return {"enabled": False, "confidence": int(round(legacy_confidence))}
    family_map = {
        "trend": "trend", "ema_cross": "trend", "ema": "trend", "pullback": "trend",
        "macd": "momentum", "momentum": "momentum", "macd_divergence": "momentum",
        "volatility": "volatility", "breakout": "volatility", "breakout_consolidation": "volatility",
        "price_action": "price_action", "support_resistance": "price_action",
        "rsi_bollinger": "mean_reversion", "reversal": "mean_reversion", "stochastic": "mean_reversion",
        "rsi": "mean_reversion", "bollinger": "mean_reversion",
    }
    family_labels = {
        "trend": "Tendência", "momentum": "Momentum", "volatility": "Volatilidade",
        "price_action": "Price Action/SR", "mean_reversion": "Reversão/Osciladores",
    }
    perf = _technical_strategy_performance_multipliers()
    direction_sign = 1 if score > 0 else (-1 if score < 0 else 0)
    active_weight = 0.0
    aligned_weight = 0.0
    opposed_weight = 0.0
    family_scores: Dict[str, float] = {k: 0.0 for k in family_labels}
    effective_contributions: Dict[str, float] = {}
    effective_weights: Dict[str, float] = {}
    active_models = 0
    for idx, (key, vote, _reason) in enumerate(model_rows):
        base = float(base_weights[idx])
        mult = float(perf.get(key, 1.0) or 1.0)
        eff_w = base * mult
        eff_c = float(vote) * eff_w
        effective_weights[key] = round(eff_w, 3)
        effective_contributions[key] = round(eff_c, 3)
        fam = family_map.get(key, "other")
        if fam not in family_scores:
            family_scores[fam] = 0.0
        family_scores[fam] += eff_c
        if int(vote or 0) != 0:
            active_models += 1
            active_weight += eff_w
            if direction_sign and int(vote) * direction_sign > 0:
                aligned_weight += eff_w
            elif direction_sign and int(vote) * direction_sign < 0:
                opposed_weight += eff_w
    purity = (aligned_weight / active_weight * 100.0) if active_weight > 0 and direction_sign else 0.0
    aligned_families = []
    opposed_families = []
    neutral_families = []
    for fam in family_labels:
        v = float(family_scores.get(fam, 0.0) or 0.0)
        if abs(v) < 0.20 or not direction_sign:
            neutral_families.append(fam)
        elif v * direction_sign > 0:
            aligned_families.append(fam)
        else:
            opposed_families.append(fam)
    breadth = len(aligned_families)
    breadth_factor = {0: 0.0, 1: 0.50, 2: 0.68, 3: 0.82, 4: 0.92, 5: 0.97}.get(min(5, breadth), 0.97)
    target = purity * breadth_factor
    old = float(legacy_confidence or 0.0)
    max_boost = float(cfg_get("technical_consensus_max_boost_pp", 12) or 12)
    max_penalty = float(cfg_get("technical_consensus_max_penalty_pp", 8) or 8)
    final = max(old - max_penalty, min(old + max_boost, target))
    is_real = str(cfg_get("account_type", "PRACTICE")).upper() == "REAL"
    min_families = int(cfg_get("technical_consensus_min_families_real" if is_real else "technical_consensus_min_families_demo", 3 if is_real else 2) or (3 if is_real else 2))
    family_cap = int(cfg_get("technical_consensus_single_family_cap", 59) or 59)
    if direction_sign and breadth < min_families:
        final = min(final, float(family_cap))
    final = max(0.0, min(100.0, final))
    family_detail = []
    for fam, label in family_labels.items():
        v = float(family_scores.get(fam, 0.0) or 0.0)
        st = "aligned" if fam in aligned_families else "opposed" if fam in opposed_families else "neutral"
        family_detail.append({"key": fam, "name": label, "score": round(v, 2), "status": st})
    return {
        "enabled": True,
        "confidence": int(round(final)),
        "legacy_confidence": int(round(old)),
        "target_confidence": round(target, 1),
        "purity": round(purity, 1),
        "active_models": int(active_models),
        "active_weight": round(active_weight, 2),
        "aligned_weight": round(aligned_weight, 2),
        "opposed_weight": round(opposed_weight, 2),
        "aligned_families": list(aligned_families),
        "opposed_families": list(opposed_families),
        "family_count": int(breadth),
        "min_families": int(min_families),
        "family_details": family_detail,
        "performance_multipliers": {k: round(float(v), 3) for k, v in perf.items()},
        "effective_weights": effective_weights,
        "effective_contributions": effective_contributions,
        "boost_pp": int(round(final - old)),
    }


def analyze_closes(closes: List[float], strategy: str = "combined") -> SignalDecision:
    rsi = calc_rsi(closes)
    ema9 = calc_ema(closes, 9)
    ema21 = calc_ema(closes, 21)
    ema50 = calc_ema(closes, 50)
    macd_line, macd_signal, macd_hist = calc_macd(closes)
    bb_upper, bb_mid, bb_lower, bb_pct, bb_width = calc_bb(closes)
    stoch_k, stoch_d, stoch_k_prev, stoch_d_prev = calc_stochastic(closes)
    price = closes[-1]

    votes: List[int] = []
    reasons: List[str] = []
    strategy = strategy if strategy in VALID_STRATEGIES else "combined"

    def add_vote(v: int, reason: str) -> None:
        votes.append(v)
        if v != 0:
            reasons.append(reason)

    rsi_vote = 1 if rsi <= 28 else (-1 if rsi >= 72 else 0)
    ema_vote = 1 if ema9 > ema21 and price > ema50 else (-1 if ema9 < ema21 and price < ema50 else 0)
    ema_cross_vote = calc_ema_cross_vote(closes)
    macd_vote = 1 if macd_line > macd_signal and macd_hist > 0 else (-1 if macd_line < macd_signal and macd_hist < 0 else 0)
    bb_vote = 1 if bb_pct <= 8 else (-1 if bb_pct >= 92 else 0)
    oscillator_vote = 1 if rsi <= 30 and bb_pct <= 12 else (-1 if rsi >= 70 and bb_pct >= 88 else 0)
    stochastic_vote = 0
    if stoch_k_prev <= 20 and stoch_k > 20 and stoch_k >= stoch_d:
        stochastic_vote = 1
    elif stoch_k_prev >= 80 and stoch_k < 80 and stoch_k <= stoch_d:
        stochastic_vote = -1
    sr_vote, sr_reason = calc_support_resistance_vote(closes)
    consolidation_breakout_vote, consolidation_reason = calc_consolidation_breakout_vote(closes)
    divergence_vote, divergence_reason = calc_macd_divergence_vote(closes, macd_hist)

    # Força simples das últimas velas fechadas: não é gatilho sozinho, apenas confirmação.
    momentum_vote = 0
    if len(closes) >= 4:
        recent_delta = closes[-1] - closes[-4]
        small_ref = max(abs(closes[-1]) * 0.00008, 1e-9)
        if recent_delta > small_ref:
            momentum_vote = 1
        elif recent_delta < -small_ref:
            momentum_vote = -1

    # Leituras adicionais para modelos profissionais.
    price_delta_3 = closes[-1] - closes[-4] if len(closes) >= 4 else 0
    price_delta_6 = closes[-1] - closes[-7] if len(closes) >= 7 else price_delta_3
    trend_vote = 1 if ema9 > ema21 > ema50 else (-1 if ema9 < ema21 < ema50 else 0)
    pullback_vote = 0
    if trend_vote == 1 and 38 <= rsi <= 58 and bb_pct <= 48 and macd_hist >= 0:
        pullback_vote = 1
    elif trend_vote == -1 and 42 <= rsi <= 62 and bb_pct >= 52 and macd_hist <= 0:
        pullback_vote = -1
    breakout_vote = 0
    if bb_width >= 0.025 and momentum_vote == 1 and macd_hist > 0 and price_delta_6 > 0:
        breakout_vote = 1
    elif bb_width >= 0.025 and momentum_vote == -1 and macd_hist < 0 and price_delta_6 < 0:
        breakout_vote = -1
    reversal_vote = 0
    if rsi <= 25 and bb_pct <= 6 and momentum_vote >= 0:
        reversal_vote = 1
    elif rsi >= 75 and bb_pct >= 94 and momentum_vote <= 0:
        reversal_vote = -1
    price_action_vote = 0
    if len(closes) >= 5:
        last_move = closes[-1] - closes[-2]
        prev_move = closes[-2] - closes[-3]
        body_ref = max(abs(closes[-1]) * 0.00006, 1e-9)
        if last_move > body_ref and prev_move > 0 and closes[-1] > ema9:
            price_action_vote = 1
        elif last_move < -body_ref and prev_move < 0 and closes[-1] < ema9:
            price_action_vote = -1
    volatility_vote = 0
    if bb_width >= 0.02 and bb_width <= 0.12:
        volatility_vote = momentum_vote or macd_vote

    # Metadados do consenso por regime. Permanecem neutros em estratégias individuais.
    regime_ctx: Dict[str, Any] = {}
    consensus_regime = "fixed"
    consensus_label = "Pesos fixos"
    priority_names: List[str] = []
    consensus_weights: Dict[str, int] = {}
    consensus_contributions: Dict[str, int] = {}
    consensus_effective_contributions: Dict[str, float] = {}
    technical_consensus_v2_meta: Dict[str, Any] = {}
    factory_consensus: Dict[str, Any] = {}
    factory_adjustment = 0

    if strategy == "rsi":
        add_vote(rsi_vote, f"RSI extremo {rsi}")
        score = sum(votes)
        score_total = max(1, len(votes))
        min_score = 1
    elif strategy == "ema":
        add_vote(ema_vote, "EMA9/EMA21 alinhada com EMA50")
        score = sum(votes)
        score_total = max(1, len(votes))
        min_score = 1
    elif strategy == "macd":
        add_vote(macd_vote, "MACD com histograma confirmando")
        score = sum(votes)
        score_total = max(1, len(votes))
        min_score = 1
    elif strategy == "bb":
        add_vote(bb_vote, f"Bollinger %B {bb_pct}")
        score = sum(votes)
        score_total = max(1, len(votes))
        min_score = 1
    elif strategy == "trend_sniper":
        weighted = [
            (trend_vote, 3, "Tendência EMA 9/21/50"),
            (macd_vote, 2, "MACD acompanha tendência"),
            (momentum_vote, 2, "Força das últimas velas"),
            (volatility_vote, 1, "Volatilidade saudável"),
        ]
        score = 0; score_total = 0
        for v, weight, reason in weighted:
            score += v * weight; score_total += weight
            if v != 0: reasons.append(f"{reason} x{weight}")
        min_score = 5
    elif strategy == "pullback":
        weighted = [
            (pullback_vote, 3, "Pullback a favor da tendência"),
            (trend_vote, 2, "Tendência principal"),
            (macd_vote, 1, "MACD não contradiz"),
            (momentum_vote, 1, "Retomada do movimento"),
        ]
        score = 0; score_total = 0
        for v, weight, reason in weighted:
            score += v * weight; score_total += weight
            if v != 0: reasons.append(f"{reason} x{weight}")
        min_score = 4
    elif strategy == "breakout":
        weighted = [
            (breakout_vote, 3, "Rompimento com volatilidade"),
            (momentum_vote, 2, "Impulso recente"),
            (macd_vote, 2, "MACD confirma rompimento"),
            (ema_vote, 1, "Preço alinhado à média"),
        ]
        score = 0; score_total = 0
        for v, weight, reason in weighted:
            score += v * weight; score_total += weight
            if v != 0: reasons.append(f"{reason} x{weight}")
        min_score = 5
    elif strategy == "reversal_pro":
        weighted = [
            (reversal_vote, 3, "Reversão em extremo"),
            (rsi_vote, 2, f"RSI extremo {rsi}"),
            (bb_vote, 2, f"Bollinger extremo {bb_pct}"),
            (-momentum_vote if reversal_vote else 0, 1, "Perda de força do movimento anterior"),
        ]
        score = 0; score_total = 0
        for v, weight, reason in weighted:
            score += v * weight; score_total += weight
            if v != 0: reasons.append(f"{reason} x{weight}")
        min_score = 5
    elif strategy == "volatility_flow":
        weighted = [
            (volatility_vote, 3, "Fluxo com volatilidade saudável"),
            (momentum_vote, 2, "Direção do fluxo"),
            (macd_vote, 2, "MACD confirma fluxo"),
            (ema_vote, 1, "Médias alinhadas"),
        ]
        score = 0; score_total = 0
        for v, weight, reason in weighted:
            score += v * weight; score_total += weight
            if v != 0: reasons.append(f"{reason} x{weight}")
        min_score = 5
    elif strategy == "price_action":
        weighted = [
            (price_action_vote, 3, "Price action últimas velas"),
            (momentum_vote, 2, "Continuação curta"),
            (ema_vote, 1, "Preço/média coerentes"),
            (macd_vote, 1, "Momentum técnico"),
        ]
        score = 0; score_total = 0
        for v, weight, reason in weighted:
            score += v * weight; score_total += weight
            if v != 0: reasons.append(f"{reason} x{weight}")
        min_score = 4
    elif strategy == "trend_ema_9_21":
        weighted = [
            (ema_cross_vote, 4, "Tendência iniciante EMA 9/21"),
            (macd_vote, 2, "MACD confirma tendência"),
            (momentum_vote, 1, "Força das últimas velas"),
        ]
        score = 0; score_total = 0
        for v, weight, reason in weighted:
            score += v * weight; score_total += weight
            if v != 0: reasons.append(f"{reason} x{weight}")
        min_score = 5
    elif strategy == "support_resistance":
        weighted = [
            (sr_vote, 4, sr_reason),
            (price_action_vote, 2, "Candle/fechamento confirma zona"),
            (-momentum_vote if sr_vote else 0, 1, "Perda de força contra a zona"),
        ]
        score = 0; score_total = 0
        for v, weight, reason in weighted:
            score += v * weight; score_total += weight
            if v != 0 or reason.startswith("S/R:"): reasons.append(f"{reason} x{weight}")
        min_score = 5
    elif strategy == "oscillator_rsi_bb":
        weighted = [
            (oscillator_vote, 4, f"RSI+Bollinger confluentes RSI {rsi} / %B {bb_pct}"),
            (rsi_vote, 2, f"RSI extremo {rsi}"),
            (bb_vote, 2, f"Bollinger extremo {bb_pct}"),
            (-trend_vote if oscillator_vote else 0, 1, "Evita comprar/vender contra tendência muito forte"),
        ]
        score = 0; score_total = 0
        for v, weight, reason in weighted:
            score += v * weight; score_total += weight
            if v != 0: reasons.append(f"{reason} x{weight}")
        min_score = 6
    elif strategy == "breakout_consolidation":
        weighted = [
            (consolidation_breakout_vote, 4, consolidation_reason),
            (momentum_vote, 2, "Impulso após lateralidade"),
            (macd_vote, 2, "MACD acompanha rompimento"),
            (volatility_vote, 1, "Volatilidade saudável"),
        ]
        score = 0; score_total = 0
        for v, weight, reason in weighted:
            score += v * weight; score_total += weight
            if v != 0 or reason.startswith("Breakout:"): reasons.append(f"{reason} x{weight}")
        min_score = 6
    elif strategy == "macd_divergence":
        weighted = [
            (divergence_vote, 4, divergence_reason),
            (rsi_vote, 1, f"RSI auxilia divergência {rsi}"),
            (bb_vote, 1, f"Bollinger auxilia divergência {bb_pct}"),
            (-momentum_vote if divergence_vote else 0, 1, "Perda de força do movimento"),
        ]
        score = 0; score_total = 0
        for v, weight, reason in weighted:
            score += v * weight; score_total += weight
            if v != 0 or reason.startswith("Divergência"): reasons.append(f"{reason} x{weight}")
        min_score = 5
    elif strategy == "scalp_stochastic":
        weighted = [
            (stochastic_vote, 4, f"Estocástico 5,3 cruza zona K={stoch_k} D={stoch_d}"),
            (momentum_vote, 1, "Confirmação curta do candle"),
            (price_action_vote, 1, "Price action curto"),
        ]
        score = 0; score_total = 0
        for v, weight, reason in weighted:
            score += v * weight; score_total += weight
            if v != 0: reasons.append(f"{reason} x{weight}")
        min_score = 5
    elif strategy == "ema_macd_sync":
        weighted = [
            (ema_cross_vote, 3, "EMA 9/21 sincronizada"),
            (ema_vote, 2, "EMA com tendência longa"),
            (macd_vote, 3, "MACD confirma direção"),
            (momentum_vote, 2, "Momentum confirma fluxo"),
            (trend_vote, 2, "Tendência estrutural"),
        ]
        score = 0; score_total = 0
        for v, weight, reason in weighted:
            score += v * weight; score_total += weight
            if v != 0: reasons.append(f"{reason} x{weight}")
        min_score = 8
    elif strategy == "mean_reversion_sr":
        weighted = [
            (sr_vote, 3, "Suporte/Resistência"),
            (oscillator_vote, 3, "RSI+Bollinger extremo"),
            (reversal_vote, 3, "Reversal em extremo"),
            (stochastic_vote, 2, "Estocástico de reversão"),
            (bb_vote, 1, "Bollinger extremo"),
        ]
        score = 0; score_total = 0
        for v, weight, reason in weighted:
            score += v * weight; score_total += weight
            if v != 0: reasons.append(f"{reason} x{weight}")
        min_score = 7
    elif strategy == "volatility_breakout_pro":
        weighted = [
            (breakout_vote, 4, "Breakout com expansão"),
            (consolidation_breakout_vote, 3, "Rompimento de consolidação"),
            (volatility_vote, 3, "Fluxo de volatilidade"),
            (momentum_vote, 2, "Momentum de rompimento"),
            (macd_vote, 2, "MACD de continuação"),
        ]
        score = 0; score_total = 0
        for v, weight, reason in weighted:
            score += v * weight; score_total += weight
            if v != 0: reasons.append(f"{reason} x{weight}")
        min_score = 9
    elif strategy == "adaptive_trend_pullback":
        weighted = [
            (trend_vote, 3, "Tendência estrutural"),
            (pullback_vote, 4, "Pullback a favor da tendência"),
            (ema_cross_vote, 2, "EMA 9/21"),
            (price_action_vote, 2, "Price Action de retomada"),
            (macd_vote, 1, "MACD de confirmação"),
        ]
        score = 0; score_total = 0
        for v, weight, reason in weighted:
            score += v * weight; score_total += weight
            if v != 0: reasons.append(f"{reason} x{weight}")
        min_score = 8
    elif strategy == "all_strategies":
        # V108.8.0 · Regime Consensus Engine.
        # Todas as estratégias continuam sendo calculadas, porém os mesmos 33 pontos
        # são redistribuídos conforme o contexto do mercado. Assim o regime muda a
        # RELEVÂNCIA de cada modelo sem criar um novo gatilho e sem alterar a grade
        # técnica usada pelos pisos REAL/adaptive (score_total permanece exatamente 33).
        regime_seed = {
            "bb_width": bb_width,
            "trend_vote": trend_vote,
            "ema9": ema9,
            "ema21": ema21,
            "ema50": ema50,
        }
        regime_ctx = detect_market_regime(closes, regime_seed)
        raw_regime = str(regime_ctx.get("name") or "transition")
        if raw_regime in {"trend_up", "trend_down"}:
            consensus_regime = "trend"
            consensus_label = "Tendência"
            priority_names = ["Tendência", "EMA 9/21", "Pullback", "Momentum", "Price Action"]
        elif raw_regime == "lateral":
            consensus_regime = "range"
            consensus_label = "Lateralização"
            priority_names = ["Suporte/Resistência", "RSI+Bollinger", "Reversal", "RSI", "Bollinger"]
        elif raw_regime == "volatile":
            consensus_regime = "expansion"
            consensus_label = "Expansão de volatilidade"
            priority_names = ["Breakout", "Momentum", "MACD", "Volatilidade", "Breakout Consolidação"]
        else:
            consensus_regime = "transition"
            consensus_label = "Transição / misto"
            priority_names = ["Tendência", "EMA 9/21", "MACD", "Momentum", "Price Action"]

        # Ordem fixa dos 17 modelos. Cada preset soma 33 para preservar a grade.
        weight_presets = {
            "transition": [3,3,2,2,2,2,2,2,2,2,2,2,2,2,1,1,1],
            "trend":      [4,4,3,2,3,1,3,1,1,4,1,1,1,1,1,1,1],
            "range":      [1,1,1,1,1,1,3,4,4,1,1,1,2,3,2,3,3],
            "expansion":  [1,1,2,4,4,4,2,1,1,1,4,3,1,1,1,1,1],
        }
        ws = weight_presets.get(consensus_regime, weight_presets["transition"])
        model_rows = [
            ("trend", trend_vote, "Modelo Tendência"),
            ("ema_cross", ema_cross_vote, "Modelo EMA 9/21 iniciante"),
            ("ema", ema_vote, "Modelo EMA"),
            ("macd", macd_vote, "Modelo MACD"),
            ("momentum", momentum_vote, "Modelo Momentum"),
            ("volatility", volatility_vote, "Modelo Volatilidade"),
            ("price_action", price_action_vote, "Modelo Price Action"),
            ("support_resistance", sr_vote, "Modelo Suporte/Resistência"),
            ("rsi_bollinger", oscillator_vote, "Modelo RSI+Bollinger"),
            ("pullback", pullback_vote, "Modelo Pullback"),
            ("breakout", breakout_vote, "Modelo Breakout"),
            ("breakout_consolidation", consolidation_breakout_vote, "Modelo Breakout Consolidação"),
            ("macd_divergence", divergence_vote, "Modelo Divergência MACD"),
            ("reversal", reversal_vote, "Modelo Reversal"),
            ("stochastic", stochastic_vote, "Modelo Scalp Estocástico"),
            ("rsi", rsi_vote, f"Modelo RSI {rsi}"),
            ("bollinger", bb_vote, f"Modelo Bollinger {bb_pct}"),
        ]
        weighted = [(vote, int(ws[idx]), reason) for idx, (_key, vote, reason) in enumerate(model_rows)]
        score = 0; score_total = 0
        consensus_weights: Dict[str, int] = {}
        consensus_contributions: Dict[str, int] = {}
        for idx, (key, v, reason) in enumerate(model_rows):
            weight = int(ws[idx])
            score += v * weight
            score_total += weight
            consensus_weights[key] = weight
            consensus_contributions[key] = int(v * weight)
            if v != 0:
                reasons.append(f"{reason} x{weight}")
        # Strategy Factory: uma estratégia IA já promovida pode reforçar ou reduzir
        # levemente o consenso. Nunca cria entrada sozinha e score_total permanece 33.
        factory_signals = {
            "rsi": rsi, "ema9": ema9, "ema21": ema21, "ema50": ema50,
            "macd_hist": macd_hist, "bb_pct": bb_pct, "bb_width": bb_width,
        }
        try:
            factory_consensus = ai_strategy_factory_consensus_vote(factory_signals, consensus_regime)
        except Exception:
            factory_consensus = {"vote":0,"bonus":0,"matched":None}
        fvote = int(factory_consensus.get("vote",0) or 0)
        fbonus = int(factory_consensus.get("bonus",0) or 0)
        if fvote and fbonus:
            if score == 0:
                factory_adjustment = 0
            elif (score > 0 and fvote > 0) or (score < 0 and fvote < 0):
                factory_adjustment = fvote * fbonus
            else:
                factory_adjustment = fvote * min(1, fbonus)
            score = max(-33, min(33, score + factory_adjustment))
            match = factory_consensus.get("matched") or {}
            reasons.append(f"Strategy Factory: {match.get('name','IA')} {'reforçou' if factory_adjustment and ((score>0 and fvote>0) or (score<0 and fvote<0)) else 'ajustou'} consenso {factory_adjustment:+d}")
        # Direção mínima preservada; os gates de confiança REAL/PRACTICE continuam
        # sendo aplicados posteriormente, assim como Lumi, payout, memória e Preflight.
        min_score = 12
        reasons.append(f"Regime Consensus: {consensus_label} · prioridades: {', '.join(priority_names[:3])}")
    else:
        # V13: pontuação ponderada. Tendência e momentum pesam mais; RSI/Bollinger apenas refinam entrada.
        weighted = [
            (ema_vote, 2, "Tendência EMA"),
            (macd_vote, 2, "Momentum MACD"),
            (rsi_vote, 1, f"RSI {rsi}"),
            (bb_vote, 1, f"Bollinger %B {bb_pct}"),
            (momentum_vote, 1, "Força das últimas velas"),
        ]
        score = 0
        score_total = 0
        for v, weight, reason in weighted:
            score += v * weight
            score_total += weight
            if v != 0:
                reasons.append(f"{reason} x{weight}")
        min_score = 4

    confidence_exact = abs(score) / max(1, score_total) * 100.0
    if strategy == "all_strategies" and bool(cfg_get("technical_granular_confidence_enabled", True)):
        confidence = int(round(confidence_exact))
    else:
        confidence = int(confidence_exact)
    if strategy == "all_strategies" and bool(cfg_get("technical_consensus_v2_enabled", True)):
        try:
            technical_consensus_v2_meta = _technical_consensus_v2(model_rows, ws, score, confidence_exact)
            confidence = int(technical_consensus_v2_meta.get("confidence", confidence) or confidence)
            consensus_effective_contributions = dict(technical_consensus_v2_meta.get("effective_contributions") or {})
            reasons.append(
                f"Technical Consensus V2: {int(technical_consensus_v2_meta.get('family_count',0))}/{int(technical_consensus_v2_meta.get('min_families',3))} famílias · "
                f"pureza {float(technical_consensus_v2_meta.get('purity',0)):.0f}% · confiança {int(technical_consensus_v2_meta.get('legacy_confidence',0))}%→{confidence}%"
            )
        except Exception as exc:
            technical_consensus_v2_meta = {"enabled": False, "error": str(exc)[:120], "confidence": confidence}

    direction = None
    if score >= min_score:
        direction = "call"
    elif score <= -min_score:
        direction = "put"

    # Filtro de mercado muito parado: evita operar quando a banda está comprimida demais.
    if direction and bb_width < 0.015:
        reasons.append("volatilidade baixa: sinal bloqueado")
        direction = None
        confidence = 0

    # V108.8.0 · identifica a estratégia dominante da decisão para auditoria/ranking.
    strategy_display_names = {
        "trend": "Tendência", "ema_cross": "EMA 9/21", "ema": "EMA", "macd": "MACD",
        "momentum": "Momentum", "volatility": "Volatilidade", "price_action": "Price Action",
        "support_resistance": "Suporte/Resistência", "rsi_bollinger": "RSI+Bollinger",
        "pullback": "Pullback", "breakout": "Breakout", "breakout_consolidation": "Breakout Consolidação",
        "macd_divergence": "Divergência MACD", "reversal": "Reversal", "stochastic": "Estocástico",
        "rsi": "RSI", "bollinger": "Bollinger", "trend_sniper": "Trend Sniper",
        "reversal_pro": "Reversal Pro", "volatility_flow": "Volatility Flow",
        "oscillator_rsi_bb": "RSI+Bollinger", "scalp_stochastic": "Scalp Estocástico",
        "ema_macd_sync": "EMA + MACD Sync", "mean_reversion_sr": "Mean Reversion S/R",
        "volatility_breakout_pro": "Volatility Breakout Pro", "adaptive_trend_pullback": "Adaptive Trend Pullback",
        "all_strategies": "ALL_STRATEGIES", "combined": "Combinada",
    }
    dominant_strategy_key = str(strategy)
    dominant_strategy_name = strategy_display_names.get(str(strategy), str(strategy).replace("_", " ").title())
    dominant_strategy_contribution = 0
    strategy_influences: List[str] = []
    contribution_source = consensus_effective_contributions or consensus_contributions
    if strategy == "all_strategies" and contribution_source:
        sign = 1 if score > 0 else (-1 if score < 0 else 0)
        aligned = []
        for key, contribution in contribution_source.items():
            contribution = float(contribution or 0)
            if sign and contribution * sign > 0:
                aligned.append((abs(contribution), key, contribution))
        if aligned:
            aligned.sort(reverse=True)
            _, dominant_strategy_key, dominant_strategy_contribution = aligned[0]
            dominant_strategy_name = strategy_display_names.get(dominant_strategy_key, dominant_strategy_key.replace("_", " ").title())
            strategy_influences = [strategy_display_names.get(k, k.replace("_", " ").title()) for _, k, _ in aligned[:4]]
        else:
            dominant_strategy_key = "all_strategies"
            dominant_strategy_name = f"ALL_STRATEGIES · {consensus_label}"
    factory_match = dict(factory_consensus.get("matched") or {}) if isinstance(factory_consensus, dict) else {}
    if factory_adjustment and factory_match.get("name"):
        ai_name = str(factory_match.get("name") or "Lumi Strategy")
        strategy_influences.append(ai_name)

    signals = {
        "rsi": rsi,
        "ema9": round(ema9, 6),
        "ema21": round(ema21, 6),
        "ema50": round(ema50, 6),
        "macd": macd_line,
        "macd_signal": macd_signal,
        "macd_hist": macd_hist,
        "bb_pct": bb_pct,
        "bb_width": bb_width,
        "stochastic_k": stoch_k,
        "stochastic_d": stoch_d,
        "price": price,
        "confidence": confidence,
        "reasons": reasons,
        "score": score,
        "score_total": score_total,
        "momentum_vote": momentum_vote,
        "trend_vote": trend_vote,
        "ema_cross_vote": ema_cross_vote,
        "support_resistance_vote": sr_vote,
        "oscillator_vote": oscillator_vote,
        "breakout_consolidation_vote": consolidation_breakout_vote,
        "macd_divergence_vote": divergence_vote,
        "stochastic_vote": stochastic_vote,
        "pullback_vote": pullback_vote,
        "breakout_vote": breakout_vote,
        "reversal_vote": reversal_vote,
        "price_action_vote": price_action_vote,
        "volatility_vote": volatility_vote,
        "regime_consensus_enabled": strategy == "all_strategies",
        "regime_consensus": consensus_regime,
        "regime_consensus_label": consensus_label,
        "regime_consensus_confidence": int(regime_ctx.get("confidence", 0) or 0) if regime_ctx else 0,
        "regime_consensus_direction": str(regime_ctx.get("direction", "hold") or "hold") if regime_ctx else "hold",
        "regime_consensus_efficiency": float(regime_ctx.get("efficiency", 0.0) or 0.0) if regime_ctx else 0.0,
        "regime_consensus_volatility_bps": float(regime_ctx.get("volatility_bps", 0.0) or 0.0) if regime_ctx else 0.0,
        "regime_consensus_priorities": list(priority_names),
        "regime_consensus_weights": dict(consensus_weights),
        "regime_consensus_contributions": dict(consensus_contributions),
        "regime_consensus_effective_contributions": dict(consensus_effective_contributions),
        "regime_consensus_weight_total": int(sum(consensus_weights.values())) if consensus_weights else int(score_total),
        "technical_consensus_v2": dict(technical_consensus_v2_meta),
        "technical_consensus_legacy_confidence": int(technical_consensus_v2_meta.get("legacy_confidence", round(confidence_exact)) or round(confidence_exact)) if strategy == "all_strategies" else int(round(confidence_exact)),
        "technical_consensus_family_count": int(technical_consensus_v2_meta.get("family_count", 0) or 0),
        "technical_consensus_purity": float(technical_consensus_v2_meta.get("purity", 0) or 0),
        "primary_strategy_key": dominant_strategy_key,
        "primary_strategy_name": dominant_strategy_name,
        "primary_strategy_contribution": int(dominant_strategy_contribution),
        "strategy_influences": list(dict.fromkeys(strategy_influences)),
        "ai_strategy_factory_enabled": bool(cfg_get("ai_strategy_factory_enabled", True)),
        "ai_strategy_factory_adjustment": int(factory_adjustment),
        "ai_strategy_factory_match": dict(factory_consensus.get("matched") or {}) if isinstance(factory_consensus, dict) else {},
    }
    return SignalDecision(direction, confidence, reasons, signals)


def analyze(closes: List[float]) -> SignalDecision:
    decision = analyze_closes(closes, str(cfg_get("strategy", "combined")))
    with state_lock:
        state["signals"] = decision.signals
        state["last_signal"] = decision.direction
        state["signal_panel_asset"] = cfg_get("asset", "-")
        state["signal_panel_status"] = "Indicadores do ativo selecionado."
    return decision


def build_lumi_context_snapshot(row: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    """V108.1: contexto numérico auditável exibido em Sinais e enviado à Lumi.

    Não executa I/O nem nova leitura de candles; usa somente o row já calculado.
    """
    if not row:
        return {}
    sig = row.get("signals") if isinstance(row.get("signals"), dict) else {}
    ci = row.get("candle_intelligence") if isinstance(row.get("candle_intelligence"), dict) else {}
    lumi = row.get("lumi") if isinstance(row.get("lumi"), dict) else {}
    direction = normalize_lumi_action(row.get("direction") or sig.get("direction") or "hold")
    tech = int(row.get("technical_confidence", sig.get("confidence", 0)) or 0)
    candle = int(row.get("candle_score", ci.get("score", 50)) or 50)
    pa = int(ci.get("price_action_score", 50) or 50)
    mtf = float(row.get("mtf_alignment", 50) or 50)
    fakeout = int(ci.get("false_breakout_risk", 0) or 0)
    barrier = float(ci.get("barrier_distance_atr", 0) or 0)
    macd_hist = float(sig.get("macd_hist", 0) or 0)
    technical_required = int(row.get("technical_required", cfg_get("min_technical_confidence", 0)) or 0)
    payout_required = int(row.get("payout_required", cfg_get("min_payout", 0)) or 0)
    lumi_required = int(row.get("lumi_required", cfg_get("lumi_min_confidence", 0)) or 0)
    lumi_called = bool(lumi) and str(lumi.get("source") or "").lower() not in {"", "not_called"}
    return {
        "asset": normalize_asset_name(row.get("asset", "")),
        "direction": direction.upper(),
        "tech": tech,
        "candle": candle,
        "pa": pa,
        "mtf": round(mtf, 1),
        "fakeout": fakeout,
        "barrier_atr": round(barrier, 2),
        "breakout": bool(ci.get("breakout_confirmed", False)),
        "breakout_state": str(ci.get("breakout") or "none"),
        "structure": str(ci.get("structure") or "indefinido"),
        "price_action": str(ci.get("price_action") or "indefinido"),
        "rsi": round(float(sig.get("rsi", 50) or 50), 1),
        "macd_hist": round(macd_hist, 6),
        "macd_sign": "+" if macd_hist > 0 else "-" if macd_hist < 0 else "0",
        "payout": int(row.get("payout", 0) or 0),
        "technical_required": technical_required,
        "lumi_required": lumi_required,
        "payout_required": payout_required,
        "lumi_called": lumi_called,
        "lumi_action": str(lumi.get("action") or "hold").upper() if lumi else "AGUARDANDO",
        "lumi_confidence": int(lumi.get("confidence", 0) or 0) if lumi else 0,
        "lumi_reason": str(lumi.get("reason") or lumi.get("error") or "")[:220] if lumi else "",
        "block_reason": str(row.get("block_reason") or "")[:220],
        "updated_at": now_hms(),
    }


def update_signal_panel_from_row(row: Optional[Dict[str, Any]], status: str = "") -> None:
    """Alimenta os cards RSI/MACD/EMA/Bollinger com o candidato mais relevante.

    Antes, esses cards só eram atualizados quando o loop analisava o ativo fixo
    para entrada. Em modo scanner, o bot pode bloquear a entrada antes disso
    e os cards ficavam com "—", mesmo já existindo candles calculados.
    """
    if not row:
        return
    signals = row.get("signals") or {}
    if not signals:
        return
    lumi_context_snapshot = build_lumi_context_snapshot(row)
    with state_lock:
        state["signals"] = signals
        state["last_signal"] = row.get("direction")
        state["signal_panel_asset"] = row.get("asset") or "-"
        state["signal_panel_status"] = status or row.get("decision_status") or row.get("block_reason") or "Indicadores do melhor candidato."
        state["lumi_context"] = lumi_context_snapshot
        if isinstance(row.get("candle_intelligence"), dict):
            ci = dict(row.get("candle_intelligence") or {})
            ci.update({"asset": normalize_asset_name(row.get("asset", "")), "timeframe": int(cfg_get("timeframe",300) or 300), "updated_at": now_hms()})
            state["candle_intelligence"] = ci


# ── Scanner de oportunidades OTC ──────────────────────────
def normalize_asset_name(asset: str) -> str:
    """Normaliza nomes vindos de payout/OTC antes de consultar candles."""
    asset = str(asset or "").strip().upper()
    # Alguns retornos podem aparecer como BTCUSD-OTC-op; candle costuma usar BTCUSD-OTC.
    if asset.endswith("-OP"):
        asset = asset[:-3]
    aliases = {
        "JPN225-OTC": "JP225-OTC",
        "FACEBOOK-OTC": "FB-OTC",
        "US500-OTC": "SP500-OTC",
        "NASDAQ-OTC": "NAS100-OTC",
        "DOWJONES-OTC": "US30-OTC",
    }
    return aliases.get(asset, asset)


def is_supported_by_local_consts(asset: str) -> bool:
    """Consulta apenas o cache local já sincronizado; não é filtro de descoberta."""
    if not IQOPTION_ACTIVES:
        return True
    return asset in IQOPTION_ACTIVES


def is_otc_asset(asset: str) -> bool:
    return "OTC" in asset.upper()


def is_crypto_asset(asset: str) -> bool:
    raw = str(asset or "").upper().replace("-OTC", "")
    for base in CRYPTO_BASES:
        if raw == f"{base}USD" or raw.startswith(base):
            return True
    return False


def _asset_allowed_for_market_mode(asset: str, mode: Optional[str] = None) -> bool:
    """V108.8.0: autoridade única de elegibilidade por modo, usada por scanner e workers."""
    asset = normalize_asset_name(asset)
    mode = normalize_market_mode(mode if mode is not None else cfg_get("market_mode", "auto"))
    if not asset:
        return False
    if mode == "otc_only":
        return is_otc_asset(asset)
    if mode == "crypto_only":
        return (not is_otc_asset(asset)) and is_crypto_asset(asset)
    if mode == "normal_only":
        return not is_otc_asset(asset)  # Forex/Binárias normais + Cripto
    return True


def _filter_assets_for_market_mode(assets: Any, mode: Optional[str] = None) -> List[str]:
    mode = normalize_market_mode(mode if mode is not None else cfg_get("market_mode", "auto"))
    out: List[str] = []
    seen = set()
    for raw in list(assets or []):
        asset = normalize_asset_name(raw)
        if asset and asset not in seen and _asset_allowed_for_market_mode(asset, mode):
            seen.add(asset)
            out.append(asset)
    return out


def _market_mode_snapshot() -> Tuple[str, int]:
    global MARKET_MODE_ACTIVE, MARKET_MODE_GENERATION
    with MARKET_MODE_ISOLATION_LOCK:
        mode = normalize_market_mode(cfg_get("market_mode", MARKET_MODE_ACTIVE or "auto"))
        return mode, int(MARKET_MODE_GENERATION)


def _apply_market_mode_isolation(new_mode: Any, reason: str = "config", force: bool = False) -> Dict[str, Any]:
    """Troca o universo ativo sem apagar aprendizado histórico.

    Preserva Signal Lab/Shadow resolvido e last-known-good histórico, mas remove do caminho
    ativo qualquer símbolo incompatível com o novo modo: universo cached, quote priorities e
    snapshot de payout da rodada. Shadows antigos pendentes continuam apenas para resolução.
    """
    global MARKET_MODE_ACTIVE, MARKET_MODE_GENERATION, FAST_MARKET_INTEL_CURSOR
    mode = normalize_market_mode(new_mode)
    with MARKET_MODE_ISOLATION_LOCK:
        old = normalize_market_mode(MARKET_MODE_ACTIVE or cfg_get("market_mode", "auto"))
        changed = force or old != mode
        if changed:
            MARKET_MODE_GENERATION += 1
        generation = int(MARKET_MODE_GENERATION)
        MARKET_MODE_ACTIVE = mode

    removed_universe = removed_quote = removed_payout = 0
    active_assets: List[str] = []
    with state_lock:
        state["market_mode"] = mode
        state["scanner_otc_only"] = mode == "otc_only"
        cached = dict(cfg_get("_last_market_universe") or {})
        before = list(cached.get("assets") or [])
        if before:
            active_assets = _filter_assets_for_market_mode(before, mode)
            removed_universe = max(0, len(before) - len(active_assets))
            meta = dict(cached.get("meta") or {})
            meta.update({
                "configured_mode": mode, "configured_label": market_mode_label(mode),
                "used_mode": "mode_switch_isolated_cache",
                "reason": f"V108.8.0: cache refiltrado imediatamente para {market_mode_label(mode)}",
                "selected_otc_count": sum(1 for a in active_assets if is_otc_asset(a)),
                "selected_crypto_count": sum(1 for a in active_assets if (not is_otc_asset(a)) and is_crypto_asset(a)),
                "selected_normal_count": sum(1 for a in active_assets if (not is_otc_asset(a)) and not is_crypto_asset(a)),
                "mode_generation": generation,
            })
            state["_last_market_universe"] = {**cached, "assets": active_assets, "meta": meta, "saved_at": time.time()}
        state["_market_mode_generation"] = generation
        state["_market_mode_isolation"] = {
            "mode": mode, "label": market_mode_label(mode), "generation": generation,
            "reason": str(reason or "config"), "updated_at": now_hms(),
        }

    # Cooldowns de preflight de outro modo também não devem atravessar a troca.
    with PREFLIGHT_RELIABILITY_LOCK:
        for asset in list(PREFLIGHT_TIMEOUT_COOLDOWN.keys()):
            if not _asset_allowed_for_market_mode(asset, mode):
                PREFLIGHT_TIMEOUT_COOLDOWN.pop(asset, None)

    # Quote Cache histórico pode permanecer, mas nenhum símbolo incompatível fica prioritário.
    with QUOTE_CACHE_LOCK:
        for asset in list(QUOTE_PRIORITY.keys()):
            if not _asset_allowed_for_market_mode(asset, mode):
                QUOTE_PRIORITY.pop(asset, None)
                removed_quote += 1

    # Snapshot corrente não pode carregar payout OTC para uma rodada normal_only e vice-versa.
    try:
        items = dict(PAYOUT_ROUND_SNAPSHOT.get("items") or {})
        filtered = {a: v for a, v in items.items() if _asset_allowed_for_market_mode(a, mode)}
        removed_payout = max(0, len(items) - len(filtered))
        if removed_payout:
            PAYOUT_ROUND_SNAPSHOT["items"] = filtered
            PAYOUT_ROUND_SNAPSHOT["ts"] = 0.0  # força snapshot fresco do novo universo
            PAYOUT_ROUND_SNAPSHOT["source"] = "mode_switch_invalidated"
    except Exception:
        pass

    FAST_MARKET_INTEL_CURSOR = 0
    if changed:
        counts = {
            "otc": sum(1 for a in active_assets if is_otc_asset(a)),
            "crypto": sum(1 for a in active_assets if (not is_otc_asset(a)) and is_crypto_asset(a)),
            "normal": sum(1 for a in active_assets if (not is_otc_asset(a)) and not is_crypto_asset(a)),
        }
        log(
            f"🔄 MARKET MODE SWITCH V108.8.0 | {market_mode_label(old)} → {market_mode_label(mode)} · geração={generation} · "
            f"cache ativo={len(active_assets)} (normal={counts['normal']} cripto={counts['crypto']} OTC={counts['otc']}) · "
            f"removidos universo/quote/payout={removed_universe}/{removed_quote}/{removed_payout} · Shadow histórico preservado; novos Shadows seguem somente o modo atual.",
            "info",
        )
    return {"old": old, "mode": mode, "generation": generation, "changed": changed, "active": len(active_assets)}


def _market_mode_generation_changed(generation: int) -> bool:
    with MARKET_MODE_ISOLATION_LOCK:
        return int(MARKET_MODE_GENERATION) != int(generation)


def _buyability_prune(now: Optional[float] = None) -> None:
    """Remove falsos-OPEN e recusas antigas sem bloquear o scanner."""
    now_ts = float(now if now is not None else time.time())
    window = max(5, int(cfg_get("buyability_normal_reject_window_minutes", 30) or 30)) * 60
    with LUMI_CACHE_LOCK:
        expired = [k for k, item in BUYABILITY_FALSE_OPEN_CACHE.items() if float((item or {}).get("until", 0) or 0) <= now_ts]
        for key in expired:
            BUYABILITY_FALSE_OPEN_CACHE.pop(key, None)
        BUYABILITY_NORMAL_REJECTIONS[:] = [ts for ts in BUYABILITY_NORMAL_REJECTIONS if now_ts - float(ts or 0) <= window]
        false_count = len(BUYABILITY_FALSE_OPEN_CACHE)
    with state_lock:
        state["buyability_false_open_count"] = false_count


def buyability_false_open_remaining(asset: str) -> int:
    key = normalize_asset_name(asset)
    now_ts = time.time()
    _buyability_prune(now_ts)
    with LUMI_CACHE_LOCK:
        item = BUYABILITY_FALSE_OPEN_CACHE.get(key) or {}
        until = float(item.get("until", 0) or 0)
    return max(0, int(until - now_ts))


def buyability_false_open_reason(asset: str) -> str:
    key = normalize_asset_name(asset)
    with LUMI_CACHE_LOCK:
        item = BUYABILITY_FALSE_OPEN_CACHE.get(key) or {}
    return str(item.get("reason") or "api.buy recusou apesar de V2 OPEN")


def buyability_false_open_assets() -> List[str]:
    _buyability_prune()
    with LUMI_CACHE_LOCK:
        return sorted(BUYABILITY_FALSE_OPEN_CACHE.keys())


def buyability_otc_priority_remaining() -> int:
    global BUYABILITY_OTC_PRIORITY_UNTIL
    now_ts = time.time()
    try:
        remaining = max(0, int(float(BUYABILITY_OTC_PRIORITY_UNTIL or 0.0) - now_ts))
    except Exception:
        remaining = 0
    if remaining <= 0:
        with state_lock:
            state["buyability_otc_priority_until"] = 0.0
            state["buyability_otc_priority_reason"] = ""
    return remaining


def _buyability_is_weekend() -> bool:
    try:
        return int(time.localtime().tm_wday) >= 5
    except Exception:
        return False


def _record_buyability_success(asset: str) -> None:
    """Uma compra aceita é a melhor evidência de negociabilidade do instrumento."""
    key = normalize_asset_name(asset)
    with LUMI_CACHE_LOCK:
        BUYABILITY_FALSE_OPEN_CACHE.pop(key, None)
    _buyability_prune()


def _record_buyability_rejection(asset: str, reason: str) -> Dict[str, Any]:
    """Aprende com uma recusa explícita da corretora.

    `asset unavailable` cria FALSE-OPEN por 2h (configurável). Em ativos normais,
    várias recusas na janela ativam prioridade OTC por 30min, sem declarar que
    todo o mercado normal está fechado.
    """
    global BUYABILITY_OTC_PRIORITY_UNTIL, BUYABILITY_OTC_PRIORITY_REASON
    key = normalize_asset_name(asset)
    now_ts = time.time()
    info = {"false_open": False, "false_open_minutes": 0, "normal_rejects": 0, "otc_priority_seconds": 0}
    if not _is_asset_unavailable_error(reason):
        return info

    false_minutes = max(30, int(cfg_get("buyability_false_open_minutes", 120) or 120))
    with LUMI_CACHE_LOCK:
        previous = BUYABILITY_FALSE_OPEN_CACHE.get(key) or {}
        count = int(previous.get("count", 0) or 0) + 1
        BUYABILITY_FALSE_OPEN_CACHE[key] = {
            "until": now_ts + false_minutes * 60,
            "reason": str(reason or "asset unavailable")[:220],
            "count": count,
            "last_ts": now_ts,
        }
    info.update({"false_open": True, "false_open_minutes": false_minutes})
    log(
        f"🚫 Buyability FALSE-OPEN: {key} bloqueado por {false_minutes}min — V2 pode indicar OPEN, "
        f"mas api.buy recusou o instrumento. Motivo: {str(reason)[:140]}",
        "warn",
    )

    if not is_otc_asset(key) and not is_crypto_asset(key):
        window_minutes = max(5, int(cfg_get("buyability_normal_reject_window_minutes", 30) or 30))
        threshold = max(2, int(cfg_get("buyability_normal_reject_threshold", 3) or 3))
        priority_minutes = max(5, int(cfg_get("buyability_otc_priority_minutes", 30) or 30))
        with LUMI_CACHE_LOCK:
            BUYABILITY_NORMAL_REJECTIONS.append(now_ts)
        _buyability_prune(now_ts)
        with LUMI_CACHE_LOCK:
            reject_count = len(BUYABILITY_NORMAL_REJECTIONS)
        info["normal_rejects"] = reject_count
        if reject_count >= threshold and normalize_market_mode(cfg_get("market_mode", "auto")) not in {"normal_only", "crypto_only"}:
            new_until = now_ts + priority_minutes * 60
            was_active = buyability_otc_priority_remaining() > 0
            BUYABILITY_OTC_PRIORITY_UNTIL = max(float(BUYABILITY_OTC_PRIORITY_UNTIL or 0.0), new_until)
            BUYABILITY_OTC_PRIORITY_REASON = f"{reject_count} recusas normais em {window_minutes}min"
            with state_lock:
                state["buyability_otc_priority_until"] = BUYABILITY_OTC_PRIORITY_UNTIL
                state["buyability_otc_priority_reason"] = BUYABILITY_OTC_PRIORITY_REASON
            info["otc_priority_seconds"] = max(0, int(BUYABILITY_OTC_PRIORITY_UNTIL - now_ts))
            if not was_active:
                log(
                    f"⚡ Buyability Engine: {reject_count} recusas recentes em ativos normais; "
                    f"OTC será priorizado por {priority_minutes}min. O mercado normal continua disponível como fallback.",
                    "warn",
                )

    _buyability_prune(now_ts)
    return info


def order_failure_key(asset: str) -> str:
    return normalize_asset_name(asset)


def is_order_failure_blocked(asset: str) -> int:
    key = order_failure_key(asset)
    now = time.time()
    with LUMI_CACHE_LOCK:
        item = ORDER_FAILURE_BLOCKS.get(key)
        if not item:
            return 0
        until = float(item.get("until", 0) or 0)
        if until <= now:
            ORDER_FAILURE_BLOCKS.pop(key, None)
            return 0
        return max(1, int(until - now))


def order_failure_reason(asset: str) -> str:
    key = order_failure_key(asset)
    with LUMI_CACHE_LOCK:
        item = ORDER_FAILURE_BLOCKS.get(key) or {}
    return str(item.get("reason") or "falha anterior ao abrir ordem")


def normal_market_block_remaining() -> int:
    """Quando binárias normais retornam api.buy=False, o modo auto passa a priorizar OTC por alguns minutos."""
    try:
        return max(0, int(float(globals().get("NORMAL_MARKET_FAIL_UNTIL", 0.0)) - time.time()))
    except Exception:
        return 0

def mark_normal_market_temporarily_unavailable(reason: str = "binária normal recusou ordem") -> int:
    """Prioriza OTC após recusa REAL do api.buy em mercado normal.

    Primeira recusa: 30min (configurável). Reincidência dentro da janela de reset:
    60min. Isso evita voltar ao mesmo mercado normal recusado a cada 5 minutos.
    Retorna os minutos efetivamente aplicados.
    """
    global NORMAL_MARKET_FAIL_UNTIL, NORMAL_MARKET_FAIL_COUNT, NORMAL_MARKET_LAST_FAIL_TS
    now = time.time()
    first_minutes = max(15, int(cfg_get("normal_market_first_block_minutes", 30) or 30))
    repeat_minutes = max(first_minutes, int(cfg_get("normal_market_repeat_block_minutes", 60) or 60))
    reset_minutes = max(30, int(cfg_get("normal_market_failure_reset_minutes", 120) or 120))

    if (not NORMAL_MARKET_LAST_FAIL_TS) or (now - NORMAL_MARKET_LAST_FAIL_TS > reset_minutes * 60):
        NORMAL_MARKET_FAIL_COUNT = 0
    NORMAL_MARKET_FAIL_COUNT += 1
    NORMAL_MARKET_LAST_FAIL_TS = now
    minutes = first_minutes if NORMAL_MARKET_FAIL_COUNT == 1 else repeat_minutes

    NORMAL_MARKET_FAIL_UNTIL = max(float(globals().get("NORMAL_MARKET_FAIL_UNTIL", 0.0) or 0.0), now + minutes * 60)
    with state_lock:
        state["normal_market_fail_until"] = NORMAL_MARKET_FAIL_UNTIL
        state["normal_market_fail_reason"] = reason[:180]
        state["normal_market_fail_count"] = NORMAL_MARKET_FAIL_COUNT
        state["normal_market_fail_minutes"] = minutes
    nivel = "primeira recusa" if NORMAL_MARKET_FAIL_COUNT == 1 else f"reincidência #{NORMAL_MARKET_FAIL_COUNT}"
    current_mode = normalize_market_mode(cfg_get("market_mode", "auto"))
    if current_mode in {"normal_only", "crypto_only"}:
        log(f"Mercado normal em quarentena por {minutes}min ({nivel}); OTC NÃO será usado porque o modo atual é {market_mode_label(current_mode)}. Motivo: {reason[:120]}", "warn")
    else:
        log(f"Mercado normal em quarentena; priorizando OTC por {minutes}min ({nivel}). Motivo: {reason[:120]}", "warn")
    return minutes


def block_order_failure(asset: str, reason: str = "falha ao abrir ordem") -> None:
    minutes = max(30, int(cfg_get("order_failure_block_minutes", 30) or 30))
    if _is_asset_unavailable_error(reason):
        minutes = max(minutes, int(cfg_get("buyability_false_open_minutes", 120) or 120))
    key = order_failure_key(asset)
    with LUMI_CACHE_LOCK:
        ORDER_FAILURE_BLOCKS[key] = {"until": time.time() + minutes * 60, "reason": reason[:180]}
    log(f"Ativo {key} bloqueado por {minutes}min após falha de abertura. Motivo: {reason[:120]}", "warn")
    if not is_otc_asset(key):
        # Active not found e "asset is not available at the moment" são falhas
        # específicas do instrumento. Não derrubam todo o mercado normal.
        if _is_asset_specific_buy_error(reason):
            log(f"Mercado normal mantido ativo: falha de {key} é específica deste instrumento; os demais ativos continuam liberados.", "info")
        else:
            # Apenas recusas que não sejam claramente específicas do ativo podem
            # ativar a quarentena global do mercado normal.
            mark_normal_market_temporarily_unavailable(reason)


def otc_variant(asset: str) -> str:
    asset = normalize_asset_name(asset)
    return asset if is_otc_asset(asset) else f"{asset}-OTC"


def revalidate_before_entry(api: Any, asset: str, tf: int, direction: str, min_tech: int, min_payout: int, strategy: str) -> Tuple[bool, str, Optional[int], Optional[SignalDecision], Optional[List[Tuple[int, float]]], int]:
    """Revalida ativo/candles/payout logo antes de abrir ordem.

    Isso evita o caso visto no log: o sinal foi aprovado alguns minutos antes,
    mas no segundo da entrada o ativo normal já não aceitava ordem.
    """
    asset = normalize_asset_name(asset)
    if str(cfg_get("account_type", "PRACTICE")).upper() == "REAL":
        min_tech = max(int(min_tech), REAL_HARD_TECH_FLOOR)
    blocked = is_order_failure_blocked(asset)
    if blocked:
        return False, f"ativo bloqueado por falha anterior; tentar novamente em {blocked}s", None, None, None, 0
    if not is_supported_by_local_consts(asset):
        sync = _sync_active_opcode_from_live(api, asset, max(1, int(tf or 300) // 60), force_refresh=True)
        if not sync.get("ok"):
            return False, "ativo não reconhecido por get_all_init/get_all_init_v2", None, None, None, 0
    payout = get_payout(api, asset)
    if real_requires_valid_payout() and int(payout or 0) <= 0:
        return False, "payout não retornado pela API em REAL", None, None, None, payout
    if payout and payout < min_payout:
        return False, f"payout caiu para {payout}% antes da entrada", None, None, None, payout
    try:
        candles = api.get_candles(asset, tf, 80, time.time())
        closed = get_closed_candles(candles or [], tf)
    except Exception as e:
        return False, f"falha ao recarregar velas antes da entrada: {str(e)[:120]}", None, None, None, payout
    if len(closed) < 50:
        return False, "histórico insuficiente ao revalidar antes da entrada", None, None, None, payout
    closes = [c for _, c in closed]
    fresh_decision = analyze_closes(closes, strategy)
    if fresh_decision.direction != direction:
        return False, f"sinal mudou antes da entrada: {fresh_decision.direction or 'HOLD'}", closed[-1][0], fresh_decision, closed, payout
    if fresh_decision.confidence < min_tech:
        return False, f"confiança caiu antes da entrada: {fresh_decision.confidence}% < {min_tech}%", closed[-1][0], fresh_decision, closed, payout
    return True, "ativo revalidado para entrada", closed[-1][0], fresh_decision, closed, payout


def try_otc_recovery_after_normal_reject(
    api: Any, asset: str, direction: str, amount: float, duration_min: int, tf: int,
    min_tech: int, min_payout: int, strategy: str
) -> Tuple[bool, Any, str, Optional[SignalDecision], Optional[List[Tuple[int, float]]], Optional[int], int, str]:
    """Após api.buy=False em ativo normal, tenta o correspondente OTC com NOVA análise.

    Não copia cegamente o sinal do mercado normal: recarrega candles OTC, recalcula
    indicadores/direção/confiança, reconsulta payout e reaplica as travas finais.
    """
    current_mode = normalize_market_mode(cfg_get("market_mode", "auto"))
    if current_mode in {"normal_only", "crypto_only"}:
        return False, None, "", None, None, None, 0, f"recuperação OTC proibida pelo modo {market_mode_label(current_mode)}"
    if not bool(cfg_get("otc_recovery_after_normal_reject", True)):
        return False, None, "", None, None, None, 0, "recuperação OTC desativada"
    if is_otc_asset(asset):
        return False, None, "", None, None, None, 0, "ativo recusado já era OTC"

    alt = otc_variant(asset)
    if not alt or alt == asset:
        return False, None, alt, None, None, None, 0, "sem variante OTC"
    if not is_supported_by_local_consts(alt):
        sync_alt = _sync_active_opcode_from_live(api, alt, max(1, int(duration_min or 5)), force_refresh=True)
        if not sync_alt.get("ok"):
            return False, None, alt, None, None, None, 0, "variante OTC ausente em get_all_init/get_all_init_v2"

    log(f"🔄 Recuperação OTC: {asset} recusado; recalculando {alt} antes de qualquer nova ordem...", "warn")
    ok, reason, candle_ts, fresh_decision, fresh_closed, payout = revalidate_before_entry(
        api, alt, tf, direction, min_tech, min_payout, strategy
    )
    if not ok or fresh_decision is None:
        log(f"Recuperação OTC cancelada em {alt}: {reason}", "info")
        return False, None, alt, fresh_decision, fresh_closed, candle_ts, int(payout or 0), reason

    pf_alt = market_preflight_final_fast(api, alt, duration_min=duration_min)
    if not pf_alt.get("ok"):
        reason_pf = f"preflight {str(pf_alt.get('product') or '').upper()} recusou OTC: {pf_alt.get('reason')}"
        log(f"Recuperação OTC cancelada em {alt}: {reason_pf}", "warn")
        return False, None, alt, fresh_decision, fresh_closed, candle_ts, int(payout or 0), reason_pf

    final_block = safety_block_reason(
        alt, candle_ts, int(payout or 0),
        ignore_entry_window=bool(cfg_get("immediate_entry_after_approval", True)),
    )
    if final_block:
        reason2 = f"trava final OTC: {final_block}"
        log(f"Recuperação OTC cancelada em {alt}: {reason2}", "info")
        return False, None, alt, fresh_decision, fresh_closed, candle_ts, int(payout or 0), reason2

    log(
        f"⚡ OTC revalidado: {alt} {direction.upper()} · técnica {fresh_decision.confidence}% · payout {int(payout or 0)}% · enviando ordem.",
        direction,
    )
    status, order_id, buy_error = _buy_result(api, amount, alt, direction, duration_min)
    if not status:
        exact_reason = f"api.buy OTC recusado: {buy_error}"
        block_order_failure(alt, exact_reason)
        log(f"❌ IQ Option recusou {alt} {direction.upper()} {duration_min}min: {buy_error}", "error")
        return False, None, alt, fresh_decision, fresh_closed, candle_ts, int(payout or 0), f"IQ Option também recusou a variante OTC: {buy_error}"

    return True, order_id, alt, fresh_decision, fresh_closed, candle_ts, int(payout or 0), "ordem OTC aberta após revalidação"



def _option_product_for_duration(duration_min: Optional[int] = None) -> str:
    """Mapeia a duração usada por api.buy para o produto binário da IQ Option.

    Na iqoptionapi clássica, expirações de 1 a 5 minutos são TURBO; acima disso,
    o produto esperado é BINARY. O preflight precisa validar o MESMO produto que
    será usado na ordem, para não aceitar `binary=open` quando `turbo=closed`.
    """
    try:
        duration = int(duration_min if duration_min is not None else max(1, int(cfg_get("timeframe", 300) or 300) // 60))
    except Exception:
        duration = 5
    return "turbo" if 1 <= duration <= 5 else "binary"


def _direct_asset_payload(data: Any, asset: str) -> Any:
    """Busca o ativo apenas no nível informado, sem atravessar turbo/binary."""
    if not isinstance(data, dict):
        return None
    variants = set(_asset_lookup_variants(asset))
    for key, value in data.items():
        try:
            key_txt = str(key)
            key_norm = normalize_asset_name(key_txt)
            key_base = key_txt.upper().replace("-OTC", "")
            if key_txt in variants or key_norm in variants or key_base in variants:
                return value
        except Exception:
            continue
    return None


def _find_option_product_payload(data: Any, asset: str, product: str) -> Any:
    """Localiza o payload do ativo especificamente dentro de TURBO ou BINARY.

    Suporta as duas formas mais comuns da iqoptionapi:
      {"turbo": {"EURUSD": {...}}, "binary": {...}}
      {"EURUSD": {"turbo": {...}, "binary": {...}}}
    e níveis intermediários como `msg`/`actives`.
    """
    if not isinstance(data, dict):
        return None
    product = str(product or "turbo").strip().lower()

    # Forma: {asset: {turbo:{...}, binary:{...}}}
    direct_asset = _direct_asset_payload(data, asset)
    if isinstance(direct_asset, dict):
        sub = direct_asset.get(product)
        if sub is not None:
            return sub

    # Forma: {turbo: {asset:{...}}}
    product_node = data.get(product)
    if isinstance(product_node, dict):
        direct = _direct_asset_payload(product_node, asset)
        if direct is not None:
            return direct
        # Algumas versões usam ids/actives em mais um nível.
        for child in product_node.values():
            if isinstance(child, dict):
                direct = _direct_asset_payload(child, asset)
                if direct is not None:
                    return direct

    # Procura recursiva controlada para wrappers como msg/result/data.
    for key, value in data.items():
        if key in {"turbo", "binary"}:
            continue
        if isinstance(value, dict):
            found = _find_option_product_payload(value, asset, product)
            if found is not None:
                return found
    return None


def _market_payload_flag_text(payload: Any) -> str:
    """Resumo curto das flags relevantes para diagnóstico do preflight."""
    if not isinstance(payload, dict):
        return "payload=ausente"
    parts: List[str] = []
    for key in ("enabled", "is_suspended", "suspended", "open", "is_open", "opened", "available", "tradable"):
        if key in payload:
            parts.append(f"{key}={payload.get(key)!r}")
    return ", ".join(parts) if parts else "flags explícitas ausentes"


def _format_buy_rejection(response: Any) -> str:
    """Preserva a resposta real do segundo retorno de api.buy quando status=False."""
    if response is None:
        # stable_api.buy retorna (False, None) após ~5s sem resposta.
        return "sem resposta da IQ Option em até 5s (timeout interno da iqoptionapi)"
    if isinstance(response, (dict, list, tuple)):
        try:
            txt = json.dumps(response, ensure_ascii=False, default=str)
        except Exception:
            txt = str(response)
    else:
        txt = str(response)
    txt = re.sub(r"\s+", " ", txt).strip()
    return txt[:500] or "resposta vazia da IQ Option"


def _buy_result(api: Any, amount: float, asset: str, direction: str, duration_min: int) -> Tuple[bool, Any, str]:
    """Executa api.buy usando o opcode LIVE já validado pelo Dual Cache.

    V108.8.0 não faz get_all_init síncrono antes da ordem. Se a IQ responder
    explicitamente `Active not found`, aí sim uma ressincronização excepcional é
    feita pela sessão Market Data antes de um único retry seguro.
    """
    asset = normalize_asset_name(asset)
    product = _option_product_for_duration(duration_min)
    live_id = _cached_live_active_opcode(asset, product)
    before = _local_active_opcode(asset)
    if live_id is not None:
        changed = _set_live_active_opcode(asset, live_id)
        if changed:
            log(f"🔄 Active opcode do Dual Cache aplicado antes da ordem: {asset} {before} → {live_id} ({product.upper()}).", "info")

    status, response = api.buy(amount, asset, direction, duration_min)
    if status:
        _record_buyability_success(asset)
        return True, response, ""
    first_error = _format_buy_rejection(response)

    # Resposta explícita de símbolo/opcode inválido é segura para retry: a primeira
    # tentativa foi rejeitada antes de criar uma ordem. Não fazemos retry em timeout.
    if _is_active_not_found_error(first_error):
        resync_api = get_market_data_api(api)
        resync = _sync_active_opcode_from_live(resync_api, asset, duration_min, force_refresh=True)
        live_id = resync.get("live_active_id")
        before = resync.get("local_active_id_before")
        after = resync.get("local_active_id_after")
        if live_id is not None:
            log(
                f"🔄 IQ Option respondeu Active not found em {asset}; opcode LIVE ressincronizado "
                f"{before} → {after} ({str(resync.get('product')).upper()}) e será feita 1 nova tentativa.",
                "warn",
            )
            status2, response2 = api.buy(amount, asset, direction, duration_min)
            if status2:
                _record_buyability_success(asset)
                log(f"✅ Retry após ressincronização de opcode abriu {asset} com sucesso. ID:{response2}", "info")
                return True, response2, ""
            second_error = _format_buy_rejection(response2)
            return False, None, f"{second_error} (após ressincronização live active_id={live_id})"
        return False, None, f"{first_error} (get_all_init não forneceu active_id LIVE para {asset})"

    if _is_asset_unavailable_error(first_error):
        # Não repete uma compra explicitamente recusada por indisponibilidade.
        # A recusa passa a ser evidência do Buyability Engine, mesmo se o V2 continuar OPEN.
        _record_buyability_rejection(asset, first_error)
        # Atualiza apenas o snapshot v2 para que a próxima varredura já enxergue
        # o estado mais recente do instrumento.
        detail_v2, v2_err = _binary_open_v2_snapshot(get_market_data_api(api), force_refresh=True)
        product = _option_product_for_duration(duration_min)
        v2_state, _v2_payload, v2_flags = _v2_product_state(detail_v2, asset, product)
        state_txt = "OPEN" if v2_state is True else ("CLOSED" if v2_state is False else "UNKNOWN")
        log(
            f"🔄 Snapshot v2 atualizado após recusa de {asset}: {product.upper()} {state_txt} · {v2_flags}"
            + (f" · {v2_err[:100]}" if v2_err else ""),
            "warn",
        )
        return False, None, f"{first_error} [v2 após recusa: {state_txt} · {v2_flags}]"

    return False, None, first_error

def _boolish_market_flag(value: Any) -> Optional[bool]:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)) and value in (0, 1):
        return bool(value)
    if isinstance(value, str):
        low = value.strip().lower()
        if low in {"1", "true", "yes", "sim", "open", "opened", "enabled", "available", "tradable"}:
            return True
        if low in {"0", "false", "no", "nao", "não", "closed", "disabled", "unavailable", "suspended"}:
            return False
    return None


def _market_payload_open_state(payload: Any) -> Optional[bool]:
    """Extrai somente flags explícitas de negociabilidade; não adivinha por payout."""
    if not isinstance(payload, dict):
        return None
    negative_keys = ("suspended", "is_suspended", "disabled", "closed", "is_closed")
    positive_keys = ("open", "opened", "is_open", "enabled", "available", "tradable", "is_tradable")
    for key in negative_keys:
        if key in payload:
            flag = _boolish_market_flag(payload.get(key))
            if flag is True:
                return False
            # suspended=False / closed=False apenas dizem que ESTA trava negativa
            # não está ativa; não provam que o instrumento esteja habilitado.
            # Continua para conferir enabled/open e evitar falso OPEN.
    for key in positive_keys:
        if key in payload:
            flag = _boolish_market_flag(payload.get(key))
            if flag is not None:
                return flag
    # Alguns retornos aninham os metadados do mesmo ativo em turbo/binary.
    nested_states: List[bool] = []
    for key in ("turbo", "binary"):
        sub = payload.get(key)
        if isinstance(sub, dict):
            st = _market_payload_open_state(sub)
            if st is not None:
                nested_states.append(st)
    if any(nested_states):
        return True
    if nested_states and not any(nested_states):
        return False
    return None



def _binary_init_detail_and_opcodes(init_info: Any) -> Tuple[Dict[str, Any], Dict[str, Dict[str, int]]]:
    """Converte get_all_init() em detalhe por símbolo + mapa LIVE de active_id.

    A stable_api usa o ID numérico em OP_code.ACTIVES na hora de api.buy(). O
    get_all_init() é a fonte viva que também alimenta get_binary_option_detail(),
    então manter os dois derivados do MESMO snapshot evita OPEN com opcode antigo.
    """
    detail: Dict[str, Any] = {}
    opcodes: Dict[str, Dict[str, int]] = {"turbo": {}, "binary": {}}
    if not isinstance(init_info, dict):
        return detail, opcodes
    result = init_info.get("result")
    if not isinstance(result, dict):
        return detail, opcodes
    for product in ("turbo", "binary"):
        node = result.get(product)
        actives = node.get("actives") if isinstance(node, dict) else None
        if not isinstance(actives, dict):
            continue
        for raw_id, payload in actives.items():
            if not isinstance(payload, dict):
                continue
            raw_name = str(payload.get("name") or "").strip()
            if "." in raw_name:
                raw_name = raw_name.split(".", 1)[1]
            asset_name = normalize_asset_name(raw_name)
            if not asset_name:
                continue
            try:
                live_id = int(raw_id)
            except Exception:
                # Algumas forks também carregam o id dentro do próprio payload.
                live_id = None
                for key in ("active_id", "activeId", "id"):
                    try:
                        candidate = payload.get(key)
                        if candidate is not None:
                            live_id = int(candidate)
                            break
                    except Exception:
                        pass
                if live_id is None:
                    continue
            detail.setdefault(asset_name, {})[product] = payload
            opcodes.setdefault(product, {})[asset_name] = live_id
    return detail, opcodes



def _binary_v2_detail(v2_info: Any) -> Dict[str, Any]:
    """Converte get_all_init_v2() em detalhe por símbolo/produto.

    A iqoptionapi usa get_all_init_v2() dentro de get_all_open_time() para decidir
    se TURBO/BINARY está realmente disponível no instante atual. Diferente do
    get_all_init(), este snapshot é usado SOMENTE para OPEN/CLOSED; opcode/payout
    continuam vindo do v1.
    """
    detail: Dict[str, Any] = {}
    if not isinstance(v2_info, dict):
        return detail
    root = v2_info
    result = v2_info.get("result")
    if isinstance(result, dict) and any(k in result for k in ("turbo", "binary")):
        root = result
    for product in ("turbo", "binary"):
        node = root.get(product) if isinstance(root, dict) else None
        actives = node.get("actives") if isinstance(node, dict) else None
        if not isinstance(actives, dict):
            continue
        for raw_id, payload in actives.items():
            if not isinstance(payload, dict):
                continue
            raw_name = str(payload.get("name") or "").strip()
            if "." in raw_name:
                raw_name = raw_name.split(".", 1)[1]
            asset_name = normalize_asset_name(raw_name)
            if not asset_name:
                continue
            enriched = dict(payload)
            try:
                enriched.setdefault("active_id", int(raw_id))
            except Exception:
                pass
            detail.setdefault(asset_name, {})[product] = enriched
    return detail



def _preflight_publish_v1_good(detail: Any, opcodes: Any, source: str = "get_all_init") -> None:
    """Publica snapshot V1 íntegro em cache independente do V2.

    V108.8.0: o Preflight FINAL não chama mais get_all_init() na sessão de ordem.
    O worker de Market Data mantém V1 (flags + active_id) e V2 (OPEN/CLOSED)
    atualizados em background, cada um com timestamp próprio.
    """
    if not isinstance(detail, dict) or not detail:
        return
    opcodes = opcodes if isinstance(opcodes, dict) else {"turbo": {}, "binary": {}}
    now_ts = time.time()
    with LUMI_CACHE_LOCK:
        MARKET_PREFLIGHT_DETAIL_CACHE.update({
            "ts": now_ts, "data": detail, "error": "", "opcodes": opcodes,
            "last_good_ts": now_ts, "last_good_data": detail,
            "last_good_opcodes": opcodes, "last_good_source": str(source or "get_all_init")[:80],
        })


def _preflight_last_good_v1(max_age_seconds: Optional[float] = None) -> Tuple[Optional[Dict[str, Any]], Dict[str, Any], float, str]:
    limit = float(max_age_seconds if max_age_seconds is not None else (cfg_get("market_preflight_background_max_age_seconds", 25) or 25))
    with LUMI_CACHE_LOCK:
        detail = MARKET_PREFLIGHT_DETAIL_CACHE.get("last_good_data")
        opcodes = MARKET_PREFLIGHT_DETAIL_CACHE.get("last_good_opcodes") or {"turbo": {}, "binary": {}}
        ts = float(MARKET_PREFLIGHT_DETAIL_CACHE.get("last_good_ts", 0) or 0)
        source = str(MARKET_PREFLIGHT_DETAIL_CACHE.get("last_good_source") or "background_v1")
    age = max(0.0, time.time() - ts) if ts > 0 else 999999.0
    if not isinstance(detail, dict) or age > max(1.0, limit):
        return None, dict(opcodes if isinstance(opcodes, dict) else {}), age, source
    return detail, dict(opcodes if isinstance(opcodes, dict) else {}), age, source


def _preflight_last_good_v1_age() -> float:
    with LUMI_CACHE_LOCK:
        ts = float(MARKET_PREFLIGHT_DETAIL_CACHE.get("last_good_ts", 0) or 0)
    return max(0.0, time.time() - ts) if ts > 0 else 999999.0


def _preflight_publish_v2_good(detail: Any, source: str = "get_all_init_v2") -> None:
    """Publica o último snapshot V2 íntegro para o Preflight Reliability.

    O cache bom é separado do snapshot corrente para que uma chamada que falhou
    não destrua a evidência OPEN recém-obtida em background.
    """
    if not isinstance(detail, dict) or not detail:
        return
    now_ts = time.time()
    with LUMI_CACHE_LOCK:
        MARKET_PREFLIGHT_V2_CACHE.update({
            "ts": now_ts,
            "data": detail,
            "error": "",
            "last_good_ts": now_ts,
            "last_good_data": detail,
            "last_good_source": str(source or "get_all_init_v2")[:80],
        })
    # Se uma V2 que excedeu o deadline termina logo depois e confirma OPEN, o
    # cooldown daquele ativo pode ser liberado: a próxima tentativa usará o caminho
    # híbrido (cache V2 + V1 fresco), sem recriar a tempestade de V2.
    try:
        with PREFLIGHT_RELIABILITY_LOCK:
            cooling = {a: dict(v or {}) for a, v in PREFLIGHT_TIMEOUT_COOLDOWN.items()}
        recovered = []
        for asset, cooldown_item in cooling.items():
            # Timeout na conexão de TRADE mantém o cooldown completo: a thread V1
            # pode continuar viva e não queremos liberar api.buy só porque o V2 atualizou.
            cooldown_reason = str(cooldown_item.get("reason") or "").lower()
            if "get_all_init clássico" in cooldown_reason and "timeout" in cooldown_reason:
                continue
            for product in ("turbo", "binary"):
                st, payload, _flags = _v2_product_state(detail, asset, product)
                if payload is not None and st is True:
                    recovered.append(asset)
                    break
        if recovered:
            with PREFLIGHT_RELIABILITY_LOCK:
                for asset in recovered:
                    PREFLIGHT_TIMEOUT_COOLDOWN.pop(asset, None)
            with state_lock:
                state["preflight_timeout_cooldowns"] = len(PREFLIGHT_TIMEOUT_COOLDOWN)
    except Exception:
        pass


def _preflight_last_good_v2(max_age_seconds: Optional[float] = None) -> Tuple[Optional[Dict[str, Any]], float, str]:
    limit = float(max_age_seconds if max_age_seconds is not None else (cfg_get("market_preflight_background_max_age_seconds", 25) or 25))
    with LUMI_CACHE_LOCK:
        detail = MARKET_PREFLIGHT_V2_CACHE.get("last_good_data")
        ts = float(MARKET_PREFLIGHT_V2_CACHE.get("last_good_ts", 0) or 0)
        source = str(MARKET_PREFLIGHT_V2_CACHE.get("last_good_source") or "background_v2")
    age = max(0.0, time.time() - ts) if ts > 0 else 999999.0
    if not isinstance(detail, dict) or age > max(1.0, limit):
        return None, age, source
    return detail, age, source


def _preflight_last_good_age() -> float:
    with LUMI_CACHE_LOCK:
        ts = float(MARKET_PREFLIGHT_V2_CACHE.get("last_good_ts", 0) or 0)
    return max(0.0, time.time() - ts) if ts > 0 else 999999.0


def _preflight_dual_cache_check(asset: str, product: str, duration: int) -> Dict[str, Any]:
    """V108.8.0: prova OPEN O(1) usando V1 + V2 já coletados em background.

    V2 continua autoridade de OPEN/CLOSED. V1 confirma o mesmo produto e fornece
    active_id LIVE. Nenhuma chamada get_all_init/get_all_init_v2 ocorre na sessão
    de ordem. Cache ausente/stale/conflitante bloqueia por segurança.
    """
    asset = normalize_asset_name(asset)
    max_age = max(5.0, float(cfg_get("market_preflight_background_max_age_seconds", 25) or 25))
    v2_detail, v2_age, v2_source = _preflight_last_good_v2(max_age)
    v1_detail, v1_opcodes, v1_age, v1_source = _preflight_last_good_v1(max_age)
    base = {
        "product": product, "duration_min": int(duration), "attempts": 0, "elapsed_ms": 0,
        "source": "dual_cache_background", "evidence": "preflight_dual_cache",
        "cache_age_seconds": round(v2_age, 2), "cache_v2_age_seconds": round(v2_age, 2),
        "cache_v1_age_seconds": round(v1_age, 2),
        "cache_sources": f"v2={v2_source};v1={v1_source}",
    }
    if not isinstance(v2_detail, dict) or not isinstance(v1_detail, dict):
        missing = []
        if not isinstance(v2_detail, dict): missing.append(f"V2 stale/ausente ({v2_age:.1f}s)")
        if not isinstance(v1_detail, dict): missing.append(f"V1 stale/ausente ({v1_age:.1f}s)")
        return {**base, "ok": False, "verified": False, "reason": "dual-cache incompleto: " + ", ".join(missing), "flags": "cache OPEN incompleto", "opcode": "—", "cache_problem": True}

    v2_state, v2_payload, v2_flags = _v2_product_state(v2_detail, asset, product)
    v1_payload = _find_option_product_payload(v1_detail, asset, product)
    v1_state = _market_payload_open_state(v1_payload)
    v1_flags = _market_payload_flag_text(v1_payload)
    live_id = None
    try:
        live_id = int(((v1_opcodes.get(product) or {}).get(asset)))
    except Exception:
        live_id = _payload_active_id(v1_payload)
    if live_id is None:
        live_id = _payload_active_id(v2_payload)
    if live_id is not None:
        _set_live_active_opcode(asset, live_id)
    local_id = _local_active_opcode(asset)
    opcode_txt = f"live_id={live_id if live_id is not None else '—'}, local_id={local_id if local_id is not None else '—'}"
    flags_txt = f"v2: {v2_flags} · v1: {v1_flags}"

    if v2_payload is None:
        return {**base, "ok": False, "verified": True, "reason": f"{product.upper()} não apareceu no V2 background", "flags": flags_txt, "opcode": opcode_txt}
    if v2_state is not True:
        return {**base, "ok": False, "verified": True, "reason": f"V2 background não confirmou OPEN ({v2_flags})", "flags": flags_txt, "opcode": opcode_txt}
    if v1_payload is None:
        return {**base, "ok": False, "verified": True, "reason": f"V1 background não reconheceu {asset}/{product}", "flags": flags_txt, "opcode": opcode_txt}
    if v1_state is not True:
        return {**base, "ok": False, "verified": True, "reason": f"V1 background não confirmou OPEN ({v1_flags})", "flags": flags_txt, "opcode": opcode_txt}
    if live_id is None or local_id is None:
        return {**base, "ok": False, "verified": True, "reason": "active_id LIVE/local indisponível para api.buy", "flags": flags_txt, "opcode": opcode_txt}

    _clear_preflight_timeout(asset, "dual_cache_background")
    with PREFLIGHT_RELIABILITY_LOCK:
        PREFLIGHT_RELIABILITY_META["hybrid_success"] = int(PREFLIGHT_RELIABILITY_META.get("hybrid_success", 0) or 0) + 1
        PREFLIGHT_RELIABILITY_META["last_source"] = "dual_cache_background"
    return {
        **base, "ok": True, "verified": True,
        "reason": f"OPEN confirmado por V1+V2 background · V1 {v1_age:.1f}s / V2 {v2_age:.1f}s",
        "flags": flags_txt, "opcode": opcode_txt,
    }


def _preflight_timeout_remaining(asset: str) -> int:
    key = normalize_asset_name(asset)
    now_ts = time.time()
    with PREFLIGHT_RELIABILITY_LOCK:
        item = dict(PREFLIGHT_TIMEOUT_COOLDOWN.get(key) or {})
        until = float(item.get("until", 0) or 0)
        if until <= now_ts:
            PREFLIGHT_TIMEOUT_COOLDOWN.pop(key, None)
            return 0
        return max(1, int(until - now_ts))


def _preflight_timeout_reason(asset: str) -> str:
    key = normalize_asset_name(asset)
    with PREFLIGHT_RELIABILITY_LOCK:
        return str((PREFLIGHT_TIMEOUT_COOLDOWN.get(key) or {}).get("reason") or "preflight temporariamente indisponível")


def _mark_preflight_timeout(asset: str, reason: str, seconds_override: Optional[int] = None) -> int:
    key = normalize_asset_name(asset)
    seconds = max(5, int(seconds_override if seconds_override is not None else (cfg_get("market_preflight_timeout_cooldown_seconds", 30) or 30)))
    until = time.time() + seconds
    with PREFLIGHT_RELIABILITY_LOCK:
        PREFLIGHT_TIMEOUT_COOLDOWN[key] = {"until": until, "reason": str(reason or "timeout")[:180], "ts": time.time()}
        PREFLIGHT_RELIABILITY_META["timeouts"] = int(PREFLIGHT_RELIABILITY_META.get("timeouts", 0) or 0) + 1
        PREFLIGHT_RELIABILITY_META["last_asset"] = key
        PREFLIGHT_RELIABILITY_META["last_error"] = str(reason or "timeout")[:180]
    with state_lock:
        state["preflight_timeout_cooldowns"] = len(PREFLIGHT_TIMEOUT_COOLDOWN)
        state["preflight_last_timeout"] = {"asset": key, "reason": str(reason or "timeout")[:180], "until": until, "time": now_hms()}
    return seconds


def _clear_preflight_timeout(asset: str, source: str = "") -> None:
    key = normalize_asset_name(asset)
    with PREFLIGHT_RELIABILITY_LOCK:
        PREFLIGHT_TIMEOUT_COOLDOWN.pop(key, None)
        PREFLIGHT_RELIABILITY_META["last_source"] = str(source or "")[:80]
        PREFLIGHT_RELIABILITY_META["last_asset"] = key
        PREFLIGHT_RELIABILITY_META["last_error"] = ""
        PREFLIGHT_RELIABILITY_META["last_success_ts"] = time.time()
    with state_lock:
        state["preflight_timeout_cooldowns"] = len(PREFLIGHT_TIMEOUT_COOLDOWN)


def _binary_open_v2_snapshot(api: Any, force_refresh: bool = False, allow_stale: bool = False) -> Tuple[Optional[Dict[str, Any]], str]:
    """Snapshot de disponibilidade REAL de TURBO/BINARY via get_all_init_v2().

    Não chama get_all_open_time(), evitando o caminho de digitais que pode quebrar
    em algumas forks. Reproduz apenas a parte binária oficial: enabled=True e
    is_suspended=False significa OPEN.
    """
    ttl = max(3, min(20, int(cfg_get("market_preflight_snapshot_ttl_seconds", 20) or 20)))
    now_ts = time.time()
    with LUMI_CACHE_LOCK:
        ts = float(MARKET_PREFLIGHT_V2_CACHE.get("ts", 0) or 0)
        data = MARKET_PREFLIGHT_V2_CACHE.get("data")
        err = str(MARKET_PREFLIGHT_V2_CACHE.get("error") or "")
        if not force_refresh and (allow_stale or now_ts - ts <= ttl) and isinstance(data, dict):
            return data, err

    if not hasattr(api, "get_all_init_v2"):
        err = "get_all_init_v2 indisponível nesta iqoptionapi"
        with LUMI_CACHE_LOCK:
            MARKET_PREFLIGHT_V2_CACHE.update({"ts": now_ts, "data": None, "error": err})
        return None, err
    try:
        raw = api.get_all_init_v2()
        detail = _binary_v2_detail(raw)
        if detail:
            _preflight_publish_v2_good(detail, "market_universe_background")
            return detail, ""
        err = "get_all_init_v2 retornou sem ativos TURBO/BINARY"
    except Exception as exc:
        err = f"get_all_init_v2 falhou: {str(exc)[:160]}"
    with LUMI_CACHE_LOCK:
        MARKET_PREFLIGHT_V2_CACHE.update({"ts": now_ts, "data": None, "error": err})
    return None, err


def _v2_product_state(detail_v2: Optional[Dict[str, Any]], asset: str, product: str) -> Tuple[Optional[bool], Any, str]:
    payload = _find_option_product_payload(detail_v2, asset, product) if isinstance(detail_v2, dict) else None
    state_now = _market_payload_open_state(payload)
    return state_now, payload, _market_payload_flag_text(payload)


def _set_live_active_opcode(asset: str, live_id: Any) -> bool:
    """Registra um active_id vindo da própria IQ Option no mapa local da iqoptionapi.

    `constants.ACTIVES` deixa de ser filtro de descoberta; passa a ser apenas um cache
    de compatibilidade preenchido dinamicamente pelos snapshots get_all_init/v2.
    """
    key = normalize_asset_name(asset)
    if not key:
        return False
    try:
        value = int(live_id)
    except Exception:
        return False
    changed = False
    try:
        if IQOPTION_CONSTANTS is not None and isinstance(getattr(IQOPTION_CONSTANTS, "ACTIVES", None), dict):
            if IQOPTION_CONSTANTS.ACTIVES.get(key) != value:
                IQOPTION_CONSTANTS.ACTIVES[key] = value
                changed = True
        if isinstance(IQOPTION_ACTIVES, dict) and IQOPTION_ACTIVES.get(key) != value:
            IQOPTION_ACTIVES[key] = value
            changed = True
    except Exception:
        pass
    return changed


def _payload_active_id(payload: Any) -> Optional[int]:
    if not isinstance(payload, dict):
        return None
    for key in ("active_id", "activeId", "id"):
        try:
            value = payload.get(key)
            if value is not None:
                return int(value)
        except Exception:
            pass
    return None


def _live_option_market_universe(api: Any, duration_min: int, force_refresh: bool = False, allow_stale: bool = False) -> Dict[str, Any]:
    """Monta o universo vivo de opções sem depender dos consts estáticos.

    Autoridades:
      * get_all_init()    -> reconhecimento do símbolo + active_id LIVE/payout;
      * get_all_init_v2() -> disponibilidade OPEN/CLOSED atual + active_id de apoio.

    Um ativo só é chamado de incompatível se não existir em NENHUMA das duas fontes.
    Quando qualquer fonte fornece active_id, o mapa local é sincronizado antes de
    get_candles()/api.buy(), incluindo símbolos OTC novos.
    """
    product = _option_product_for_duration(duration_min)
    detail_v1, err_v1 = _binary_detail_snapshot(api, force_refresh=force_refresh, allow_stale=allow_stale)
    detail_v2, err_v2 = _binary_open_v2_snapshot(api, force_refresh=force_refresh, allow_stale=allow_stale)

    v1_assets = set()
    if isinstance(detail_v1, dict):
        for raw_asset in detail_v1.keys():
            asset = normalize_asset_name(raw_asset)
            if asset and _find_option_product_payload(detail_v1, asset, product) is not None:
                v1_assets.add(asset)

    v2_assets = set()
    if isinstance(detail_v2, dict):
        for raw_asset in detail_v2.keys():
            asset = normalize_asset_name(raw_asset)
            if asset and _find_option_product_payload(detail_v2, asset, product) is not None:
                v2_assets.add(asset)

    recognized = v1_assets | v2_assets
    with LUMI_CACHE_LOCK:
        opcodes = MARKET_PREFLIGHT_DETAIL_CACHE.get("opcodes") or {}
        v1_opcode_map = dict((opcodes.get(product) or {}) if isinstance(opcodes, dict) else {})

    synced = 0
    live_ids: Dict[str, int] = {}
    open_assets: List[str] = []
    closed_assets: List[str] = []
    unknown_assets: List[str] = []

    for asset in sorted(recognized):
        live_id = None
        try:
            value = v1_opcode_map.get(asset)
            if value is not None:
                live_id = int(value)
        except Exception:
            live_id = None
        if live_id is None and isinstance(detail_v2, dict):
            live_id = _payload_active_id(_find_option_product_payload(detail_v2, asset, product))
        if live_id is not None:
            live_ids[asset] = int(live_id)
            if _set_live_active_opcode(asset, live_id):
                synced += 1

        if isinstance(detail_v2, dict):
            st, payload, _flags = _v2_product_state(detail_v2, asset, product)
            if st is True:
                open_assets.append(asset)
            elif payload is None:
                unknown_assets.append(asset)
            else:
                closed_assets.append(asset)
        else:
            # Sem V2 não inventamos OPEN; deixamos reconhecido para fallback inicial.
            unknown_assets.append(asset)

    # Pool apenas para diagnóstico de incompatibilidade. Não dirige a descoberta.
    candidate_pool = set(NORMAL_BINARY_CANDIDATE_ASSETS) | set(CRYPTO_CANDIDATE_ASSETS) | set(OTC_CANDIDATE_ASSETS)
    # V102: não chama get_all_profit aqui. Esse pool serve apenas ao diagnóstico de
    # incompatibilidade; o payout é lido UMA vez no Payout Snapshot depois do prefilter.
    # Isso evita uma segunda consulta redundante antes mesmo da análise técnica.
    normalized_candidates = {normalize_asset_name(a) for a in candidate_pool if normalize_asset_name(a)}
    with state_lock:
        broker_health_status = str((cfg_get("broker_health") or {}).get("status") or "").lower()
        cached_market = dict(cfg_get("_last_market_universe") or {})
    source_error = bool(str(err_v1 or "").strip() or str(err_v2 or "").strip())
    source_suspicious = source_error and len(recognized) < max(10, int(len(normalized_candidates) * 0.50))
    suppress_incompatible = broker_health_status in {"degraded", "reconnecting", "warming", "offline"} or source_suspicious
    incompatible = [] if suppress_incompatible else sorted(a for a in normalized_candidates if a not in recognized)

    # Se as fontes vierem parciais durante recovery, o radar preserva o último universo
    # válido. Isso NÃO autoriza ordem: Preflight FINAL continua obrigatório/fail-closed.
    cached_assets = [normalize_asset_name(a) for a in list(cached_market.get("assets") or []) if normalize_asset_name(a)]
    if suppress_incompatible and cached_assets and (not recognized or source_suspicious):
        recognized |= set(cached_assets)
        unknown_assets = sorted(set(unknown_assets) | set(cached_assets))

    # Se V2 existe, OPEN vem exclusivamente dele. Se V2 falhar, o scanner recebe os
    # símbolos reconhecidos por V1/V2, porém o preflight final continua obrigatório.
    verified = isinstance(detail_v2, dict) and not (suppress_incompatible and source_suspicious)
    usable_before_buyability = sorted(open_assets if verified else recognized)
    active_false_open = set(buyability_false_open_assets())
    false_open_assets = [a for a in usable_before_buyability if a in active_false_open]
    false_open_set = set(false_open_assets)
    usable = [a for a in usable_before_buyability if a not in false_open_set]

    return {
        "product": product,
        "verified": verified,
        "recognized_assets": sorted(recognized),
        "open_assets": usable,
        "open_assets_before_buyability": usable_before_buyability,
        "false_open_assets": sorted(false_open_assets),
        "false_open_count": len(false_open_assets),
        "v2_open_assets": sorted(open_assets),
        "closed_assets": sorted(closed_assets),
        "unknown_assets": sorted(unknown_assets),
        "v1_assets": sorted(v1_assets),
        "v2_assets": sorted(v2_assets),
        "live_ids": live_ids,
        "synced_opcodes": synced,
        "incompatible_assets": incompatible,
        "incompatible_diagnostic_suppressed": bool(suppress_incompatible),
        "candidate_count": len(normalized_candidates),
        "error_v1": err_v1,
        "error_v2": err_v2,
    }


def _mix_asset_groups(*groups: List[str]) -> List[str]:
    """Intercala categorias para `scanner_max_assets` não expulsar OTC do radar."""
    buckets = [list(dict.fromkeys(g)) for g in groups if g]
    out: List[str] = []
    seen = set()
    pos = 0
    while buckets:
        next_buckets = []
        for bucket in buckets:
            if pos < len(bucket):
                asset = bucket[pos]
                if asset not in seen:
                    seen.add(asset)
                    out.append(asset)
            if pos + 1 < len(bucket):
                next_buckets.append(bucket)
        buckets = next_buckets
        pos += 1
    return out


def _full_market_radar_order(assets: List[str]) -> List[str]:
    """V108.5: ordenação barata e diversificada do universo OPEN inteiro.

    Em AUTO/fim de semana mantém viés OTC, mas não deixa normais/cripto invisíveis
    durante dezenas de velas. Ciclo aproximado: 3 OTC : 1 normal : 1 cripto.
    Nenhuma consulta de candles/API acontece aqui.
    """
    universe = list(dict.fromkeys(normalize_asset_name(a) for a in (assets or []) if a))
    otc = [a for a in universe if is_otc_asset(a)]
    crypto = [a for a in universe if (not is_otc_asset(a)) and is_crypto_asset(a)]
    normal = [a for a in universe if (not is_otc_asset(a)) and not is_crypto_asset(a)]
    if not otc or normalize_market_mode(cfg_get("market_mode", "auto")) != "auto":
        return _mix_asset_groups(normal, crypto, otc) if len([g for g in (normal, crypto, otc) if g]) > 1 else universe
    out: List[str] = []
    seen = set()
    io = inn = ic = 0
    while io < len(otc) or inn < len(normal) or ic < len(crypto):
        for _ in range(3):
            if io < len(otc):
                a = otc[io]; io += 1
                if a not in seen: seen.add(a); out.append(a)
        if inn < len(normal):
            a = normal[inn]; inn += 1
            if a not in seen: seen.add(a); out.append(a)
        if ic < len(crypto):
            a = crypto[ic]; ic += 1
            if a not in seen: seen.add(a); out.append(a)
    for a in universe:
        if a not in seen:
            seen.add(a); out.append(a)
    return out


def _filter_assets_by_v2_open(api: Any, assets: List[str], duration_min: int) -> Tuple[List[str], Dict[str, Any]]:
    """Pré-filtra o universo do scanner usando somente ativos OPEN no init_v2.

    Se o v2 estiver temporariamente indisponível, não zera o scanner; o preflight
    individual/final ainda fará a proteção. Quando o snapshot existe, ausência no
    produto também é tratada como indisponível.
    """
    original = list(dict.fromkeys(normalize_asset_name(a) for a in assets if a))
    detail_v2, err = _binary_open_v2_snapshot(api, force_refresh=False)
    product = _option_product_for_duration(duration_min)
    if not isinstance(detail_v2, dict):
        return original, {
            "verified": False, "product": product, "before": len(original), "open": len(original),
            "closed": 0, "missing": 0, "error": err,
        }
    opened: List[str] = []
    closed = 0
    missing = 0
    for asset in original:
        st, payload, _flags = _v2_product_state(detail_v2, asset, product)
        if st is True:
            opened.append(asset)
        elif payload is None:
            missing += 1
        else:
            closed += 1
    return opened, {
        "verified": True, "product": product, "before": len(original), "open": len(opened),
        "closed": closed, "missing": missing, "error": "",
    }

def _local_active_opcode(asset: str) -> Optional[int]:
    key = normalize_asset_name(asset)
    try:
        source = getattr(IQOPTION_CONSTANTS, "ACTIVES", None) if IQOPTION_CONSTANTS is not None else IQOPTION_ACTIVES
        value = source.get(key) if isinstance(source, dict) else None
        return int(value) if value is not None else None
    except Exception:
        return None


def _cached_live_active_opcode(asset: str, product: str) -> Optional[int]:
    key = normalize_asset_name(asset)
    prod = str(product or "turbo").strip().lower()
    with LUMI_CACHE_LOCK:
        opcodes = MARKET_PREFLIGHT_DETAIL_CACHE.get("opcodes") or {}
        product_map = opcodes.get(prod) if isinstance(opcodes, dict) else None
        value = product_map.get(key) if isinstance(product_map, dict) else None
        if value is None:
            last_opcodes = MARKET_PREFLIGHT_DETAIL_CACHE.get("last_good_opcodes") or {}
            last_map = last_opcodes.get(prod) if isinstance(last_opcodes, dict) else None
            value = last_map.get(key) if isinstance(last_map, dict) else None
    try:
        return int(value) if value is not None else None
    except Exception:
        return None


def _sync_active_opcode_from_live(api: Any, asset: str, duration_min: int, force_refresh: bool = False) -> Dict[str, Any]:
    """Sincroniza ACTIVES[símbolo] com active_id LIVE de get_all_init ou init_v2."""
    key = normalize_asset_name(asset)
    product = _option_product_for_duration(duration_min)
    _binary_detail_snapshot(api, force_refresh=force_refresh)
    live_id = _cached_live_active_opcode(key, product)
    source = "get_all_init"
    if live_id is None:
        detail_v2, _ = _binary_open_v2_snapshot(api, force_refresh=force_refresh)
        payload_v2 = _find_option_product_payload(detail_v2, key, product) if isinstance(detail_v2, dict) else None
        live_id = _payload_active_id(payload_v2)
        if live_id is not None:
            source = "get_all_init_v2"
    before = _local_active_opcode(key)
    changed = _set_live_active_opcode(key, live_id) if live_id is not None else False
    after = _local_active_opcode(key)
    return {
        "asset": key,
        "product": product,
        "source": source if live_id is not None else "sem_live_id",
        "live_active_id": live_id,
        "local_active_id_before": before,
        "local_active_id_after": after,
        "changed": bool(changed),
        "ok": live_id is not None,
    }

def _is_active_not_found_error(value: Any) -> bool:
    text = str(value or "").strip().lower()
    return "active" in text and "not found" in text


def _is_asset_unavailable_error(value: Any) -> bool:
    """Recusa específica do instrumento; não significa fechamento do mercado inteiro."""
    text = str(value or "").strip().lower()
    needles = (
        "asset is not available at the moment",
        "instrument is not available",
        "active is not available",
        "cannot purchase an option",
    )
    return any(n in text for n in needles)


def _is_asset_specific_buy_error(value: Any) -> bool:
    return _is_active_not_found_error(value) or _is_asset_unavailable_error(value)

def _binary_detail_snapshot(api: Any, force_refresh: bool = False, allow_stale: bool = False) -> Tuple[Optional[Dict[str, Any]], str]:
    """Snapshot único de detalhe + opcodes LIVE derivados de get_all_init()."""
    ttl = max(5, int(cfg_get("market_preflight_snapshot_ttl_seconds", 20) or 20))
    now_ts = time.time()
    with LUMI_CACHE_LOCK:
        ts = float(MARKET_PREFLIGHT_DETAIL_CACHE.get("ts", 0) or 0)
        data = MARKET_PREFLIGHT_DETAIL_CACHE.get("data")
        err = str(MARKET_PREFLIGHT_DETAIL_CACHE.get("error") or "")
        if not force_refresh and (allow_stale or now_ts - ts <= ttl) and isinstance(data, dict):
            return data, err

    # Preferimos get_all_init porque nele o active_id está na chave de `actives`.
    # get_binary_option_detail() preserva flags, mas descarta essa chave numérica.
    if hasattr(api, "get_all_init"):
        try:
            init_info = api.get_all_init() or {}
            detail, opcodes = _binary_init_detail_and_opcodes(init_info)
            if detail:
                _preflight_publish_v1_good(detail, opcodes, "market_universe_background" if force_refresh else "get_all_init_cache")
                return detail, ""
        except Exception as exc:
            init_err = str(exc)[:180]
        else:
            init_err = "get_all_init retornou sem ativos binários"
    else:
        init_err = "get_all_init indisponível nesta iqoptionapi"

    # Fallback para forks que só exponham o detalhe pronto. Nesse caso mantemos o
    # preflight, porém sem inventar active_id vivo.
    if not hasattr(api, "get_binary_option_detail"):
        with LUMI_CACHE_LOCK:
            MARKET_PREFLIGHT_DETAIL_CACHE.update({"ts": now_ts, "data": None, "error": init_err, "opcodes": {"turbo": {}, "binary": {}}})
        return None, init_err
    try:
        data = api.get_binary_option_detail() or {}
        if not isinstance(data, dict):
            data = {}
        with LUMI_CACHE_LOCK:
            MARKET_PREFLIGHT_DETAIL_CACHE.update({"ts": now_ts, "data": data, "error": init_err, "opcodes": {"turbo": {}, "binary": {}}})
        return data, init_err
    except Exception as exc:
        err = f"{init_err}; detalhe: {str(exc)[:120]}"[:220]
        with LUMI_CACHE_LOCK:
            MARKET_PREFLIGHT_DETAIL_CACHE.update({"ts": now_ts, "data": None, "error": err, "opcodes": {"turbo": {}, "binary": {}}})
        return None, err


def market_preflight_final_fast(trade_api: Any, asset: str, duration_min: Optional[int] = None) -> Dict[str, Any]:
    """V108.8.0 — Preflight Dual Cache, sem I/O síncrono na hora da ordem.

    O Market Data Engine já coleta get_all_init (V1) e get_all_init_v2 (V2) em
    background. O FINAL apenas cruza as duas fotografias recentes:
      * V2: autoridade de OPEN/CLOSED;
      * V1: confirmação independente + active_id LIVE.

    Se uma das fontes estiver velha/ausente/conflitante, falha fechado e pede ao
    worker de universo uma renovação. Nenhuma thread get_all_init fica pendurada na
    conexão de trade e nenhuma chamada V2 é criada no instante crítico.
    """
    asset = normalize_asset_name(asset)
    duration = int(duration_min if duration_min is not None else max(1, int(cfg_get("timeframe", 300) or 300) // 60))
    product = _option_product_for_duration(duration)

    cool = _preflight_timeout_remaining(asset)
    if cool > 0:
        return {
            "ok": False, "verified": False, "product": product, "duration_min": duration,
            "reason": f"cooldown Preflight Dual Cache ativo por {cool}s: {_preflight_timeout_reason(asset)}",
            "evidence": "preflight_timeout_cooldown", "flags": "cooldown", "opcode": "—",
            "attempts": 0, "elapsed_ms": 0, "source": "cooldown",
            "cache_v1_age_seconds": round(_preflight_last_good_v1_age(), 2),
            "cache_v2_age_seconds": round(_preflight_last_good_age(), 2),
        }
    false_open = buyability_false_open_remaining(asset)
    if false_open > 0:
        return {"ok": False, "verified": True, "product": product, "duration_min": duration, "reason": f"Buyability FALSE-OPEN ativo por {false_open}s", "evidence": "buyability_false_open", "flags": "bloqueado", "opcode": "—", "attempts": 0, "elapsed_ms": 0, "source": "buyability"}
    blocked = is_order_failure_blocked(asset)
    if blocked > 0:
        return {"ok": False, "verified": True, "product": product, "duration_min": duration, "reason": f"ativo em quarentena ({blocked}s)", "evidence": "order_failure_block", "flags": "bloqueado", "opcode": "—", "attempts": 0, "elapsed_ms": 0, "source": "order_failure"}

    market_api = get_market_data_api(trade_api)
    if bool(cfg_get("market_data_isolation_enabled", True)) and market_api is trade_api and str(cfg_get("account_type", "PRACTICE")).upper() == "REAL":
        return {"ok": False, "verified": False, "product": product, "duration_min": duration, "reason": "sessão Market Data dedicada indisponível para Preflight Dual Cache", "evidence": "market_data_session_missing", "flags": "sem sessão dedicada", "opcode": "—", "attempts": 0, "elapsed_ms": 0, "source": "market_data_missing"}

    started = time.perf_counter()
    proof = _preflight_dual_cache_check(asset, product, duration)
    proof["elapsed_ms"] = int((time.perf_counter() - started) * 1000)
    if proof.get("ok"):
        return proof

    # V108.9.2 JIT Preflight Recovery: se o candidato já passou Técnica/Lumi/Candle/EV
    # e o único problema é cache stale, dá prioridade ao worker Market Data e espera
    # uma janela curta pela nova prova V1+V2. A sessão de TRADE continua sem get_all_init.
    if proof.get("cache_problem"):
        retry_enabled = bool(cfg_get("market_preflight_final_retry_enabled", True))
        retry_timeout = max(0.8, min(4.0, float(cfg_get("market_preflight_final_retry_timeout_seconds", 3.8) or 3.8)))
        retry_delay = max(0.02, min(0.50, float(cfg_get("market_preflight_final_retry_delay_seconds", 0.05) or 0.05)))
        attempts = 0
        try:
            PREFLIGHT_REFRESH_REQUESTED.set()
            _kick_market_universe_refresh_worker(market_api)
        except Exception:
            pass
        if retry_enabled:
            deadline = time.monotonic() + retry_timeout
            last_proof = dict(proof)
            while time.monotonic() < deadline:
                time.sleep(retry_delay)
                attempts += 1
                refreshed = _preflight_dual_cache_check(asset, product, duration)
                refreshed["attempts"] = attempts
                refreshed["elapsed_ms"] = int((time.perf_counter() - started) * 1000)
                last_proof = refreshed
                # OPEN confirmado ou CLOSED/conflito explicitamente verificado: decisão final.
                if refreshed.get("ok") or not refreshed.get("cache_problem"):
                    refreshed["source"] = "dual_cache_jit_refresh" if refreshed.get("ok") else str(refreshed.get("source") or "dual_cache_jit_verified")
                    refreshed["jit_refresh"] = True
                    if refreshed.get("ok"):
                        _clear_preflight_timeout(asset, "dual_cache_jit_refresh")
                    return refreshed
            proof = last_proof
        reason = str(proof.get("reason") or "dual-cache indisponível")
        cooldown = _mark_preflight_timeout(asset, reason, seconds_override=12)
        proof["attempts"] = attempts
        proof["elapsed_ms"] = int((time.perf_counter() - started) * 1000)
        proof["reason"] = f"{reason}; refresh JIT não confirmou dentro de {retry_timeout:.1f}s · cooldown {cooldown}s"
        proof["evidence"] = "preflight_dual_cache_stale"
        proof["source"] = "dual_cache_jit_timeout"
        proof["jit_refresh"] = True
        return proof

    # CLOSED/conflito explícito é uma decisão verificada; não criamos tempestade nem
    # tentamos contornar a corretora com uma chamada alternativa.
    return proof

def market_preflight(api: Any, asset: str, row: Optional[Dict[str, Any]] = None, force_refresh: bool = False, duration_min: Optional[int] = None) -> Dict[str, Any]:
    """Valida se o MESMO produto da ordem está negociável agora.

    Separação de responsabilidades:
      * get_all_init()    -> payout/detalhes + active_id LIVE (opcode)
      * get_all_init_v2() -> autoridade de OPEN/CLOSED de TURBO/BINARY

    O v1 pode ficar aparentemente `enabled=True` mesmo quando a compra é recusada.
    Por isso ele não é mais usado como prova de OPEN. Na revalidação final
    (`force_refresh=True`), ausência do v2 bloqueia a entrada por segurança.
    """
    asset = normalize_asset_name(asset)
    if not bool(cfg_get("market_preflight_enabled", True)):
        return {"ok": True, "verified": False, "reason": "preflight desativado", "evidence": "off"}
    cool = _preflight_timeout_remaining(asset)
    if cool > 0:
        return {"ok": False, "verified": False, "reason": f"Preflight Reliability em cooldown por {cool}s: {_preflight_timeout_reason(asset)}", "evidence": "preflight_timeout_cooldown"}
    false_open = buyability_false_open_remaining(asset)
    if false_open > 0:
        return {
            "ok": False, "verified": True,
            "reason": f"Buyability FALSE-OPEN ativo por {false_open}s: {buyability_false_open_reason(asset)}",
            "evidence": "buyability_false_open",
        }
    blocked = is_order_failure_blocked(asset)
    if blocked > 0:
        return {"ok": False, "verified": True, "reason": f"ativo em quarentena por falha anterior ({blocked}s)", "evidence": "order_failure_block"}
    if not is_otc_asset(asset) and normal_market_block_remaining() > 0:
        return {"ok": False, "verified": True, "reason": f"mercado normal em quarentena ({normal_market_block_remaining()}s)", "evidence": "normal_market_quarantine"}

    duration = int(duration_min if duration_min is not None else max(1, int(cfg_get("timeframe", 300) or 300) // 60))
    product = _option_product_for_duration(duration)
    product_label = product.upper()

    # V1: mantido para active_id LIVE/opcode e diagnóstico. NÃO prova OPEN.
    detail_v1, detail_v1_error = _binary_detail_snapshot(api, force_refresh=force_refresh)
    payload_v1 = _find_option_product_payload(detail_v1, asset, product) if isinstance(detail_v1, dict) else None
    v1_state = _market_payload_open_state(payload_v1)
    v1_flags = _market_payload_flag_text(payload_v1)

    # V2: fonte oficial usada pela própria iqoptionapi em get_all_open_time().
    detail_v2, detail_v2_error = _binary_open_v2_snapshot(api, force_refresh=force_refresh)
    v2_state, payload_v2, v2_flags = _v2_product_state(detail_v2, asset, product)
    v2_available = isinstance(detail_v2, dict)

    live_active_id = _cached_live_active_opcode(asset, product)
    local_active_id = _local_active_opcode(asset)
    opcode_txt = f"live_id={live_active_id if live_active_id is not None else '—'}, local_id={local_active_id if local_active_id is not None else '—'}"
    base_result = {
        "product": product,
        "duration_min": duration,
        "flags": f"v2: {v2_flags}",
        "v2_flags": v2_flags,
        "v1_flags": v1_flags,
        "v2_state": v2_state,
        "v1_state": v1_state,
        "availability_source": "get_all_init_v2" if v2_available else "v2_indisponível",
        "v2_error": detail_v2_error,
        "v1_error": detail_v1_error,
        "live_active_id": live_active_id,
        "local_active_id": local_active_id,
        "opcode": opcode_txt,
        "opcode_sync_needed": bool(live_active_id is not None and live_active_id != local_active_id),
    }

    if local_active_id is None and live_active_id is None:
        return {**base_result, "ok": False, "verified": True, "reason": "símbolo não existe nos consts locais e get_all_init não forneceu active_id LIVE", "evidence": "local+live_opcode_missing"}

    if v2_available:
        # Se o snapshot existe, ausência do ativo no produto é uma informação útil:
        # aquele símbolo não está no universo negociável TURBO/BINARY atual.
        if payload_v2 is None:
            return {
                **base_result, "ok": False, "verified": True,
                "reason": f"{product_label} {duration}min não apareceu no get_all_init_v2 atual",
                "evidence": f"get_all_init_v2:{product}:missing",
            }
        if v2_state is False:
            return {
                **base_result, "ok": False, "verified": True,
                "reason": f"{product_label} {duration}min fechado/indisponível no get_all_init_v2 ({v2_flags})",
                "evidence": f"get_all_init_v2:{product}:closed",
            }
        if v2_state is True:
            return {
                **base_result, "ok": True, "verified": True,
                "reason": f"{product_label} {duration}min confirmado OPEN pelo get_all_init_v2 ({v2_flags})",
                "evidence": f"get_all_init_v2:{product}:open",
            }
        # V2 presente mas sem flags claras: não inventa OPEN.
        return {
            **base_result, "ok": False, "verified": True,
            "reason": f"{product_label} {duration}min apareceu no get_all_init_v2, mas sem flags suficientes de disponibilidade ({v2_flags})",
            "evidence": f"get_all_init_v2:{product}:unknown",
        }

    # Na hora de esperar/abrir uma ordem, a disponibilidade precisa ser confirmada
    # por v2. Não usamos v1.enabled=True como substituto porque foi exatamente o
    # falso positivo observado em GBPAUD/COKE.
    if force_refresh:
        return {
            **base_result, "ok": False, "verified": False,
            "reason": f"não foi possível confirmar OPEN via get_all_init_v2 na revalidação final ({detail_v2_error or 'sem resposta'})",
            "evidence": "get_all_init_v2:unavailable_final",
        }

    # Pré-scan tolerante apenas quando o v2 falhou temporariamente. Um CLOSED
    # explícito no v1 ainda pode economizar trabalho, mas OPEN no v1 não é prova.
    if v1_state is False:
        return {
            **base_result, "ok": False, "verified": False,
            "reason": f"v2 indisponível; v1 também marcou {product_label} como fechado ({v1_flags})",
            "evidence": f"get_all_init:{product}:closed_fallback",
        }

    known_normal = asset in NORMAL_BINARY_CANDIDATE_ASSETS or is_crypto_asset(asset)
    strict_exotic = bool(cfg_get("market_preflight_strict_normal_exotics", True))
    payout = int((row or {}).get("payout", 0) or 0)
    payout_source = str((row or {}).get("payout_source") or "")
    if not is_otc_asset(asset) and not known_normal and strict_exotic:
        return {
            **base_result, "ok": False, "verified": False,
            "reason": f"ativo normal extra sem confirmação OPEN do get_all_init_v2 em {product_label} {duration}min",
            "evidence": f"{payout_source or 'payout'} não prova api.buy",
        }

    reason = f"get_all_init_v2 temporariamente indisponível; ativo conhecido passou apenas no preflight inicial conservador"
    if detail_v2_error:
        reason += f" · {detail_v2_error[:110]}"
    if payout > 0:
        reason += f" · payout {payout}%"
    return {**base_result, "ok": True, "verified": False, "reason": reason, "evidence": "v2_unavailable_conservative_scan"}

def list_open_turbo_assets(api: Any, otc_only: bool = True) -> List[str]:
    """Lista símbolos reconhecidos/OPEN pelas fontes LIVE, sem filtrar por constants.ACTIVES."""
    try:
        duration = max(1, int(cfg_get("timeframe", 300) or 300) // 60)
    except Exception:
        duration = 5
    snap = _live_option_market_universe(api, duration, force_refresh=False)
    assets = list(snap.get("open_assets") or [])
    if otc_only:
        assets = [a for a in assets if is_otc_asset(a)]
        key = "otc"
    else:
        key = "all"
    incompatible = list(snap.get("incompatible_assets") or [])
    LAST_DISCOVERY_STATS[key] = {
        "found": int(snap.get("candidate_count", len(assets)) or len(assets)),
        "compatible": len(assets),
        "incompatible_ignored": len(incompatible),
    }
    return assets


def list_scan_assets(api: Any, market_mode: str, *, force_refresh: bool = False, allow_stale: bool = True) -> Tuple[List[str], Dict[str, Any]]:
    """Constrói o radar diretamente de get_all_init/get_all_init_v2.

    `constants.ACTIVES` não participa da decisão de compatibilidade. Os active_id
    vivos são adicionados ao mapa local automaticamente. Em AUTO, as categorias
    são intercaladas para que um limite de 40 ativos não elimine todos os OTC.
    """
    mode = normalize_market_mode(market_mode)
    try:
        duration_scan = max(1, int(cfg_get("timeframe", 300) or 300) // 60)
    except Exception:
        duration_scan = 5

    snap = _live_option_market_universe(api, duration_scan, force_refresh=force_refresh, allow_stale=allow_stale)
    live_assets = list(snap.get("open_assets") or [])
    verified = bool(snap.get("verified"))

    otc = sorted(a for a in live_assets if is_otc_asset(a))
    crypto = sorted(a for a in live_assets if (not is_otc_asset(a)) and is_crypto_asset(a))
    normal = sorted(a for a in live_assets if (not is_otc_asset(a)) and not is_crypto_asset(a))
    forex_binary = list(normal)
    normal_block = normal_market_block_remaining()

    if mode == "normal_only":
        selected = _mix_asset_groups(normal, crypto)
        used = "normal_only"
        reason = "modo Forex/Binárias + Cripto: universo LIVE; OTC ignorado"
    elif mode == "crypto_only":
        selected = list(crypto)
        used = "crypto_only"
        reason = "modo Somente Cripto: universo LIVE; Forex tradicional e OTC ignorados"
    elif mode == "otc_only":
        selected = list(otc)
        used = "otc_only"
        reason = "modo Somente OTC: universo LIVE do get_all_init/v2"
    else:
        otc_priority_seconds = buyability_otc_priority_remaining()
        weekend_priority = bool(cfg_get("buyability_weekend_otc_priority", True)) and _buyability_is_weekend() and bool(otc)
        if normal_block and otc:
            selected = list(otc) + list(crypto)
            used = "otc_fallback_after_normal_fail"
            reason = f"mercado normal em quarentena por {normal_block}s; priorizando OTC LIVE"
        elif otc and otc_priority_seconds > 0:
            # Buyability Engine: várias recusas normais recentes. OTC primeiro,
            # depois cripto e somente então normais, sem desabilitar os normais.
            selected = list(otc) + list(crypto) + list(normal)
            used = "buyability_otc_priority"
            reason = f"Buyability Engine priorizando OTC por {otc_priority_seconds}s ({str(globals().get('BUYABILITY_OTC_PRIORITY_REASON',''))})"
        elif weekend_priority:
            # Em sábado/domingo, o V2 pode anunciar normais que api.buy recusa.
            # OTC fica na frente; normais continuam disponíveis caso sobrem vagas.
            selected = list(otc) + list(crypto) + list(normal)
            used = "weekend_otc_priority"
            reason = "fim de semana: OTC priorizado por maior buyability observada; cripto e normais permanecem como fallback"
        else:
            # Fora de regime de prioridade, mantém diversidade por categoria.
            selected = _mix_asset_groups(normal, otc, crypto)
            used = "normal_crypto_and_otc_live"
            reason = (
                f"universo LIVE: {len(normal)} normal(is) + {len(crypto)} cripto + {len(otc)} OTC"
                if verified else
                f"V2 indisponível; usando {len(live_assets)} símbolo(s) reconhecido(s) por get_all_init/v2 com preflight final obrigatório"
            )

    incompatible = list(snap.get("incompatible_assets") or [])
    if bool(snap.get("incompatible_diagnostic_suppressed")):
        incompatible = []
    if incompatible:
        new_bad = [a for a in incompatible if a not in UNSUPPORTED_ASSETS_LOGGED]
        if new_bad:
            UNSUPPORTED_ASSETS_LOGGED.update(new_bad)
            preview = ", ".join(new_bad[:12])
            extra = f" +{len(new_bad)-12}" if len(new_bad) > 12 else ""
            log(
                f"Scanner: {len(new_bad)} ativo(s) realmente incompatível(is) — ausentes tanto no get_all_init quanto no get_all_init_v2: {preview}{extra}",
                "warn",
            )

    if int(snap.get("synced_opcodes", 0) or 0) > 0:
        log(f"🔄 Scanner sincronizou {int(snap.get('synced_opcodes', 0))} active_id(s) LIVE no mapa local da iqoptionapi.", "info")

    v2_meta = {
        "verified": verified,
        "product": str(snap.get("product") or _option_product_for_duration(duration_scan)),
        "before": len(snap.get("recognized_assets") or []),
        "open": len(snap.get("v2_open_assets") or []) if verified else len(selected),
        "closed": len(snap.get("closed_assets") or []),
        "missing": 0,
        "error": str(snap.get("error_v2") or ""),
        "authority": "get_all_init_v2" if verified else "get_all_init/v2 reconhecidos",
    }
    reason += (
        f"; {str(v2_meta['product']).upper()} OPEN via get_all_init_v2={len(snap.get('v2_open_assets') or [])}"
        if verified else
        f"; get_all_init_v2 indisponível: {str(snap.get('error_v2') or 'sem resposta')[:100]}"
    )

    meta = {
        "configured_mode": mode,
        "configured_label": market_mode_label(mode),
        "used_mode": used,
        "reason": reason,
        "normal_count": len(normal),
        "forex_binary_count": len(normal),
        "crypto_count": len(crypto),
        "otc_count": len(otc),
        "open_normal_count": len(normal),
        "open_crypto_count": len(crypto),
        "open_otc_count": len(otc),
        "open_total_count": len(live_assets),
        "found_count": int(snap.get("candidate_count", len(snap.get("recognized_assets") or [])) or 0),
        "compatible_count": len(snap.get("recognized_assets") or []),
        "incompatible_ignored": len(incompatible),
        "normal_fallback_remaining": normal_block,
        "v2_prefilter": v2_meta,
        "v2_prefilter_open_count": int(v2_meta.get("open", len(selected)) or 0),
        "v2_prefilter_before_count": int(v2_meta.get("before", len(selected)) or 0),
        "live_recognized_count": len(snap.get("recognized_assets") or []),
        "live_opcode_count": len(snap.get("live_ids") or {}),
        "live_opcode_synced": int(snap.get("synced_opcodes", 0) or 0),
        "false_open_count": int(snap.get("false_open_count", 0) or 0),
        "false_open_assets": list(snap.get("false_open_assets") or [])[:120],
        "buyability_otc_priority_remaining": buyability_otc_priority_remaining(),
        "buyability_weekend": 1 if _buyability_is_weekend() else 0,
    }
    return selected, meta


def _market_universe_cache_status() -> Dict[str, Any]:
    with state_lock:
        cached = dict(cfg_get("_last_market_universe") or {})
    with MARKET_UNIVERSE_REFRESH_LOCK:
        refresh_meta = dict(MARKET_UNIVERSE_REFRESH_META)
    saved_at = float(cached.get("saved_at", 0) or 0)
    age = max(0.0, time.time() - saved_at) if saved_at else 999999.0
    return {"cached": cached, "age_seconds": age, "refresh": refresh_meta}



def _fast_market_intelligence_snapshot() -> Dict[str, Dict[str, Any]]:
    with state_lock:
        raw = dict(cfg_get("_fast_market_intelligence") or {})
    return {normalize_asset_name(k): dict(v or {}) for k,v in raw.items() if k}


def _fast_market_features(candles: List[Dict[str, Any]], asset: str, tf: int) -> Optional[Dict[str, Any]]:
    ohlc=[_candle_ohlc(c) for c in list(candles or [])]
    ohlc=[x for x in ohlc if x]
    if len(ohlc)<8: return None
    ohlc.sort(key=lambda x:x["ts"])
    closes=[float(x["close"]) for x in ohlc]
    if not closes or closes[-1] == 0: return None
    diffs=[closes[i]-closes[i-1] for i in range(1,len(closes))]
    pct=[abs(d/max(1e-12,closes[i-1]))*100.0 for i,d in enumerate(diffs, start=1)]
    avg_abs=(sum(pct)/max(1,len(pct)))
    short_ret=(closes[-1]/max(1e-12,closes[-4])-1.0)*100.0 if len(closes)>=4 else 0.0
    long_ret=(closes[-1]/max(1e-12,closes[0])-1.0)*100.0
    path=sum(abs(d) for d in diffs) or 1e-12
    trend_eff=min(1.0,abs(closes[-1]-closes[0])/path)
    last_pct=(diffs[-1]/max(1e-12,closes[-2]))*100.0
    prev_pct=(diffs[-2]/max(1e-12,closes[-3]))*100.0 if len(diffs)>=2 else 0.0
    accel=last_pct-prev_pct
    ema3=sum(closes[-3:])/min(3,len(closes))
    ema8=sum(closes[-8:])/min(8,len(closes))
    direction="call" if ema3>ema8 and short_ret>0 else "put" if ema3<ema8 and short_ret<0 else "hold"
    move_ratio=abs(short_ret)/max(0.001,avg_abs)
    momentum_strength=min(100.0,abs(last_pct)/max(0.001,avg_abs)*28.0)
    trend_strength=min(100.0,trend_eff*100.0)
    acceleration_strength=min(100.0,abs(accel)/max(0.001,avg_abs)*20.0)
    # Volatilidade tem faixa útil; mercado morto e ruído extremo perdem pontos.
    vol_ratio=min(4.0,avg_abs/max(0.001,statistics.median(pct) if pct else avg_abs))
    vol_quality=max(20.0,100.0-abs(vol_ratio-1.4)*35.0)
    score=35.0 + trend_strength*0.28 + min(100.0,move_ratio*22.0)*0.18 + momentum_strength*0.12 + acceleration_strength*0.08 + vol_quality*0.09
    if direction=="hold": score-=8.0
    score=max(0.0,min(100.0,score))
    return {
        "asset": normalize_asset_name(asset), "score":round(score,1), "direction":direction,
        "short_return_pct":round(short_ret,5), "long_return_pct":round(long_ret,5),
        "momentum":round(last_pct,5), "acceleration":round(accel,5), "avg_abs_return_pct":round(avg_abs,5),
        "trend_efficiency":round(trend_eff*100.0,1), "volatility_quality":round(vol_quality,1),
        "latest_price":float(closes[-1]), "price_ts":int(ohlc[-1].get("ts",0) or 0),
        "tf":int(tf), "updated_ts":time.time(), "updated_at":now_hms(), "candles":len(ohlc),
    }


def _quote_cache_set(asset: str, price: Any, source: str = "m1", candle_ts: int = 0) -> Optional[Dict[str, Any]]:
    if not bool(cfg_get("quote_cache_enabled", True)):
        return None
    try:
        value = float(price)
    except Exception:
        return None
    if not math.isfinite(value) or value <= 0:
        return None
    item = {
        "asset": normalize_asset_name(asset), "price": value, "ts": time.time(),
        "source": str(source or "m1")[:80], "candle_ts": int(candle_ts or 0),
    }
    with QUOTE_CACHE_LOCK:
        QUOTE_CACHE[item["asset"]] = dict(item)
    return item


def _quote_cache_get(asset: str, max_age: Optional[float] = None) -> Optional[Dict[str, Any]]:
    asset = normalize_asset_name(asset)
    age_limit = float(max_age if max_age is not None else (cfg_get("quote_cache_max_age_seconds", 3.0) or 3.0))
    with QUOTE_CACHE_LOCK:
        item = dict(QUOTE_CACHE.get(asset) or {})
    if not item:
        return None
    age = max(0.0, time.time() - float(item.get("ts", 0) or 0))
    if age > max(0.2, age_limit):
        return None
    item["age_seconds"] = age
    return item


def _set_execution_quote_priority(asset: str, ttl: Optional[int] = None) -> None:
    asset = normalize_asset_name(asset)
    if not asset or not _asset_allowed_for_market_mode(asset):
        return
    keep = int(ttl if ttl is not None else (cfg_get("quote_cache_priority_ttl_seconds", 25) or 25))
    with QUOTE_CACHE_LOCK:
        QUOTE_PRIORITY[asset] = max(float(QUOTE_PRIORITY.get(asset, 0) or 0), time.time() + max(5, keep))


def _quote_priority_assets() -> List[str]:
    now = time.time()
    with QUOTE_CACHE_LOCK:
        expired = [a for a, until in QUOTE_PRIORITY.items() if float(until or 0) <= now]
        for a in expired:
            QUOTE_PRIORITY.pop(a, None)
        mode = normalize_market_mode(cfg_get("market_mode", "auto"))
        ineligible = [a for a in QUOTE_PRIORITY if not _asset_allowed_for_market_mode(a, mode)]
        for a in ineligible:
            QUOTE_PRIORITY.pop(a, None)
        return list(QUOTE_PRIORITY.keys())[:6]


def _quote_priority_pending() -> bool:
    return bool(_quote_priority_assets())


def _quote_cache_background_worker(seed_api: Any) -> None:
    global QUOTE_CACHE_THREAD
    cursor = 0
    try:
        while bool(cfg_get("running", False)) and bool(cfg_get("quote_cache_enabled", True)):
            mode, generation = _market_mode_snapshot()
            assets = [a for a in _quote_priority_assets() if _asset_allowed_for_market_mode(a, mode)]
            if not assets:
                time.sleep(0.25)
                continue
            if SCANNER_PRIORITY_ACTIVE.is_set() or MARKET_UNIVERSE_IO_ACTIVE.is_set():
                time.sleep(0.15)
                continue
            with state_lock:
                api = cfg_get("market_api") or seed_api
            if api is None:
                time.sleep(0.25)
                continue
            asset = assets[cursor % len(assets)]
            cursor += 1
            if _market_mode_generation_changed(generation) or not _asset_allowed_for_market_mode(asset):
                continue
            timeout_s = max(0.5, min(2.5, float(cfg_get("quote_cache_probe_timeout_seconds", 1.2) or 1.2)))
            QUOTE_CACHE_IO_ACTIVE.set()
            try:
                ok, payload, err = _call_daemon_timeout(lambda a=asset: api.get_candles(a, 60, 2, time.time()), timeout_s)
                if ok and isinstance(payload, list):
                    candles = [c for c in payload if isinstance(c, dict) and c.get("close") is not None]
                    candles.sort(key=lambda c: int(c.get("from") or c.get("at") or c.get("id") or 0))
                    if candles and not _market_mode_generation_changed(generation) and _asset_allowed_for_market_mode(asset):
                        last = candles[-1]
                        _quote_cache_set(asset, last.get("close"), "quote_bg_m1", int(last.get("from") or last.get("at") or last.get("id") or 0))
            finally:
                QUOTE_CACHE_IO_ACTIVE.clear()
            time.sleep(max(0.15, float(cfg_get("quote_cache_worker_interval_seconds", 0.35) or 0.35)))
    except Exception:
        pass
    finally:
        with QUOTE_CACHE_LOCK:
            QUOTE_CACHE_THREAD = None


def _kick_quote_cache_worker(api: Any) -> None:
    global QUOTE_CACHE_THREAD
    if api is None or not bool(cfg_get("running", False)) or not bool(cfg_get("quote_cache_enabled", True)):
        return
    with QUOTE_CACHE_LOCK:
        if QUOTE_CACHE_THREAD is not None and QUOTE_CACHE_THREAD.is_alive():
            return
        QUOTE_CACHE_THREAD = threading.Thread(target=_quote_cache_background_worker, args=(api,), daemon=True, name="quote-cache-v108721")
        QUOTE_CACHE_THREAD.start()


def _persist_fast_market_memory(items: Dict[str, Any]) -> None:
    try:
        # Retém somente ativos vistos nos últimos 48h para o arquivo não crescer sem limite.
        cutoff=time.time()-172800
        trimmed={k:v for k,v in items.items() if float((v or {}).get("updated_ts",0) or 0)>=cutoff}
        safe_write_json(FAST_MARKET_MEMORY_FILE,{"version":1,"items":trimmed,"updated_at":datetime.now().isoformat(timespec="seconds")})
    except Exception: pass


def _fast_market_background_worker(seed_api: Any) -> None:
    global FAST_MARKET_INTEL_THREAD, FAST_MARKET_INTEL_CURSOR
    try:
        while bool(cfg_get("running",False)) and bool(cfg_get("fast_market_background_enabled",True)):
            pause=max(10,int(cfg_get("fast_market_background_pause_before_scan_seconds",25) or 25))
            with state_lock:
                next_in=int(cfg_get("next_scan_in_seconds",999) or 999)
                api=cfg_get("market_api") or seed_api
                cached=dict(cfg_get("_last_market_universe") or {})
            if api is None: time.sleep(2); continue
            if SCANNER_PRIORITY_ACTIVE.is_set() or MARKET_UNIVERSE_IO_ACTIVE.is_set() or _quote_priority_pending() or next_in<=pause:
                time.sleep(1.0); continue
            mode, generation = _market_mode_snapshot()
            universe=_filter_assets_for_market_mode(list(cached.get("assets") or []), mode)
            if not universe: time.sleep(2); continue
            batch_n=max(2,min(16,int(cfg_get("fast_market_background_batch_assets",8) or 8)))
            start=FAST_MARKET_INTEL_CURSOR%len(universe)
            batch=(universe[start:]+universe[:start])[:batch_n]
            FAST_MARKET_INTEL_CURSOR=(start+len(batch))%len(universe)
            tf=max(60,int(cfg_get("fast_market_background_timeframe",60) or 60))
            count=max(8,min(30,int(cfg_get("fast_market_background_candles",14) or 14)))
            updates={}; failed=0
            FAST_MARKET_INTEL_IO_ACTIVE.set()
            try:
                for asset in batch:
                    if _market_mode_generation_changed(generation):
                        break
                    if not _asset_allowed_for_market_mode(asset, mode):
                        continue
                    if SCANNER_PRIORITY_ACTIVE.is_set() or int(cfg_get("next_scan_in_seconds",999) or 999)<=pause: break
                    ok,payload,err=_call_daemon_timeout(lambda a=asset: api.get_candles(a,tf,count,time.time()),1.8)
                    if not ok or not isinstance(payload,list):
                        failed+=1
                        if err=="timeout":
                            with FAST_MARKET_INTEL_LOCK: FAST_MARKET_INTEL_META["last_error"]=f"timeout {asset}"
                            break
                        continue
                    feat=_fast_market_features(payload,asset,tf)
                    if feat and not _market_mode_generation_changed(generation) and _asset_allowed_for_market_mode(asset, mode):
                        updates[asset]=feat
                        _quote_cache_set(asset, feat.get("latest_price"), "fast_bg_m1", int(feat.get("price_ts",0) or 0))
                    else: failed+=1
            finally:
                FAST_MARKET_INTEL_IO_ACTIVE.clear()
            if _market_mode_generation_changed(generation):
                updates = {}
            if updates:
                with state_lock:
                    memory=dict(cfg_get("_fast_market_intelligence") or {})
                    memory.update(updates)
                    state["_fast_market_intelligence"]=memory
                _persist_fast_market_memory(memory)
            snap=_fast_market_intelligence_snapshot()
            max_age=max(60,int(cfg_get("fast_market_background_max_age_seconds",240) or 240))
            now=time.time(); coverage=sum(1 for a in universe if now-float((snap.get(a) or {}).get("updated_ts",0) or 0)<=max_age)
            # V108.8.0 Lock Order Guard:
            # NUNCA chama log()/cfg que possa tocar state_lock enquanto segura FAST_MARKET_INTEL_LOCK.
            # Antes, /status fazia state_lock -> FAST lock e este worker podia fazer FAST lock -> state_lock,
            # criando deadlock AB/BA e uma sequência infinita de HTTP 503.
            log_every=max(15,int(cfg_get("fast_market_background_log_interval_seconds",30) or 30))
            should_log=False
            with FAST_MARKET_INTEL_LOCK:
                FAST_MARKET_INTEL_META.update({"updated":int(FAST_MARKET_INTEL_META.get("updated",0))+len(updates),"failed":int(FAST_MARKET_INTEL_META.get("failed",0))+failed,"coverage":coverage,"universe":len(universe),"last_update_ts":now,"last_batch_updated":len(updates),"last_batch_size":len(batch),"mode":mode})
                last_log=float(FAST_MARKET_INTEL_META.get("last_log_ts",0) or 0)
                if now-last_log>=log_every:
                    FAST_MARKET_INTEL_META["last_log_ts"]=now
                    should_log=True
            if should_log:
                otc_active=sum(1 for a in universe if is_otc_asset(a))
                crypto_active=sum(1 for a in universe if (not is_otc_asset(a)) and is_crypto_asset(a))
                normal_active=max(0,len(universe)-otc_active-crypto_active)
                log(f"🌡 FAST BG V108.8.0: mercado atual {coverage}/{len(universe)} com leitura M1 recente · modo={mode} · ativos normal={normal_active} cripto={crypto_active} OTC={otc_active} · lote={len(updates)}/{len(batch)} · próximo scan em {int(next_in)}s.","info")
            time.sleep(max(0.5,float(cfg_get("fast_market_background_interval_seconds",2.0) or 2.0)))
    except Exception as exc:
        with FAST_MARKET_INTEL_LOCK: FAST_MARKET_INTEL_META["last_error"]=str(exc)[:180]
    finally:
        with FAST_MARKET_INTEL_LOCK: FAST_MARKET_INTEL_THREAD=None


def _kick_fast_market_intelligence_worker(api: Any) -> None:
    global FAST_MARKET_INTEL_THREAD
    if api is None or not bool(cfg_get("fast_market_background_enabled",True)) or not bool(cfg_get("running",False)): return
    with FAST_MARKET_INTEL_LOCK:
        if FAST_MARKET_INTEL_THREAD is not None and FAST_MARKET_INTEL_THREAD.is_alive(): return
        FAST_MARKET_INTEL_THREAD=threading.Thread(target=_fast_market_background_worker,args=(api,),daemon=True,name="fast-market-intel-v108721")
        FAST_MARKET_INTEL_THREAD.start()


def _market_universe_refresh_once(api: Any, tf: int) -> bool:
    if api is None or SCANNER_PRIORITY_ACTIVE.is_set() or FAST_MARKET_INTEL_IO_ACTIVE.is_set():
        return False
    started = time.perf_counter()
    with MARKET_UNIVERSE_REFRESH_LOCK:
        MARKET_UNIVERSE_REFRESH_META["last_attempt_ts"] = time.time()
    MARKET_UNIVERSE_IO_ACTIVE.set()
    try:
        mode, generation = _market_mode_snapshot()
        assets, meta = list_scan_assets(api, mode, force_refresh=True, allow_stale=False)
        assets = _filter_assets_for_market_mode(assets, mode)
        if not assets:
            raise RuntimeError("snapshot de universo retornou vazio")
        if _market_mode_generation_changed(generation):
            return False
        elapsed_ms = int((time.perf_counter() - started) * 1000)
        meta = dict(meta or {})
        meta["mode_generation"] = generation
        with state_lock:
            state["_last_market_universe"] = {"assets": list(assets), "meta": meta, "saved_at": time.time()}
        with MARKET_UNIVERSE_REFRESH_LOCK:
            MARKET_UNIVERSE_REFRESH_META.update({"last_success_ts": time.time(), "elapsed_ms": elapsed_ms, "last_error": ""})
        _market_data_success_event(api)
        return True
    except Exception as exc:
        with MARKET_UNIVERSE_REFRESH_LOCK:
            MARKET_UNIVERSE_REFRESH_META.update({"elapsed_ms": int((time.perf_counter() - started) * 1000), "last_error": str(exc)[:180]})
        return False
    finally:
        MARKET_UNIVERSE_IO_ACTIVE.clear()


def _market_universe_refresh_worker(seed_api: Any) -> None:
    global MARKET_UNIVERSE_REFRESH_THREAD
    first = True
    try:
        while True:
            if not bool(cfg_get("market_universe_background_refresh_enabled", True)):
                break
            with state_lock:
                running = bool(cfg_get("running"))
                current_api = cfg_get("market_api") or seed_api
                next_in = int(cfg_get("next_scan_in_seconds", 999) or 999)
            # Permite um warm-up único logo após conectar, mesmo antes de iniciar o bot.
            if not running and not first:
                break
            if current_api is None:
                break
            # V108.8.0: Quote Cache não pode impedir indefinidamente a renovação da
            # prova OPEN V2. Se o last-good envelheceu, o universo ganha prioridade.
            preflight_age = _preflight_last_good_age()
            preflight_max_age = max(3.0, float(cfg_get("market_preflight_background_max_age_seconds", 25) or 25))
            quote_blocks_refresh = _quote_priority_pending() and preflight_age <= preflight_max_age
            preflight_refresh_requested = PREFLIGHT_REFRESH_REQUESTED.is_set()
            if (not preflight_refresh_requested) and (SCANNER_PRIORITY_ACTIVE.is_set() or FAST_MARKET_INTEL_IO_ACTIVE.is_set() or quote_blocks_refresh or (running and next_in <= 12)):
                time.sleep(1.0)
                first = False
                continue
            refreshed = _market_universe_refresh_once(current_api, int(cfg_get("timeframe", 300) or 300))
            if refreshed and preflight_refresh_requested:
                PREFLIGHT_REFRESH_REQUESTED.clear()
            first = False
            if not running:
                break
            interval = max(5, int(cfg_get("market_universe_refresh_interval_seconds", 8) or 8))
            slept = 0
            while slept < interval:
                # V108.9.2: candidato aprovado não espera o intervalo periódico inteiro;
                # stale no Preflight FINAL acorda imediatamente este worker dedicado.
                if PREFLIGHT_REFRESH_REQUESTED.is_set():
                    break
                time.sleep(1.0)
                slept += 1
                with state_lock:
                    if not bool(cfg_get("running")):
                        return
    finally:
        with MARKET_UNIVERSE_REFRESH_LOCK:
            MARKET_UNIVERSE_REFRESH_THREAD = None


def _kick_market_universe_refresh_worker(api: Any) -> None:
    global MARKET_UNIVERSE_REFRESH_THREAD
    if api is None or not bool(cfg_get("market_universe_background_refresh_enabled", True)):
        return
    with MARKET_UNIVERSE_REFRESH_LOCK:
        if MARKET_UNIVERSE_REFRESH_THREAD is not None and MARKET_UNIVERSE_REFRESH_THREAD.is_alive():
            return
        MARKET_UNIVERSE_REFRESH_THREAD = threading.Thread(
            target=_market_universe_refresh_worker, args=(api,), daemon=True, name="market-universe-v103"
        )
        MARKET_UNIVERSE_REFRESH_THREAD.start()


def _fallback_scan_candidates(market_mode: str) -> Tuple[List[str], Dict[str, Any]]:
    mode = normalize_market_mode(market_mode)
    if mode == "otc_only":
        assets = list(OTC_CANDIDATE_ASSETS)
    elif mode == "crypto_only":
        assets = list(CRYPTO_CANDIDATE_ASSETS)
    elif mode == "normal_only":
        assets = list(dict.fromkeys(NORMAL_BINARY_CANDIDATE_ASSETS + CRYPTO_CANDIDATE_ASSETS))
    else:
        # Em fallback só gera radar; a prova OPEN ocorre no preflight FINAL da ordem.
        assets = list(dict.fromkeys(OTC_CANDIDATE_ASSETS + CRYPTO_CANDIDATE_ASSETS + NORMAL_BINARY_CANDIDATE_ASSETS))
    meta = {
        "configured_mode": mode,
        "configured_label": market_mode_label(mode),
        "used_mode": "background_snapshot_warming",
        "reason": "snapshot OPEN em background ainda não disponível; candidatos conservadores, com revalidação final obrigatória",
        "normal_count": sum(1 for a in assets if not is_otc_asset(a) and not is_crypto_asset(a)),
        "crypto_count": sum(1 for a in assets if not is_otc_asset(a) and is_crypto_asset(a)),
        "otc_count": sum(1 for a in assets if is_otc_asset(a)),
        "open_total_count": 0,
        "found_count": len(assets),
        "compatible_count": len(assets),
        "incompatible_ignored": 0,
        "v2_prefilter": {"verified": False, "product": _option_product_for_duration(max(1, int(cfg_get("timeframe", 300) or 300)//60)), "before": len(assets), "open": 0, "closed": 0, "missing": 0, "error": "background warming", "authority": "final_preflight_only"},
        "v2_prefilter_open_count": 0,
        "v2_prefilter_before_count": len(assets),
        "market_init_background": 1,
        "market_init_stale": 1,
    }
    return assets, meta


def _list_scan_assets_budgeted(api: Any, market_mode: str) -> Tuple[List[str], Dict[str, Any]]:
    """V103: scanner NUNCA espera get_all_init/get_all_init_v2.

    Ele lê o último snapshot publicado pelo worker de Market Universe. Se ainda não
    existe snapshot, usa um radar conservador e deixa a confirmação OPEN para o
    preflight fresco imediatamente antes de api.buy().
    """
    started = time.perf_counter()
    _kick_market_universe_refresh_worker(api)
    status = _market_universe_cache_status()
    cached = dict(status.get("cached") or {})
    requested_mode = normalize_market_mode(market_mode)
    raw_cached_assets = list(cached.get("assets") or [])
    assets = _filter_assets_for_market_mode(raw_cached_assets, requested_mode)
    meta = dict(cached.get("meta") or {})
    if raw_cached_assets and len(assets) != len(raw_cached_assets):
        meta["mode_isolation_filtered"] = len(raw_cached_assets) - len(assets)
    meta["configured_mode"] = requested_mode
    meta["configured_label"] = market_mode_label(requested_mode)
    age = float(status.get("age_seconds", 999999) or 999999)
    max_stale = max(30, int(cfg_get("market_universe_max_stale_seconds", 180) or 180))
    if assets and age <= max_stale:
        meta["market_init_background"] = 1
        meta["market_init_stale"] = 0
        meta["market_snapshot_age_seconds"] = round(age, 1)
        meta["market_background_refresh_ms"] = int((status.get("refresh") or {}).get("elapsed_ms", 0) or 0)
    elif assets:
        # Mesmo stale continua útil para ranking; não autoriza ordem. Preflight FINAL decide.
        meta["market_init_background"] = 1
        meta["market_init_stale"] = 1
        meta["market_snapshot_age_seconds"] = round(age, 1)
        meta["reason"] = f"snapshot OPEN em background com {int(age)}s; usado apenas no radar, preflight final obrigatório"
    else:
        assets, meta = _fallback_scan_candidates(market_mode)
    _phase_timing_add("market_init_ms", (time.perf_counter() - started) * 1000.0)
    return assets, meta


# ── Smart Prefilter V94: HOT + exploração + cooldown técnico ─────────────────
def _smart_asset_memory_snapshot() -> Dict[str, Dict[str, Any]]:
    acquired = state_lock.acquire(timeout=0.02)
    try:
        raw = cfg_get("_smart_asset_memory") or {}
        return {normalize_asset_name(k): dict(v or {}) for k, v in dict(raw).items() if k}
    finally:
        if acquired:
            state_lock.release()


def _smart_lab_asset_stats(limit: int = 900) -> Dict[str, Dict[str, Any]]:
    """V101: snapshot já calculado pelo Laboratório; prefilter NUNCA espera signal_lab_lock."""
    try:
        raw = cfg_get("_smart_lab_stats_cache") or {}
        return {normalize_asset_name(k): dict(v or {}) for k, v in dict(raw).items() if k}
    except Exception:
        return {}


def _smart_prefilter_score(asset: str, mem: Dict[str, Any], lab: Dict[str, Any]) -> float:
    """Score HOT V96: recompensa força recente e derruba rapidamente sinais em deterioração."""
    now = time.time()
    score = 0.0
    tech = float(mem.get("last_tech", 0) or 0)
    payout = float(mem.get("last_payout", 0) or 0)
    adaptive = float(mem.get("last_adaptive", tech) or tech)
    signal = float(mem.get("last_signal", tech) or tech)
    entry = float(mem.get("last_entry", tech) or tech)
    score += tech * 1.55 + adaptive * 0.35 + signal * 0.30 + entry * 0.45
    score += max(0.0, payout - 65.0) * 0.55

    # HOT Diversity V96: 50% é a faixa mínima que ainda pode ganhar promoção Lumi.
    # Abaixo disso o ativo perde espaço HOT, mas continua elegível à exploração rotativa.
    if tech >= 55:
        score += 30.0
    elif tech >= 50:
        score += 8.0
    elif tech >= 47:
        score -= 14.0
    elif tech > 0:
        score -= 30.0

    below50 = int(mem.get("below50_streak", 0) or 0)
    decline = int(mem.get("decline_streak", 0) or 0)
    delta = float(mem.get("last_tech_delta", 0) or 0)
    score -= min(42.0, below50 * 13.0)
    score -= min(30.0, decline * 9.0)
    if delta < 0:
        score -= min(22.0, abs(delta) * 2.2)
    if float(mem.get("hot_exclude_until", 0) or 0) > now:
        score -= 80.0

    last_seen = float(mem.get("last_seen", 0) or 0)
    if last_seen > 0:
        age = max(0.0, now - last_seen)
        score += max(0.0, 18.0 - age / 60.0)
    if int(mem.get("last_approved", 0) or 0):
        score += 22.0
    samples = int(lab.get("samples", 0) or 0)
    if samples >= 5:
        wr = float(lab.get("winrate", 50) or 50)
        score += max(-18.0, min(22.0, (wr - 50.0) * 0.8))
        score += min(10.0, samples / 12.0)
    return float(score)


def _fmi_payout_quality(payout: Any) -> float:
    """Converte payout atual em qualidade 0..100 sem criar sinal por si só."""
    try:
        p = float(payout or 0)
    except Exception:
        p = 0.0
    if p <= 0:
        return 30.0
    # 70%=~33, 80%=~67, 90%=100. Payout baixo perde ranking, nunca vira veto aqui.
    return max(0.0, min(100.0, (p - 60.0) * (100.0 / 30.0)))


def _fmi_contract_label(asset: str, payout_info: Optional[Dict[str, Any]] = None) -> str:
    source=str((payout_info or {}).get("source") or "").lower()
    for kind in ("digital","binary","turbo"):
        if f":{kind}" in source: return kind
    return "otc" if is_otc_asset(asset) else "binary"


def _fmi_underlying_family(asset: str) -> str:
    return normalize_asset_name(asset).replace("-OTC", "")


def full_market_opportunity_score(asset: str, mem: Dict[str, Any], lab: Dict[str, Any], payout_info: Optional[Dict[str, Any]] = None, fast_market: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """V108.8.0: avaliação FAST O(1) para CADA ativo OPEN.

    Não chama candles. Usa somente payout do snapshot único da rodada, inteligência
    persistida da última análise técnica e estatística do Lab. É um RANKING de descoberta;
    jamais aprova entrada nem reduz qualquer guardrail REAL.
    """
    now = time.time()
    payout = int((payout_info or {}).get("payout", 0) or 0)
    has_mem = bool(mem)
    tech_raw = float(mem.get("last_tech", 50) if has_mem else 50)
    tech = max(0.0, min(100.0, tech_raw if tech_raw > 0 else 50.0))
    adaptive = max(0.0, min(100.0, float(mem.get("last_adaptive", tech) or tech)))
    signal = max(0.0, min(100.0, float(mem.get("last_signal", tech) or tech)))
    entry = max(0.0, min(100.0, float(mem.get("last_entry", tech) or tech)))
    samples = int(lab.get("samples", 0) or 0)
    min_hist = max(1, int(cfg_get("full_market_intelligence_min_history_samples", 3) or 3))
    lab_wr = float(lab.get("winrate", 50) or 50) if samples >= min_hist else 50.0
    lab_wr = max(0.0, min(100.0, lab_wr))
    payout_q = _fmi_payout_quality(payout)
    fast_market = dict(fast_market or {})
    max_fast_age = max(60, int(cfg_get("fast_market_background_max_age_seconds", 240) or 240))
    fast_age = max(0.0, time.time()-float(fast_market.get("updated_ts",0) or 0)) if fast_market else 999999.0
    fast_fresh = bool(fast_market and fast_age <= max_fast_age)
    fast_score = max(0.0, min(100.0, float(fast_market.get("score",50) or 50))) if fast_fresh else 50.0

    # V108.8.0: o mercado ATUAL tem peso alto para quebrar empates no cold-start.
    # Memória/Lab continuam importantes, mas nenhuma dessas parcelas aprova ordem.
    if fast_fresh:
        score = tech*0.16 + adaptive*0.08 + signal*0.07 + entry*0.09 + payout_q*0.18 + lab_wr*0.12 + fast_score*0.30
    else:
        score = tech*0.24 + adaptive*0.13 + signal*0.12 + entry*0.16 + payout_q*0.20 + lab_wr*0.15
    penalty = 0.0
    below50 = int(mem.get("below50_streak", 0) or 0)
    decline = int(mem.get("decline_streak", 0) or 0)
    penalty += min(10.0, below50 * 2.5)
    penalty += min(8.0, decline * 2.0)
    if float(mem.get("weak_until", 0) or 0) > now:
        penalty += 5.0
    if float(mem.get("hot_exclude_until", 0) or 0) > now or bool(mem.get("recovery_required")):
        penalty += 4.0
    if int(mem.get("last_approved", 0) or 0):
        score += 3.0

    last_seen = float(mem.get("last_seen", 0) or 0)
    age_s = max(0.0, now - last_seen) if last_seen else None
    # Descoberta global: ativo nunca analisado recebe bônus pequeno; ativo muito antigo
    # recupera prioridade gradualmente. Não é quota por categoria e não autoriza ordem.
    discovery_bonus = 0.0
    if age_s is None:
        discovery_bonus = 5.0
    elif age_s <= 900:
        discovery_bonus = max(0.0, 2.0 - age_s / 450.0)
    elif age_s >= 1800:
        discovery_bonus = min(7.0, 2.0 + (age_s - 1800.0) / 1800.0)
    score += discovery_bonus

    score = max(0.0, min(100.0, score - penalty))
    return {
        "asset": normalize_asset_name(asset),
        "score": round(score, 1),
        "payout": payout,
        "payout_quality": round(payout_q, 1),
        "cached_tech": int(round(tech)) if has_mem else None,
        "cached_adaptive": int(round(adaptive)) if has_mem else None,
        "lab_samples": samples,
        "lab_winrate": round(lab_wr, 1) if samples >= min_hist else None,
        "history": bool(has_mem or samples >= min_hist),
        "fast_market_score": round(fast_score,1) if fast_fresh else None,
        "fast_market_direction": str(fast_market.get("direction") or "hold") if fast_fresh else None,
        "fast_market_age_s": int(fast_age) if fast_fresh else None,
        "contract": _fmi_contract_label(asset, payout_info),
        "underlying": _fmi_underlying_family(asset),
        "penalty": round(penalty, 1),
        "discovery_bonus": round(discovery_bonus, 1),
    }


ELITE_CHANGE_LOCK = threading.RLock()
ELITE_CHANGE_HISTORY: Dict[str, Dict[str, Any]] = {}

def _elite_change_gate_allows(asset: str, feat: Dict[str, Any], ranked: Dict[str, Any], now_ts: float) -> Tuple[bool, str]:
    """V108.8.0: libera nova reanálise apenas quando houve informação nova relevante.

    O gate atua somente na frequência do Elite Watcher. Não aprova nem bloqueia entrada REAL;
    o FULL Scan continua independente e todos os gates DEEP/MTF/Lumi/EV/Preflight permanecem.
    """
    if not bool(cfg_get("elite_change_gate_enabled", True)):
        return True, "change gate desativado"
    asset = normalize_asset_name(asset)
    cooldown = max(15, int(cfg_get("elite_repeat_cooldown_seconds", 55) or 55))
    min_fast_delta = max(0.5, float(cfg_get("elite_min_fast_delta", 2.0) or 2.0))
    min_tech_delta = max(1, int(cfg_get("elite_min_tech_delta", 3) or 3))
    fast_score = float((feat or {}).get("score", 0) or 0)
    direction = normalize_lumi_action((feat or {}).get("direction") or "hold")
    price_ts = int((feat or {}).get("price_ts", 0) or 0)
    cached_tech = ranked.get("cached_tech")
    try: cached_tech = int(cached_tech) if cached_tech is not None else None
    except Exception: cached_tech = None
    with ELITE_CHANGE_LOCK:
        prev = dict(ELITE_CHANGE_HISTORY.get(asset) or {})
        if not prev:
            return True, "primeira observação elite"
        elapsed = max(0.0, now_ts - float(prev.get("selected_ts", 0) or 0))
        if elapsed >= cooldown:
            return True, f"cooldown {cooldown}s concluído"
        if price_ts and int(prev.get("price_ts", 0) or 0) and price_ts != int(prev.get("price_ts", 0) or 0):
            return True, "nova vela M1"
        if direction != normalize_lumi_action(prev.get("direction") or "hold"):
            return True, "direção FAST mudou"
        if abs(fast_score - float(prev.get("fast_score", fast_score) or fast_score)) >= min_fast_delta:
            return True, f"FAST mudou >= {min_fast_delta:.1f}"
        prev_tech = prev.get("cached_tech")
        if cached_tech is not None and prev_tech is not None and abs(cached_tech - int(prev_tech)) >= min_tech_delta:
            return True, f"técnica mudou >= {min_tech_delta}pp"
        return False, f"mesma vela/condição; cooldown {max(1, int(cooldown-elapsed))}s"

def _elite_change_gate_mark_selected(rows: List[Dict[str, Any]], fast: Dict[str, Dict[str, Any]], now_ts: float) -> None:
    with ELITE_CHANGE_LOCK:
        for row in rows:
            asset = normalize_asset_name(row.get("asset", ""))
            if not asset: continue
            feat = dict(fast.get(asset) or {})
            ELITE_CHANGE_HISTORY[asset] = {
                "selected_ts": now_ts,
                "price_ts": int(feat.get("price_ts", 0) or 0),
                "fast_score": float(feat.get("score", row.get("fast_market_score", 0)) or 0),
                "direction": normalize_lumi_action(feat.get("direction") or row.get("fast_market_direction") or "hold"),
                "cached_tech": row.get("cached_tech"),
            }
        # Evita crescimento ilimitado.
        cutoff = now_ts - 3600
        for key in list(ELITE_CHANGE_HISTORY.keys()):
            if float((ELITE_CHANGE_HISTORY.get(key) or {}).get("selected_ts", 0) or 0) < cutoff:
                ELITE_CHANGE_HISTORY.pop(key, None)

def elite_opportunity_candidates() -> Tuple[List[str], Dict[str, Any]]:
    """V108.8.0 Elite Watcher 2.0: fila quente com prioridade contextual + Change Gate.

    Seleção continua O(1), baseada em FAST BG/memória/Lab/payout. FAST nunca autoriza
    compra: os selecionados ainda precisam de DEEP, Técnica, MTF, Lumi/fallback, EV,
    freshness e Preflight FINAL.
    """
    if not bool(cfg_get("elite_opportunity_watcher_enabled", True)):
        return [], {"enabled": False, "reason": "desativado"}
    mode = normalize_market_mode(cfg_get("market_mode", "auto"))
    fast = _fast_market_intelligence_snapshot()
    memory = _smart_asset_memory_snapshot()
    lab = _smart_lab_asset_stats()
    with state_lock:
        cached_universe = dict(cfg_get("_last_market_universe") or {})
    allowed_universe = set(_filter_assets_for_market_mode(list(cached_universe.get("assets") or []), mode))
    active = {normalize_asset_name(o.get("asset", "")) for o in get_active_open_orders() if o.get("asset")}
    now_ts = time.time()
    max_age = max(30, int(cfg_get("elite_opportunity_max_fast_age_seconds", 150) or 150))
    min_fast = float(cfg_get("elite_opportunity_min_fast_score", 66.0) or 66.0)
    min_score = float(cfg_get("elite_opportunity_min_score", 66.0) or 66.0)
    require_direction = bool(cfg_get("elite_opportunity_require_direction", True))
    tech_target = max(40, int(cfg_get("elite_priority_cached_tech_target", 57) or 57))
    rows: List[Dict[str, Any]] = []
    skipped_change = 0
    skipped_change_assets: List[str] = []
    for asset, feat in fast.items():
        asset = normalize_asset_name(asset)
        if not asset or asset in active or not _asset_allowed_for_market_mode(asset, mode):
            continue
        if allowed_universe and asset not in allowed_universe:
            continue
        age = max(0.0, now_ts - float((feat or {}).get("updated_ts", 0) or 0))
        if age > max_age:
            continue
        fast_score = float((feat or {}).get("score", 0) or 0)
        direction = normalize_lumi_action((feat or {}).get("direction") or "hold")
        if fast_score < min_fast or (require_direction and direction not in VALID_DIRECTIONS):
            continue
        payout_info = _payout_cache_get(asset) or _payout_last_good_get(asset) or {"payout": 0, "source": "elite:no_payout_cache"}
        ranked = full_market_opportunity_score(asset, memory.get(asset, {}), lab.get(asset, {}), payout_info, feat)
        if float(ranked.get("score", 0) or 0) < min_score:
            continue
        ranked["fast_market_score"] = round(fast_score, 1)
        ranked["fast_market_direction"] = direction
        ranked["fast_market_age_s"] = int(age)
        ranked["fast_price_ts"] = int((feat or {}).get("price_ts", 0) or 0)

        # Prioridade contextual: favorece oportunidade que já se aproxima do corte técnico,
        # payout saudável e FAST forte. Isso ordena a fila; não reduz nenhum gate REAL.
        cached_tech = ranked.get("cached_tech")
        try: tech = float(cached_tech) if cached_tech is not None else 50.0
        except Exception: tech = 50.0
        payout = int(ranked.get("payout", 0) or 0)
        priority = float(ranked.get("score", 0) or 0)
        priority += max(0.0, fast_score - min_fast) * 0.75
        priority += max(-5.0, min(10.0, (tech - tech_target) * 0.55))
        priority += max(0.0, min(5.0, (payout - 70) * 0.22))
        if tech >= tech_target: priority += 3.0
        if tech >= 60: priority += 2.0
        ranked["elite_priority_score"] = round(priority, 2)
        ranked["elite_priority_reason"] = f"FAST {fast_score:.0f} · T* {int(tech) if cached_tech is not None else '—'} · payout {payout or '—'}"

        allow, gate_reason = _elite_change_gate_allows(asset, feat or {}, ranked, now_ts)
        ranked["elite_change_gate"] = gate_reason
        if not allow:
            skipped_change += 1
            if len(skipped_change_assets) < 8: skipped_change_assets.append(asset)
            continue
        rows.append(ranked)

    rows.sort(key=lambda x: (float(x.get("elite_priority_score", 0) or 0), float(x.get("score", 0) or 0), float(x.get("fast_market_score", 0) or 0), int(x.get("payout", 0) or 0)), reverse=True)
    max_assets = max(2, min(10, int(cfg_get("elite_opportunity_max_assets", 6) or 6)))
    selected: List[Dict[str, Any]] = []
    families = set()
    for row in rows:
        fam = str(row.get("underlying") or _fmi_underlying_family(row.get("asset", "")))
        if bool(cfg_get("full_market_contract_diversity_enabled", True)) and fam in families:
            continue
        selected.append(row); families.add(fam)
        if len(selected) >= max_assets: break
    if len(selected) < max_assets:
        selected_assets = {r.get("asset") for r in selected}
        for row in rows:
            if row.get("asset") in selected_assets: continue
            selected.append(row)
            if len(selected) >= max_assets: break
    _elite_change_gate_mark_selected(selected, fast, now_ts)
    assets = [normalize_asset_name(r.get("asset", "")) for r in selected if r.get("asset")]
    status = "fila inteligente pronta" if assets else (f"Change Gate segurou {skipped_change} repetição(ões) sem mudança" if skipped_change else "aguardando oportunidade FAST acima do gatilho")
    meta = {
        "enabled": True, "eligible": len(rows), "selected": len(assets), "assets": assets,
        "top": selected[:10], "min_score": min_score, "min_fast_score": min_fast,
        "max_age_seconds": max_age, "open_orders": len(active), "updated_at": now_hms(),
        "last_poll_ts": now_ts, "status": status, "change_gate_skipped": skipped_change,
        "change_gate_assets": skipped_change_assets,
    }
    with state_lock: state["elite_watcher"] = dict(meta)
    return assets, meta

def full_market_intelligence_select_assets(assets: List[str], tf: int, payout_snapshot: Optional[Dict[str, Any]]) -> Tuple[List[str], Dict[str, Any]]:
    """V108.8.0: 100% OPEN -> Opportunity Score -> ranking global -> Top 24 + 10 reservas.

    Não há quota por OTC/normal/cripto. Todas as categorias competem pelo MESMO score.
    """
    started = time.perf_counter()
    universe_all = list(dict.fromkeys(normalize_asset_name(a) for a in (assets or []) if a))
    active_assets = {normalize_asset_name(o.get("asset", "")) for o in get_active_open_orders() if o.get("asset")}
    universe = [a for a in universe_all if a not in active_assets]
    memory = _smart_asset_memory_snapshot()
    lab_stats = _smart_lab_asset_stats()
    fast_market = _fast_market_intelligence_snapshot()
    ranked: List[Dict[str, Any]] = []
    for asset in universe:
        info = _payout_snapshot_info(payout_snapshot, asset)
        item = full_market_opportunity_score(asset, memory.get(asset, {}), lab_stats.get(asset, {}), info, fast_market.get(asset, {}))
        ranked.append(item)
    ranked.sort(key=lambda x: (float(x.get("score", 0)), int(x.get("payout", 0)), str(x.get("asset", ""))), reverse=True)
    for idx, item in enumerate(ranked, start=1):
        item["rank"] = idx

    heavy_n = max(12, min(len(ranked), int(cfg_get("full_market_radar_heavy_assets", 24) or 24))) if ranked else 0
    reserve_n = max(0, min(max(0, len(ranked) - heavy_n), int(cfg_get("full_market_radar_reserve_assets", 10) or 10)))
    if bool(cfg_get("full_market_contract_diversity_enabled", True)) and ranked:
        max_same=max(1,int(cfg_get("full_market_max_same_underlying",1) or 1))
        selected_items=[]; remaining=[]; family_count={}
        for item in ranked:
            fam=str(item.get("underlying") or _fmi_underlying_family(item.get("asset","")))
            if len(selected_items)<heavy_n and int(family_count.get(fam,0))<max_same:
                selected_items.append(item); family_count[fam]=int(family_count.get(fam,0))+1
            else:
                remaining.append(item)
        if len(selected_items)<heavy_n:
            selected_items.extend(remaining[:heavy_n-len(selected_items)])
            remaining=remaining[heavy_n-len(selected_items):]
        selected_keys={x.get("asset") for x in selected_items}
        remaining=[x for x in ranked if x.get("asset") not in selected_keys]
        reserve_items=remaining[:reserve_n]
    else:
        selected_items = ranked[:heavy_n]
        reserve_items = ranked[heavy_n:heavy_n + reserve_n]
    selected = [x["asset"] for x in selected_items]
    reserves = [x["asset"] for x in reserve_items]
    now = time.time()
    weak_count = sum(1 for a in universe if float((memory.get(a) or {}).get("weak_until", 0) or 0) > now)
    declining = sum(1 for a in universe if int((memory.get(a) or {}).get("decline_streak", 0) or 0) >= 1)
    history_count = sum(1 for x in ranked if x.get("history"))
    top_n = max(5, min(10, int(cfg_get("full_market_intelligence_log_top", 10) or 10)))
    meta = {
        "enabled": True,
        "full_market_radar": 1,
        "full_market_intelligence": 1,
        "before": len(universe_all),
        "evaluated_fast": len(ranked),
        "history_covered": history_count,
        "fast_background_covered": sum(1 for x in ranked if x.get("fast_market_score") is not None),
        "open_order_skipped": max(0, len(universe_all) - len(universe)),
        "selected": len(selected),
        "selected_otc": sum(1 for a in selected if is_otc_asset(a)),
        "selected_crypto": sum(1 for a in selected if (not is_otc_asset(a)) and is_crypto_asset(a)),
        "selected_normal": sum(1 for a in selected if (not is_otc_asset(a)) and not is_crypto_asset(a)),
        "hot": sum(1 for x in selected_items if float(x.get("score", 0)) >= 65.0),
        "explore": sum(1 for x in selected_items if not x.get("history")),
        "weak_cooldown": weak_count,
        "hot_excluded": sum(1 for a in universe if float((memory.get(a) or {}).get("hot_exclude_until", 0) or 0) > now or bool((memory.get(a) or {}).get("recovery_required"))),
        "declining": declining,
        "forced_recovery": 0,
        "recovery_ready": sum(1 for a in universe if bool((memory.get(a) or {}).get("recovery_required")) and float((memory.get(a) or {}).get("hot_exclude_until", 0) or 0) <= now),
        "budget": heavy_n,
        "hot_assets": [x["asset"] for x in selected_items if float(x.get("score", 0)) >= 65.0][:12],
        "explore_assets": [x["asset"] for x in selected_items if not x.get("history")][:16],
        "reserve_assets": reserves,
        "reserve_count": len(reserves),
        "top_opportunities": ranked[:top_n],
        "fast_ranking": ranked,
        "prefilter_budget_fallback": 0,
        "elapsed_ms": int((time.perf_counter() - started) * 1000),
    }
    return selected, meta



def _shadow_breakout_flag(ci: Dict[str, Any]) -> str:
    if bool(ci.get("breakout_confirmed")) or bool(ci.get("breakout")): return "breakout"
    if int(ci.get("false_breakout_risk",0) or 0)>=60: return "fakeout"
    return "neutral"


def shadow_intelligence_for_row(row: Dict[str, Any]) -> Dict[str, Any]:
    """Edge contextual Shadow com fallback por camadas e amostra mínima.

    Edge positivo apenas melhora ranking. Edge fortemente negativo, com amostra suficiente,
    pode bloquear no Wall Street Risk Gate. Nunca reduz o corte REAL.
    """
    if not bool(cfg_get("shadow_intelligence_enabled",True)):
        return {"samples":0,"edge_pp":0.0,"adjustment":0.0,"status":"disabled","source":"disabled"}
    direction=normalize_lumi_action(row.get("direction") or "hold")
    if direction not in VALID_DIRECTIONS:
        return {"samples":0,"edge_pp":0.0,"adjustment":0.0,"status":"hold","source":"hold"}
    tech=int(row.get("technical_confidence",0) or 0)
    ci=dict(row.get("candle_intelligence") or {})
    candle=int(row.get("candle_score",ci.get("score",50)) or 50)
    pa=int(ci.get("price_action_score",50) or 50)
    fake=int(ci.get("false_breakout_risk",0) or 0)
    regime=str(row.get("regime") or (row.get("regime_info") or {}).get("name") or "indefinido")
    breakout=_shadow_breakout_flag(ci)
    key=f"{direction}|{tech//5}|{candle//10}|{pa//10}|{fake//20}|{regime}|{breakout}"
    now=time.time()
    with SHADOW_INTELLIGENCE_LOCK:
        cached=SHADOW_INTELLIGENCE_CACHE.get(key)
        if cached and now-float(cached.get("ts",0) or 0)<60:
            return dict(cached.get("value") or {})
    records=_signal_lab_resolved_records(limit=SIGNAL_LAB_HISTORY_WINDOW)
    prepared=[]
    for r in records:
        result=str(r.get("actual_result") or "").upper()
        if result not in {"WIN","LOSS"}: result=str(r.get("result") or "").upper()
        if result not in {"WIN","LOSS"}: continue
        if normalize_lumi_action(r.get("direction") or "hold")!=direction: continue
        rci=dict(r.get("candle_intelligence") or {})
        prepared.append((r,result,int(r.get("technical_confidence",0) or 0),int(r.get("candle_score",rci.get("score",50)) or 50),int(rci.get("price_action_score",50) or 50),int(rci.get("false_breakout_risk",0) or 0),str(r.get("regime") or "indefinido"),_shadow_breakout_flag(rci)))
    min_n=max(8,int(cfg_get("shadow_intelligence_min_samples",20) or 20))
    tiers=[]
    tiers.append(("contexto_completo",[x for x in prepared if abs(x[2]-tech)<=7 and abs(x[3]-candle)<=15 and abs(x[4]-pa)<=20 and (x[5]//25)==(fake//25) and (regime=="indefinido" or x[6] in {regime,"indefinido"}) and (breakout=="neutral" or x[7]==breakout)]))
    tiers.append(("tecnica+candle+pa",[x for x in prepared if abs(x[2]-tech)<=8 and abs(x[3]-candle)<=20 and abs(x[4]-pa)<=25]))
    tiers.append(("direcao+faixa_tecnica",[x for x in prepared if abs(x[2]-tech)<=8]))
    source="coletando"; similar=[]
    for name,rows in tiers:
        if len(rows)>=min_n:
            source=name; similar=rows[:300]; break
        if len(rows)>len(similar): source=name; similar=rows[:300]
    n=len(similar)
    wins=sum(1 for x in similar if x[1]=="WIN")
    wr=wins/max(1,n)*100.0 if n else 0.0
    payouts=[int(x[0].get("payout",0) or 0) for x in similar if int(x[0].get("payout",0) or 0)>0]
    avg_p=sum(payouts)/len(payouts) if payouts else float(row.get("payout",0) or cfg_get("min_payout",70) or 70)
    be=100.0/(1.0+max(0.01,avg_p/100.0))
    edge=wr-be if n else 0.0
    influence_min=8
    full_min=max(20,min_n)
    cap=max(0.0,float(cfg_get("shadow_intelligence_max_adjustment",8.0) or 8.0))
    raw_adjust=max(-cap,min(cap,edge*0.35))
    if n < influence_min:
        confidence=0.0
        adjustment=0.0
        si_status="collecting"
        weight_tier="none"
    elif n < full_min:
        progress=(n-influence_min)/max(1.0,float(full_min-influence_min))
        confidence=0.25 + 0.35*max(0.0,min(1.0,progress))
        reduced_cap=min(cap,2.5)
        adjustment=max(-reduced_cap,min(reduced_cap,raw_adjust*confidence))
        si_status="reduced"
        weight_tier="reduced"
    else:
        confidence=min(1.0,n/max(1.0,full_min*2.0))
        adjustment=raw_adjust*confidence
        si_status="active"
        weight_tier="normal"
    value={"samples":n,"wins":wins,"losses":n-wins,"winrate":round(wr,1),"break_even":round(be,1),"edge_pp":round(edge,1),"adjustment":round(adjustment,2),"status":si_status,"weight_tier":weight_tier,"confidence":round(confidence,3),"pattern":key,"source":source}
    with SHADOW_INTELLIGENCE_LOCK: SHADOW_INTELLIGENCE_CACHE[key]={"ts":now,"value":dict(value)}
    return value

def _deep_market_opportunity_score(row: Dict[str, Any]) -> int:
    """Ranking DEEP após candles. Ordena; não substitui gates/thresholds."""
    tech = max(0.0, min(100.0, float(row.get("technical_confidence", 0) or 0)))
    adaptive = max(0.0, min(100.0, float(row.get("adaptive_score", tech) or tech)))
    ci = row.get("candle_intelligence") if isinstance(row.get("candle_intelligence"), dict) else {}
    candle = max(0.0, min(100.0, float(row.get("candle_score", ci.get("score", 50)) or 50)))
    pa = max(0.0, min(100.0, float(ci.get("price_action_score", 50) or 50)))
    fakeout = max(0.0, min(100.0, float(ci.get("false_breakout_risk", 0) or 0)))
    payout_q = _fmi_payout_quality(row.get("payout", 0))
    quality = float(compute_opportunity_quality(row, row.get("lumi") if isinstance(row.get("lumi"), dict) else None).get("score", 0) or 0)
    mtf_raw = row.get("mtf_alignment")
    has_mtf = mtf_raw is not None
    mtf = max(0.0, min(100.0, float(mtf_raw or 50)))
    # V108.8.0: Quality entra no RANKING, nunca substitui o hard gate técnico.
    if has_mtf:
        score = tech*0.26 + quality*0.20 + adaptive*0.10 + candle*0.12 + pa*0.07 + payout_q*0.08 + mtf*0.13 + (100.0-fakeout)*0.04
    else:
        score = tech*0.30 + quality*0.20 + adaptive*0.11 + candle*0.14 + pa*0.08 + payout_q*0.10 + (100.0-fakeout)*0.07
    si=shadow_intelligence_for_row(row)
    row["shadow_intelligence"]=si
    score += float(si.get("adjustment",0) or 0)
    if normalize_lumi_action(row.get("direction") or "hold") not in VALID_DIRECTIONS:
        score -= 12.0
    return int(round(max(0.0, min(100.0, score))))


def _log_fmi_top(meta: Dict[str, Any]) -> None:
    top = list(meta.get("top_opportunities") or [])
    if not top:
        return
    def fmt(x):
        tech = x.get("cached_tech")
        tech_txt = f"T*{tech}" if tech is not None else "T*—"
        fast=x.get("fast_market_score")
        fast_txt=f" F={float(fast):.0f}{str(x.get('fast_market_direction') or 'h')[:1].upper()}" if fast is not None else " F=—"
        contract=str(x.get("contract") or "")[:3].upper()
        return f"#{int(x.get('rank',0))} {x.get('asset')} S={float(x.get('score',0)):.1f} P={int(x.get('payout',0) or 0)}% {tech_txt}{fast_txt} C={contract}"
    log("🌎 FAST MARKET TOP 1-5 | " + " · ".join(fmt(x) for x in top[:5]), "info")
    if len(top) > 5:
        log("🌎 FAST MARKET TOP 6-10 | " + " · ".join(fmt(x) for x in top[5:10]), "info")


def _log_technical_distribution(rows: List[Dict[str, Any]], min_tech: int) -> None:
    """V108.8.0: expõe a distribuição do Technical Engine em cada rodada."""
    valid=[r for r in rows if r.get("asset") and not r.get("excluded_from_round")]
    if not valid:
        return
    vals=[max(0,min(100,int(r.get("technical_confidence",0) or 0))) for r in valid]
    b0=b1=b2=b3=b4=0
    for v in vals:
        if v < 40: b0 += 1
        elif v < 50: b1 += 1
        elif v < 60: b2 += 1
        elif v < 70: b3 += 1
        else: b4 += 1
    best=max(valid,key=lambda r:int(r.get("technical_confidence",0) or 0))
    best_v=int(best.get("technical_confidence",0) or 0)
    avg=sum(vals)/max(1,len(vals))
    passed=sum(1 for v in vals if v >= int(min_tech))
    log(
        f"📊 TECH DISTRIBUTION V108.8.0 | <40={b0} · 40-49={b1} · 50-59={b2} · 60-69={b3} · 70+={b4} · "
        f"média={avg:.1f}% · máx={best_v}% {best.get('asset')} · >={int(min_tech)}={passed}/{len(vals)} · degrau anterior={technical_previous_level(min_tech, cfg_get('strategy','combined'))}%.",
        "info",
    )



def _log_technical_consensus_v2(rows: List[Dict[str, Any]], limit: int = 3) -> None:
    if not bool(cfg_get("technical_consensus_log_enabled", True)):
        return
    candidates = []
    for r in rows or []:
        if not isinstance(r, dict) or not r.get("asset") or r.get("excluded_from_round"):
            continue
        sig = r.get("signals") if isinstance(r.get("signals"), dict) else {}
        meta = sig.get("technical_consensus_v2") if isinstance(sig.get("technical_consensus_v2"), dict) else {}
        if meta.get("enabled"):
            candidates.append(r)
    if not candidates:
        return
    candidates.sort(key=lambda r: (int(r.get("technical_confidence",0) or 0), int((r.get("opportunity_quality") or {}).get("score",0) or 0), int(r.get("payout",0) or 0)), reverse=True)
    parts=[]
    for r in candidates[:max(1,int(limit or 3))]:
        sig = r.get("signals") if isinstance(r.get("signals"), dict) else {}
        meta = sig.get("technical_consensus_v2") or {}
        fams=[]
        for f in list(meta.get("family_details") or []):
            if not isinstance(f,dict) or f.get("status") == "neutral":
                continue
            symbol = "✓" if f.get("status") == "aligned" else "×"
            fams.append(f"{f.get('name','?')}{symbol}")
        parts.append(
            f"{r.get('asset')} {str(r.get('direction') or 'HOLD').upper()} T={int(r.get('technical_confidence',0) or 0)} "
            f"raw={int(meta.get('legacy_confidence',0) or 0)} fam={int(meta.get('family_count',0) or 0)}/{int(meta.get('min_families',0) or 0)} "
            f"pureza={float(meta.get('purity',0) or 0):.0f}% boost={int(meta.get('boost_pp',0) or 0):+d} · {','.join(fams[:5]) or 'sem famílias'}"
        )
    if parts:
        log("🧠 TECH CONSENSUS V2 | " + " · ".join(parts), "info")

def _log_deep_market_top(rows: List[Dict[str, Any]], limit: int = 10) -> None:
    candidates = [r for r in rows if r.get("asset") and not r.get("excluded_from_round")]
    for r in candidates:
        r["deep_rank_score"] = _deep_market_opportunity_score(r)
    candidates.sort(key=lambda r: (int(r.get("deep_rank_score",0)), int(r.get("technical_confidence",0)), int(r.get("payout",0))), reverse=True)
    for idx, r in enumerate(candidates, start=1):
        r["deep_rank_position"] = idx
    top = candidates[:max(1, min(10, int(limit or 10)))]
    def fmt(r):
        ci = r.get("candle_intelligence") if isinstance(r.get("candle_intelligence"), dict) else {}
        sig = r.get("signals") if isinstance(r.get("signals"), dict) else {}
        strategy_name = str(sig.get("primary_strategy_name") or "ALL_STRATEGIES")
        q = int(compute_opportunity_quality(r, r.get("lumi") if isinstance(r.get("lumi"), dict) else None).get("score",0) or 0)
        return (f"#{int(r.get('deep_rank_position',0))} {r.get('asset')} {str(r.get('direction') or 'HOLD').upper()} "
                f"D={int(r.get('deep_rank_score',0))} Q={q} T={int(r.get('technical_confidence',0) or 0)} "
                f"C={int(r.get('candle_score',ci.get('score',50)) or 50)} PA={int(ci.get('price_action_score',50) or 50)} P={int(r.get('payout',0) or 0)}% "
                f"EST={strategy_name} · SI={float((r.get('shadow_intelligence') or {}).get('edge_pp',0) or 0):+.1f}/{int((r.get('shadow_intelligence') or {}).get('samples',0) or 0)}")
    if top:
        log("🎯 DEEP RANKING 1-5 | " + " · ".join(fmt(r) for r in top[:5]), "info")
    if len(top) > 5:
        log("🎯 DEEP RANKING 6-10 | " + " · ".join(fmt(r) for r in top[5:10]), "info")


def _smart_force_release_exclusions(universe: List[str], now: float) -> int:
    """V101: proteção global HOT sem esperar locks ocupados pelo Laboratório/UI."""
    ratio = max(0.50, min(0.95, float(cfg_get("smart_prefilter_hot_exclusion_max_ratio", 0.80) or 0.80)))
    max_excluded = int(math.floor(len(universe) * ratio)) if universe else 0
    acquired = state_lock.acquire(timeout=0.02)
    if not acquired:
        return 0
    try:
        memory = dict(cfg_get("_smart_asset_memory") or {})
        excluded = []
        for asset in universe:
            item = dict(memory.get(asset) or {})
            if float(item.get("hot_exclude_until", 0) or 0) > now or bool(item.get("recovery_required")):
                excluded.append(asset)
        excess = max(0, len(excluded) - max_excluded)
        if excess <= 0:
            return 0
        excluded.sort(key=lambda a: (
            1 if float((memory.get(a) or {}).get("weak_until", 0) or 0) > now else 0,
            -float((memory.get(a) or {}).get("last_tech", 0) or 0),
            float((memory.get(a) or {}).get("hot_exclude_until", 0) or 0),
        ))
        released = 0
        for asset in excluded[:excess]:
            item = dict(memory.get(asset) or {})
            item["hot_exclude_until"] = 0.0
            item["recovery_required"] = False
            item["below50_streak"] = min(1, int(item.get("below50_streak", 0) or 0))
            item["forced_recovery_at"] = now
            memory[asset] = item
            released += 1
        state["_smart_asset_memory"] = memory
        return released
    finally:
        state_lock.release()


def smart_prefilter_select_assets(assets: List[str], tf: int) -> Tuple[List[str], Dict[str, Any]]:
    """Smart Prefilter V99: HOT qualificado + exploração + recuperação progressiva.

    - HOT: prioriza >=55%, depois 50–54%, histórico/Lab e payout.
    - <50% repetido: sai do HOT e entra em recuperação.
    - Após 2–3 candles, volta primeiro pela exploração; >=50% recupera HOT.
    - Proteção global: no máximo ~80% do radar fica simultaneamente fora do HOT.
    """
    prefilter_started = time.perf_counter()
    universe_all = [normalize_asset_name(a) for a in assets if a]
    active_assets = {normalize_asset_name(o.get("asset", "")) for o in get_active_open_orders() if o.get("asset")}
    universe = [a for a in universe_all if a not in active_assets]
    open_order_skipped = max(0, len(universe_all) - len(universe))
    if not bool(cfg_get("smart_prefilter_enabled", True)) or len(universe) <= 6:
        return universe, {"enabled": False, "before": len(universe_all), "selected": len(universe), "hot": len(universe), "explore": 0, "weak_cooldown": 0, "hot_excluded": 0, "forced_recovery": 0, "recovery_ready": 0, "open_order_skipped": open_order_skipped}

    full_radar = bool(cfg_get("full_market_radar_enabled", True))
    if full_radar:
        budget = max(12, min(len(universe), int(cfg_get("full_market_radar_heavy_assets", 20) or 20)))
        hot_budget = max(2, min(budget, int(cfg_get("full_market_radar_hot_assets", 8) or 8)))
        explore_budget = max(2, min(budget, int(cfg_get("full_market_radar_explore_assets", 12) or 12)))
    else:
        budget = max(6, min(len(universe), int(cfg_get("smart_prefilter_scan_assets", 12) or 12)))
        hot_budget = max(2, min(budget, int(cfg_get("smart_prefilter_hot_assets", 8) or 8)))
        explore_budget = max(1, min(budget, int(cfg_get("smart_prefilter_explore_assets", 4) or 4)))
    if hot_budget + explore_budget > budget:
        hot_budget = max(1, budget - explore_budget)

    now = time.time()
    forced_recovery = _smart_force_release_exclusions(universe, now)
    memory = _smart_asset_memory_snapshot()
    lab_stats = _smart_lab_asset_stats()
    weak_blocked: List[str] = []
    eligible: List[str] = []
    for asset in universe:
        mem = memory.get(asset, {})
        if float(mem.get("weak_until", 0) or 0) > now:
            weak_blocked.append(asset)
            continue
        eligible.append(asset)

    # Se cooldowns pesados consumirem demais o orçamento, libera os que vencem primeiro
    # somente para exploração; nunca deixa a rodada sem diversidade.
    if len(eligible) < min(budget, len(universe)):
        blocked_sorted = sorted(weak_blocked, key=lambda a: float((memory.get(a) or {}).get("weak_until", 0) or 0))
        for asset in blocked_sorted:
            if len(eligible) >= min(budget, len(universe)):
                break
            eligible.append(asset)

    scored = []
    for idx, asset in enumerate(eligible):
        mem = memory.get(asset, {})
        lab = lab_stats.get(asset, {})
        has_history = bool(mem) or int(lab.get("samples", 0) or 0) >= 3
        hot_excluded = float(mem.get("hot_exclude_until", 0) or 0) > now or bool(mem.get("recovery_required"))
        scored.append((_smart_prefilter_score(asset, mem, lab), 1 if has_history else 0, 1 if hot_excluded else 0, -idx, asset))
    scored.sort(reverse=True)

    hot: List[str] = []
    for x in scored:
        asset = x[4]
        mem = memory.get(asset, {})
        tech = int(mem.get("last_tech", 0) or 0)
        if x[1] > 0 and x[2] == 0 and tech >= 50:
            hot.append(asset)
            if len(hot) >= hot_budget:
                break
    if len(hot) < hot_budget:
        for asset in eligible:
            mem = memory.get(asset, {})
            excluded = float(mem.get("hot_exclude_until", 0) or 0) > now or bool(mem.get("recovery_required"))
            if asset in hot or excluded:
                continue
            tech = int(mem.get("last_tech", 0) or 0)
            if not mem or tech >= 50:
                hot.append(asset)
                if len(hot) >= hot_budget:
                    break

    remaining = [a for a in eligible if a not in hot]
    # Quem cumpriu a espera de recuperação recebe preferência nas vagas de exploração
    # para provar que melhorou antes de voltar ao HOT.
    recovery_ready = [
        a for a in remaining
        if bool((memory.get(a) or {}).get("recovery_required"))
        and float((memory.get(a) or {}).get("hot_exclude_until", 0) or 0) <= now
    ]
    normal_remaining = [a for a in remaining if a not in recovery_ready]
    explore: List[str] = []
    explore_target = max(explore_budget, budget - len(hot))
    for asset in recovery_ready[:explore_target]:
        if asset not in explore:
            explore.append(asset)
    slots_left = max(0, explore_target - len(explore))
    if normal_remaining and slots_left > 0:
        acquired = state_lock.acquire(timeout=0.02)
        try:
            cursor = int(cfg_get("_smart_explore_cursor", 0) or 0) if acquired else 0
            start_cursor = cursor % len(normal_remaining)
            for i in range(min(slots_left, len(normal_remaining))):
                explore.append(normal_remaining[(start_cursor + i) % len(normal_remaining)])
            if acquired:
                state["_smart_explore_cursor"] = (start_cursor + max(1, slots_left)) % max(1, len(normal_remaining))
        finally:
            if acquired:
                state_lock.release()

    selected = hot + [a for a in explore if a not in hot]
    if len(selected) < budget:
        for asset in eligible:
            if asset not in selected:
                selected.append(asset)
                if len(selected) >= budget:
                    break

    # V108.4: fila reserva ordenada pelo mesmo score do prefilter. Ela NÃO aumenta
    # a meta pesada; só substitui DATA_SLOW/timeout/bloqueios dos 12 principais.
    reserve_limit = max(0, int(cfg_get("full_market_radar_reserve_assets", 8) or 0)) if full_radar else max(0, int(cfg_get("candle_engine_reserve_assets", 6) or 0))
    scored_order = [x[4] for x in scored]
    reserve_pool = [a for a in scored_order if a not in selected]
    if len(reserve_pool) < reserve_limit:
        reserve_pool.extend([a for a in universe if a not in selected and a not in reserve_pool])
    reserve_assets = reserve_pool[:reserve_limit]

    # Conta exclusão EFETIVA após a proteção global.
    memory = _smart_asset_memory_snapshot()
    hot_excluded_count = len([
        a for a in universe
        if float((memory.get(a) or {}).get("hot_exclude_until", 0) or 0) > now
        or bool((memory.get(a) or {}).get("recovery_required"))
    ])
    declining_count = len([a for a in universe if int((memory.get(a) or {}).get("decline_streak", 0) or 0) >= 1])
    elapsed_ms = int((time.perf_counter() - prefilter_started) * 1000)
    max_ms = max(20, int(cfg_get("smart_prefilter_max_ms", 100) or 100))
    if elapsed_ms > max_ms:
        # Nenhuma espera adicional: usa ordem do universo/rotação e deixa o scanner seguir.
        selected = universe[:budget]
        hot = []
        explore = list(selected)
        recovery_ready = []
        forced_recovery = 0
    meta = {
        "enabled": True,
        "full_market_radar": 1 if full_radar else 0,
        "before": len(universe_all),
        "open_order_skipped": open_order_skipped,
        "selected": len(selected),
        "selected_otc": sum(1 for a in selected if is_otc_asset(a)),
        "selected_crypto": sum(1 for a in selected if (not is_otc_asset(a)) and is_crypto_asset(a)),
        "selected_normal": sum(1 for a in selected if (not is_otc_asset(a)) and not is_crypto_asset(a)),
        "hot": len(hot),
        "explore": len([a for a in selected if a in explore]),
        "weak_cooldown": len([a for a in universe if float((memory.get(a) or {}).get("weak_until", 0) or 0) > now]),
        "hot_excluded": hot_excluded_count,
        "declining": declining_count,
        "forced_recovery": forced_recovery,
        "recovery_ready": len(recovery_ready),
        "budget": budget,
        "hot_assets": hot[:12],
        "explore_assets": explore[:12],
        "reserve_assets": reserve_assets,
        "reserve_count": len(reserve_assets),
        "prefilter_budget_fallback": 1 if elapsed_ms > max_ms else 0,
    }
    return selected[:budget], meta


def smart_prefilter_record_row(row: Dict[str, Any], tf: int, *, count_weak: bool = True) -> None:
    asset = normalize_asset_name(row.get("asset", ""))
    if not asset:
        return
    now = time.time()
    tech = int(row.get("technical_confidence", 0) or 0)
    weak_threshold = int(cfg_get("smart_prefilter_weak_threshold", 46) or 46)
    weak_strikes_needed = int(cfg_get("smart_prefilter_weak_strikes", 2) or 2)
    cooldown_candles = int(cfg_get("smart_prefilter_weak_cooldown_candles", 2) or 2)
    recovery_delay = int(cfg_get("smart_prefilter_recovery_delay_candles", 2) or 2)
    bucket = str(row.get("smart_prefilter_bucket") or "").lower()
    acquired = state_lock.acquire(timeout=0.03)
    if not acquired:
        return
    try:
        memory = dict(cfg_get("_smart_asset_memory") or {})
        item = dict(memory.get(asset) or {})
        previous_tech = int(item.get("last_tech", 0) or 0)
        if count_weak:
            if tech <= weak_threshold:
                item["weak_streak"] = int(item.get("weak_streak", 0) or 0) + 1
                if int(item["weak_streak"]) >= weak_strikes_needed:
                    item["weak_until"] = max(float(item.get("weak_until", 0) or 0), now + max(60, int(tf or 300)) * cooldown_candles)
            else:
                item["weak_streak"] = 0
                if tech >= weak_threshold + 3:
                    item["weak_until"] = 0.0

            # Recuperação progressiva: o ativo excluído precisa voltar pela exploração.
            if bool(item.get("recovery_required")) and bucket == "explore":
                if tech >= 50:
                    item["recovery_required"] = False
                    item["hot_exclude_until"] = 0.0
                    item["below50_streak"] = 0
                    item["recovered_at"] = now
                else:
                    item["hot_exclude_until"] = now + max(60, int(tf or 300)) * recovery_delay
                    item["recovery_last_failed_at"] = now

            if tech < 50:
                item["below50_streak"] = int(item.get("below50_streak", 0) or 0) + 1
                if int(item["below50_streak"]) >= 2:
                    item["recovery_required"] = True
                    item["hot_exclude_until"] = max(
                        float(item.get("hot_exclude_until", 0) or 0),
                        now + max(60, int(tf or 300)) * recovery_delay,
                    )
            else:
                # Se não estava em recuperação, um sinal >=50 limpa a penalidade normalmente.
                if not bool(item.get("recovery_required")):
                    item["below50_streak"] = 0
                    item["hot_exclude_until"] = 0.0

            if previous_tech > 0:
                delta = tech - previous_tech
                item["last_tech_delta"] = delta
                if delta <= -2:
                    item["decline_streak"] = int(item.get("decline_streak", 0) or 0) + 1
                elif delta >= 0:
                    item["decline_streak"] = 0
            else:
                item["last_tech_delta"] = 0
                item["decline_streak"] = 0

        item.update({
            "last_seen": now,
            "last_tech": tech,
            "last_payout": int(row.get("payout", 0) or 0),
            "last_adaptive": int(row.get("adaptive_score", tech) or tech),
            "last_signal": int(row.get("signal_score", tech) or tech),
            "last_entry": int(row.get("entry_score", tech) or tech),
            "last_approved": 1 if row.get("approved") else 0,
            "last_direction": str(row.get("direction") or ""),
            "last_bucket": bucket,
        })
        memory[asset] = item
        if len(memory) > 500:
            keep = sorted(memory.items(), key=lambda kv: float((kv[1] or {}).get("last_seen", 0) or 0), reverse=True)[:400]
            memory = dict(keep)
        state["_smart_asset_memory"] = memory
    finally:
        state_lock.release()

def _safe_market_payout(api: Any, asset: str) -> Dict[str, Any]:
    """V101: payout do scanner também recebe teto de tempo; cache vem primeiro."""
    cached = _payout_cache_get(asset)
    if cached:
        cached["cached"] = True
        return cached
    timeout_s = max(0.8, min(6.0, float(cfg_get("market_data_payout_timeout_seconds", 2.5) or 2.5)))
    started = time.perf_counter()
    ok, payload, err = _call_daemon_timeout(lambda: get_payout_with_source(api, asset, use_cache=False), timeout_s)
    elapsed = (time.perf_counter() - started) * 1000.0
    _phase_timing_add("payout_ms", elapsed)
    if ok and isinstance(payload, dict):
        return payload
    if err == "timeout":
        _market_data_timeout_event(api, f"payout timeout {asset}")
    return {"payout": 0, "source": "timeout_v101", "detail": f"payout excedeu {timeout_s:.1f}s", "ts": time.time(), "time": now_hms()}


def evaluate_asset(api: Any, asset: str, tf: int, strategy: str, payout_snapshot: Optional[Dict[str, Any]] = None) -> Optional[Dict[str, Any]]:
    asset = normalize_asset_name(asset)
    if not is_supported_by_local_consts(asset):
        sync = _sync_active_opcode_from_live(api, asset, max(1, int(tf or 300) // 60), force_refresh=False)
        if not sync.get("ok"):
            return None
    bundle = get_candle_bundle_cached(api, asset, tf, 64)
    closed = list(bundle.get("closed") or [])
    if len(closed) < 50:
        return None
    closes = [c for _, c in closed]
    decision = analyze_closes(closes, strategy)
    try:
        record_strategy_usage(decision.signals, asset, decision.direction or "hold", "analysis")
    except Exception:
        pass
    payout_info = _payout_snapshot_info(payout_snapshot, asset) if payout_snapshot is not None else _safe_market_payout(api, asset)
    payout = int(payout_info.get("payout", 0) or 0)
    s = decision.signals
    candle_intel = build_candle_intelligence(list(bundle.get("ohlc") or []), s, decision.direction)
    if not decision.direction:
        rank = 0
    else:
        candle_rank = int(round((int(candle_intel.get("score", 50) or 50) - 50) * 0.18))
        rank = decision.confidence + min(20, max(0, payout - 70)) + min(10, int(float(s.get("bb_width", 0)) * 100)) + candle_rank
    row = {
        "asset": asset,
        "direction": decision.direction,
        "technical_confidence": decision.confidence,
        "rank": rank,
        "payout": payout,
        "payout_source": payout_info.get("source", "desconhecido"),
        "payout_detail": payout_info.get("detail", ""),
        "payout_unknown": int(payout or 0) <= 0,
        "last_candle_ts": closed[-1][0],
        "signals": s,
        "reasons": decision.reasons,
        "closed": closed,
        "ohlc": list(bundle.get("ohlc") or []),
        "candle_shape": candle_shape(closed),
        "candle_intelligence": candle_intel,
        "candle_score": int(candle_intel.get("score", 50) or 50),
        "candle_risk": int(candle_intel.get("risk", 50) or 50),
        "lumi": None,
        "approved": False,
        "block_reason": "",
        "decision_status": "avaliado",
        "decision_steps": [],
        "next_action": "aguardar próxima rodada",
        "next_in_seconds": 0,
    }
    regime = detect_market_regime(closes, s)
    row["regime_info"] = regime
    row["regime"] = regime.get("name", "indefinido")
    row["regime_label"] = regime.get("label", "Indefinido")
    adaptive = compute_adaptive_signal_score(row)
    row["adaptive"] = adaptive
    row["calibration"] = adaptive.get("calibration") if isinstance(adaptive.get("calibration"), dict) else {}
    row["adaptive_score"] = int(adaptive.get("score", decision.confidence) or decision.confidence)
    # O ranking adaptativo só ordena candidatos; não substitui as travas de técnica/payout/Lumi.
    row["ranking_score"] = int(row["adaptive_score"] * 100 + rank)
    compute_opportunity_quality(row, None)
    return row



def anti_stall_context() -> Dict[str, Any]:
    """Calcula flexibilização controlada em DEMO quando o bot passa muito tempo sem entrada.

    Não remove travas de risco, não ignora Lumi quando ela confirma risco, e não libera conta REAL.
    Ele apenas reduz os mínimos dentro de um piso configurado e permite testar mais candidatos fortes na Lumi.
    """
    now = time.time()
    started = float(cfg_get("bot_started_at") or now)
    last_trade = float(cfg_get("last_trade_ts") or 0.0)
    reference = max(started, last_trade) if last_trade > 0 else started
    idle_seconds = max(0, int(now - reference))
    enabled = bool(cfg_get("anti_stall_enabled", True))
    trigger = int(cfg_get("anti_stall_minutes", 20) or 20) * 60
    active = enabled and idle_seconds >= trigger and cfg_get("account_type") == "PRACTICE"
    base_tech = int(cfg_get("min_technical_confidence", 60) or 60)
    base_lumi = int(cfg_get("lumi_min_confidence", 65) or 65)
    floor_tech = int(cfg_get("anti_stall_floor_tech", 57) or 57)
    floor_lumi = int(cfg_get("anti_stall_lumi_floor", 60) or 60)
    effective_tech = max(floor_tech, min(base_tech, base_tech - 3)) if active else base_tech
    effective_lumi = max(floor_lumi, min(base_lumi, base_lumi - 5)) if active else base_lumi
    status = "anti-paralisia ativo" if active else f"anti-paralisia aguardando {max(0, trigger-idle_seconds)}s"
    return {
        "enabled": enabled,
        "active": active,
        "idle_seconds": idle_seconds,
        "trigger_seconds": trigger,
        "base_tech": base_tech,
        "base_lumi": base_lumi,
        "effective_tech": effective_tech,
        "effective_lumi": effective_lumi,
        "status": status,
    }


def _safe_num(value: Any, default: float = 0.0) -> float:
    try:
        v = float(value)
        if math.isnan(v) or math.isinf(v):
            return default
        return v
    except Exception:
        return default


def _near_step_text(step: Dict[str, Any]) -> str:
    label = str(step.get("label") or "Trava")
    detail = str(step.get("detail") or "")
    return f"{label}: {detail}" if detail else label


def _block_category(row: Dict[str, Any], min_tech: int, min_payout: int, min_lumi: int) -> str:
    text = str(row.get("block_reason") or row.get("decision_status") or "").lower()
    if not row.get("direction"): return "sem_direcao"
    if int(row.get("technical_confidence",0) or 0) < int(min_tech): return "tecnica"
    if "ev" in text or "shadow intelligence contextual" in text: return "ev_historico"
    if "candle intelligence" in text or "anti-chase" in text: return "candle_pa"
    if "mtf" in text or "entry score" in text: return "mtf_entry"
    if "lumi" in text or "hold" in text or "ia" in text: return "lumi"
    payout = int(row.get("payout",0) or 0)
    if payout <= 0 or payout < int(min_payout): return "payout"
    if "preflight" in text or "negoci" in text or "abertura" in text: return "preflight_buyability"
    return "outras"

def build_block_diagnostics(rows: List[Dict[str, Any]], min_tech: int, min_payout: int, min_lumi: int) -> Dict[str, Any]:
    counts = {k:0 for k in ("tecnica","sem_direcao","ev_historico","candle_pa","mtf_entry","lumi","payout","preflight_buyability","outras")}
    for row in rows or []:
        if row.get("approved"): continue
        counts[_block_category(row, min_tech, min_payout, min_lumi)] += 1
    total = sum(counts.values())
    ranked = sorted(counts.items(), key=lambda kv: kv[1], reverse=True)
    top = ranked[0] if ranked else ("outras",0)
    labels = {"tecnica":"Técnica","sem_direcao":"Sem direção","ev_historico":"EV/Histórico","candle_pa":"Candle/PA","mtf_entry":"MTF/Entry","lumi":"Lumi","payout":"Payout","preflight_buyability":"Preflight/Buyability","outras":"Outras"}
    return {"counts":counts,"total":total,"top_category":top[0],"top_label":labels.get(top[0],top[0]),"top_count":top[1],"top_pct":round((top[1]/total*100.0),1) if total else 0.0,"labels":labels,"updated_at":now_hms()}

def accumulate_block_diagnostics(diag: Dict[str, Any]) -> Dict[str, Any]:
    today = datetime.now().strftime("%Y-%m-%d")
    with state_lock:
        current = dict(cfg_get("block_diagnostics_today") or {})
        if current.get("date") != today:
            current = {"date":today,"counts":{},"rounds":0}
        counts = dict(current.get("counts") or {})
        for k,v in (diag.get("counts") or {}).items(): counts[k]=int(counts.get(k,0) or 0)+int(v or 0)
        current["counts"]=counts; current["rounds"]=int(current.get("rounds",0) or 0)+1; current["updated_at"]=now_hms()
        total=sum(int(v or 0) for v in counts.values()); labels=diag.get("labels") or {}
        ranked=sorted(counts.items(), key=lambda kv:int(kv[1] or 0), reverse=True)
        top=ranked[0] if ranked else ("outras",0)
        current["total"]=total; current["top_label"]=labels.get(top[0],top[0]); current["top_pct"]=round(top[1]/total*100.0,1) if total else 0.0
        state["block_diagnostics_today"]=current
        return dict(current)

def log_block_diagnostics(diag: Dict[str, Any]) -> None:
    if not bool(cfg_get("opportunity_health_diagnostics_enabled", True)): return
    c=diag.get("counts") or {}; labels=diag.get("labels") or {}
    parts=[]
    for key in ("tecnica","sem_direcao","ev_historico","candle_pa","mtf_entry","lumi","payout","preflight_buyability","outras"):
        if int(c.get(key,0) or 0)>0: parts.append(f"{labels.get(key,key)}={int(c.get(key,0))}")
    log(f"🚧 BLOQUEIOS DA RODADA V108.8.0 | {' · '.join(parts) if parts else 'nenhum'} · gargalo={diag.get('top_label','—')} {float(diag.get('top_pct',0)):.0f}%", "info")
    today = accumulate_block_diagnostics(diag)
    tc=today.get("counts") or {}; tparts=[]
    for key in ("tecnica","sem_direcao","ev_historico","candle_pa","mtf_entry","lumi","payout","preflight_buyability","outras"):
        if int(tc.get(key,0) or 0)>0: tparts.append(f"{labels.get(key,key)}={int(tc.get(key,0))}")
    log(f"📅 BLOQUEIOS DE HOJE | {' · '.join(tparts) if tparts else 'nenhum'} · gargalo={today.get('top_label','—')} {float(today.get('top_pct',0)):.0f}% · rodadas={int(today.get('rounds',0))}", "info")


def classify_near_miss(row: Dict[str, Any], min_tech: int, min_payout: int, min_lumi_conf: int) -> Dict[str, Any]:
    """Monta diagnóstico do melhor ativo que quase passou.

    O objetivo é trocar mensagens genéricas como "nenhum sinal passou" por:
    - qual ativo ficou mais perto;
    - qual trava bloqueou;
    - quanto faltou de técnica/payout/Lumi;
    - próxima ação.
    """
    asset = normalize_asset_name(row.get("asset", "-")) if row.get("asset") else "-"
    direction = normalize_lumi_action(row.get("direction") or "hold")
    tech = int(_safe_num(row.get("technical_confidence"), 0))
    payout = int(_safe_num(row.get("payout"), 0))
    lumi = row.get("lumi") if isinstance(row.get("lumi"), dict) else {}
    lumi_action = normalize_lumi_action(lumi.get("action") or "hold") if lumi else "hold"
    lumi_conf = int(_safe_num(lumi.get("confidence"), 0)) if lumi else 0
    try:
        lumi_effective_conf = int(_safe_num(lumi.get("calibrated_confidence", lumi.get("real_band_calibrated_confidence", lumi_conf)), lumi_conf)) if lumi else 0
    except Exception:
        lumi_effective_conf = lumi_conf
    block_reason = str(row.get("block_reason") or row.get("decision_status") or "aguardando diagnóstico")[:240]
    steps = list(row.get("decision_steps") or [])
    failed_steps = [st for st in steps if isinstance(st, dict) and st.get("ok") is False]
    missing: List[str] = []
    blocked_by = ""

    if not row.get("direction"):
        blocked_by = "técnica sem direção"
        missing.append("faltou direção CALL/PUT na técnica")
    if tech < int(min_tech or 0):
        blocked_by = "técnica"
        missing.append(f"faltou técnica: {tech}% / mínimo {int(min_tech or 0)}%")
    if payout > 0 and payout < int(min_payout or 0):
        blocked_by = "payout"
        missing.append(f"faltou payout: {payout}% / mínimo {int(min_payout or 0)}%")
    if not payout:
        missing.append(f"payout não retornado pela API / mínimo {int(min_payout or 0)}%")
    if lumi:
        if not lumi.get("ok"):
            blocked_by = "Lumi indisponível/fallback"
            missing.append(f"Lumi não confirmou: {str(lumi.get('reason') or lumi.get('error') or 'indisponível')[:110]}")
        elif lumi_action == "hold":
            blocked_by = "Lumi HOLD"
            hold_reason = clean_lumi_reason(
                lumi.get("reason") or lumi.get("analysis_summary"),
                action="hold",
                focus=lumi.get("focus") if isinstance(lumi.get("focus"), list) else None,
                condition=str(lumi.get("market_condition") or ""),
            )
            missing.append(f"Lumi pediu HOLD: {hold_reason}")
        elif direction in VALID_DIRECTIONS and lumi_action != direction:
            blocked_by = "Lumi divergiu"
            missing.append(f"Lumi divergiu: técnica {direction.upper()} x Lumi {lumi_action.upper()}")
        elif lumi_effective_conf < int(min_lumi_conf or 0):
            blocked_by = "confiança Lumi"
            if lumi_effective_conf != lumi_conf:
                missing.append(f"faltou confiança Lumi calibrada: raw {lumi_conf}% → efetiva {lumi_effective_conf}% / mínimo {int(min_lumi_conf or 0)}%")
            else:
                missing.append(f"faltou confiança Lumi: {lumi_conf}% / mínimo {int(min_lumi_conf or 0)}%")

    fallback_reason = str(row.get("fallback_reason") or "").strip()
    if row.get("fallback_evaluated") and fallback_reason:
        compact_fb = fallback_reason
        if compact_fb.lower().startswith("fallback bloqueado:"):
            compact_fb = "fallback:" + compact_fb.split(":", 1)[1]
        blocked_by = compact_fb[:150]
        fb_missing = f"Fallback técnico recusado: {fallback_reason}"
        if fb_missing not in missing:
            missing.append(fb_missing)

    low_reason = block_reason.lower()
    if row.get("fallback_evaluated") and fallback_reason and "janela" not in low_reason and "fora da janela" not in low_reason:
        # Mantém a causa concreta do fallback como trava principal.
        pass
    elif "janela" in low_reason or "fora da janela" in low_reason:
        blocked_by = "janela da vela"
        missing.append(block_reason)
    elif "cooldown" in low_reason:
        blocked_by = "cooldown"
    elif "loss memory" in low_reason or "memória de loss" in low_reason or "padrao" in low_reason or "padrão" in low_reason:
        blocked_by = "memória de loss"
    elif "ranking" in low_reason:
        blocked_by = "ranking Lumi"
    elif "falha de abertura" in low_reason or "negociabilidade" in low_reason:
        blocked_by = "ativo/negociabilidade"
    elif "bloqueado após hold" in low_reason or "lumi pediu hold" in low_reason:
        blocked_by = "Lumi HOLD"
    elif "travas finais" in low_reason or "aguardando travas" in low_reason:
        blocked_by = "travas finais"
    elif "aguardando ranking" in low_reason or "ranking/lumi" in low_reason:
        blocked_by = "ranking/Lumi"
    elif "payout" in low_reason and "abaixo" in low_reason:
        blocked_by = "payout"
    elif "confiança técnica" in low_reason or "confianca tecnica" in low_reason:
        blocked_by = "técnica"
    elif "confiança lumi" in low_reason or "confianca lumi" in low_reason:
        blocked_by = "confiança Lumi"

    for st in failed_steps[:5]:
        txt = _near_step_text(st)
        if txt and txt not in missing:
            missing.append(txt)

    # Último recurso: usar a primeira etapa realmente reprovada ou o motivo concreto
    # do backend. Nunca publicar apenas "trava: trava".
    if not blocked_by and failed_steps:
        blocked_by = str(failed_steps[0].get("label") or "trava final").strip()
    if not blocked_by:
        if block_reason and _normalize_reason_key(block_reason) not in {"trava", "aguardando diagnóstico", "aguardando diagnostico"}:
            blocked_by = block_reason[:80]
        else:
            blocked_by = "trava final não identificada"

    if not missing:
        missing.append(block_reason if block_reason and block_reason != "trava" else "faltou passar nas travas finais")

    # Score de proximidade: direção e técnica pesam mais; payout ajuda se retornou.
    proximity = tech
    if direction in VALID_DIRECTIONS:
        proximity += 18
    if payout:
        proximity += min(12, max(0, payout - 70) // 2)
    if lumi and lumi.get("ok") and lumi_action == direction:
        proximity += 14
    if row.get("loss_memory_rejected"):
        proximity -= 25
    proximity = max(0, min(100, int(proximity)))

    payout_label = f"{payout}%" if payout else f"—% via {str(row.get('payout_source') or 'desconhecido')}"
    summary = f"Quase passou: {asset} {direction.upper() if direction in VALID_DIRECTIONS else 'HOLD'} · técnica {tech}%/{int(min_tech or 0)}% · payout {payout_label}/{int(min_payout or 0)}%"
    if lumi:
        if lumi_action == "hold":
            hold_reason = clean_lumi_reason(
                lumi.get("reason") or lumi.get("analysis_summary"),
                action="hold",
                focus=lumi.get("focus") if isinstance(lumi.get("focus"), list) else None,
                condition=str(lumi.get("market_condition") or ""),
            )
            conf_txt = f" {lumi_conf}%" if lumi_conf > 0 else ""
            summary += f" · Lumi HOLD{conf_txt} · {hold_reason}"
        elif lumi.get("ok"):
            required_txt = f"/{int(min_lumi_conf or 0)}%" if int(min_lumi_conf or 0) > 0 else ""
            lumi_effective_log = lumi_effective_conf
            if lumi_effective_log != lumi_conf:
                summary += f" · Lumi {lumi_action.upper()} raw {lumi_conf}% → efetiva {lumi_effective_log}%{required_txt}"
            else:
                summary += f" · Lumi {lumi_action.upper()} {lumi_conf}%{required_txt}"
        else:
            summary += f" · Lumi indisponível: {clean_lumi_reason(lumi.get('reason') or lumi.get('error'), action='hold')}"
    summary += f" · trava: {blocked_by}"

    supervisor_meta = row.get("trader_supervisor") if isinstance(row.get("trader_supervisor"), dict) else {}
    return {
        "asset": asset,
        "direction": direction,
        "technical_confidence": tech,
        "technical_required": int(min_tech or 0),
        "technical_gap": max(0, int(min_tech or 0) - tech),
        "payout": payout,
        "payout_required": int(min_payout or 0),
        "payout_gap": max(0, int(min_payout or 0) - payout) if payout else int(min_payout or 0),
        "lumi_action": lumi_action,
        "lumi_confidence": lumi_conf,
        "lumi_effective_confidence": lumi_effective_conf,
        "lumi_required": int(min_lumi_conf or 0),
        "lumi_evaluated": bool(lumi),
        "lumi_gap": max(0, int(min_lumi_conf or 0) - lumi_effective_conf) if lumi else int(min_lumi_conf or 0),
        "supervisor_action": str(supervisor_meta.get("action") or "").upper(),
        "supervisor_score": float(supervisor_meta.get("score", 0) or 0),
        "supervisor_required_score": float(supervisor_meta.get("required_score", 0) or 0),
        "supervisor_reason": str(supervisor_meta.get("reason") or "")[:420],
        "supervisor_floors": list(supervisor_meta.get("floors") or [])[:8],
        "supervisor_quality": int(supervisor_meta.get("quality", 0) or 0),
        "supervisor_candle": int(supervisor_meta.get("candle", 0) or 0),
        "supervisor_price_action": int(supervisor_meta.get("price_action", 0) or 0),
        "supervisor_mtf": float(supervisor_meta.get("mtf", 0) or 0),
        "supervisor_counterfactual_adjustment": float(supervisor_meta.get("counterfactual_adjustment", 0) or 0),
        "blocked_by": blocked_by,
        "status": summary[:260],
        "details": block_reason,
        "missing": missing[:8],
        "next_action": str(row.get("next_action") or "aguardar próxima rodada")[:180],
        "next_in_seconds": int(row.get("next_in_seconds", 0) or 0),
        "proximity_score": proximity,
        "steps": steps[:8],
        "updated_at": now_hms(),
    }


def choose_near_miss(rows: List[Dict[str, Any]], min_tech: int, min_payout: int, min_lumi_conf: int) -> Optional[Dict[str, Any]]:
    if not rows:
        return None
    candidates: List[Tuple[int, Dict[str, Any], Dict[str, Any]]] = []
    for row in rows:
        if row.get("approved"):
            continue
        # CLOSED/MISSING no universo OPEN da rodada não é oportunidade e não pode
        # reaparecer em ranking, painel ou "Quase passou".
        if row.get("excluded_from_round"):
            continue
        # Ativo em HOLD não é "quase passou": ele já foi deliberadamente retirado da fila.
        low_block = str(row.get("block_reason") or row.get("decision_status") or "").lower()
        if row.get("hold_active") or "hold ativo" in low_block or "bloqueado após hold" in low_block or "lumi pediu hold" in low_block:
            continue
        nm = classify_near_miss(row, min_tech, min_payout, min_lumi_conf)
        score = int(nm.get("proximity_score", 0))
        # Prioriza sinais com direção; depois técnica; depois payout/rank.
        if real_requires_valid_payout() and int(row.get("payout", 0) or 0) <= 0:
            score -= 45
        elif real_allow_unknown_payout() and int(row.get("payout", 0) or 0) <= 0:
            score -= 8
        if row.get("direction") in VALID_DIRECTIONS:
            score += 25
        score += min(20, int(row.get("rank", 0) or 0) // 4)
        candidates.append((score, row, nm))
    if not candidates:
        return None
    candidates.sort(key=lambda item: item[0], reverse=True)
    return candidates[0][2]


def save_near_miss(near_miss: Optional[Dict[str, Any]]) -> None:
    if not near_miss:
        return
    with state_lock:
        state["near_miss"] = near_miss


def log_near_miss_once(near_miss: Dict[str, Any]) -> None:
    """Loga o quase passou sem spammar a cada /status."""
    try:
        key = f"{near_miss.get('asset')}|{near_miss.get('direction')}|{near_miss.get('blocked_by')}|{near_miss.get('technical_confidence')}|{near_miss.get('payout')}|{near_miss.get('lumi_action')}|{near_miss.get('lumi_confidence')}"
        with state_lock:
            last_key = cfg_get("_last_near_miss_log_key")
            if last_key == key:
                return
            state["_last_near_miss_log_key"] = key
        log(str(near_miss.get("status") or "Quase passou detectado")[:260], "info")
    except Exception:
        pass

def _scan_opportunities_impl(api: Any, tf: int, elite_assets: Optional[List[str]] = None, scan_kind: str = "full") -> Tuple[Optional[Dict[str, Any]], List[Dict[str, Any]]]:
    elite_mode = str(scan_kind or "full").lower() == "elite" and bool(elite_assets)
    elite_assets_norm = list(dict.fromkeys(normalize_asset_name(a) for a in (elite_assets or []) if a))
    round_perf_started = time.perf_counter()
    hard_deadline_s = max(15.0, min(60.0, float(cfg_get("full_scan_hard_deadline_seconds", 30) or 30)))
    if elite_mode:
        hard_deadline_s = max(10.0, min(hard_deadline_s, float(cfg_get("elite_scan_hard_deadline_seconds", 18) or 18)))
    hard_deadline_at = round_perf_started + hard_deadline_s
    progress_component = "elite_scan_progress" if elite_mode else "full_scan_progress"

    def _scan_progress(phase: str, asset: str = "", current: int = 0, total: int = 0, **extra: Any) -> None:
        _runtime_heartbeat(progress_component, phase, asset=normalize_asset_name(asset) if asset else "", current=int(current or 0), total=int(total or 0), elapsed_seconds=round(time.perf_counter()-round_perf_started, 2), deadline_seconds=hard_deadline_s, **extra)

    def _scan_deadline_exceeded() -> bool:
        return time.perf_counter() >= hard_deadline_at

    def _scan_abort_if_deadline(phase: str) -> bool:
        if not _scan_deadline_exceeded():
            return False
        elapsed = time.perf_counter() - round_perf_started
        _scan_progress("deadline", asset=phase, elapsed_seconds=round(elapsed, 2))
        log(f"⏱ TRUE HARD DEADLINE V108.8.0 | fase={phase} · {elapsed:.1f}s/{hard_deadline_s:.0f}s · rodada abortada sem ordem; próxima análise continuará.", "warn")
        return True

    _scan_progress("start")
    universe_perf_started = time.perf_counter()
    scanner_ms = 0
    mtf_ms = 0
    lumi_ms = 0
    with LUMI_CACHE_LOCK:
        _cache_hits_before = int(ANALYSIS_CACHE_STATS.get("candle_hits", 0)) + int(ANALYSIS_CACHE_STATS.get("feature_hits", 0))
        _cache_misses_before = int(ANALYSIS_CACHE_STATS.get("candle_misses", 0)) + int(ANALYSIS_CACHE_STATS.get("feature_misses", 0))
    market_mode, round_mode_generation = _market_mode_snapshot()
    max_assets = int(cfg_get("scanner_max_assets", 40))
    technical_top = int(cfg_get("scanner_technical_top", 10))
    lumi_top = int(cfg_get("scanner_lumi_top", 1))
    lumi_top_mode = normalize_lumi_top_mode(cfg_get("lumi_top_mode", "normal"))
    stall = anti_stall_context()
    strategy = str(cfg_get("strategy", "combined"))

    def _cfg_int(key: str, default: int) -> int:
        v = cfg_get(key, default)
        try:
            return int(v) if v is not None else int(default)
        except Exception:
            return int(default)

    min_payout = _cfg_int("min_payout", 70)
    base_tech = _cfg_int("min_technical_confidence", 55)
    base_lumi = _cfg_int("lumi_min_confidence", 0)
    adaptive_thresholds = compute_adaptive_thresholds(base_tech, base_lumi, min_payout, scanner_nonblocking=True)
    if adaptive_thresholds.get("ready"):
        min_tech = int(adaptive_thresholds.get("effective_tech", base_tech) if adaptive_thresholds.get("effective_tech") is not None else base_tech)
        min_lumi_scan = int(adaptive_thresholds.get("effective_lumi", base_lumi) if adaptive_thresholds.get("effective_lumi") is not None else base_lumi)
        if stall.get("active"):
            if min_tech <= base_tech:
                min_tech = min(min_tech, int(stall.get("effective_tech", base_tech) if stall.get("effective_tech") is not None else base_tech))
            if min_lumi_scan <= base_lumi:
                min_lumi_scan = min(min_lumi_scan, int(stall.get("effective_lumi", base_lumi) if stall.get("effective_lumi") is not None else base_lumi))
    else:
        min_tech = int(stall.get("effective_tech", base_tech) if stall.get("effective_tech") is not None else base_tech)
        min_lumi_scan = int(stall.get("effective_lumi", base_lumi) if stall.get("effective_lumi") is not None else base_lumi)

    if _scan_abort_if_deadline("adaptive_thresholds"):
        return None, []

    # Lumi Agente FULL: usa métricas do agente. 0 em lumi_min = não exige Lumi (fallback técnico cobre).
    agent_metrics = lumi_agent_effective_metrics()
    agent_tech = agent_metrics.get("min_technical_confidence")
    agent_lumi = agent_metrics.get("lumi_min_confidence")
    agent_pay = agent_metrics.get("min_payout")
    if agent_tech is not None:
        min_tech = int(agent_tech)
    if agent_lumi is not None:
        min_lumi_scan = int(agent_lumi)
    if agent_pay is not None and int(agent_pay) > 0:
        min_payout = int(agent_pay)

    # V108.6: no REAL nenhum mecanismo automático (Lab, Anti-Stall ou Agente) pode
    # REDUZIR os cortes configurados pelo usuário. Aprendizado pode apenas manter/subir.
    if str(cfg_get("account_type", "PRACTICE")).upper() == "REAL":
        min_tech = max(int(min_tech), int(base_tech))
        min_lumi_scan = max(int(min_lumi_scan), int(base_lumi))

    # V104: aprendizado REAL recente só aumenta prudência. Em REAL aplica também
    # pisos profissionais mesmo quando a configuração antiga estava permissiva.
    min_tech, min_lumi_scan, wallstreet_learning = wallstreet_apply_round_thresholds(min_tech, min_lumi_scan, min_payout)
    if str(cfg_get("account_type", "PRACTICE")).upper() == "REAL":
        min_tech = technical_threshold_grid(max(int(min_tech), REAL_HARD_TECH_FLOOR), strategy, "ceil")
        min_lumi_scan = max(int(min_lumi_scan), REAL_HARD_LUMI_FLOOR)
    adaptive_thresholds["wallstreet"] = dict(wallstreet_learning)
    adaptive_thresholds["effective_tech"] = int(min_tech)
    adaptive_thresholds["effective_lumi"] = int(min_lumi_scan)

    # V108.8.0: o piso Lumi permanece 67% mesmo em cooldown/offline. O fallback técnico
    # já possui tratamento próprio por source e não precisa falsificar o corte exibido para 0%.
    lumi_down = time.time() < float(cfg_get("lumi_cooldown_until", 0) or 0)
    lumi_status = str(cfg_get("lumi_quota_status") or "").lower()
    lumi_fallback_active = bool(lumi_down or lumi_status in {"timeout", "erro_conexao", "memoria_baixa", "cota_429", "cooldown", "http_error"})
    if str(cfg_get("account_type", "PRACTICE")).upper() == "REAL":
        min_lumi_scan = max(int(min_lumi_scan), REAL_HARD_LUMI_FLOOR)
    try:
        lumi_top = max(1, int(agent_metrics.get("scanner_lumi_top", lumi_top) or lumi_top))
    except Exception:
        lumi_top = max(1, int(lumi_top or 3))
    # Publica os valores realmente usados pelo scanner depois de combinar Config + Laboratório + Lumi Agente.
    with state_lock:
        agent_snapshot = dict(cfg_get("lumi_agent") or _default_lumi_agent_state())
        effective_snapshot = dict(agent_snapshot.get("effective_metrics") or {})
        effective_snapshot.update({
            "min_technical_confidence": int(min_tech),
            "lumi_min_confidence": int(min_lumi_scan),
            "min_payout": int(min_payout),
            "scanner_lumi_top": int(lumi_top),
            "lumi_min_technical_to_call": int(agent_metrics.get("lumi_min_technical_to_call", cfg_get("lumi_min_technical_to_call", 60)) or 60),
            "hold_candles": int(agent_metrics.get("hold_candles", cfg_get("lumi_hold_block_candles", 3)) or 3),
        })
        agent_snapshot["effective_metrics"] = effective_snapshot
        state["lumi_agent"] = agent_snapshot

    with state_lock:
        state["adaptive_thresholds"] = adaptive_thresholds
        adaptive_key = f"{int(adaptive_thresholds.get('effective_tech', base_tech) or base_tech)}|{int(adaptive_thresholds.get('effective_lumi', base_lumi) or base_lumi)}|{bool(adaptive_thresholds.get('ready'))}"
        adaptive_changed = cfg_get("_last_adaptive_threshold_log") != adaptive_key
        if adaptive_changed:
            state["_last_adaptive_threshold_log"] = adaptive_key
    if adaptive_changed and adaptive_thresholds.get("ready"):
        log(f"🧪 Laboratório V108.8.0: autoajuste protegido · técnica {min_tech}% · Lumi {min_lumi_scan}% · {adaptive_thresholds.get('resolved_samples', 0)} resultado(s) comparável(is) REAL+Shadow.", "info")
    _scan_progress("calibration")
    calibration_profile = adaptive_calibration_scanner_snapshot()
    _scan_progress("calibration_done")
    if _scan_abort_if_deadline("calibration"):
        return None, []
    calibration_key = f"{calibration_profile.get('samples',0)}|{calibration_profile.get('actual_samples',0)}|{calibration_profile.get('winrate',0)}|{calibration_profile.get('edge',0)}"
    with state_lock:
        calibration_changed = cfg_get("_last_calibration_log") != calibration_key
        if calibration_changed:
            state["_last_calibration_log"] = calibration_key
    if calibration_changed and int(calibration_profile.get("samples",0) or 0) > 0:
        log(
            f"🧠 Calibração persistente V108.8.0: {int(calibration_profile.get('samples',0))} resultado(s) · "
            f"REAL={int(calibration_profile.get('actual_samples',0))}/{int(calibration_profile.get('real_records_reserved',calibration_profile.get('actual_samples',0)) or 0)} reservados · shadow={int(calibration_profile.get('shadow_samples',0))} · "
            f"WR ponderado {float(calibration_profile.get('winrate',0)):.1f}% · edge {float(calibration_profile.get('edge',0)):+.1f}pp · "
            f"peso REAL×{float(calibration_profile.get('real_weight_multiplier',1)):.2g} · shadow×{float(calibration_profile.get('shadow_weight_scale',1)):.3f}.",
            "info",
        )
    learning_key = f"{wallstreet_learning.get('recent_real',0)}|{wallstreet_learning.get('loss_streak',0)}|{wallstreet_learning.get('tech_boost',0)}|{wallstreet_learning.get('lumi_boost',0)}|{min_tech}|{min_lumi_scan}"
    with state_lock:
        learning_changed = cfg_get("_last_wallstreet_learning_log") != learning_key
        if learning_changed:
            state["_last_wallstreet_learning_log"] = learning_key
    if learning_changed:
        log(
            f"🏦 Wall Street Adaptive V108.8.0: REAL recente {int(wallstreet_learning.get('recent_wins',0))}W/{int(wallstreet_learning.get('recent_losses',0))}L · "
            f"edge {float(wallstreet_learning.get('edge',0)):+.1f}pp · loss streak {int(wallstreet_learning.get('loss_streak',0))} · "
            f"fonte={str(wallstreet_learning.get('source') or 'ledger_daily')} · cortes efetivos técnica {min_tech}% / Lumi {min_lumi_scan}%.",
            "warn" if int(wallstreet_learning.get("tech_boost",0) or 0) > 0 else "info",
        )
    scan_label = "Elite Watcher" if elite_mode else "Scanner de mercado"
    update_entry_progress(
        stage="elite" if elite_mode else "scanner",
        status=(f"⚡ Elite Watcher · reanalisando {len(elite_assets_norm)} oportunidade(s) quente(s)" if elite_mode else f"Iniciando varredura · {market_mode_label(market_mode)}"),
        min_tech=min_tech, min_payout=min_payout, min_lumi=min_lumi_scan,
    )

    update_decision_diagnostic(
        phase="elite" if elite_mode else "scanner",
        status=(f"Elite Opportunity Watcher em execução · {len(elite_assets_norm)} candidato(s)." if elite_mode else f"Scanner de mercado em execução · {market_mode_label(market_mode)}."),
        details=(f"Reanálise seletiva FAST → DEEP → MTF → Lumi; gates inalterados. Técnica mínima efetiva {min_tech}%." if elite_mode else f"Buscando ativos compatíveis, lendo velas fechadas e ranqueando sinais. {stall.get('status')} · técnica mínima efetiva {min_tech}%."),
        next_action="avaliar oportunidades",
        steps=[make_step("Modo de mercado", True, market_mode_label(market_mode))],
    )

    _scan_progress("universe_snapshot")
    universe_perf_started = time.perf_counter()
    assets_all, market_meta = _list_scan_assets_budgeted(api, market_mode)
    _scan_progress("universe_ready", total=len(assets_all))
    if _scan_abort_if_deadline("universe"):
        return None, []
    assets_all = _filter_assets_for_market_mode(assets_all, market_mode)
    if elite_mode:
        broker_open = {normalize_asset_name(a) for a in assets_all if a}
        active_assets = {normalize_asset_name(o.get("asset", "")) for o in get_active_open_orders() if o.get("asset")}
        assets_all = [a for a in elite_assets_norm if a in broker_open and a not in active_assets and _asset_allowed_for_market_mode(a, market_mode)]
        market_meta = dict(market_meta or {})
        market_meta["elite_watcher"] = True
        market_meta["elite_requested"] = len(elite_assets_norm)
        market_meta["elite_open_eligible"] = len(assets_all)
        if assets_all:
            log(f"⚡ ELITE WATCHER V108.8.0: {len(assets_all)}/{len(elite_assets_norm)} candidato(s) OPEN → DEEP seletivo · {', '.join(assets_all[:6])}.", "info")
        else:
            log("⚡ ELITE WATCHER V108.8.0: fila quente ficou vazia após OPEN/ordens ativas; aguardando novo FAST BG.", "info")
    if _market_mode_generation_changed(round_mode_generation):
        log(f"🔄 MARKET MODE V108.8.0: rodada antiga abortada antes do DEEP; modo mudou durante a seleção.", "info")
        return None, []
    full_market_radar = bool(cfg_get("full_market_radar_enabled", True))
    full_market_intelligence = bool(full_market_radar and cfg_get("full_market_intelligence_enabled", True))
    if full_market_intelligence:
        # V108.6: ranking será global; não ordena/intercala por categoria antes do score.
        assets = list(dict.fromkeys(normalize_asset_name(a) for a in assets_all if a))
        full_cap = max(0, int(cfg_get("full_market_radar_max_universe", 0) or 0))
        if full_cap > 0:
            assets = assets[:full_cap]
    elif full_market_radar:
        assets = _full_market_radar_order(assets_all)
        full_cap = max(0, int(cfg_get("full_market_radar_max_universe", 0) or 0))
        if full_cap > 0:
            assets = assets[:full_cap]
    else:
        assets = assets_all[:max_assets]
    universe_ms = int((time.perf_counter() - universe_perf_started) * 1000)
    prefilter_perf_started = time.perf_counter()

    # v93: o snapshot V2 que montou `assets` é a fonte única de negociabilidade
    # DURANTE ESTA RODADA. Não atualizamos o V2 no meio do ranking/Lumi, porque uma
    # rodada pode durar mais que o TTL e isso gerava contradições do tipo:
    # "descartado como CLOSED" e segundos depois "Quase passou" para o mesmo ativo.
    # A disponibilidade volta a ser forçada/revalidada antes de esperar/abrir a ordem.
    round_v2_meta = dict(market_meta.get("v2_prefilter") or {})
    round_v2_verified = bool(round_v2_meta.get("verified"))
    round_open_assets = {normalize_asset_name(a) for a in assets if a}
    selected_otc_count = sum(1 for a in assets if is_otc_asset(a))
    selected_crypto_count = sum(1 for a in assets if (not is_otc_asset(a)) and is_crypto_asset(a))
    selected_normal_count = max(0, len(assets) - selected_otc_count - selected_crypto_count)
    market_meta["selected_otc_count"] = selected_otc_count
    market_meta["selected_crypto_count"] = selected_crypto_count
    market_meta["selected_normal_count"] = selected_normal_count
    market_meta["round_v2_verified"] = round_v2_verified
    market_meta["round_open_count"] = len(round_open_assets)
    market_meta["round_open_assets"] = sorted(round_open_assets)[:120]
    market_meta["mode_generation"] = int(round_mode_generation)

    scan_stats = {
        "found": int(market_meta.get("found_count", len(assets_all)) or len(assets_all)),
        "compatible": len(assets_all),
        "candles_loaded": 0,
        "strong_signals": 0,
        "sent_lumi": 0,
        "hold_blocked": 0,
        "approved": 0,
        "incompatible_ignored": int(market_meta.get("incompatible_ignored", 0) or 0),
        "technical_fallback": 0,
        "loss_memory_rejected": 0,
        "win_memory_matched": 0,
        "wallstreet_ev_rejected": 0,
        "fast_elite_triggered": 0,
        "fast_elite_asset": "",
        "fast_elite_scanned": 0,
        "fast_elite_saved_assets": 0,
        "elite_watcher": 1 if elite_mode else 0,
        "elite_requested": len(elite_assets_norm) if elite_mode else 0,
        "elite_scanned": len(assets) if elite_mode else 0,
        "candle_budget_exhausted": 0,
        "candle_budget_saved_assets": 0,
        "candle_timeout_limit_hit": 0,
        "candle_engine_timeout_ms": int(float(cfg_get("candle_engine_per_asset_timeout_seconds", 3.0) or 3.0) * 1000),
        "candle_soft_slow": 0,
        "candle_reserve_available": 0,
        "candle_reserve_attempted": 0,
        "candle_reserve_filled": 0,
        "anti_stall_active": 1 if stall.get("active") else 0,
        "idle_seconds": int(stall.get("idle_seconds", 0)),
        "effective_min_tech": int(min_tech),
        "effective_min_lumi": int(min_lumi_scan),
        "adaptive_ready": 1 if adaptive_thresholds.get("ready") else 0,
        "adaptive_samples": int(adaptive_thresholds.get("resolved_samples", 0) or 0),
        "adaptive_mode": str(adaptive_thresholds.get("mode", "coletando")),
        "lumi_agent_autonomous": 1,
        "lumi_agent_min_tech": int(min_tech),
        "lumi_agent_min_lumi": int(min_lumi_scan),
        "lumi_agent_min_payout": int(min_payout),
        "lumi_agent_top": int(lumi_top),
        "rotation_enabled": 1 if bool(cfg_get("scanner_lumi_rotation_enabled", True)) else 0,
        "rotation_budget": 0,
        "rotation_batch_size": 0,
        "rotation_evaluated": 0,
        "rotation_exhausted": 0,
        "round_v2_verified": 1 if round_v2_verified else 0,
        "round_open_universe": len(round_open_assets),
        "precision_enriched": 0,
        "precision_early_filtered": 0,
        "precision_lumi_shortlist": 0,
        "precision_cache_hits": 0,
        "precision_cache_misses": 0,
        "lumi_health_degraded": 0,
        "lumi_health_borderline_skipped": 0,
        "lumi_health_bypass": 0,
        "smart_prefilter_enabled": 1 if bool(cfg_get("smart_prefilter_enabled", True)) else 0,
        "smart_prefilter_before": len(assets),
        "smart_prefilter_selected": len(assets),
        "smart_prefilter_hot": 0,
        "smart_prefilter_explore": 0,
        "smart_prefilter_weak_cooldown": 0,
        "smart_prefilter_hot_excluded": 0,
        "smart_prefilter_declining": 0,
        "smart_prefilter_forced_recovery": 0,
        "smart_prefilter_recovery_ready": 0,
        "smart_prefilter_ms": 0,
        "full_market_radar_enabled": 1 if full_market_radar else 0,
        "full_market_intelligence_enabled": 1 if full_market_intelligence else 0,
        "full_market_fast_evaluated": 0,
        "full_market_fast_history_covered": 0,
        "deep_ranking_count": 0,
        "full_market_radar_seen": len(assets),
        "full_market_radar_open_total": len(assets_all),
        "lumi_timeout_round_break": 0,
        "universe_ms": int(universe_ms),
        "scanner_ms": 0,
        "mtf_ms": 0,
        "lumi_ms": 0,
        "round_total_ms": 0,
        "market_init_ms": 0,
        "candles_ms": 0,
        "payout_ms": 0,
        "payout_snapshot_ms": 0,
        "payout_snapshot_assets": 0,
        "payout_snapshot_missing": 0,
        "payout_snapshot_cached": 0,
        "preflight_ms": 0,
        "data_slow": 0,
        "scanner_budget_exhausted": 0,
        "scanner_assets_skipped_budget": 0,
        "market_data_dedicated": 1 if api is cfg_get("market_api") else 0,
    }
    with state_lock:
        state["market_status"] = market_meta
        state["scanner_stats"] = scan_stats
        universe_sig = f"{market_meta.get('used_mode')}|{1 if full_market_radar else 0}|{round_v2_verified}|{len(round_open_assets)}|{int(market_meta.get('open_normal_count',0) or 0)}|{int(market_meta.get('open_crypto_count',0) or 0)}|{int(market_meta.get('open_otc_count',0) or 0)}|{int(market_meta.get('false_open_count',0) or 0)}|{selected_normal_count}|{selected_crypto_count}|{selected_otc_count}|{int(round_v2_meta.get('closed',0) or 0)}"
        universe_changed = cfg_get("_last_round_universe_log") != universe_sig
        if universe_changed:
            state["_last_round_universe_log"] = universe_sig
    if universe_changed and round_v2_verified:
        live_normal_count = int(market_meta.get("open_normal_count", 0) or 0)
        live_crypto_count = int(market_meta.get("open_crypto_count", 0) or 0)
        live_otc_count = int(market_meta.get("open_otc_count", 0) or 0)
        live_total_count = int(market_meta.get("open_total_count", live_normal_count + live_crypto_count + live_otc_count) or 0)
        false_open_count = int(market_meta.get("false_open_count", 0) or 0)
        priority_label = str(market_meta.get("used_mode") or "normal")
        discarded_otc = max(0, live_otc_count - selected_otc_count) if market_mode in {"normal_only", "crypto_only"} else 0
        log(
            f"📡 Universo TURBO OPEN da rodada (V2): BROKER OPEN={live_total_count} · "
            f"descobertos normal={live_normal_count} cripto={live_crypto_count} OTC={live_otc_count} · "
            f"ELEGÍVEL={len(round_open_assets)} modo={market_mode} → normal={selected_normal_count} cripto={selected_crypto_count} OTC={selected_otc_count} · "
            f"OTC descartado pelo modo={discarded_otc} · FALSE-OPEN={false_open_count} · prioridade={priority_label}. "
            f"Somente ELEGÍVEIS entram em FAST/DEEP/MTF/Lumi/ordem.",
            "info",
        )
    if not assets:
        log(f"Scanner: nenhum ativo compatível no modo {market_mode_label(market_mode)}. {market_meta.get('reason','')}", "warn")
        update_decision_diagnostic(
            phase="sem_ativos",
            status="Nenhum ativo compatível encontrado.",
            details=f"{market_meta.get('reason','')} Forex/Binárias={market_meta.get('forex_binary_count',0)} | Cripto={market_meta.get('crypto_count',0)} | OTC={market_meta.get('otc_count',0)}.",
            next_action="aguardar próxima varredura",
            steps=[make_step("Ativos compatíveis", False, "lista vazia")],
        )

    # V108.6: UMA chamada de payout para todo o universo OPEN alimenta a avaliação FAST
    # de 100% dos ativos. Depois o ranking global escolhe 24 + 10 reservas.
    full_market_payout_snapshot = build_round_payout_snapshot(api, assets) if full_market_intelligence else None
    if _market_mode_generation_changed(round_mode_generation):
        log("🔄 MARKET MODE V108.8.0: rodada antiga abortada durante payout/FAST; nenhum ativo antigo seguirá para DEEP.", "info")
        return None, []
    if full_market_intelligence:
        scan_assets, smart_meta = full_market_intelligence_select_assets(assets, tf, full_market_payout_snapshot)
        scan_stats["full_market_fast_evaluated"] = int(smart_meta.get("evaluated_fast", 0) or 0)
        scan_stats["full_market_fast_history_covered"] = int(smart_meta.get("history_covered", 0) or 0)
    else:
        scan_assets, smart_meta = smart_prefilter_select_assets(assets, tf)
    prefilter_ms = int((time.perf_counter() - prefilter_perf_started) * 1000)
    scan_stats["smart_prefilter_before"] = int(smart_meta.get("before", len(assets)) or len(assets))
    scan_stats["smart_prefilter_selected"] = int(smart_meta.get("selected", len(scan_assets)) or len(scan_assets))
    scan_stats["smart_prefilter_hot"] = int(smart_meta.get("hot", 0) or 0)
    scan_stats["smart_prefilter_explore"] = int(smart_meta.get("explore", 0) or 0)
    scan_stats["smart_prefilter_weak_cooldown"] = int(smart_meta.get("weak_cooldown", 0) or 0)
    scan_stats["smart_prefilter_hot_excluded"] = int(smart_meta.get("hot_excluded", 0) or 0)
    scan_stats["smart_prefilter_declining"] = int(smart_meta.get("declining", 0) or 0)
    scan_stats["smart_prefilter_forced_recovery"] = int(smart_meta.get("forced_recovery", 0) or 0)
    scan_stats["smart_prefilter_recovery_ready"] = int(smart_meta.get("recovery_ready", 0) or 0)
    scan_stats["smart_prefilter_ms"] = int(prefilter_ms)
    market_meta["smart_prefilter"] = dict(smart_meta)
    if smart_meta.get("enabled"):
        if full_market_intelligence:
            log(
                f"🌐 Market Intelligence 2.0 V108.8.0: OPEN {int(smart_meta.get('before',len(assets)))} → "
                f"FAST {int(smart_meta.get('evaluated_fast',0))}/{int(smart_meta.get('before',len(assets)))} → DEEP {len(scan_assets)} · "
                f"ranking GLOBAL sem quotas · mix Top24 OTC={int(smart_meta.get('selected_otc',0))}/normal={int(smart_meta.get('selected_normal',0))}/cripto={int(smart_meta.get('selected_crypto',0))} · "
                f"histórico FAST={int(smart_meta.get('history_covered',0))}/{int(smart_meta.get('evaluated_fast',0))} · FAST BG={int(smart_meta.get('fast_background_covered',0))}/{int(smart_meta.get('evaluated_fast',0))} · reservas={int(smart_meta.get('reserve_count',0))} · "
                f"ordem aberta ignorada={int(smart_meta.get('open_order_skipped',0))} · {prefilter_ms}ms.",
                "info",
            )
            _log_fmi_top(smart_meta)
        else:
            log(
                (f"🌐 Full Market Radar V108.5: OPEN {int(smart_meta.get('before',len(assets)))} → {len(scan_assets)} ativo(s) pesados · " if full_market_radar else f"⚡ Smart Prefilter: radar {int(smart_meta.get('before',len(assets)))} → {len(scan_assets)} ativo(s) pesados · ")
                + f"HOT={int(smart_meta.get('hot',0))} · exploração={int(smart_meta.get('explore',0))} · "
                + (f"mix pesado OTC={int(smart_meta.get('selected_otc',0))}/normal={int(smart_meta.get('selected_normal',0))}/cripto={int(smart_meta.get('selected_crypto',0))} · " if full_market_radar else "")
                + f"cooldown fraco={int(smart_meta.get('weak_cooldown',0))} · fora HOT={int(smart_meta.get('hot_excluded',0))} · "
                f"recuperação={int(smart_meta.get('recovery_ready',0))} · liberação proteção={int(smart_meta.get('forced_recovery',0))} · "
                f"reservas={int(smart_meta.get('reserve_count',0))} · em queda={int(smart_meta.get('declining',0))} · ordem aberta ignorada={int(smart_meta.get('open_order_skipped',0))} · {prefilter_ms}ms.",
                "info",
            )
    # V108.6: os principais do Full Market Intelligence têm fila reserva. Payout continua sendo um único
    # snapshot, agora cobrindo principais + reservas para a substituição não criar I/O extra.
    primary_scan_assets = list(scan_assets)
    reserve_assets = [normalize_asset_name(a) for a in (smart_meta.get("reserve_assets") or []) if a and normalize_asset_name(a) not in {normalize_asset_name(x) for x in primary_scan_assets}]
    scan_queue = primary_scan_assets + reserve_assets
    target_analyzed = max(1, len(primary_scan_assets))
    scan_stats["candle_reserve_available"] = len(reserve_assets)
    _scan_progress("payout_snapshot", total=len(scan_queue))
    payout_snapshot = full_market_payout_snapshot if full_market_intelligence and isinstance(full_market_payout_snapshot, dict) else build_round_payout_snapshot(api, scan_queue)
    _scan_progress("payout_ready", total=len(scan_queue))
    if _scan_abort_if_deadline("payout_snapshot"):
        return None, []
    scan_stats["payout_snapshot_ms"] = int(payout_snapshot.get("elapsed_ms", 0) or 0)
    scan_stats["payout_snapshot_assets"] = int(payout_snapshot.get("resolved", 0) or 0)
    scan_stats["payout_snapshot_missing"] = int(payout_snapshot.get("missing", 0) or 0)
    scan_stats["payout_snapshot_cached"] = 1 if payout_snapshot.get("cached_snapshot") else 0

    technical_perf_started = time.perf_counter()
    smart_hot_set = {normalize_asset_name(a) for a in (smart_meta.get("hot_assets") or [])}
    smart_explore_set = {normalize_asset_name(a) for a in (smart_meta.get("explore_assets") or [])}
    smart_reserve_set = set(reserve_assets)

    rows: List[Dict[str, Any]] = []
    total_assets_scan = target_analyzed
    technical_budget_s = max(5.0, float(cfg_get("scanner_technical_budget_seconds", 20) or 20))
    candle_budget_s = max(5.0, float(cfg_get("candle_engine_round_budget_seconds", 18.5) or 18.5)) if bool(cfg_get("candle_engine_fast_enabled", True)) else technical_budget_s
    if full_market_radar:
        # 20 ativos custam mais que os 12 legados, mas continuam sob teto global.
        technical_budget_s = max(technical_budget_s, 18.0)
        candle_budget_s = max(candle_budget_s, 16.5)
    effective_technical_budget_s = min(technical_budget_s, candle_budget_s)
    timeout_warned = False
    for asset_index, asset in enumerate(scan_queue, start=1):
        _scan_progress("candles", asset=asset, current=asset_index, total=len(scan_queue))
        if _scan_deadline_exceeded():
            scan_stats["hard_deadline_exhausted"] = 1
            missing_target = max(0, target_analyzed - int(scan_stats.get("candles_loaded", 0) or 0))
            scan_stats["candle_budget_saved_assets"] = max(int(scan_stats.get("candle_budget_saved_assets", 0) or 0), missing_target)
            log(f"⏱ FULL SCAN DEADLINE V108.8.0 | fase=candles · {time.perf_counter()-round_perf_started:.1f}s/{hard_deadline_s:.0f}s · encerrando com {int(scan_stats.get('candles_loaded',0) or 0)}/{target_analyzed} ativos válidos; próxima rodada continuará.", "warn")
            break
        if int(getattr(_API_TIMING_LOCAL, "market_data_reconnect_round", 0) or 0) > 0:
            scan_stats["market_data_reconnect_abort"] = 1
            missing_target = max(0, target_analyzed - int(scan_stats.get("candles_loaded", 0) or 0))
            scan_stats["scanner_assets_skipped_budget"] = max(int(scan_stats.get("scanner_assets_skipped_budget", 0) or 0), missing_target)
            log(
                f"🔄 Candle Engine V108.8.0: sessão Market Data foi rotacionada nesta rodada; encerrando DEEP com "
                f"{int(scan_stats.get('candles_loaded',0) or 0)}/{target_analyzed} válidos para não reutilizar a conexão degradada. "
                f"A próxima rodada usará a sessão nova.",
                "warn",
            )
            break
        if _market_mode_generation_changed(round_mode_generation):
            log("🔄 MARKET MODE V108.8.0: rodada antiga abortada durante Candle Engine; nenhum restante será analisado.", "info")
            return None, []
        if not _asset_allowed_for_market_mode(asset, market_mode):
            continue
        if int(scan_stats.get("candles_loaded", 0) or 0) >= target_analyzed:
            break
        using_reserve = normalize_asset_name(asset) in smart_reserve_set
        timeout_limit = max(1, int(cfg_get("candle_engine_max_timeouts_per_round", 2) or 2))
        timeout_count = int(getattr(_API_TIMING_LOCAL, "candle_timeouts_round", 0) or 0)
        if bool(cfg_get("candle_engine_fast_enabled", True)) and timeout_count >= timeout_limit and not timeout_warned:
            timeout_warned = True
            scan_stats["candle_timeout_limit_hit"] = 1
            log(f"⚡ Candle Engine V108.8.0: {timeout_count} timeout(s) na rodada; NÃO abortando. Ativos lentos serão descartados e a fila reserva continuará até a meta {target_analyzed} ou o orçamento global.", "warn")
        if (time.perf_counter() - technical_perf_started) >= effective_technical_budget_s:
            scan_stats["scanner_budget_exhausted"] = 1
            scan_stats["candle_budget_exhausted"] = 1
            missing_target = max(0, target_analyzed - int(scan_stats.get("candles_loaded", 0) or 0))
            scan_stats["scanner_assets_skipped_budget"] = missing_target
            scan_stats["candle_budget_saved_assets"] = missing_target
            log(f"⚡ Candle Engine V108.8.0: {scan_stats.get('candles_loaded',0)}/{target_analyzed} ativos válidos analisados · orçamento global {effective_technical_budget_s:.1f}s atingido; faltaram {missing_target}. Timeouts não encerraram a rodada antecipadamente.", "warn")
            break
        slow_for = data_slow_remaining(asset, tf)
        if slow_for > 0:
            scan_stats["data_slow"] = int(scan_stats.get("data_slow", 0) or 0) + 1
            continue
        if using_reserve:
            scan_stats["candle_reserve_attempted"] = int(scan_stats.get("candle_reserve_attempted", 0) or 0) + 1
        try:
            update_entry_progress(
                asset=asset, stage="analisando",
                status=f"Analisando {asset} · alvo {int(scan_stats.get('candles_loaded',0))+1}/{total_assets_scan}" + (" · RESERVA" if using_reserve else "") + " · lendo candles e indicadores",
                min_tech=min_tech, min_payout=min_payout, min_lumi=min_lumi_scan,
            )
            if has_active_order_for_asset(asset):
                scan_stats["active_order_asset_skipped"] = int(scan_stats.get("active_order_asset_skipped", 0) or 0) + 1
                continue
            order_block = is_order_failure_blocked(asset)
            if order_block > 0:
                rows.append({
                    "asset": asset,
                    "direction": None,
                    "technical_confidence": 0,
                    "rank": 0,
                    "payout": int(_payout_snapshot_info(payout_snapshot, asset).get("payout", 0) or 0),
                    "signals": {},
                    "reasons": [],
                    "lumi": None,
                    "approved": False,
                    "block_reason": f"ativo bloqueado por falha de abertura anterior ({order_block}s)",
                    "decision_status": f"ativo bloqueado por falha de abertura anterior ({order_block}s)",
                    "decision_steps": [make_step("Negociabilidade", False, order_failure_reason(asset))],
                    "next_action": "aguardar desbloqueio ou outro ativo",
                    "next_in_seconds": order_block,
                })
                continue
            row = evaluate_asset(api, asset, tf, strategy, payout_snapshot=payout_snapshot)
            _scan_progress("technical", asset=asset, current=asset_index, total=len(scan_queue))
            if not row:
                continue
            norm_asset = normalize_asset_name(asset)
            row["smart_prefilter_bucket"] = "hot" if norm_asset in smart_hot_set else ("explore" if norm_asset in smart_explore_set else ("reserve" if norm_asset in smart_reserve_set else "fill"))
            smart_prefilter_record_row(row, tf, count_weak=True)
            scan_stats["candles_loaded"] += 1
            if using_reserve:
                scan_stats["candle_reserve_filled"] = int(scan_stats.get("candle_reserve_filled", 0) or 0) + 1
            steps = base_decision_steps(row, min_tech, min_payout)
            row["decision_steps"] = steps
            row["professional_score"] = compute_professional_score(row, None)
            update_professional_score(row, None)
            ci_block, ci_reason = candle_intelligence_guard_reason(row)
            row["decision_steps"] = list(row.get("decision_steps") or []) + [make_step("Candle Intelligence", not ci_block, ci_reason)]
            if ci_block:
                scan_stats["candle_intelligence_rejected"] = int(scan_stats.get("candle_intelligence_rejected", 0) or 0) + 1
                row["shadow_rejection_stage"] = "candle_intelligence"
                set_row_status(row, f"Candle Intelligence bloqueou: {ci_reason}", row.get("decision_steps"), "aguardar estrutura/price action melhor")
                rows.append(row)
                continue

            loss_rejected, loss_steps = apply_loss_memory_to_row(row, tf)
            if loss_steps:
                steps = row.get("decision_steps", []) + loss_steps
                row["decision_steps"] = steps
                row["adaptive"] = compute_adaptive_signal_score(row)
                row["calibration"] = (row.get("adaptive") or {}).get("calibration") if isinstance((row.get("adaptive") or {}).get("calibration"), dict) else {}
                row["adaptive_score"] = int((row.get("adaptive") or {}).get("score", row.get("technical_confidence", 0)) or 0)
                row["ranking_score"] = int(row["adaptive_score"] * 100 + int(row.get("rank", 0) or 0))
                row["professional_score"] = compute_professional_score(row, None)
                update_professional_score(row, None)
            if loss_rejected:
                scan_stats["loss_memory_rejected"] = int(scan_stats.get("loss_memory_rejected", 0) or 0) + 1
                rows.append(row)
                continue

            # V104: WIN Memory favorece ranking, nunca libera entrada sozinho.
            win_bonus, win_steps = apply_win_memory_to_row(row, tf)
            if win_steps:
                scan_stats["win_memory_matched"] = int(scan_stats.get("win_memory_matched", 0) or 0) + 1
                steps = list(row.get("decision_steps") or []) + win_steps
                row["decision_steps"] = steps

            # V108.8: aprendizado REAL contextual. LOSS afeta o arquétipo semelhante, não o bot inteiro.
            ali_block, ali_steps = apply_adaptive_loss_intelligence_to_row(row, int(min_tech), None, "pre_lumi")
            if ali_steps:
                row["decision_steps"] = list(row.get("decision_steps") or []) + ali_steps
            if ali_block:
                rows.append(row)
                continue

            # V104: Gate de EV usa Laboratório + resultados REAL/Shadow comparáveis.
            # Com pouca amostra apenas registra cautela; com evidência negativa suficiente bloqueia.
            risk_gate = wallstreet_row_risk_gate(row)
            if risk_gate.get("penalty") or risk_gate.get("block"):
                steps = list(row.get("decision_steps") or []) + [
                    make_step("Wall Street EV", not bool(risk_gate.get("block")), str(risk_gate.get("reason") or "histórico"))
                ]
                row["decision_steps"] = steps
            row["adaptive"] = compute_adaptive_signal_score(row)
            row["calibration"] = (row.get("adaptive") or {}).get("calibration") if isinstance((row.get("adaptive") or {}).get("calibration"), dict) else row.get("calibration", {})
            row["adaptive_score"] = int((row.get("adaptive") or {}).get("score", row.get("technical_confidence", 0)) or 0)
            row["ranking_score"] = int(row["adaptive_score"] * 100 + int(row.get("rank", 0) or 0))
            row["professional_score"] = compute_professional_score(row, None)
            if risk_gate.get("block"):
                scan_stats["wallstreet_ev_rejected"] = int(scan_stats.get("wallstreet_ev_rejected", 0) or 0) + 1
                set_row_status(row, f"Wall Street EV bloqueou: {risk_gate.get('reason')}", row.get("decision_steps"), "aguardar padrão com edge melhor")
                rows.append(row)
                continue

            if str(cfg_get("account_type", "PRACTICE")).upper() == "REAL" and not int(row.get("payout", 0) or 0) and real_allow_unknown_payout():
                unknown_min_tech, _unknown_min_lumi = real_unknown_payout_requirements()
                if row.get("technical_confidence", 0) < unknown_min_tech:
                    set_row_status(row, f"payout desconhecido no REAL; exige técnica {unknown_min_tech}%", steps + [make_step("Payout desconhecido", False, f"fonte {row.get('payout_source','desconhecido')}; técnica {row.get('technical_confidence',0)}%/{unknown_min_tech}%")], "aguardar sinal mais forte")
                else:
                    set_row_status(row, f"payout desconhecido permitido com trava extra REAL; fonte {row.get('payout_source','desconhecido')}", steps + [make_step("Payout desconhecido", True, f"modo controlado: técnica mínima {unknown_min_tech}% e Lumi extra")], "pode ir para análise Lumi com trava extra")
            elif real_requires_valid_payout() and not int(row.get("payout", 0) or 0):
                set_row_status(row, "payout não retornado no REAL; ativo ignorado", steps, "procurar outro ativo com payout válido")
            elif row["payout"] and row["payout"] < min_payout:
                set_row_status(row, f"payout {row['payout']}% abaixo do mínimo", steps, "aguardar payout melhor")
            elif not row["direction"]:
                set_row_status(row, "sinal técnico neutro", steps, "aguardar novo candle")
            elif row["technical_confidence"] < min_tech:
                set_row_status(row, "confiança técnica baixa", steps, "aguardar sinal mais forte")
            else:
                set_row_status(row, "passou na técnica; aguardando ranking/Lumi", steps, "pode ir para análise Lumi")
            update_entry_progress(
                asset=row.get("asset", asset), direction=row.get("direction"),
                technical=int(row.get("technical_confidence", 0) or 0), payout=int(row.get("payout", 0) or 0),
                min_tech=min_tech, min_payout=min_payout, min_lumi=min_lumi_scan,
                stage="técnica", status=f"{row.get('asset', asset)} · {row.get('decision_status') or 'análise técnica concluída'}",
                blocker=row.get("block_reason", ""),
            )
            rows.append(row)

            # V104 Fast Elite: depois de uma amostra mínima do HOT, um candidato
            # excepcional encerra somente a LEITURA dos demais ativos. Ele ainda
            # passa por Precision MTF, Lumi, EV, freshness e preflight FINAL.
            fast_ok, fast_reason = wallstreet_fast_elite_candidate(
                row, int(scan_stats.get("candles_loaded", 0) or 0), min_tech, min_payout, wallstreet_learning
            )
            if fast_ok:
                scan_stats["fast_elite_triggered"] = 1
                scan_stats["fast_elite_asset"] = str(row.get("asset") or "")
                scan_stats["fast_elite_scanned"] = int(scan_stats.get("candles_loaded", 0) or 0)
                scan_stats["fast_elite_saved_assets"] = max(0, target_analyzed - int(scan_stats.get("candles_loaded", 0) or 0))
                log(
                    f"⚡ Fast Elite V108: {row.get('asset')} {str(row.get('direction') or '').upper()} · {fast_reason} · "
                    f"parando leitura pesada após {scan_stats['fast_elite_scanned']}/{target_analyzed} ativos; seguindo para MTF/Lumi.",
                    "info",
                )
                break
        except Exception as e:
            rows.append({
                "asset": asset,
                "direction": None,
                "technical_confidence": 0,
                "rank": 0,
                "payout": 0,
                "signals": {},
                "reasons": [],
                "lumi": None,
                "approved": False,
                "block_reason": str(e)[:120],
                "decision_status": f"erro ao avaliar: {str(e)[:80]}",
                "decision_steps": [make_step("Leitura/análise", False, str(e)[:160])],
                "next_action": "ignorar ativo nesta rodada",
                "next_in_seconds": 0,
            })

    scanner_ms = int((time.perf_counter() - technical_perf_started) * 1000)
    scan_stats["scanner_ms"] = scanner_ms

    _log_technical_distribution(rows, int(min_tech))
    try:
        _log_technical_consensus_v2(rows, 3 if str(scan_kind).lower() == "full" else 2)
    except Exception:
        pass

    # V108.6 Deep Ranking: depois de Candle Intelligence, ranqueia todos os ativos
    # pesados atuais. É somente prioridade; não altera nenhum gate de entrada REAL.
    if full_market_intelligence:
        _log_deep_market_top(rows, int(cfg_get("full_market_intelligence_log_top", 10) or 10))
        log_strategy_usage_summary(5)
        log_strategy_performance_summary(5)
        scan_stats["deep_ranking_count"] = len([r for r in rows if r.get("asset") and not r.get("excluded_from_round")])

    if _market_mode_generation_changed(round_mode_generation):
        log("🔄 MARKET MODE V108.8.0: rodada antiga abortada antes da Lumi; modo atual já mudou.", "info")
        return None, []

    # Atualiza o painel de indicadores com o candidato mais relevante da rodada,
    # mesmo quando a entrada ficar bloqueada por confiança, payout, Lumi ou janela.
    panel_rows = [r for r in rows if not r.get("excluded_from_round") and _asset_allowed_for_market_mode(r.get("asset"), market_mode)]
    if panel_rows:
        panel_row = max(panel_rows, key=lambda r: (int(r.get("deep_rank_score", 0) or 0), int(r.get("adaptive_score", 0) or 0), int(r.get("technical_confidence", 0) or 0), int(r.get("rank", 0) or 0)))
        update_signal_panel_from_row(panel_row, panel_row.get("decision_status") or panel_row.get("block_reason") or "Melhor candidato da última varredura.")

    # A Lumi pode analisar antecipadamente a faixa limítrofe. Em PRACTICE continua
    # usando o piso configurável; em REAL somente o degrau técnico imediatamente
    # anterior ao corte efetivo entra no radar. Isso NÃO reduz o piso REAL absoluto.
    agent_call_min = int(agent_metrics.get("lumi_min_technical_to_call", min_tech) or min_tech)
    candidate_tech_min = min(min_tech, agent_call_min) if cfg_get("lumi_enabled") else min_tech
    if cfg_get("lumi_enabled") and bool(cfg_get("lumi_borderline_promotion_enabled", True)):
        if str(cfg_get("account_type", "PRACTICE")).upper() == "REAL" and (bool(cfg_get("real_borderline_promotion_enabled", True)) or bool(cfg_get("adaptive_premium_override_enabled", True))):
            if bool(cfg_get("real_borderline_promotion_enabled", True)):
                candidate_tech_min = min(candidate_tech_min, max(technical_threshold_grid(REAL_HARD_TECH_FLOOR, strategy, "ceil"), technical_previous_level(min_tech, strategy)))
            if bool(cfg_get("adaptive_premium_override_enabled", True)):
                candidate_tech_min = min(candidate_tech_min, max(60, int(cfg_get("adaptive_premium_override_tech_floor", 60) or 60)))
        elif str(cfg_get("account_type", "PRACTICE")).upper() != "REAL":
            candidate_tech_min = min(candidate_tech_min, int(cfg_get("lumi_borderline_tech_floor", 50) or 50))
    if real_requires_valid_payout():
        viable = [r for r in rows if r.get("direction") and not r.get("loss_memory_rejected") and r.get("technical_confidence", 0) >= max(candidate_tech_min, int(r.get("context_tech_floor", candidate_tech_min) or candidate_tech_min)) and int(r.get("payout", 0) or 0) >= min_payout]
    elif real_allow_unknown_payout():
        unknown_min_tech, _unknown_min_lumi = real_unknown_payout_requirements()
        viable = [r for r in rows if r.get("direction") and not r.get("loss_memory_rejected") and ((int(r.get("payout", 0) or 0) >= min_payout and r.get("technical_confidence", 0) >= max(candidate_tech_min, int(r.get("context_tech_floor", candidate_tech_min) or candidate_tech_min))) or (int(r.get("payout", 0) or 0) <= 0 and r.get("technical_confidence", 0) >= max(min_tech, unknown_min_tech, int(r.get("context_tech_floor", min_tech) or min_tech))))]
    else:
        viable = [r for r in rows if r.get("direction") and not r.get("loss_memory_rejected") and r.get("technical_confidence", 0) >= max(candidate_tech_min, int(r.get("context_tech_floor", candidate_tech_min) or candidate_tech_min)) and (not r.get("payout") or r.get("payout", 0) >= min_payout)]
    viable.sort(key=lambda r: (r.get("deep_rank_score", 0), r.get("adaptive_score", 0), r.get("rank", 0), r.get("technical_confidence", 0), r.get("payout", 0)), reverse=True)

    # V108.8.0 Elite Lumi Budget: o watcher rápido não gasta IA com setup ainda longe
    # do corte. 57–(corte-1) só segue se Candle/Price Action for excepcional; >= corte
    # segue normal. Isso reduz Ollama sem facilitar entrada. O FULL Scan permanece igual.
    if elite_mode and cfg_get("lumi_enabled"):
        elite_lumi_floor = max(50, int(cfg_get("elite_lumi_min_technical", 57) or 57))
        elite_candle_floor = max(60, int(cfg_get("elite_lumi_borderline_min_candle", 85) or 85))
        elite_pa_floor = max(60, int(cfg_get("elite_lumi_borderline_min_price_action", 80) or 80))
        elite_viable = []
        for row in viable:
            tech_now = int(row.get("technical_confidence", 0) or 0)
            candle_now = int(row.get("candle_score", (row.get("candle_intelligence") or {}).get("score", 50)) or 50)
            pa_now = int((row.get("candle_intelligence") or {}).get("price_action_score", 50) or 50)
            if tech_now < elite_lumi_floor:
                row["elite_lumi_deferred"] = True
                set_row_status(row, f"Elite: técnica {tech_now}% < {elite_lumi_floor}% · IA poupada", row.get("decision_steps", []) + [make_step("Elite Lumi Budget", False, f"abaixo de {elite_lumi_floor}%")], "aguardar técnica/vela mudar")
                continue
            if tech_now < int(min_tech):
                apo_band = False
                apo_context_ok = False
                if str(cfg_get("account_type", "PRACTICE")).upper() == "REAL" and bool(cfg_get("adaptive_premium_override_enabled", True)):
                    apo_floor = max(60, int(cfg_get("adaptive_premium_override_tech_floor", 60) or 60))
                    apo_gap = int(min_tech) - tech_now
                    apo_band = apo_floor <= tech_now < int(min_tech) and 1 <= apo_gap <= int(cfg_get("adaptive_premium_override_max_gap_pp", 4) or 4)
                    apo_q = int((row.get("opportunity_quality") or {}).get("score", row.get("opportunity_quality_score", 0)) or 0)
                    if apo_q <= 0:
                        apo_q = int(compute_opportunity_quality(row, None).get("score", 0) or 0)
                    apo_mtf = float(row.get("mtf_alignment", 50) or 50)
                    apo_context_ok = (
                        candle_now >= int(cfg_get("adaptive_premium_override_min_candle", 75) or 75)
                        and pa_now >= int(cfg_get("adaptive_premium_override_min_price_action", 75) or 75)
                        and apo_q >= int(cfg_get("adaptive_premium_override_min_quality", 75) or 75)
                        and apo_mtf >= int(cfg_get("adaptive_premium_override_min_mtf", 70) or 70)
                    )
                old_elite_ok = candle_now >= elite_candle_floor and pa_now >= elite_pa_floor
                if not ((apo_band and apo_context_ok) or old_elite_ok):
                    row["elite_lumi_deferred"] = True
                    set_row_status(row, f"Elite: borderline {tech_now}% sem contexto excepcional · IA poupada", row.get("decision_steps", []) + [make_step("Elite Lumi Budget", False, f"Candle {candle_now} · PA {pa_now} · APO={'sim' if apo_band else 'não'}")], "aguardar contexto premium ou técnica atingir corte")
                    continue
            elite_viable.append(row)
        viable = elite_viable

    # UNIVERSO OPEN ÚNICO DA RODADA. Quando o get_all_init_v2 foi obtido no início,
    # `list_scan_assets()` já removeu CLOSED/MISSING antes de ler candles. Nesta etapa
    # NÃO fazemos novo refresh, para o mesmo ativo não mudar de estado no meio da rodada
    # e reaparecer em ranking/"Quase passou". Se o V2 inicial falhou, preservamos o
    # preflight individual conservador como fallback. A entrada tem revalidação V2 FINAL.
    preflight_viable: List[Dict[str, Any]] = []
    scan_stats["preflight_rejected"] = 0
    scan_stats["preflight_verified"] = 0
    for row in viable:
        asset_key = normalize_asset_name(row.get("asset", ""))
        if round_v2_verified:
            if asset_key not in round_open_assets:
                # Defesa de consistência: não deveria ocorrer, pois nem deveria ter sido
                # avaliado. Se ocorrer, sai completamente da rodada e do near-miss.
                row["excluded_from_round"] = True
                row["excluded_reason"] = "fora do universo TURBO OPEN congelado no início da rodada"
                scan_stats["preflight_rejected"] += 1
                continue
            pf = {
                "ok": True,
                "verified": True,
                "reason": "TURBO OPEN no snapshot get_all_init_v2 congelado desta rodada",
                "evidence": "round_v2_open_universe",
                "round_snapshot": True,
            }
        else:
            # V103: não transforma falha/ausência do snapshot de background em nova
            # chamada get_all_init/v2 no caminho crítico. O ativo pode continuar no
            # ranking, mas OPEN será confirmado de forma fresca somente antes de api.buy().
            pf = {
                "ok": True,
                "verified": False,
                "reason": "snapshot OPEN de background indisponível/stale; revalidação fresca reservada ao preflight FINAL",
                "evidence": "background_snapshot_pending_final_preflight",
                "round_snapshot": False,
            }

        row["market_preflight"] = pf
        if not pf.get("ok"):
            row["excluded_from_round"] = True
            row["excluded_reason"] = str(pf.get("reason") or "negociabilidade não confirmada")
            scan_stats["preflight_rejected"] += 1
            steps_pf = list(row.get("decision_steps") or []) + [make_step("Preflight negociabilidade", False, str(pf.get("reason") or "não confirmado"))]
            set_row_status(row, f"preflight recusou ativo antes da Lumi: {pf.get('reason')}", steps_pf, "promover próximo candidato imediatamente")
            update_decision_diagnostic(
                "preflight", row.get("asset"), row.get("direction"),
                f"{row.get('asset')} descartado antes da Lumi.",
                str(pf.get("reason") or "negociabilidade não confirmada"),
                "promover próximo candidato", 0, steps_pf,
            )
            log(f"🛡 Preflight descartou {row.get('asset')} antes da Lumi: {str(pf.get('reason') or '')[:160]}", "warn")
            continue
        if pf.get("verified"):
            scan_stats["preflight_verified"] += 1
        row["decision_steps"] = list(row.get("decision_steps") or []) + [make_step("Preflight negociabilidade", True, str(pf.get("reason") or "aprovado"))]
        preflight_viable.append(row)
    viable = preflight_viable
    scan_stats["strong_signals"] = len(viable)

    # Circuit breaker da Lumi: quando o modelo local está lento, não desperdiça MTF/IA
    # em 50–54%, pois essa faixa não pode usar fallback. Sinais >= corte técnico
    # continuam no pipeline e, se necessário, seguem direto para fallback técnico.
    health_before_precision = lumi_health_snapshot()
    if health_before_precision.get("degraded"):
        scan_stats["lumi_health_degraded"] = 1
        healthy_viable: List[Dict[str, Any]] = []
        for row in viable:
            tech_now = int(row.get("technical_confidence", 0) or 0)
            if tech_now < int(min_tech):
                scan_stats["lumi_health_borderline_skipped"] = int(scan_stats.get("lumi_health_borderline_skipped", 0) or 0) + 1
                row["precision_deferred"] = True
                set_row_status(
                    row,
                    f"Lumi degradada ({health_before_precision.get('remaining',0)}s); faixa {tech_now}% < {min_tech}% exige resposta real da IA",
                    list(row.get("decision_steps") or []) + [make_step("Lumi Health", False, "circuit breaker ativo; setup limítrofe não usa fallback")],
                    "aguardar Lumi recuperar ou sinal técnico >= corte",
                    int(health_before_precision.get("remaining", 0) or 0),
                )
                continue
            healthy_viable.append(row)
        viable = healthy_viable
        scan_stats["strong_signals"] = len(viable)

    mtf_perf_started = time.perf_counter()
    # Precision Engine: MTF completo somente nos TOP 3 rápidos.
    # Isso concentra as chamadas extras onde elas podem alterar a decisão e mantém
    # o Qwen com contexto compacto. Depois o ranking usa Signal + Entry Score.
    if bool(cfg_get("precision_engine_enabled", True)) and viable:
        feature_budget = max(1, min(6, int(cfg_get("precision_feature_top", 5) or 5), len(viable)))
        base_sorted = sorted(
            viable,
            key=lambda r: (
                1 if int(r.get("technical_confidence", 0) or 0) >= int(min_tech) else 0,
                int(r.get("deep_rank_score", 0) or 0),
                int(r.get("technical_confidence", 0) or 0),
                int(r.get("adaptive_score", 0) or 0),
                int(r.get("payout", 0) or 0),
            ),
            reverse=True,
        )
        shortlist_source = base_sorted[:feature_budget]
        precision_ok: List[Dict[str, Any]] = []
        for row in shortlist_source:
            try:
                enrich_row_precision(api, row)
                row["deep_rank_score"] = _deep_market_opportunity_score(row)
                smart_prefilter_record_row(row, tf, count_weak=False)
                scan_stats["precision_enriched"] = int(scan_stats.get("precision_enriched", 0) or 0) + 1
                refined_risk = wallstreet_row_risk_gate(row)
                if refined_risk.get("penalty"):
                    # Recalcula o score com a penalidade de risco refinada após MTF.
                    row["adaptive"] = compute_adaptive_signal_score(row)
                    row["adaptive_score"] = int((row.get("adaptive") or {}).get("score", row.get("adaptive_score", 0)) or 0)
                    row["decision_steps"] = list(row.get("decision_steps") or []) + [
                        make_step("Wall Street EV pós-MTF", True, str(refined_risk.get("reason") or "cautela"))
                    ]
                if refined_risk.get("block"):
                    scan_stats["wallstreet_ev_rejected"] = int(scan_stats.get("wallstreet_ev_rejected", 0) or 0) + 1
                    row["precision_filter_reason"] = str(refined_risk.get("reason") or "EV histórico negativo")
                    row["decision_steps"] = list(row.get("decision_steps") or []) + [
                        make_step("Wall Street EV pós-MTF", False, row["precision_filter_reason"])
                    ]
                    set_row_status(row, f"Wall Street EV bloqueou após MTF: {row['precision_filter_reason']}", row.get("decision_steps"), "aguardar setup com edge melhor")
                    continue
                exhaustion = wallstreet_exhaustion_guard(row)
                if exhaustion.get("extreme"):
                    row["decision_steps"] = list(row.get("decision_steps") or []) + [make_step("Anti-Chase Bollinger", not exhaustion.get("block"), str(exhaustion.get("reason") or ""))]
                if exhaustion.get("block"):
                    scan_stats["exhaustion_rejected"] = int(scan_stats.get("exhaustion_rejected", 0) or 0) + 1
                    set_row_status(row, str(exhaustion.get("reason") or "Anti-Chase bloqueou"), row.get("decision_steps"), "aguardar preço sair do extremo ou breakout confirmar")
                    continue
                ok_precision, reason_precision = precision_early_filter(row, min_tech)
                row["precision_filter_reason"] = reason_precision
                row["decision_steps"] = list(row.get("decision_steps") or []) + [
                    make_step("Precision MTF", ok_precision, reason_precision)
                ]
                if not ok_precision:
                    scan_stats["precision_early_filtered"] = int(scan_stats.get("precision_early_filtered", 0) or 0) + 1
                    set_row_status(
                        row,
                        f"Precision Engine bloqueou: {reason_precision}",
                        row.get("decision_steps"),
                        "aguardar alinhamento/entrada melhor",
                    )
                    continue
                precision_ok.append(row)
            except Exception as exc:
                # Falha de feature não derruba um sinal bom: segue com score técnico original.
                row["precision_status"] = "error"
                row["precision_filter_reason"] = f"features indisponíveis: {str(exc)[:80]}"
                row["signal_score"] = int(row.get("technical_confidence", 0) or 0)
                row["entry_score"] = int(row.get("technical_confidence", 0) or 0)
                row["decision_priority_score"] = int(row.get("adaptive_score", row.get("technical_confidence", 0)) or 0)
                precision_ok.append(row)
        # Apenas candidatos enriquecidos entram na fila da Lumi nesta rodada.
        # Os demais continuam registrados no Laboratório e podem subir em nova rodada.
        for row in base_sorted[feature_budget:]:
            row["precision_deferred"] = True
            if not row.get("decision_status") or row.get("decision_status") == "avaliado":
                set_row_status(row, "fora da shortlist inteligente desta rodada", row.get("decision_steps"), "aguardar próxima rodada")
        viable = sorted(
            precision_ok,
            key=lambda r: (
                1 if int(r.get("technical_confidence", 0) or 0) >= int(min_tech) else 0,
                int(r.get("deep_rank_score", 0) or 0),
                int(r.get("decision_priority_score", 0) or 0),
                int(r.get("entry_score", 0) or 0),
                int(r.get("signal_score", 0) or 0),
                int(r.get("technical_confidence", 0) or 0),
                int(r.get("payout", 0) or 0),
            ),
            reverse=True,
        )
        smart_top = max(1, min(2, int(cfg_get("precision_lumi_smart_top", 2) or 2)))
        scan_stats["precision_lumi_shortlist"] = min(len(viable), smart_top)
        with LUMI_CACHE_LOCK:
            cache_hits_total = int(ANALYSIS_CACHE_STATS.get("candle_hits", 0)) + int(ANALYSIS_CACHE_STATS.get("feature_hits", 0))
            cache_misses_total = int(ANALYSIS_CACHE_STATS.get("candle_misses", 0)) + int(ANALYSIS_CACHE_STATS.get("feature_misses", 0))
        cache_hits = max(0, cache_hits_total - _cache_hits_before)
        cache_misses = max(0, cache_misses_total - _cache_misses_before)
        scan_stats["precision_cache_hits"] = cache_hits
        scan_stats["precision_cache_misses"] = cache_misses
        scan_stats["strong_signals"] = len(viable)
        if scan_stats["precision_enriched"]:
            log(
                f"🧠 Precision Engine: MTF={scan_stats['precision_enriched']} · early-filter={scan_stats['precision_early_filtered']} · "
                f"shortlist Lumi={scan_stats['precision_lumi_shortlist']} · cache hits/misses={cache_hits}/{cache_misses}.",
                "info",
            )

    mtf_ms = int((time.perf_counter() - mtf_perf_started) * 1000)
    scan_stats["mtf_ms"] = mtf_ms

    min_lumi_conf = min_lumi_scan
    best = None
    if not cfg_get("lumi_enabled"):
        lumi_limit = technical_top
    elif lumi_top_mode == "adaptive":
        # V87: a Lumi Agente decide quantos dos melhores candidatos (1–3) quer analisar.
        max_adaptive = int(cfg_get("adaptive_lumi_max", 3) or 3)
        lumi_limit = max(1, min(max_adaptive, lumi_top, technical_top))
    elif lumi_top_mode == "dynamic":
        # Oportunidade forte: permite TOP 2 na mesma rodada, mas para no primeiro aprovado.
        lumi_limit = max(1, min(2, lumi_top if lumi_top > 1 else 2, technical_top))
    else:
        # Normal e Ultra econômico: TOP 1.
        lumi_limit = 1

    # Rotação contínua da MESMA rodada. O TOP define o tamanho do lote prioritário,
    # não o total máximo da rodada. Se um lote inteiro der HOLD/divergência/baixa confiança,
    # o scanner promove automaticamente o lote seguinte até achar uma entrada ou esgotar
    # o orçamento seguro de análises da Lumi.
    rotation_enabled = bool(cfg_get("scanner_lumi_rotation_enabled", True))
    rotation_max = max(1, min(12, int(cfg_get("scanner_lumi_rotation_max", 8) or 8)))
    batch_size = max(1, int(lumi_limit or 1))
    smart_lumi_cap = max(1, min(2, int(cfg_get("precision_lumi_smart_top", 2) or 2))) if bool(cfg_get("precision_engine_enabled", True)) else rotation_max
    if rotation_enabled:
        rotation_budget = min(len(viable), rotation_max, smart_lumi_cap)
    else:
        rotation_budget = min(len(viable), batch_size, smart_lumi_cap)
    scan_stats["rotation_budget"] = int(rotation_budget)
    scan_stats["rotation_batch_size"] = int(batch_size)

    # Ativos que receberam HOLD/divergência são pulados ANTES de consumir chamada da Lumi.
    chosen_for_lumi: List[Dict[str, Any]] = []
    for pos, row in enumerate(viable, start=1):
        row["lumi_rank_position"] = pos
        blocked_for = is_lumi_hold_blocked(row["asset"], tf) if cfg_get("lumi_enabled") else 0
        if blocked_for > 0:
            row["hold_active"] = True
            scan_stats["hold_blocked"] += 1
            until_hms = lumi_hold_block_until_hms(row["asset"], tf)
            steps_block = row.get("decision_steps", []) + [
                make_step("Bloqueio após HOLD", False, f"até {until_hms or '?'} · restam {blocked_for}s"),
                make_step("Rotação contínua", True, "ativo removido da fila desta rodada; próximo candidato promovido imediatamente"),
            ]
            set_row_status(
                row,
                f"HOLD ativo até {until_hms or '?'} ({blocked_for}s) · ignorado nesta rodada",
                steps_block,
                "seguir imediatamente para o próximo candidato",
                blocked_for,
            )
            continue
        if len(chosen_for_lumi) < rotation_budget:
            slot = len(chosen_for_lumi) + 1
            row["lumi_rotation_slot"] = slot
            row["lumi_rotation_batch"] = ((slot - 1) // batch_size) + 1
            chosen_for_lumi.append(row)

    # Candidatos fortes fora do orçamento ficam explícitos, sem fingir que a fila acabou no TOP inicial.
    chosen_ids = {id(r) for r in chosen_for_lumi}
    for pos, row in enumerate(viable, start=1):
        if id(row) in chosen_ids or row.get("hold_active") or row.get("approved"):
            continue
        set_row_status(
            row,
            f"fila forte excedeu limite da rotação: ranking #{pos} · orçamento {rotation_budget}",
            row.get("decision_steps", []) + [make_step("Rotação Lumi", False, f"ranking #{pos}; orçamento desta rodada {rotation_budget}")],
            "aguardar próxima rodada; orçamento de IA esgotado",
            max(0, int(cfg_get("lumi_min_interval_seconds", 45) or 45)),
        )

    round_budget_s = min(max(20.0, float(cfg_get("scanner_round_budget_seconds", 42) or 42)), hard_deadline_s)
    for lumi_index, row in enumerate(chosen_for_lumi, start=1):
        _scan_progress("lumi", asset=str(row.get("asset") or ""), current=lumi_index, total=len(chosen_for_lumi))
        if _scan_deadline_exceeded():
            scan_stats["hard_deadline_exhausted"] = 1
            set_row_status(row, f"deadline rígido da rodada {hard_deadline_s:.0f}s atingido", row.get("decision_steps", []) + [make_step("Deadline da rodada", False, f"máximo {hard_deadline_s:.0f}s")], "aguardar próxima rodada")
            log(f"⏱ FULL SCAN DEADLINE V108.8.0 | fase=Lumi · {time.perf_counter()-round_perf_started:.1f}s/{hard_deadline_s:.0f}s · IA restante adiada para próxima rodada.", "warn")
            break
        if _market_mode_generation_changed(round_mode_generation):
            log("🔄 MARKET MODE V108.8.0: fila Lumi antiga cancelada imediatamente após troca de modo.", "info")
            return None, []
        if not _asset_allowed_for_market_mode(row.get("asset"), market_mode):
            continue
        if (time.perf_counter() - round_perf_started) >= round_budget_s:
            scan_stats["scanner_budget_exhausted"] = 1
            set_row_status(row, f"orçamento máximo da rodada {round_budget_s:.0f}s atingido", row.get("decision_steps", []) + [make_step("Budget da rodada", False, f"máximo {round_budget_s:.0f}s")], "aguardar próxima rodada")
            break
        rank_pos = int(row.get("lumi_rank_position", 1) or 1)
        rotation_slot = int(row.get("lumi_rotation_slot", 1) or 1)
        rotation_batch = int(row.get("lumi_rotation_batch", 1) or 1)
        ranking_msg = (
            "selecionado como melhor candidato da rodada"
            if rotation_slot == 1
            else f"rotação contínua · lote {rotation_batch} · candidato {rotation_slot}/{max(1, int(scan_stats.get('rotation_budget', 1) or 1))} · ranking #{rank_pos}"
        )
        steps = row.get("decision_steps", []) + [make_step("Ranking Lumi", True, ranking_msg)]
        if rotation_slot > 1:
            log(
                f"🔄 Rotação Lumi: promovendo {row['asset']} {str(row.get('direction') or 'hold').upper()} · "
                f"candidato {rotation_slot}/{max(1, int(scan_stats.get('rotation_budget', 1) or 1))} · lote {rotation_batch}.",
                "info",
            )
        update_decision_diagnostic(
            phase="lumi",
            asset=row["asset"],
            direction=row.get("direction"),
            status="Candidato forte selecionado; consultando Lumi.",
            details=f"Técnica {row.get('technical_confidence', 0)}% · Signal {row.get('signal_score', row.get('technical_confidence',0))}% · Entry {row.get('entry_score', row.get('technical_confidence',0))}% · payout {row.get('payout') or '—'}% · direção {str(row.get('direction')).upper()}.",
            next_action="aguardar confirmação da IA",
            steps=steps,
        )

        if cfg_get("lumi_enabled"):
            blocked_for = is_lumi_hold_blocked(row["asset"], tf)
            if blocked_for > 0:
                row["hold_active"] = True
                until_hms = lumi_hold_block_until_hms(row["asset"], tf)
                steps2 = steps + [make_step("Bloqueio após HOLD", False, f"até {until_hms or '?'} · restam {blocked_for}s")]
                set_row_status(row, f"ativo bloqueado após HOLD até {until_hms or '?'} ({blocked_for}s)", steps2, "testar próximo candidato ou aguardar fim do bloqueio", blocked_for)
                update_decision_diagnostic("bloqueado", row["asset"], row.get("direction"), row["block_reason"], "A IA pediu HOLD recentemente neste ativo; o bot evita repetir análise/entrada nele e faz rotação para outros candidatos.", "testar próximo candidato", blocked_for, steps2)
                continue

            health_now_pre = lumi_health_snapshot()
            if health_now_pre.get("degraded"):
                update_entry_progress(
                    asset=row["asset"], direction=row.get("direction"), technical=int(row.get("technical_confidence", 0) or 0),
                    payout=int(row.get("payout", 0) or 0), min_tech=min_tech, min_payout=min_payout, min_lumi=min_lumi_conf,
                    stage="lumi_health", status=f"Lumi degradada · fallback imediato em {row['asset']}", blocker="circuit breaker ativo",
                )
            else:
                scan_stats["sent_lumi"] += 1
                update_entry_progress(
                    asset=row["asset"], direction=row.get("direction"), technical=int(row.get("technical_confidence", 0) or 0),
                    payout=int(row.get("payout", 0) or 0), min_tech=min_tech, min_payout=min_payout, min_lumi=min_lumi_conf,
                    stage="lumi", status=f"Lumi Agente analisando {row['asset']} · tendência, momentum, volatilidade, regime e risco", blocker="Lumi processando",
                )
            lumi_context = dict(
                row["signals"], direction=row.get("direction"), payout=int(row.get("payout", 0) or 0),
                technical_required=int(min_tech), lumi_required=int(min_lumi_conf), payout_required=int(min_payout),
                regime=row.get("regime", "indefinido"), regime_label=row.get("regime_label", "Indefinido"),
                regime_confidence=int((row.get("regime_info") or {}).get("confidence", 0) or 0),
                adaptive_score=int(row.get("adaptive_score", row.get("technical_confidence", 0)) or 0),
                ranking_position=int(row.get("lumi_rank_position", 0) or 0),
                signal_score=int(row.get("signal_score", row.get("technical_confidence", 0)) or 0),
                entry_score=int(row.get("entry_score", row.get("technical_confidence", 0)) or 0),
                mtf_alignment=float(row.get("mtf_alignment", 50) or 50),
                mtf_compact=row.get("precision_summary") or {},
                calibration=row.get("calibration") or adaptive_calibration_for_row(row),
                calibration_compact=adaptive_calibration_compact(row.get("calibration") or adaptive_calibration_for_row(row)),
                candle_intelligence=dict(row.get("candle_intelligence") or {}),
                candle_score=int(row.get("candle_score", (row.get("candle_intelligence") or {}).get("score", 50)) or 50),
                price_action_score=int((row.get("candle_intelligence") or {}).get("price_action_score", 50) or 50),
                false_breakout_risk=int((row.get("candle_intelligence") or {}).get("false_breakout_risk", 0) or 0),
                barrier_distance_atr=float((row.get("candle_intelligence") or {}).get("barrier_distance_atr", 0) or 0),
                breakout_confirmed=bool((row.get("candle_intelligence") or {}).get("breakout_confirmed", False)),
                candle_structure=str((row.get("candle_intelligence") or {}).get("structure") or "indefinido"),
                price_action_pattern=str((row.get("candle_intelligence") or {}).get("price_action") or "indefinido"),
            )
            # Publica em Sinais o pacote exato antes da chamada da IA.
            row["technical_required"] = int(min_tech)
            row["lumi_required"] = int(min_lumi_conf)
            row["payout_required"] = int(min_payout)
            update_signal_panel_from_row(row, f"🧠 Lumi analisando {row['asset']} com Candle Intelligence V108")
            health_now = health_now_pre
            lumi_timed_out_this_call = False
            tech_now = int(row.get("technical_confidence", 0) or 0)
            entry_now = int(row.get("entry_score", tech_now) or tech_now)
            mtf_now = float(row.get("mtf_alignment", 50) or 50)
            if health_now.get("degraded"):
                # Não espera mais 10–12s quando a Lumi já provou estar lenta. >=55%
                # segue para o bloco de fallback existente; 50–54% foi removido antes do MTF.
                strong_direct = tech_now >= 65 and entry_now >= 70 and mtf_now >= 60
                reason_health = (
                    f"Lumi Health degradada por mais {health_now.get('remaining',0)}s; "
                    + (f"setup forte {tech_now}% / Entry {entry_now}% / MTF {mtf_now:.0f}% segue direto para fallback técnico" if strong_direct else "sinal >= corte segue para fallback técnico sem esperar IA")
                )
                lumi = {
                    "ok": False, "action": "hold", "confidence": 0,
                    "reason": reason_health, "error": reason_health,
                    "source": "lumi_health_bypass", "quota_status": "health_degraded", "raw": None,
                }
                scan_stats["lumi_health_bypass"] = int(scan_stats.get("lumi_health_bypass", 0) or 0) + 1
            else:
                lumi_perf_started = time.perf_counter()
                lumi = call_lumi(row["asset"], tf, row["closed"], lumi_context, rotation_bypass=rotation_enabled)
                lumi_elapsed = int((time.perf_counter() - lumi_perf_started) * 1000)
                lumi_ms += lumi_elapsed
                _lumi_timeout_text = " ".join([str(lumi.get("quota_status") or ""), str(lumi.get("error") or ""), str(lumi.get("reason") or "")]).lower()
                lumi_timed_out_this_call = (not bool(lumi.get("ok"))) and ("timeout" in _lumi_timeout_text or "timed out" in _lumi_timeout_text or "excedeu o orçamento" in _lumi_timeout_text)
                health_after = record_lumi_health_result(lumi, lumi_elapsed)
                if health_after.get("degraded"):
                    scan_stats["lumi_health_degraded"] = 1
            row["lumi"] = lumi
            update_signal_panel_from_row(row, f"Lumi {str(lumi.get('action','hold')).upper()} {int(lumi.get('confidence',0) or 0)}% · {row['asset']}")
            scan_stats["rotation_evaluated"] = int(scan_stats.get("rotation_evaluated", 0) or 0) + 1
            update_entry_progress(
                asset=row["asset"], direction=row.get("direction"), technical=int(row.get("technical_confidence", 0) or 0),
                payout=int(row.get("payout", 0) or 0), lumi=lumi, min_tech=min_tech, min_payout=min_payout, min_lumi=min_lumi_conf,
                stage="lumi", status=f"Lumi {str(lumi.get('action','hold')).upper()} {int(lumi.get('confidence',0) or 0)}% · {row['asset']}",
                blocker=str(lumi.get("reason") or lumi.get("error") or ""),
            )
            row["professional_score"] = compute_professional_score(row, lumi)
            update_professional_score(row, lumi)
            compute_opportunity_quality(row, lumi)
            # V108.8.0: compara o histórico direcional da Lumi com o DEEP técnico desta rodada.
            # Pode reduzir confiança ou converter a direção dominante suspeita em HARD VETO.
            lumi = apply_lumi_direction_bias_guard(lumi, row, rows, min_tech)
            row["lumi"] = lumi
            row["professional_score"] = compute_professional_score(row, lumi)
            update_professional_score(row, lumi)
            compute_opportunity_quality(row, lumi)
            if not lumi.get("ok"):
                rest = int(
                    lumi.get("cooldown_remaining")
                    or lumi_asset_cooldown_remaining(row["asset"])
                    or max(0, float(cfg_get("lumi_cooldown_until", 0)) - time.time())
                    or 0
                )
                erro_lumi = str(lumi.get("error") or lumi.get("reason") or "sem detalhe")[:140]
                # Agente full: SEMPRE tenta fallback técnico quando a Lumi falha (não só cota/timeout).
                # Passa o corte REAL usado nesta rodada para não existir um segundo mínimo oculto.
                row["technical_required"] = int(min_tech)
                fb_ok, fb_reason, fb_steps = technical_fallback_decision(row, min_payout)
                row["fallback_evaluated"] = True
                row["fallback_reason"] = fb_reason
                row["fallback_steps"] = fb_steps
                if fb_ok:
                    fallback_lumi = {
                        "ok": True,
                        "action": row.get("direction"),
                        "confidence": int(row.get("technical_confidence", 0) or 0),
                        "market_condition": "fallback técnico REAL" if cfg_get("account_type") == "REAL" else "fallback técnico DEMO",
                        "reason": fb_reason,
                        "source": "technical_fallback",
                        "error": erro_lumi,
                        "raw": None,
                    }
                    row["lumi"] = fallback_lumi
                    row["professional_score"] = compute_professional_score(row, fallback_lumi)
                    update_professional_score(row, fallback_lumi)
                    scan_stats["technical_fallback"] = int(scan_stats.get("technical_fallback", 0) or 0) + 1
                    row["approved"] = True
                    scan_stats["approved"] += 1
                    steps2 = steps + [make_step("Lumi IA", False, f"indisponível: {erro_lumi}"), *fb_steps]
                    set_row_status(row, ("aprovada por fallback técnico REAL" if cfg_get("account_type") == "REAL" else "aprovada por fallback técnico DEMO"), steps2, "verificar janela da vela e risco")
                    best = row
                    progress_payload = update_entry_progress(
                        asset=row["asset"], direction=row.get("direction"), technical=int(row.get("technical_confidence", 0) or 0),
                        payout=int(row.get("payout", 0) or 0), lumi=fallback_lumi, min_tech=min_tech, min_payout=min_payout, min_lumi=min_lumi_conf,
                        stage="travas finais", status="Fallback técnico aprovado · verificando janela da vela, cooldown e risco", blocker="travas finais pendentes",
                    )
                    if progress_payload.get("percent", 0) >= 100:
                        with state_lock:
                            state["entry_progress"]["percent"] = 99
                    update_decision_diagnostic(
                        "fallback_tecnico", row["asset"], row.get("direction"),
                        (f"{lumi_unavailable_label(lumi)}; fallback técnico REAL aprovado." if cfg_get("account_type") == "REAL" else f"{lumi_unavailable_label(lumi)}; fallback técnico DEMO aprovado."),
                        "Lumi offline/timeout. Agente full operou por técnica + payout com filtros anti-extremo.",
                        "verificar travas finais", 0, steps2
                    )
                    log(f"⚡ Fallback técnico APROVOU {row['asset']} {str(row.get('direction','')).upper()} · tech {row.get('technical_confidence')}% · payout {row.get('payout')}% (Lumi: {erro_lumi[:80]})", "info")
                    break
                steps2 = steps + [make_step("Lumi IA", False, erro_lumi), *fb_steps]
                next_fb = f"próximo candidato; {fb_reason}"
                set_row_status(row, f"{lumi_unavailable_label(lumi)}; {fb_reason}", steps2, next_fb, rest)
                update_decision_diagnostic("lumi_falhou", row["asset"], row.get("direction"), row["block_reason"], fb_reason, next_fb, rest, steps2)
                log(
                    f"🛑 Fallback técnico RECUSOU {row['asset']} {str(row.get('direction','')).upper()} · "
                    f"tech {int(row.get('technical_confidence',0) or 0)}% · payout {int(row.get('payout',0) or 0)}% · motivo: {fb_reason}",
                    "warn",
                )
                if lumi_timed_out_this_call:
                    scan_stats["lumi_timeout_round_break"] = 1
                    log(
                        f"⏱ Lumi timeout em {row['asset']}: fila de IA encerrada nesta rodada para não consumir outro timeout. "
                        "Fallback/próxima rodada assumem o fluxo; o Health Engine mantém a memória do atraso.",
                        "warn",
                    )
                    break
                continue

            lumi_action = str(lumi.get("action", "hold")).lower()
            lumi_conf = int(lumi.get("confidence", 0) or 0)
            if lumi_action == "hold":
                # V108.8.0: HOLD de coerência/viés é veto terminal nesta oportunidade.
                # Não pode cair em fallback técnico, borderline, APO ou martingale.
                if _lumi_hard_veto(lumi):
                    veto_code = str(lumi.get("hard_veto_code") or "coerência")
                    veto_reason = str(lumi.get("reason") or "Lumi detectou inconsistência interna")[:320]
                    row["lumi_hard_veto"] = True
                    row["lumi_hard_veto_code"] = veto_code
                    row["approved"] = False
                    scan_stats["hold_blocked"] += 1
                    scan_stats["lumi_hard_veto"] = int(scan_stats.get("lumi_hard_veto", 0) or 0) + 1
                    row["hold_active"] = True
                    block_after_lumi_hold(row["asset"], tf, f"HARD VETO {veto_code}")
                    seconds = max(int(tf), 60) * max(int(effective_lumi_hold_candles()), 1)
                    until_hms = lumi_hold_block_until_hms(row["asset"], tf)
                    steps2 = steps + [
                        make_step("Lumi HARD VETO", False, f"{veto_code} · {veto_reason}"),
                        make_step("Fallback técnico", False, "proibido para HARD VETO"),
                        make_step("Bloqueio proporcional", True, f"até {until_hms or '?'}"),
                    ]
                    set_row_status(row, f"Lumi HARD VETO: {veto_code} · bloqueado até {until_hms or '?'}", steps2, "promover próximo candidato", seconds)
                    update_decision_diagnostic("lumi_hard_veto", row["asset"], row.get("direction"), row["block_reason"], veto_reason, "promover próximo candidato", 0, steps2)
                    log(
                        f"🛑 LUMI HARD VETO V108.8.0 | {row['asset']} {str(row.get('direction','')).upper()} · {veto_code} · "
                        "fallback/override bloqueados para esta oportunidade.",
                        "warn",
                    )
                    continue
                strong_tech = int(row.get("technical_confidence", 0) or 0) >= int(cfg_get("lumi_hold_override_min_tech", 72) or 72)
                hold_can_override = bool(cfg_get("lumi_hold_can_override_strong_tech", False))
                # FULL trader: HOLD é abstenção. Só vira bloqueio definitivo se a técnica não for forte
                # ou se o fallback técnico detectar payout insuficiente / extremo contra a direção.
                if strong_tech and not hold_can_override:
                    fb_ok, fb_reason, fb_steps = technical_fallback_decision(row, min_payout)
                    row["fallback_evaluated"] = True
                    row["fallback_reason"] = fb_reason
                    row["fallback_steps"] = fb_steps
                    if fb_ok:
                        fallback_lumi = {
                            "ok": True,
                            "action": row.get("direction"),
                            "confidence": int(row.get("technical_confidence", 0) or 0),
                            "market_condition": "fallback após HOLD da Lumi",
                            "reason": f"HOLD ignorado: técnica forte >= {int(cfg_get('lumi_hold_override_min_tech', 72) or 72)}%. {fb_reason}",
                            "source": "technical_fallback_after_lumi_hold",
                            "error": str(lumi.get("reason") or "HOLD"),
                            "raw": None,
                        }
                        row["lumi"] = fallback_lumi
                        row["professional_score"] = compute_professional_score(row, fallback_lumi)
                        update_professional_score(row, fallback_lumi)
                        scan_stats["technical_fallback"] = int(scan_stats.get("technical_fallback", 0) or 0) + 1
                        row["approved"] = True
                        scan_stats["approved"] += 1
                        steps2 = steps + [make_step("Lumi IA", False, f"HOLD · {lumi_conf}%"), make_step("Técnica forte", True, f"{row.get('technical_confidence', 0)}% >= {cfg_get('lumi_hold_override_min_tech', 72)}%"), *fb_steps]
                        set_row_status(row, "aprovada por técnica forte apesar do HOLD da Lumi", steps2, "verificar janela da vela e risco")
                        best = row
                        progress_payload = update_entry_progress(
                            asset=row["asset"], direction=row.get("direction"), technical=int(row.get("technical_confidence", 0) or 0),
                            payout=int(row.get("payout", 0) or 0), lumi=fallback_lumi, min_tech=min_tech, min_payout=min_payout, min_lumi=min_lumi_conf,
                            stage="travas finais", status="Técnica forte aprovou fallback após HOLD · verificando travas finais", blocker="travas finais pendentes",
                        )
                        if progress_payload.get("percent", 0) >= 100:
                            with state_lock:
                                state["entry_progress"]["percent"] = 99
                        update_decision_diagnostic("fallback_pos_hold", row["asset"], row.get("direction"), "Técnica forte manteve o sinal mesmo com HOLD da Lumi.", str(lumi.get("reason") or "A IA preferiu aguardar, mas a técnica passou nas travas."), "verificar travas finais", 0, steps2)
                        log(
                            f"⚡ HOLD da Lumi tratado como ABSTENÇÃO: {row['asset']} {str(row.get('direction','')).upper()} · "
                            f"técnica {int(row.get('technical_confidence',0) or 0)}% · payout {int(row.get('payout',0) or 0)}% · "
                            f"fallback técnico aprovado; seguindo para travas finais.",
                            "warn",
                        )
                        break

                scan_stats["hold_blocked"] += 1
                row["hold_active"] = True
                block_after_lumi_hold(row["asset"], tf, "HOLD")
                seconds = max(int(tf), 60) * max(int(effective_lumi_hold_candles()), 1)
                until_hms = lumi_hold_block_until_hms(row["asset"], tf)
                steps2 = steps + [
                    make_step("Lumi IA", False, f"HOLD · confiança {lumi_conf}%"),
                    make_step("Bloqueio proporcional", True, f"{effective_lumi_hold_candles()} vela(s) · até {until_hms or '?'}"),
                    make_step("Rotação contínua", True, "HOLD neste ativo; promovendo o próximo candidato agora, na mesma rodada"),
                ]
                set_row_status(row, f"Lumi pediu HOLD até {until_hms or '?'}", steps2, "testar próximo candidato agora", seconds)
                update_decision_diagnostic("hold", row["asset"], row.get("direction"), f"Lumi pediu HOLD até {until_hms or '?' }.", str(lumi.get("reason") or "A IA preferiu aguardar."), "promover próximo candidato nesta rodada", 0, steps2)
                continue

            if lumi_action != row.get("direction"):
                scan_stats["hold_blocked"] += 1
                row["hold_active"] = True
                block_after_lumi_hold(row["asset"], tf, f"divergiu ({lumi_action})")
                seconds = max(int(tf), 60) * max(int(effective_lumi_hold_candles()), 1)
                until_hms = lumi_hold_block_until_hms(row["asset"], tf)
                steps2 = steps + [
                    make_step("Lumi IA", False, f"divergiu: técnica {str(row.get('direction')).upper()} x Lumi {lumi_action.upper()}"),
                    make_step("Bloqueio proporcional", True, f"{effective_lumi_hold_candles()} vela(s) · até {until_hms or '?'}"),
                    make_step("Rotação contínua", True, "divergência neste ativo; promovendo o próximo candidato agora"),
                ]
                set_row_status(row, f"Lumi divergiu: {lumi_action} · bloqueado até {until_hms or '?'}", steps2, "testar próximo candidato agora", seconds)
                update_decision_diagnostic("divergencia", row["asset"], row.get("direction"), row["block_reason"], str(lumi.get("reason") or "Técnica e IA não concordaram."), "promover próximo candidato nesta rodada", 0, steps2)
                continue

            ali_post_block, ali_post_steps = apply_adaptive_loss_intelligence_to_row(row, int(min_tech), lumi, "post_lumi")
            if ali_post_steps:
                steps = steps + ali_post_steps
            context_floor_post = int(row.get("context_tech_floor", min_tech) or min_tech)
            if ali_post_block:
                reason_ctx = str((row.get("adaptive_loss_context") or {}).get("reason") or "quarentena/hard block contextual")
                steps2 = steps + [make_step("Edge REAL contextual", False, f"HARD BLOCK · técnica {int(row.get('technical_confidence',0) or 0)}% / contextual {context_floor_post}% · {reason_ctx}")]
                set_row_status(row, f"Adaptive Loss Intelligence: HARD BLOCK contextual · {reason_ctx}", steps2, "aguardar fim da quarentena/contexto recuperar edge")
                update_decision_diagnostic("adaptive_loss_context", row["asset"], row.get("direction"), row["block_reason"], reason_ctx, "promover próximo candidato", 0, steps2)
                continue
            soft_floor_post = int(row.get("context_soft_tech_floor", min_tech) or min_tech)
            if soft_floor_post > context_floor_post:
                steps = steps + [make_step("Edge REAL contextual", True, f"cautela não bloqueante · técnica {int(row.get('technical_confidence',0) or 0)}% · floor sugerido {soft_floor_post}% · ranking/Lumi calibrada absorvem o risco")]

            calibration_after_lumi = adaptive_calibration_for_row(row, lumi)
            row["calibration_lumi"] = calibration_after_lumi
            if isinstance(row.get("lumi"), dict):
                row["lumi"]["calibration"] = adaptive_calibration_compact(calibration_after_lumi)
            calibration_penalty = adaptive_calibration_lumi_penalty(calibration_after_lumi)
            persistent_calibrated_lumi = max(0, min(100, int(round(lumi_conf + float(calibration_after_lumi.get("adjustment", 0) or 0)))))
            ali_info_post = dict(row.get("adaptive_loss_context") or {})
            ali_calibrated_lumi = int(ali_info_post.get("lumi_effective_confidence", lumi_conf) or lumi_conf)
            # Em REAL, a confiança usada na decisão é a mais prudente entre a calibração
            # persistente e a calibração da faixa Lumi observada apenas em operações REAL.
            calibrated_lumi_conf = min(persistent_calibrated_lumi, ali_calibrated_lumi) if str(cfg_get("account_type", "PRACTICE")).upper() == "REAL" else persistent_calibrated_lumi
            if isinstance(row.get("lumi"), dict):
                row["lumi"]["raw_confidence"] = lumi_conf
                row["lumi"]["calibrated_confidence"] = calibrated_lumi_conf
                row["lumi"]["real_band_calibrated_confidence"] = ali_calibrated_lumi
            ali_lumi_extra = int(row.get("context_lumi_extra", 0) or 0)
            required_lumi_conf = int(min_lumi_conf) + int(math.ceil(calibration_penalty / 2.0)) + ali_lumi_extra
            if str(cfg_get("account_type", "PRACTICE")).upper() == "REAL" and int(row.get("payout", 0) or 0) <= 0 and real_allow_unknown_payout():
                _unknown_min_tech, unknown_min_lumi = real_unknown_payout_requirements()
                required_lumi_conf = max(required_lumi_conf, int(unknown_min_lumi))
            if calibration_penalty > 0 or ali_lumi_extra > 0 or calibrated_lumi_conf != lumi_conf:
                steps = steps + [make_step("Lumi calibrada REAL", True, f"raw {lumi_conf}% → efetiva {calibrated_lumi_conf}% · mínimo {required_lumi_conf}% · contexto +{ali_lumi_extra}pp")]
            compute_opportunity_quality(row, row.get("lumi") if isinstance(row.get("lumi"), dict) else None)
            # V109.2: hard EV é avaliado antes do Supervisor; jamais pode ser contornado.
            final_ev_gate = wallstreet_row_risk_gate(row, lumi)
            if final_ev_gate.get("block"):
                scan_stats["wallstreet_ev_rejected"] = int(scan_stats.get("wallstreet_ev_rejected", 0) or 0) + 1
                steps2 = steps + [make_step("Wall Street EV + Lumi", False, str(final_ev_gate.get("reason") or "edge histórico negativo"))]
                set_row_status(row, f"EV histórico bloqueou após confirmação Lumi: {final_ev_gate.get('reason')}", steps2, "aguardar padrão com expectativa melhor")
                update_decision_diagnostic("ev_negativo", row["asset"], row.get("direction"), row["block_reason"], str(final_ev_gate.get("reason") or "edge negativo"), "promover próximo candidato", 0, steps2)
                continue
            if final_ev_gate.get("penalty"):
                steps = steps + [make_step("Wall Street EV + Lumi", True, str(final_ev_gate.get("reason") or "cautela"))]
            supervisor = trader_supervisor_decision(row, int(min_tech), int(min_payout), int(required_lumi_conf), int(calibrated_lumi_conf))
            maybe_log_trader_supervisor_observatory(row, supervisor)
            steps = steps + [make_step("Trader Supervisor V109.2", supervisor.get("action") != "REJECT", str(supervisor.get("reason") or ""))]
            # V109.2 UI Truth Sync: publica a calibração e a decisão do Supervisor ANTES
            # de qualquer continue. Assim a interface nunca fica presa na Lumi raw.
            _sup_action = str(supervisor.get("action") or "REJECT").upper()
            _sup_blocker = "" if _sup_action == "TRADE" else f"Trader Supervisor {_sup_action}: {str(supervisor.get('reason') or '')[:120]}"
            update_entry_progress(
                asset=row["asset"], direction=row.get("direction"), technical=int(row.get("technical_confidence", 0) or 0),
                payout=int(row.get("payout", 0) or 0), lumi=row.get("lumi"), min_tech=min_tech, min_payout=min_payout, min_lumi=required_lumi_conf,
                stage="trader supervisor", status=f"Supervisor {_sup_action} · confiança Lumi REAL {calibrated_lumi_conf}%/{required_lumi_conf}%",
                blocker=_sup_blocker, supervisor=supervisor,
            )
            if calibrated_lumi_conf < required_lumi_conf:
                if supervisor.get("action") == "TRADE":
                    row["trader_supervisor_override_lumi"] = True
                    log(f"🧠 SUPERVISOR TRADE V109.2 | {row['asset']} {str(row.get('direction') or '').upper()} · Lumi raw {lumi_conf}% → efetiva {calibrated_lumi_conf}%/{required_lumi_conf}% compensada · {supervisor.get('reason')}", "warn")
                else:
                    label_extra = " · payout desconhecido" if int(row.get("payout", 0) or 0) <= 0 else ""
                    steps2 = steps + [make_step("Confiança Lumi calibrada", False, f"raw {lumi_conf}% · efetiva {calibrated_lumi_conf}% / mínimo {required_lumi_conf}%{label_extra}")]
                    set_row_status(row, f"confiança Lumi calibrada {calibrated_lumi_conf}% (raw {lumi_conf}%) · Supervisor {supervisor.get('action')}", steps2, "aguardar confirmação mais forte")
                    update_decision_diagnostic("lumi_fraca", row["asset"], row.get("direction"), row["block_reason"], str(supervisor.get("reason") or lumi.get("reason") or "A IA concordou, mas com confiança baixa."), "aguardar", 0, steps2)
                    continue
            steps = steps + [make_step("Lumi IA", True, f"confirmou {lumi_action.upper()} raw {lumi_conf}% → efetiva {calibrated_lumi_conf}%")]

        # Guardrail final V108.8.0: abaixo do corte normal, REAL só pode avançar por
        # Adaptive Premium Override (piso 60, gap <=4pp + confluência excepcional) ou
        # pela faixa legada quando aplicável. Timeout/fallback nunca promove borderline.
        if int(row.get("technical_confidence", 0) or 0) < int(min_tech):
            is_real_borderline = str(cfg_get("account_type", "PRACTICE")).upper() == "REAL"
            supervisor_now = row.get("trader_supervisor") if isinstance(row.get("trader_supervisor"), dict) else {}
            if supervisor_now.get("action") == "TRADE":
                row["trader_supervisor_override_tech"] = True
                row["lumi_promoted_borderline"] = True
                row["real_borderline_exception"] = bool(is_real_borderline)
                steps = steps + [make_step("Trader Supervisor técnico", True, f"gap técnico {int(min_tech)-int(row.get('technical_confidence',0) or 0)}pp compensado · score {float(supervisor_now.get('score',0) or 0):.1f}")]
                log(f"🧠 SUPERVISOR TECH OVERRIDE V109.2 | {row['asset']} {str(row.get('direction') or '').upper()} · técnica {int(row.get('technical_confidence',0) or 0)}%/{int(min_tech)}% · {supervisor_now.get('reason')}", "warn")
                promo_ok = True; promo_reason = "Trader Supervisor compensou pequeno gap técnico sem hard veto"; promo_steps = []
            else:
                promo_ok, promo_reason, promo_steps = lumi_borderline_promotion_decision(
                    row, row.get("lumi") if isinstance(row.get("lumi"), dict) else {},
                    int(min_tech), int(min_payout), int(min_lumi_conf),
                )
            if promo_ok:
                lumi_obj = row.get("lumi") if isinstance(row.get("lumi"), dict) else {}
                lumi_obj["borderline_promotion"] = True
                lumi_obj["borderline_real"] = bool(is_real_borderline)
                lumi_obj["borderline_technical_floor"] = int(technical_previous_level(min_tech, strategy) if is_real_borderline else cfg_get("lumi_borderline_tech_floor", 50) or 50)
                lumi_obj["borderline_required_lumi"] = max(
                    int(cfg_get("real_borderline_min_lumi_confidence", 85) or 85) if is_real_borderline else int(cfg_get("lumi_borderline_min_confidence", 72) or 72),
                    int(min_lumi_conf),
                )
                lumi_obj["borderline_original_tech"] = int(row.get("technical_confidence", 0) or 0)
                apo_meta = row.get("adaptive_premium_override") if isinstance(row.get("adaptive_premium_override"), dict) else {}
                if bool(apo_meta.get("approved")):
                    lumi_obj["adaptive_premium_override"] = True
                    lumi_obj["adaptive_premium_override_gap_pp"] = int(apo_meta.get("gap_pp", 0) or 0)
                    lumi_obj["adaptive_premium_override_reason"] = str(promo_reason)[:320]
                    lumi_obj["borderline_technical_floor"] = int(apo_meta.get("tech_floor", cfg_get("adaptive_premium_override_tech_floor", 60)) or 60)
                    lumi_obj["borderline_required_lumi"] = int(apo_meta.get("required_lumi", lumi_obj.get("borderline_required_lumi", min_lumi_conf)) or min_lumi_conf)
                    row["adaptive_premium_override_approved"] = True
                    scan_stats["adaptive_premium_override_approved"] = int(scan_stats.get("adaptive_premium_override_approved", 0) or 0) + 1
                row["lumi"] = lumi_obj
                row["lumi_promoted_borderline"] = True
                row["real_borderline_exception"] = bool(is_real_borderline)
                steps = steps + promo_steps + [make_step("Promoção borderline", True, promo_reason)]
                log(
                    f"⚡ {'ADAPTIVE PREMIUM OVERRIDE' if bool(lumi_obj.get('adaptive_premium_override')) else ('REAL BORDERLINE' if is_real_borderline else 'Lumi borderline')} aprovado: {row['asset']} {str(row.get('direction') or '').upper()} · "
                    f"técnica {int(row.get('technical_confidence',0) or 0)}%/{int(min_tech)}% · "
                    f"Lumi {int(lumi_obj.get('confidence',0) or 0)}% · payout {int(row.get('payout',0) or 0)}% · {promo_reason}",
                    "warn",
                )
                update_decision_diagnostic(
                    "adaptive_premium_override" if bool(lumi_obj.get("adaptive_premium_override")) else ("promocao_borderline_real" if is_real_borderline else "promocao_lumi"), row["asset"], row.get("direction"),
                    "Adaptive Premium Override aprovado por confluência excepcional." if bool(lumi_obj.get("adaptive_premium_override")) else ("Setup borderline excepcional aprovado." if is_real_borderline else "Setup limítrofe promovido pela Lumi."), promo_reason,
                    "verificar travas finais", 0, steps,
                )
            else:
                tech_now = int(row.get("technical_confidence", 0) or 0)
                steps2 = steps + promo_steps + [make_step("Técnica final", False, f"{tech_now}% / corte efetivo {int(min_tech)}%")]
                apo_failed = isinstance(row.get("adaptive_premium_override"), dict) and not bool((row.get("adaptive_premium_override") or {}).get("approved"))
                status_text = ("técnica abaixo do corte adaptativo REAL; Adaptive Premium Override recusado" if apo_failed else "técnica abaixo do corte adaptativo REAL; gate borderline recusou") if is_real_borderline else "técnica abaixo do mínimo e promoção Lumi não aprovada"
                set_row_status(row, status_text, steps2, "aguardar setup tecnicamente mais forte")
                update_decision_diagnostic("tecnica_real" if is_real_borderline else "preanalise_lumi", row["asset"], row.get("direction"), row["block_reason"], promo_reason, "promover próximo candidato", 0, steps2)
                continue
        if int(row.get("payout", 0) or 0) > 0 and int(row.get("payout", 0) or 0) < int(min_payout):
            steps2 = steps + [make_step("Payout final", False, f"{int(row.get('payout',0) or 0)}% / mínimo {int(min_payout)}%")]
            set_row_status(row, "Lumi aprovou, mas payout final ainda está abaixo do mínimo", steps2, "aguardar payout melhor")
            continue
        final_exhaustion = wallstreet_exhaustion_guard(row)
        if final_exhaustion.get("extreme"):
            steps = steps + [make_step("Anti-Chase final", not final_exhaustion.get("block"), str(final_exhaustion.get("reason") or ""))]
        if final_exhaustion.get("block"):
            scan_stats["exhaustion_rejected"] = int(scan_stats.get("exhaustion_rejected", 0) or 0) + 1
            set_row_status(row, str(final_exhaustion.get("reason") or "Anti-Chase bloqueou"), steps, "aguardar breakout confirmado ou preço sair do extremo")
            continue

        row["approved"] = True
        row["approved_ts"] = time.time()
        _set_execution_quote_priority(row["asset"])
        _approval_quote = _quote_cache_get(row["asset"], max_age=15.0)
        if _approval_quote:
            row["approved_price"] = float(_approval_quote.get("price", 0) or 0)
            row["approved_price_source"] = str(_approval_quote.get("source") or "quote_cache_m1")
        else:
            try:
                row["approved_price"] = float((row.get("closed") or [])[-1][1])
            except Exception:
                row["approved_price"] = 0.0
            row["approved_price_source"] = "analysis_closed_m5"
        row["approved_candle_ts"] = int(row.get("last_candle_ts", 0) or 0)
        scan_stats["approved"] += 1
        row["professional_score"] = compute_professional_score(row, row.get("lumi"))
        update_professional_score(row, row.get("lumi"))
        set_row_status(row, "aprovada: verificando travas finais para entrada imediata", steps, "verificar freshness, preflight, cooldown e risco")
        best = row
        progress_payload = update_entry_progress(
            asset=row["asset"], direction=row.get("direction"), technical=int(row.get("technical_confidence", 0) or 0),
            payout=int(row.get("payout", 0) or 0), lumi=row.get("lumi"), min_tech=min_tech, min_payout=min_payout, min_lumi=min_lumi_conf,
            stage="travas finais", status="Sinal aprovado · verificando entrada imediata, cooldown e risco", blocker="travas finais pendentes",
            supervisor=row.get("trader_supervisor") if isinstance(row.get("trader_supervisor"), dict) else None,
        )
        if progress_payload.get("percent", 0) >= 100:
            with state_lock:
                state["entry_progress"]["percent"] = 99
        update_decision_diagnostic(
            phase="aprovada",
            asset=row["asset"],
            direction=row.get("direction"),
            status="Oportunidade aprovada pela técnica e pela Lumi.",
            details="Ainda falta passar pelas travas finais: freshness do sinal, preflight, cooldown, limite de operações e gestão de risco.",
            next_action="verificar travas finais",
            steps=steps,
        )
        break

    if cfg_get("lumi_enabled") and rotation_enabled:
        evaluated = int(scan_stats.get("rotation_evaluated", 0) or 0)
        budget = int(scan_stats.get("rotation_budget", 0) or 0)
        if not best and evaluated > 0:
            scan_stats["rotation_exhausted"] = 1 if evaluated >= budget and budget > 0 else 0
            log(
                f"🔄 Rotação Lumi concluída: {evaluated}/{budget} candidato(s) analisado(s) nesta rodada · "
                f"HOLD/bloqueados={int(scan_stats.get('hold_blocked', 0) or 0)} · nenhuma entrada aprovada.",
                "info",
            )

    # Se nada foi aprovado, mostra o melhor NÃO-HOLD que quase passou.
    # Ativos já bloqueados pela Lumi não monopolizam mais o painel/log.
    if not best and rows:
        sorted_rows = sorted(rows, key=lambda x: (x.get("adaptive_score", 0), x.get("rank", 0), x.get("technical_confidence", 0), x.get("payout", 0)), reverse=True)
        top = sorted_rows[0]
        near_miss = choose_near_miss(rows, min_tech, min_payout, min_lumi_conf)
        if near_miss:
            save_near_miss(near_miss)
            update_entry_progress(
                asset=near_miss.get("asset", "-"), direction=near_miss.get("direction"),
                technical=int(near_miss.get("technical_confidence", 0) or 0), payout=int(near_miss.get("payout", 0) or 0),
                lumi={"ok": True, "action": near_miss.get("lumi_action", "hold"), "confidence": int(near_miss.get("lumi_confidence", 0) or 0)} if near_miss.get("lumi_evaluated") else None,
                min_tech=int(near_miss.get("technical_required", min_tech) or min_tech),
                min_payout=int(near_miss.get("payout_required", min_payout) or min_payout),
                min_lumi=int(near_miss.get("lumi_required", min_lumi_conf) or min_lumi_conf),
                stage="quase passou", status=near_miss.get("status") or "Melhor candidato da rodada", blocker=near_miss.get("blocked_by", "trava"),
            )
            log_near_miss_once(near_miss)
            wait_status = near_miss.get("status") or "Bot está aguardando: melhor candidato não passou nas travas."
            missing_txt = "; ".join(str(x) for x in (near_miss.get("missing") or [])[:4])
            wait_details = (
                f"Quase passou nesta rodada. Bloqueio principal: {near_miss.get('blocked_by', 'trava')}. "
                f"Faltou/impediu: {missing_txt}. "
                f"Avaliados {scan_stats.get('candles_loaded', 0)} ativo(s) com candles. {stall.get('status')}."
            )[:420]
            diag_steps = near_miss.get("steps") or top.get("decision_steps", [])
            diag_asset = near_miss.get("asset", top.get("asset", "-"))
            diag_direction = near_miss.get("direction", top.get("direction") or "hold")
            diag_next = near_miss.get("next_action", top.get("next_action", "aguardar próxima rodada"))
            diag_next_in = int(near_miss.get("next_in_seconds", top.get("next_in_seconds", 0)) or 0)
        else:
            non_hold_rows = [
                r for r in sorted_rows
                if not r.get("hold_active")
                and "hold ativo" not in str(r.get("block_reason", "")).lower()
                and "bloqueado após hold" not in str(r.get("block_reason", "")).lower()
                and "lumi pediu hold" not in str(r.get("block_reason", "")).lower()
            ]
            fallback_top = non_hold_rows[0] if non_hold_rows else top
            evaluated = int(scan_stats.get("rotation_evaluated", 0) or 0)
            budget = int(scan_stats.get("rotation_budget", 0) or 0)
            if scan_stats.get("strong_signals", 0) <= 0:
                wait_status = "Bot está aguardando porque nenhum sinal passou nas travas."
                wait_details = f"Foram avaliados {scan_stats.get('candles_loaded', 0)} ativo(s) com candles; nenhum atingiu técnica mínima/payout configurado. {stall.get('status')}."
            elif not non_hold_rows and evaluated > 0:
                wait_status = f"Rodada esgotada: {evaluated} candidato(s) fortes foram analisados e ficaram em HOLD/bloqueio."
                wait_details = f"A Lumi rotacionou a fila na mesma rodada até {evaluated}/{budget} análises. Os ativos em HOLD foram retirados temporariamente; o scanner voltará com uma nova fila na próxima rodada."
            else:
                wait_status = fallback_top.get("block_reason") or "Nenhuma oportunidade aprovada após rotação."
                wait_details = f"A rotação percorreu {evaluated}/{budget} candidato(s) da Lumi nesta rodada. {stall.get('status')}."
            diag_steps = fallback_top.get("decision_steps", [])
            diag_asset = fallback_top.get("asset", "-")
            diag_direction = fallback_top.get("direction") or "hold"
            diag_next = fallback_top.get("next_action", "aguardar próxima rodada")
            diag_next_in = int(fallback_top.get("next_in_seconds", 0) or 0)
        if not cfg_get("running") or cfg_get("decision_diagnostic", {}).get("phase") in {"scanner", "aguardando", "sem_ativos", "bloqueado", "lumi_falhou", "hold", "divergencia", "lumi_fraca"}:
            update_decision_diagnostic(
                phase="quase_passou",
                asset=diag_asset,
                direction=diag_direction,
                status=wait_status,
                details=wait_details,
                next_action=diag_next,
                next_in_seconds=diag_next_in,
                steps=diag_steps,
            )

    block_diag = build_block_diagnostics(rows, min_tech, min_payout, min_lumi_conf)
    scan_stats["block_diagnostics"] = block_diag
    log_block_diagnostics(block_diag)
    maybe_log_counterfactual_learning()
    if bool(cfg_get("opportunity_quality_log_enabled", True)) and rows:
        qrows = sorted([r for r in rows if isinstance(r, dict)], key=lambda r: int((r.get("opportunity_quality") or {}).get("score", r.get("opportunity_quality_score",0)) or 0), reverse=True)[:3]
        if qrows:
            log("💎 OPPORTUNITY QUALITY | " + " · ".join(f"{r.get('asset','-')} {str(r.get('direction') or 'HOLD').upper()} Q={int((r.get('opportunity_quality') or {}).get('score',r.get('opportunity_quality_score',0)) or 0)} T={int(r.get('technical_confidence',0) or 0)} P={int(r.get('payout',0) or 0)}" for r in qrows), "info")

    total_round_ms = int((time.perf_counter() - round_perf_started) * 1000)
    scan_stats["universe_ms"] = int(universe_ms)
    scan_stats["scanner_ms"] = int(scanner_ms)
    scan_stats["mtf_ms"] = int(mtf_ms)
    scan_stats["lumi_ms"] = int(lumi_ms)
    scan_stats["round_total_ms"] = total_round_ms
    scan_stats["scanner_api_ms"] = _api_timing_get("scanner")
    scan_stats["market_init_ms"] = _phase_timing_get("market_init_ms")
    scan_stats["candles_ms"] = _phase_timing_get("candles_ms")
    scan_stats["payout_ms"] = _phase_timing_get("payout_ms")
    scan_stats["payout_snapshot_ms"] = int(scan_stats.get("payout_snapshot_ms", 0) or 0)
    scan_stats["preflight_ms"] = _phase_timing_get("preflight_ms")
    # Métricas Shadow são assíncronas e pertencem ao job anterior; não entram no tempo desta rodada.
    shadow_metrics = _shadow_metrics_snapshot()
    scan_stats["shadow_api_ms"] = int(shadow_metrics.get("shadow_api_ms", 0) or 0)
    scan_stats["shadow_resolved"] = int(shadow_metrics.get("shadow_resolved", 0) or 0)
    scan_stats["shadow_deferred"] = int(shadow_metrics.get("shadow_deferred", 0) or 0)
    scan_stats["shadow_pending_due"] = int(shadow_metrics.get("shadow_pending_due", shadow_metrics.get("shadow_deferred", 0)) or 0)
    scan_stats["shadow_future_pending"] = int(shadow_metrics.get("shadow_future_pending", 0) or 0)
    scan_stats["shadow_next_due_in"] = int(shadow_metrics.get("shadow_next_due_in", 0) or 0)
    scan_stats["shadow_api_calls"] = int(shadow_metrics.get("shadow_api_calls", 0) or 0)
    health_final = lumi_health_snapshot()
    scan_stats["lumi_health_degraded"] = 1 if health_final.get("degraded") else int(scan_stats.get("lumi_health_degraded", 0) or 0)
    log(
        f"⏱ Rodada: universo={int(universe_ms)}ms · prefilter={int(scan_stats.get('smart_prefilter_ms',0) or 0)}ms · "
        f"técnico={int(scanner_ms)}ms ({int(scan_stats.get('candles_loaded',0) or 0)}/{int(scan_stats.get('smart_prefilter_selected',len(scan_assets)) or len(scan_assets))} ativos) · "
        f"MTF={int(mtf_ms)}ms · Lumi={int(lumi_ms)}ms · market_init={int(scan_stats.get('market_init_ms',0))}ms · "
        f"candles={int(scan_stats.get('candles_ms',0))}ms · payout_snapshot={int(scan_stats.get('payout_snapshot_ms',0))}ms "
        f"({int(scan_stats.get('payout_snapshot_assets',0))} ok/{int(scan_stats.get('payout_snapshot_missing',0))} sem payout) · preflight={int(scan_stats.get('preflight_ms',0))}ms · "
        f"scanner_api={int(scan_stats.get('scanner_api_ms',0))}ms · DATA_SLOW={int(scan_stats.get('data_slow',0))} · SOFT_SLOW={int(getattr(_API_TIMING_LOCAL,'candle_soft_slow_round',0) or 0)} · "
        f"Reservas={int(scan_stats.get('candle_reserve_filled',0) or 0)}/{int(scan_stats.get('candle_reserve_attempted',0) or 0)}/{int(scan_stats.get('candle_reserve_available',0) or 0)} (preenchidas/tentadas/disponíveis) · "
        f"FULL_FAST={int(scan_stats.get('full_market_fast_evaluated',0) or 0)}/{int(scan_stats.get('full_market_radar_seen',0) or 0)} · DEEP={int(scan_stats.get('deep_ranking_count',0) or 0)} · "
        f"CandleBudget={'LIMITE' if int(scan_stats.get('candle_budget_exhausted',0) or 0) else 'OK'}({int(scan_stats.get('candle_budget_saved_assets',0) or 0)} faltantes; timeouts={int(getattr(_API_TIMING_LOCAL,'candle_timeouts_round',0) or 0)}) · "
        f"EV_block={int(scan_stats.get('wallstreet_ev_rejected',0) or 0)} · WinMem={len((load_win_memory().get('patterns') or []))}p/{int(scan_stats.get('win_memory_matched',0) or 0)}m · "
        f"FastElite={str(scan_stats.get('fast_elite_asset') or '—')} · total={total_round_ms}ms · "
        f"saúde Lumi={'DEGRADADA '+str(health_final.get('remaining',0))+'s' if health_final.get('degraded') else 'OK'}.",
        "info",
    )
    if shadow_metrics.get("last_run_at") or int(shadow_metrics.get("shadow_pending_due", 0) or 0) or int(shadow_metrics.get("shadow_resolved", 0) or 0):
        shadow_err = str(shadow_metrics.get("last_error") or "")
        log(
            f"🧪 Shadow anterior: API={int(shadow_metrics.get('shadow_api_ms',0) or 0)}ms · "
            f"resolvidos={int(shadow_metrics.get('shadow_resolved',0) or 0)} · "
            f"pendentes vencidos={int(shadow_metrics.get('shadow_pending_due', shadow_metrics.get('shadow_deferred',0)) or 0)} · "
            f"futuros={int(shadow_metrics.get('shadow_future_pending',0) or 0)} · próximo={int(shadow_metrics.get('shadow_next_due_in',0) or 0)}s · "
            f"chamadas={int(shadow_metrics.get('shadow_api_calls',0) or 0)} · "
            f"última={shadow_metrics.get('last_run_at') or '—'}" + (f" · nota={shadow_err}" if shadow_err else ""),
            "info" if not shadow_err else "warn",
        )

    # Laboratório de Sinais: resolve no mesmo horizonte da expiração da operação (tf da rodada)
    # inclusive os que foram rejeitados por técnica, payout, Lumi, memória ou travas finais.
    _scan_progress("signal_lab_queue", current=len(rows), total=len(rows))
    _schedule_scan_signal_lab_update(api, rows, tf, strategy, min_tech, min_payout, min_lumi_conf)

    display_rows = []
    for r in sorted(rows, key=lambda x: (x.get("approved", False), x.get("adaptive_score", 0), x.get("rank", 0)), reverse=True)[:10]:
        display_rows.append({k: v for k, v in r.items() if k not in {"closed"}})

    with state_lock:
        state["opportunities"] = display_rows
        state["scanner_stats"] = scan_stats
        state["last_scan_at"] = now_hms()
        if elite_mode:
            state["last_elite_scan_at"] = now_hms()
            elite_state = dict(cfg_get("elite_watcher") or {})
            elite_state.update({"last_scan_at": now_hms(), "last_scanned": len(assets), "last_best": str((best or {}).get("asset") or ""), "last_approved": 1 if best else 0})
            state["elite_watcher"] = elite_state
            # next_scan_at continua apontando para a próxima varredura COMPLETA.
            state["next_scan_in_seconds"] = max(0, int(float(cfg_get("next_scan_at", 0) or 0) - time.time())) if float(cfg_get("next_scan_at", 0) or 0) > 0 else 0
        else:
            tf_int = int(tf or cfg_get("timeframe", 300) or 300)
            state["next_scan_at"] = (int(time.time()) // tf_int + 1) * tf_int + 1
            state["next_scan_in_seconds"] = max(0, int(state["next_scan_at"] - time.time()))
            state["last_full_scan_at"] = now_hms()
            elite_state = dict(cfg_get("elite_watcher") or {})
            elite_state.update({
                "enabled": bool(cfg_get("elite_opportunity_watcher_enabled", True)),
                "status": "FULL concluída · FAST BG monitorando até o próximo ciclo Elite",
                "selected": 0,
                "eligible": 0,
                "assets": [],
                "last_poll_ts": time.time(),
                "next_full_in": state["next_scan_in_seconds"],
                "updated_at": now_hms(),
            })
            state["elite_watcher"] = elite_state
        state["last_scan_error"] = ""
        state["anti_stall_status"] = stall.get("status", "")

    # V108.8.0: se a rodada terminou sem entrada aprovada, o painel de etapas
    # deve ficar neutro imediatamente. O near_miss e o diagnóstico continuam
    # preservados em cards próprios para consulta da rodada recém-concluída.
    if not best:
        reset_entry_progress_after_round("Rodada concluída · aguardando próxima análise.")

    _scan_progress("done", current=int(scan_stats.get("candles_loaded", 0) or 0), total=int(scan_stats.get("smart_prefilter_selected", len(scan_assets)) or len(scan_assets)), total_ms=total_round_ms)
    return best, display_rows


def scan_opportunities(api: Any, tf: int, elite_assets: Optional[List[str]] = None, scan_kind: str = "full") -> Tuple[Optional[Dict[str, Any]], List[Dict[str, Any]]]:
    """V108.8.0: scanner completo ou DEEP seletivo do Elite Watcher, com mesma configuração congelada/gates."""
    round_config = _capture_round_config()
    _activate_round_config(round_config)
    market_api = get_market_data_api(api)
    SCANNER_PRIORITY_ACTIVE.set()
    setattr(_API_TIMING_LOCAL, "role", "scanner")
    _api_timing_reset("scanner")
    _phase_timing_reset()
    setattr(_API_TIMING_LOCAL, "candle_timeouts_round", 0)
    setattr(_API_TIMING_LOCAL, "candle_soft_slow_round", 0)
    setattr(_API_TIMING_LOCAL, "market_data_reconnect_round", 0)
    try:
        return _scan_opportunities_impl(market_api, tf, elite_assets=elite_assets, scan_kind=scan_kind)
    finally:
        SCANNER_PRIORITY_ACTIVE.clear()
        setattr(_API_TIMING_LOCAL, "role", "idle")
        _deactivate_round_config()
        try: _kick_quote_cache_worker(market_api)
        except Exception: pass
        try: _kick_fast_market_intelligence_worker(market_api)
        except Exception: pass


# ── Segurança / risco ─────────────────────────────────────

def _extract_payout_value(value: Any) -> int:
    """Converte retornos da iqoptionapi em percentual inteiro de payout.

    Aceita formatos comuns: 0.82, 82, {value/profit/turbo/binary/digital/...},
    listas/tuplas e strings numéricas. Quando o valor representa comissão,
    use _extract_commission_payout_value().
    """
    try:
        if isinstance(value, dict):
            # Campos mais comuns da iqoptionapi para lucro/payout.
            for key in ("value", "profit", "payout", "turbo", "binary", "digital", "commission", "percent", "percentage"):
                if key in value:
                    payout = _extract_payout_value(value.get(key))
                    if payout:
                        return payout
            # Busca recursiva em estruturas mais profundas.
            for sub in value.values():
                payout = _extract_payout_value(sub)
                if payout:
                    return payout
            return 0
        if isinstance(value, (list, tuple)):
            for item in value:
                payout = _extract_payout_value(item)
                if payout:
                    return payout
            return 0
        if value is None or value is False:
            return 0
        if isinstance(value, str):
            value = value.strip().replace("%", "").replace(",", ".")
            if not value:
                return 0
        raw = float(value)
        if raw <= 0:
            return 0
        pct = raw * 100 if raw <= 1 else raw
        return max(0, min(100, int(round(pct))))
    except Exception:
        return 0


def _extract_commission_payout_value(value: Any) -> int:
    """Converte comissão da IQ Option em payout.

    Em commission_changed, comissão 20 significa payout 80%.
    """
    try:
        if isinstance(value, dict):
            for key in ("commission", "value", "profit"):
                if key in value:
                    payout = _extract_commission_payout_value(value.get(key))
                    if payout:
                        return payout
            for sub in value.values():
                payout = _extract_commission_payout_value(sub)
                if payout:
                    return payout
            return 0
        if isinstance(value, (list, tuple)):
            for item in value:
                payout = _extract_commission_payout_value(item)
                if payout:
                    return payout
            return 0
        if value is None or value is False:
            return 0
        if isinstance(value, str):
            value = value.strip().replace("%", "").replace(",", ".")
            if not value:
                return 0
        commission = float(value)
        if 0 < commission < 100:
            payout = int(round(100 - commission))
            return max(0, min(100, payout))
    except Exception:
        pass
    return 0


def _asset_lookup_variants(asset: str) -> List[str]:
    asset = normalize_asset_name(asset)
    base = asset.replace("-OTC", "")
    variants = [asset, base, asset.lower(), base.lower(), asset.upper(), base.upper()]
    return list(dict.fromkeys([v for v in variants if v]))


def _find_asset_payload(data: Any, asset: str) -> Any:
    """Procura payload de um ativo em dicionários com variações de nome."""
    if not isinstance(data, dict):
        return None
    variants = set(_asset_lookup_variants(asset))
    # match direto
    for key in variants:
        if key in data:
            return data[key]
    # match normalizado
    for key, value in data.items():
        try:
            if normalize_asset_name(str(key)) in variants or str(key).upper().replace("-OTC", "") in variants:
                return value
        except Exception:
            continue
    # alguns retornos vêm com nível: {turbo:{EURUSD:...}}
    for value in data.values():
        if isinstance(value, dict):
            found = _find_asset_payload(value, asset)
            if found is not None:
                return found
    return None


def _payout_from_all_profit_payload(all_profit: Any, asset: str) -> Dict[str, Any]:
    """Extrai somente em memória o payout de um snapshot get_all_profit()."""
    asset = normalize_asset_name(asset)
    info = _find_asset_payload(all_profit, asset) if isinstance(all_profit, dict) else None
    if isinstance(info, dict):
        # TURBO é a autoridade para expirações curtas usadas pelo bot.
        for kind in ("turbo", "binary", "digital"):
            payout = _extract_payout_value(info.get(kind))
            if payout:
                return {"payout": payout, "source": f"payout_snapshot:get_all_profit:{kind}", "detail": "snapshot único da rodada", "ts": time.time(), "time": now_hms()}
    payout = _extract_payout_value(info)
    if payout:
        return {"payout": payout, "source": "payout_snapshot:get_all_profit", "detail": "snapshot único da rodada", "ts": time.time(), "time": now_hms()}
    return {"payout": 0, "source": "payout_snapshot:missing", "detail": "ativo ausente/sem payout no snapshot", "ts": time.time(), "time": now_hms()}


def _payout_api_close_detached(old: Any, reason: str = "") -> None:
    if old is None or not hasattr(old, "close"):
        return
    key = id(old)
    with PAYOUT_DATA_CLOSE_LOCK:
        if key in PAYOUT_DATA_CLOSE_THREADS:
            return
        PAYOUT_DATA_CLOSE_THREADS[key] = time.time()
    def worker() -> None:
        try:
            _call_daemon_timeout(lambda: old.close(), 1.5)
        except Exception:
            pass
        finally:
            with PAYOUT_DATA_CLOSE_LOCK:
                PAYOUT_DATA_CLOSE_THREADS.pop(key, None)
    threading.Thread(target=worker, daemon=True, name=f"payout-close-{key:x}").start()


def _set_payout_health(status: str, reason: str, **extra: Any) -> Dict[str, Any]:
    with PAYOUT_DATA_HEALTH_LOCK:
        cur = dict(dict.get(state, "payout_health", {}) or {})
        cur.update({"status": str(status), "reason": str(reason)[:180], "updated_at": now_hms(), "updated_ts": time.time(), **extra})
        dict.__setitem__(state, "payout_health", cur)
        return dict(cur)


def _payout_api_invalidate(reason: str = "") -> None:
    old = None
    with PAYOUT_DATA_HEALTH_LOCK:
        old = dict.get(state, "payout_api")
        dict.__setitem__(state, "payout_api", None)
        dict.__setitem__(state, "payout_data_connected", False)
        dict.__setitem__(state, "payout_data_generation", int(dict.get(state, "payout_data_generation", 0) or 0) + 1)
    _set_payout_health("recovering", reason or "renovando sessão isolada de payout")
    _payout_api_close_detached(old, reason)


def _connect_payout_data_api_sync(force: bool = False) -> Any:
    global PAYOUT_DATA_LAST_RECONNECT_TS
    if not bool(cfg_get("payout_health_enabled", True)):
        return None
    if not PAYOUT_DATA_CONNECT_LOCK.acquire(blocking=False):
        return dict.get(state, "payout_api")
    try:
        existing = dict.get(state, "payout_api")
        if existing is not None and not force:
            return existing
        if existing is not None and force:
            _payout_api_invalidate("refresh solicitado")
        email = str(dict.get(state, "email", "") or "").strip()
        password = str(dict.get(state, "_runtime_password", "") or "")
        account_type = str(dict.get(state, "account_type", "PRACTICE") or "PRACTICE").upper()
        if not email or not password:
            return None
        try:
            _install_iqoption_login_recovery_patch()
            from iqoptionapi.stable_api import IQ_Option
            payout_api = IQ_Option(email, password)
            timeout = max(3.0, min(20.0, float(cfg_get("payout_session_connect_timeout_seconds", 8.0) or 8.0)))
            ok, payload, err = _call_daemon_timeout(lambda: payout_api.connect(), timeout)
            if not ok:
                raise RuntimeError(f"connect payout {err or 'falhou'}")
            if isinstance(payload, (tuple, list)):
                connected = bool(payload[0]) if payload else False
                reason = payload[1] if len(payload) > 1 else ""
            else:
                connected = bool(payload); reason = ""
            if not connected:
                raise RuntimeError(str(reason or "sessão payout recusada"))
            _call_daemon_timeout(lambda: payout_api.change_balance(account_type), 3.0)
            with PAYOUT_DATA_HEALTH_LOCK:
                dict.__setitem__(state, "payout_api", payout_api)
                dict.__setitem__(state, "payout_data_connected", True)
                dict.__setitem__(state, "payout_data_generation", int(dict.get(state, "payout_data_generation", 0) or 0) + 1)
            PAYOUT_DATA_LAST_RECONNECT_TS = time.time()
            _set_payout_health("warming", "sessão isolada conectada; aguardando snapshot fresco")
            log("💵 PAYOUT HEALTH V108.8.0 | sessão isolada conectada; candles/Trade permanecem independentes.", "info")
            return payout_api
        except Exception as exc:
            try:
                _payout_api_close_detached(locals().get("payout_api"), "connect failure")
            except Exception:
                pass
            _set_payout_health("degraded", f"falha ao conectar sessão payout: {str(exc)[:120]}")
            return None
    finally:
        PAYOUT_DATA_CONNECT_LOCK.release()


def _kick_payout_data_connect(force: bool = False) -> None:
    global PAYOUT_DATA_CONNECT_THREAD
    if not bool(cfg_get("payout_health_enabled", True)):
        return
    with PAYOUT_DATA_HEALTH_LOCK:
        if PAYOUT_DATA_CONNECT_THREAD is not None and PAYOUT_DATA_CONNECT_THREAD.is_alive():
            return
        PAYOUT_DATA_CONNECT_THREAD = threading.Thread(target=_connect_payout_data_api_sync, args=(force,), daemon=True, name="payout-data-connect-v108738")
        PAYOUT_DATA_CONNECT_THREAD.start()


def get_payout_data_api(fallback_api: Any) -> Any:
    payout_api = dict.get(state, "payout_api")
    if payout_api is not None:
        return payout_api
    _kick_payout_data_connect(False)
    return fallback_api


def _payout_health_record(fresh_resolved: int, total: int, api_success: bool, err: str = "") -> None:
    global PAYOUT_DATA_LAST_RECONNECT_TS
    if not bool(cfg_get("payout_health_enabled", True)) or total <= 0:
        return
    ratio = max(0.0, min(1.0, float(fresh_resolved) / max(1, int(total))))
    threshold = float(cfg_get("payout_health_min_fresh_coverage_ratio", 0.25) or 0.25)
    bad = (not api_success) or ratio < threshold
    cur = dict(dict.get(state, "payout_health", {}) or {})
    streak = int(cur.get("bad_streak", 0) or 0) + 1 if bad else 0
    if not bad:
        _set_payout_health("healthy", f"snapshot fresco {fresh_resolved}/{total}", fresh_coverage=round(ratio, 3), bad_streak=0)
        return
    status = "degraded" if streak >= int(cfg_get("payout_health_degraded_after_snapshots", 2) or 2) else "warming"
    _set_payout_health(status, f"snapshot fresco baixo {fresh_resolved}/{total}" + (f" · {err}" if err else ""), fresh_coverage=round(ratio, 3), bad_streak=streak)
    if status != "degraded":
        return
    cooldown = max(10, int(cfg_get("payout_health_reconnect_cooldown_seconds", 30) or 30))
    now_ts = time.time()
    if now_ts - float(PAYOUT_DATA_LAST_RECONNECT_TS or 0) < cooldown:
        return
    PAYOUT_DATA_LAST_RECONNECT_TS = now_ts
    log(f"💵 PAYOUT HEALTH V108.8.0 | DEGRADED · fresco {fresh_resolved}/{total} ({ratio*100:.0f}%) · renovando SOMENTE payout; candles/Trade intactos.", "warn")
    _payout_api_invalidate("cobertura de payout degradada")
    _kick_payout_data_connect(True)


def build_round_payout_snapshot(api: Any, assets: List[str], force: bool = False) -> Dict[str, Any]:
    """V102: uma chamada get_all_profit por rodada, depois somente lookup em memória.

    Se o snapshot fresco falhar, reaproveita o cache de payout por ativo; jamais dispara
    N chamadas individuais dentro do scanner técnico.
    """
    targets = list(dict.fromkeys(normalize_asset_name(a) for a in (assets or []) if a))
    if not targets:
        return {"ts": time.time(), "items": {}, "resolved": 0, "missing": 0, "elapsed_ms": 0, "cached_snapshot": False, "api_call": False, "source": "empty"}
    enabled = bool(cfg_get("payout_snapshot_enabled", True))
    if not enabled:
        items = {}
        for asset in targets:
            cached = _payout_cache_get(asset)
            if cached:
                items[asset] = dict(cached)
        return {"ts": time.time(), "items": items, "resolved": len(items), "missing": max(0, len(targets)-len(items)), "elapsed_ms": 0, "cached_snapshot": True, "api_call": False, "source": "snapshot_disabled_cache_only"}

    now_ts = time.time()
    ttl = max(5, min(120, int(cfg_get("payout_snapshot_ttl_seconds", 30) or 30)))
    with LUMI_CACHE_LOCK:
        previous = dict(PAYOUT_ROUND_SNAPSHOT)
        prev_items = dict(previous.get("items") or {})
    if not force and previous and now_ts - float(previous.get("ts", 0) or 0) <= ttl:
        covered = {a: dict(prev_items[a]) for a in targets if a in prev_items and int((prev_items[a] or {}).get("payout",0) or 0) > 0}
        if len(covered) >= max(1, int(len(targets) * 0.75)):
            return {
                "ts": float(previous.get("ts", now_ts) or now_ts), "items": covered,
                "resolved": len(covered), "missing": max(0, len(targets)-len(covered)),
                "elapsed_ms": 0, "cached_snapshot": True, "api_call": False,
                "source": str(previous.get("source") or "snapshot_cache"),
            }

    timeout_s = max(1.0, min(8.0, float(cfg_get("payout_snapshot_timeout_seconds", 4.0) or 4.0)))
    timeout_s = min(timeout_s, max(1.0, float(cfg_get("payout_session_rpc_timeout_seconds", 4.0) or 4.0)))
    started = time.perf_counter()
    payout_api = get_payout_data_api(api)
    ok, payload, err = _call_daemon_timeout(lambda: payout_api.get_all_profit() or {}, timeout_s)
    elapsed_ms = int((time.perf_counter() - started) * 1000)
    _phase_timing_add("payout_ms", elapsed_ms)
    items: Dict[str, Dict[str, Any]] = {}
    api_success = bool(ok and isinstance(payload, dict))
    fresh_resolved = 0
    if api_success:
        for asset in targets:
            info = _payout_from_all_profit_payload(payload, asset)
            if int(info.get("payout", 0) or 0) > 0:
                fresh_resolved += 1
            if int(info.get("payout", 0) or 0) > 0:
                # Alimenta o cache genérico para UI/fallback, sem gerar nova chamada de rede.
                cached_info = _payout_cache_set(asset, int(info["payout"]), str(info.get("source") or "payout_snapshot"), str(info.get("detail") or "snapshot único da rodada"))
                cached_info["snapshot"] = True
                items[asset] = cached_info
            else:
                cached = _payout_cache_get(asset) or _payout_last_good_get(asset)
                if cached:
                    fallback = dict(cached)
                    fallback["source"] = "payout_snapshot:last_known_good"
                    fallback["detail"] = f"ausente no snapshot atual; usando último payout válido ({int(fallback.get('stale_age_seconds',0) or 0)}s)"
                    fallback["snapshot"] = True
                    fallback["stale"] = True
                    items[asset] = fallback
    else:
        for asset in targets:
            cached = _payout_cache_get(asset) or _payout_last_good_get(asset)
            if cached:
                fallback = dict(cached)
                fallback["source"] = "payout_snapshot:last_known_good"
                fallback["detail"] = f"snapshot indisponível; usando último payout válido ({int(fallback.get('stale_age_seconds',0) or 0)}s)"
                fallback["snapshot"] = True
                fallback["stale"] = True
                items[asset] = fallback

    _payout_health_record(fresh_resolved, len(targets), api_success, str(err or ""))

    snapshot = {
        "ts": now_ts,
        "items": items,
        "resolved": sum(1 for x in items.values() if int((x or {}).get("payout",0) or 0) > 0),
        "missing": sum(1 for a in targets if int((items.get(a) or {}).get("payout",0) or 0) <= 0),
        "elapsed_ms": elapsed_ms,
        "cached_snapshot": False,
        "api_call": True,
        "source": "get_all_profit" if api_success else f"fallback:{err or 'erro'}",
        "fresh_resolved": int(fresh_resolved),
        "fresh_coverage": round(float(fresh_resolved) / max(1, len(targets)), 3),
        "payout_health": dict(dict.get(state, "payout_health", {}) or {}),
    }
    with LUMI_CACHE_LOCK:
        PAYOUT_ROUND_SNAPSHOT.clear()
        PAYOUT_ROUND_SNAPSHOT.update({"ts": now_ts, "items": dict(items), "source": snapshot["source"], "elapsed_ms": elapsed_ms, "api_call": True})
    return snapshot


def _payout_snapshot_info(snapshot: Optional[Dict[str, Any]], asset: str) -> Dict[str, Any]:
    """Lookup O(1) do payout durante o scanner; nunca consulta a IQ Option."""
    asset = normalize_asset_name(asset)
    items = dict((snapshot or {}).get("items") or {})
    info = items.get(asset)
    if isinstance(info, dict):
        out = dict(info)
        out["snapshot"] = True
        return out
    cached = _payout_cache_get(asset) or _payout_last_good_get(asset)
    if cached:
        out = dict(cached)
        out["source"] = "payout_snapshot:last_known_good" if out.get("stale") else "payout_snapshot:cache_lookup"
        out["detail"] = f"lookup local; último payout válido ({int(out.get('stale_age_seconds',0) or 0)}s)" if out.get("stale") else "lookup local; ativo não veio no snapshot desta rodada"
        out["snapshot"] = True
        return out
    return {"payout": 0, "source": "payout_snapshot:missing", "detail": "sem payout no snapshot/cache", "ts": time.time(), "time": now_hms(), "snapshot": True}


def _payout_last_good_get(asset: str, ttl: Optional[int] = None) -> Optional[Dict[str, Any]]:
    asset = normalize_asset_name(asset)
    age_limit = int(ttl if ttl is not None else (cfg_get("payout_last_good_ttl_seconds", 900) or 900))
    now_ts = time.time()
    with LUMI_CACHE_LOCK:
        item = dict(PAYOUT_LAST_GOOD.get(asset) or {})
    if not item:
        return None
    age = max(0.0, now_ts - float(item.get("ts", 0) or 0))
    if age > max(30, age_limit):
        return None
    item["stale_age_seconds"] = int(age)
    item["stale"] = True
    return item


def _payout_cache_get(asset: str) -> Optional[Dict[str, Any]]:
    ttl = int(cfg_get("payout_cache_ttl_seconds", 300) or 300)
    now_ts = time.time()
    asset = normalize_asset_name(asset)
    with LUMI_CACHE_LOCK:
        item = PAYOUT_CACHE.get(asset)
        if item and now_ts - float(item.get("ts", 0) or 0) <= ttl:
            return dict(item)
    return None


def _payout_cache_set(asset: str, payout: int, source: str, detail: str = "") -> Dict[str, Any]:
    asset = normalize_asset_name(asset)
    info = {
        "payout": int(payout or 0),
        "source": str(source or "desconhecido")[:80],
        "detail": str(detail or "")[:180],
        "ts": time.time(),
        "time": now_hms(),
    }
    persist_lkg = False
    with LUMI_CACHE_LOCK:
        PAYOUT_CACHE[asset] = dict(info)
        if int(info.get("payout", 0) or 0) > 0:
            PAYOUT_LAST_GOOD[asset] = dict(info)
            persist_lkg = True
        PAYOUT_LAST_SOURCE[asset] = dict(info)
    if persist_lkg:
        _schedule_payout_last_good_persist()
    try:
        with state_lock:
            state["payout_last_source"] = info["source"]
            state["payout_last_detail"] = f"{asset}: {info['payout']}% via {info['source']} {info['detail']}"[:240]
    except Exception:
        pass
    return info


def get_realtime_commission_payout(api: Any, asset: str) -> Dict[str, Any]:
    """Tenta ler payout por subscribe_commission_changed/get_commission_change.

    A documentação da iqoptionapi mostra que a comissão pode ser convertida em
    payout: payout = 100 - commission.
    """
    asset = normalize_asset_name(asset)
    instrument_types = ["turbo-option", "binary-option", "digital-option"]
    for instrument_type in instrument_types:
        try:
            if instrument_type not in PAYOUT_SUBSCRIBED and hasattr(api, "subscribe_commission_changed"):
                api.subscribe_commission_changed(instrument_type)
                PAYOUT_SUBSCRIBED.add(instrument_type)
                time.sleep(0.15)
            if not hasattr(api, "get_commission_change"):
                continue
            data = api.get_commission_change(instrument_type) or {}
            payload = _find_asset_payload(data, asset)
            if payload is None:
                payload = data if isinstance(data, dict) else None
            payout = _extract_commission_payout_value(payload)
            if payout:
                return _payout_cache_set(asset, payout, f"commission_changed:{instrument_type}", "comissão em tempo real")
        except Exception as exc:
            if cfg_get("debug_logs"):
                log(f"Payout engine: commission_changed falhou em {instrument_type}/{asset}: {str(exc)[:100]}", "warn")
            continue
    return {"payout": 0, "source": "commission_changed", "detail": "sem comissão para o ativo", "ts": time.time(), "time": now_hms()}


def get_payout_with_source(api: Any, asset: str, use_cache: bool = True) -> Dict[str, Any]:
    asset = normalize_asset_name(asset)
    if use_cache:
        cached = _payout_cache_get(asset)
        if cached:
            cached["cached"] = True
            return cached

    # 1) get_all_profit: mais rápido, porém pode vir vazio em algumas contas.
    try:
        all_profit = api.get_all_profit() or {}
        info = _find_asset_payload(all_profit, asset) if isinstance(all_profit, dict) else None
        if isinstance(info, dict):
            for kind in ("turbo", "binary", "digital"):
                payout = _extract_payout_value(info.get(kind))
                if payout:
                    return _payout_cache_set(asset, payout, f"get_all_profit:{kind}", "payout direto")
        payout = _extract_payout_value(info)
        if payout:
            return _payout_cache_set(asset, payout, "get_all_profit", "payout direto")
    except Exception as exc:
        if cfg_get("debug_logs"):
            log(f"Payout engine: get_all_profit falhou em {asset}: {str(exc)[:100]}", "warn")

    # 2) get_binary_option_detail: costuma trazer turbo/binary por ativo.
    try:
        if hasattr(api, "get_binary_option_detail"):
            detail = api.get_binary_option_detail() or {}
            info = _find_asset_payload(detail, asset) if isinstance(detail, dict) else None
            if isinstance(info, dict):
                for kind in ("turbo", "binary"):
                    payout = _extract_payout_value(info.get(kind))
                    if payout:
                        return _payout_cache_set(asset, payout, f"binary_option_detail:{kind}", "detalhe binário")
            payout = _extract_payout_value(info)
            if payout:
                return _payout_cache_set(asset, payout, "binary_option_detail", "detalhe binário")
    except Exception as exc:
        if cfg_get("debug_logs"):
            log(f"Payout engine: get_binary_option_detail falhou em {asset}: {str(exc)[:100]}", "warn")

    # 3) get_digital_payout: quando disponível na versão instalada.
    try:
        if hasattr(api, "get_digital_payout"):
            payout = _extract_payout_value(api.get_digital_payout(asset))
            if payout:
                return _payout_cache_set(asset, payout, "get_digital_payout", "payout digital")
    except Exception as exc:
        if cfg_get("debug_logs"):
            log(f"Payout engine: get_digital_payout falhou em {asset}: {str(exc)[:100]}", "warn")

    # 4) commission_changed: fonte de fallback em tempo real.
    if bool(cfg_get("payout_engine_enabled", True)):
        info = get_realtime_commission_payout(api, asset)
        if int(info.get("payout", 0) or 0) > 0:
            return info

    info = {"payout": 0, "source": "desconhecido", "detail": "nenhuma fonte retornou payout", "ts": time.time(), "time": now_hms()}
    with LUMI_CACHE_LOCK:
        PAYOUT_LAST_SOURCE[asset] = dict(info)
    try:
        with state_lock:
            state["payout_last_source"] = "desconhecido"
            state["payout_last_detail"] = f"{asset}: payout desconhecido"
    except Exception:
        pass
    return info


def _entry_payout_fresh_proof_get(asset: str) -> Optional[Dict[str, Any]]:
    """V109.4: retorna somente prova criada por revalidação de execução bem-sucedida."""
    asset = normalize_asset_name(asset)
    ttl = max(1.0, min(15.0, float(cfg_get("payout_fresh_proof_ttl_seconds", 8.0) or 8.0)))
    now_ts = time.time()
    current_generation = int(dict.get(state, "payout_data_generation", 0) or 0)
    with LUMI_CACHE_LOCK:
        proof = dict(PAYOUT_ENTRY_FRESH_PROOF.get(asset) or {})
    if not proof or int(proof.get("payout", 0) or 0) <= 0:
        return None
    age = max(0.0, now_ts - float(proof.get("ts", 0) or 0))
    if age > ttl:
        return None
    proof_generation = int(proof.get("payout_data_generation", current_generation) or current_generation)
    if current_generation > 0 and proof_generation > 0 and proof_generation != current_generation:
        return None
    proof["proof_age_seconds"] = round(age, 3)
    proof["proof_ttl_seconds"] = ttl
    return proof


def _entry_payout_fresh_proof_set(asset: str, payout: int, source: str) -> Dict[str, Any]:
    asset = normalize_asset_name(asset)
    proof = {
        "payout": int(payout or 0),
        "source": str(source or "entry_revalidate:get_all_profit")[:100],
        "ts": time.time(),
        "time": now_hms(),
        "payout_data_generation": int(dict.get(state, "payout_data_generation", 0) or 0),
    }
    with LUMI_CACHE_LOCK:
        PAYOUT_ENTRY_FRESH_PROOF[asset] = dict(proof)
    return proof


def get_entry_revalidated_payout(api: Any, asset: str, force_refresh: bool = False) -> Dict[str, Any]:
    """V109.4: revalida payout na sessão isolada e reaproveita prova recém-gerada.

    O primeiro checkpoint da entrada usa ``force_refresh=True`` e cria uma prova fresca.
    O Payout FINAL pode reutilizar essa MESMA prova por poucos segundos, desde que a
    sessão de payout não tenha mudado. Assim o caminho REAL continua fail-closed sem
    duplicar uma RPC imediatamente antes de api.buy().
    """
    asset = normalize_asset_name(asset)
    if not force_refresh:
        proof = _entry_payout_fresh_proof_get(asset)
        if proof:
            return {
                "payout": int(proof.get("payout", 0) or 0),
                "source": "entry_revalidate:fresh_proof",
                "detail": f"prova fresca reutilizada · idade {float(proof.get('proof_age_seconds',0) or 0):.1f}s/{float(proof.get('proof_ttl_seconds',8) or 8):.0f}s",
                "revalidated": True,
                "proof_reused": True,
                "proof_age_seconds": float(proof.get("proof_age_seconds", 0) or 0),
                "elapsed_ms": 0,
                "ts": float(proof.get("ts", time.time()) or time.time()),
                "time": str(proof.get("time") or now_hms()),
            }

    timeout_s = max(1.0, min(8.0, float(cfg_get("payout_entry_revalidate_timeout_seconds", 3.5) or 3.5)))
    started = time.perf_counter()
    payout_api = get_payout_data_api(api)
    ok, payload, err = _call_daemon_timeout(lambda: payout_api.get_all_profit() or {}, timeout_s)
    elapsed_ms = int((time.perf_counter() - started) * 1000)
    try:
        with state_lock:
            state["last_trade_payout_revalidate_ms"] = elapsed_ms
    except Exception:
        pass
    if ok and isinstance(payload, dict):
        info = _payout_from_all_profit_payload(payload, asset)
        payout = int(info.get("payout", 0) or 0)
        if payout > 0:
            source = str(info.get("source") or "entry_revalidate:get_all_profit")
            out = _payout_cache_set(asset, payout, source, "revalidado no checkpoint de execução")
            _entry_payout_fresh_proof_set(asset, payout, source)
            out["revalidated"] = True
            out["proof_reused"] = False
            out["proof_age_seconds"] = 0.0
            out["elapsed_ms"] = elapsed_ms
            return out

    cached = _payout_cache_get(asset) or _payout_last_good_get(asset)
    if cached:
        out = dict(cached)
        out["source"] = "entry_revalidate:last_known_good"
        out["detail"] = f"revalidação não concluiu ({err or 'sem payout'}); último valor válido apenas para diagnóstico"
        out["revalidated"] = False
        out["proof_reused"] = False
        out["elapsed_ms"] = elapsed_ms
        out["stale"] = True
        return out
    return {
        "payout": 0, "source": "entry_revalidate:unknown",
        "detail": f"revalidação sem payout ({err or 'sem retorno'})", "revalidated": False,
        "proof_reused": False, "elapsed_ms": elapsed_ms, "ts": time.time(), "time": now_hms(),
    }


def get_payout(api: Any, asset: str) -> int:
    return int(get_payout_with_source(api, asset).get("payout", 0) or 0)


def real_allow_unknown_payout() -> bool:
    return str(cfg_get("account_type", "PRACTICE")).upper() == "REAL" and bool(cfg_get("real_allow_unknown_payout", True))


def real_unknown_payout_requirements() -> Tuple[int, int]:
    return (
        int(cfg_get("real_unknown_payout_min_technical", 68) or 68),
        int(cfg_get("real_unknown_payout_min_lumi", 68) or 68),
    )

def get_max_concurrent_open_orders() -> int:
    """V108.9: paralelismo REAL cai automaticamente quando o edge deteriora.

    Evita abrir 2-3 ordens antes de o primeiro LOSS poder alimentar o aprendizado.
    Quando streak=0 e o edge recente volta a positivo, o limite configurado é restaurado.
    """
    try:
        limit = int(cfg_get("max_concurrent_open_orders", 3) or 3)
    except Exception:
        limit = 3
    limit = max(1, min(3, limit))
    if str(cfg_get("account_type", "PRACTICE")).upper() == "REAL" and bool(cfg_get("adaptive_loss_dynamic_parallel_enabled", True)):
        learning = dict(cfg_get("wallstreet_learning", {}) or {})
        streak = int(learning.get("loss_streak", cfg_get("loss_streak", 0)) or 0)
        edge = float(learning.get("edge", 0) or 0)
        n = int(learning.get("recent_real", 0) or 0)
        mode = str(learning.get("recovery_mode") or "normal")
        if streak >= 1 or mode in {"caution", "defensive", "recovery", "pause"}:
            limit = min(limit, max(1, int(cfg_get("adaptive_loss_caution_max_parallel", 1) or 1)))
        elif n >= 4 and edge < 0:
            limit = min(limit, max(1, int(cfg_get("adaptive_loss_negative_edge_max_parallel", 1) or 1)))
    return max(1, min(3, limit))


def get_active_open_orders() -> List[Dict[str, Any]]:
    now = time.time()
    tf = int(cfg_get("timeframe", 60) or 60)
    cutoff_age = max(tf + int(cfg_get("result_timeout_seconds", 120) or 120) + 120, 240)
    with state_lock:
        orders = list(cfg_get("open_orders", []) or [])
        fresh = [o for o in orders if now - float(o.get("opened_ts", now) or now) <= cutoff_age]
        if len(fresh) != len(orders):
            state["open_orders"] = fresh
        return list(fresh)


def has_active_order_for_asset(asset: str) -> bool:
    target = normalize_asset_name(asset)
    for order in get_active_open_orders():
        if normalize_asset_name(order.get("asset", "")) == target:
            return True
    return False


def real_requires_valid_payout() -> bool:
    """Em REAL, payout vazio/zero só é bloqueado quando o modo desconhecido controlado está desligado."""
    if str(cfg_get("account_type", "PRACTICE")).upper() != "REAL":
        return False
    if bool(cfg_get("real_ignore_missing_payout", False)) or bool(cfg_get("ignore_missing_payout_real", False)) or bool(cfg_get("skip_zero_payout_real", False)):
        return True
    return not bool(cfg_get("real_allow_unknown_payout", True))


def safety_block_reason(asset: str, candle_ts: Optional[int], payout: int, ignore_entry_window: bool = False) -> Optional[str]:
    now = time.time()
    tf = int(cfg_get("timeframe", 300) or 300)
    entry_window = int(cfg_get("entry_window_seconds", 12) or 12)
    seconds_into_candle = now - (int(now) // tf) * tf
    active_orders = get_active_open_orders()
    open_count = len(active_orders)
    max_open = get_max_concurrent_open_orders()
    parallel_enabled = bool(cfg_get("allow_parallel_entries", True))

    if real_requires_valid_payout() and int(payout or 0) <= 0:
        return "payout não retornado pela API em REAL; ativo ignorado por segurança"
    if str(cfg_get("account_type", "PRACTICE")).upper() == "REAL" and int(payout or 0) <= 0 and real_allow_unknown_payout():
        max_unknown = int(cfg_get("real_unknown_payout_max_open", 1) or 1)
        unknown_open = sum(1 for o in active_orders if int(o.get("payout", 0) or 0) <= 0)
        if unknown_open >= max_unknown:
            return f"limite de operações com payout desconhecido atingido ({unknown_open}/{max_unknown})"
    if state["trade_count"] + open_count >= state["max_trades_session"]:
        return "limite de operações da sessão atingido"
    if bool(cfg_get("intelligent_martingale_enabled", False)) and bool(cfg_get("martingale_pending", False)) and open_count > 0:
        return "Martingale Inteligente pendente; aguardando outras ordens encerrarem para não sobrepor recuperação"
    if parallel_enabled and open_count >= max_open:
        return f"limite de operações simultâneas atingido ({open_count}/{max_open})"
    if parallel_enabled and has_active_order_for_asset(asset):
        return "já existe operação ativa neste mesmo ativo"
    if (not parallel_enabled) and open_count > 0:
        return "já existe operação ativa; aguardando resultado"
    if (not ignore_entry_window) and seconds_into_candle > entry_window:
        return f"fora da janela ideal de entrada: {int(seconds_into_candle)}s após abrir a vela"
    if state["loss_streak"] >= state["max_loss_streak"]:
        return "sequência máxima de perdas atingida"
    if payout and payout < state["min_payout"]:
        return f"payout baixo ({payout}% < {state['min_payout']}%)"
    cooldown_can_be_ignored_for_parallel = parallel_enabled and open_count > 0 and open_count < max_open
    if now - state["last_trade_ts"] < state["cooldown_seconds"] and not cooldown_can_be_ignored_for_parallel:
        rest = int(state["cooldown_seconds"] - (now - state["last_trade_ts"]))
        return f"cooldown ativo: {rest}s"
    if candle_ts is not None:
        by_asset = cfg_get("last_trade_candles_by_asset", {}) or {}
        if by_asset.get(normalize_asset_name(asset)) == candle_ts:
            return "já houve entrada neste ativo nesta vela fechada"
        if (not parallel_enabled) and cfg_get("last_trade_candle") == candle_ts:
            return "já houve entrada nesta vela fechada"
    return None

def _freshness_price_consensus_decision(
    reference_price: float,
    current_price: float,
    probe_price: float,
    move_limit_pct: float,
    sanity_ratio: float,
    absurd_move_pct: float,
    consensus_tolerance_pct: float,
) -> Dict[str, Any]:
    """V108.8.0: decide qual preço está coerente sem confundir escala com movimento.

    Quando ref/current divergem de forma impossível para a idade curta do sinal, um
    terceiro preço M1 (probe direto) atua como desempate. O normalizador nunca inventa
    um preço: ele só aceita o lado confirmado por duas fontes ou bloqueia.
    """
    def _num(v: Any) -> float:
        try:
            x = abs(float(v or 0.0))
            return x if math.isfinite(x) else 0.0
        except Exception:
            return 0.0

    def _dist(a: float, b: float) -> float:
        a, b = _num(a), _num(b)
        if a <= 0 or b <= 0:
            return 999999.0
        return abs(a - b) / max(1e-12, min(a, b)) * 100.0

    ref = _num(reference_price)
    cur = _num(current_price)
    probe = _num(probe_price)
    if ref <= 0 or cur <= 0:
        return {"action":"block", "reason":"preço de referência/quote inválido", "reference_price":ref, "current_price":cur}

    ratio = max(ref, cur) / max(1e-12, min(ref, cur))
    move = abs(cur - ref) / max(1e-12, ref) * 100.0
    absurd_floor = max(float(absurd_move_pct or 5.0), float(move_limit_pct or 0.3) * 8.0)
    suspicious = ratio > max(2.0, float(sanity_ratio or 8.0)) or move > absurd_floor
    base = {
        "reference_price": ref, "current_price": cur, "probe_price": probe,
        "ratio": ratio, "move_pct": move, "absurd_floor_pct": absurd_floor,
        "suspicious": suspicious,
    }
    if not suspicious:
        return {**base, "action":"ok", "reason":"ref/quote coerentes"}
    if probe <= 0:
        return {**base, "action":"block", "reason":"deslocamento/escala suspeita sem terceiro preço M1 para consenso"}

    tolerance = max(float(consensus_tolerance_pct or 1.5), float(move_limit_pct or 0.3) * 3.0)
    cur_probe = _dist(cur, probe)
    ref_probe = _dist(ref, probe)
    base.update({"current_probe_distance_pct":cur_probe, "reference_probe_distance_pct":ref_probe, "consensus_tolerance_pct":tolerance})
    cur_agrees = cur_probe <= tolerance
    ref_agrees = ref_probe <= tolerance

    if cur_agrees and not ref_agrees:
        # Quote Cache + probe M1 concordam: baseline antiga está em escala/fonte errada.
        return {**base, "action":"reanchor_reference", "reason":"quote atual confirmada por probe M1; baseline antiga divergente", "reference_price":cur, "current_price":cur}
    if ref_agrees and not cur_agrees:
        # Baseline + probe concordam: a quote cache atual é o outlier.
        return {**base, "action":"replace_current", "reason":"baseline confirmada por probe M1; quote cache divergente", "reference_price":ref, "current_price":probe}
    if cur_agrees and ref_agrees:
        # Raro, mas se o limiar classificou suspeito e as três fontes estão próximas,
        # mantemos o probe como preço atual e seguimos com cálculo normal.
        return {**base, "action":"use_probe", "reason":"três preços dentro do consenso M1", "reference_price":ref, "current_price":probe}
    return {**base, "action":"block", "reason":"referência, quote cache e probe M1 não formaram consenso"}


def _freshness_direct_m1_probe(api: Any, asset: str, timeout: float) -> Dict[str, Any]:
    """Obtém um terceiro preço M1 curto para desempatar referência/quote suspeitas."""
    result: Dict[str, Any] = {"ok":False, "price":0.0, "timestamp":0, "age_seconds":999999.0, "source":"probe_m1_consensus"}
    ok_probe, raw = _call_api_with_timeout(api.get_candles, args=(asset, 60, 3, time.time()), timeout=max(0.5, min(2.5, float(timeout or 1.2))))
    if not ok_probe:
        result["reason"] = "timeout/erro no probe M1"
        return result
    try:
        candles = list(raw or []) if isinstance(raw, (list, tuple)) else []
        candles.sort(key=lambda c: int((c or {}).get("from") or (c or {}).get("at") or 0))
        for candle in reversed(candles):
            if not isinstance(candle, dict) or candle.get("close") is None:
                continue
            price = float(candle.get("close") or 0.0)
            ts = int(candle.get("from") or candle.get("at") or 0)
            if price <= 0:
                continue
            age = max(0.0, time.time() - ts) if ts > 0 else 0.0
            # Um candle M1 com até 3 minutos ainda serve para detectar unidade/escala.
            if ts > 0 and age > 180:
                continue
            result.update({"ok":True, "price":price, "timestamp":ts, "age_seconds":round(age,3)})
            return result
    except Exception as exc:
        result["reason"] = f"probe M1 inválido: {exc}"
        return result
    result["reason"] = "probe M1 sem close recente"
    return result


def immediate_entry_freshness_guard(
    api: Any, asset: str, tf: int, approved_ts: float, reference_price: float,
    precision_summary: Optional[Dict[str, Any]] = None,
    probe_timeout_override: Optional[float] = None, fail_closed_override: Optional[bool] = None,
    reference_source: str = "",
) -> Tuple[bool, str, Dict[str, Any]]:
    """V108.8.0: freshness por Quote Cache M1 + probe controlado, com escala saneada.

    O cache prioritário é atualizado em background depois que um setup é aprovado.
    Se faltar quote recente, fazemos um único probe M1. A primeira verificação pode
    redefinir a referência para a MESMA fonte M1; a verificação FINAL continua fail-closed.
    """
    now = time.time()
    try:
        approved_ts = float(approved_ts or now)
    except Exception:
        approved_ts = now
    age = max(0.0, now - approved_ts)
    max_age = max(5, int(cfg_get("immediate_entry_max_signal_age_seconds", 20) or 20))
    info: Dict[str, Any] = {
        "age_seconds": round(age, 3), "max_age_seconds": max_age,
        "reference_price": float(reference_price or 0.0), "reference_source": str(reference_source or "")[:80],
        "current_price": 0.0, "current_source": "", "move_pct": 0.0, "move_limit_pct": 0.0,
        "price_guard": "desativado", "baseline_reset": False,
    }
    if age > max_age:
        return False, f"sinal envelheceu antes da ordem: {age:.1f}s > {max_age}s", info
    if not bool(cfg_get("immediate_entry_price_guard_enabled", True)):
        return True, f"sinal recente ({age:.1f}s); price guard desativado", info

    ref = float(reference_price or 0.0)
    configured_limit = max(0.05, min(1.50, float(cfg_get("immediate_entry_max_move_pct", 0.30) or 0.30)))
    atr_pct = 0.0
    try:
        summary = precision_summary or {}
        atr_pct = float(((summary.get("m5") or {}).get("atr_pct", 0)) or 0)
    except Exception:
        atr_pct = 0.0
    atr_multiplier = max(0.50, min(4.0, float(cfg_get("immediate_entry_atr_multiplier", 1.50) or 1.50)))
    atr_cap = max(configured_limit, min(2.00, float(cfg_get("immediate_entry_atr_cap_pct", 1.00) or 1.00)))
    move_limit = min(atr_cap, max(configured_limit, atr_pct * atr_multiplier)) if atr_pct > 0 else configured_limit
    info.update({"atr_pct": round(atr_pct,5), "atr_multiplier": round(atr_multiplier,3), "atr_cap_pct": round(atr_cap,5), "move_limit_pct": round(move_limit,5)})

    _set_execution_quote_priority(asset)
    _kick_quote_cache_worker(api)
    quote = _quote_cache_get(asset)
    latest_price = float((quote or {}).get("price", 0) or 0)
    latest_source = str((quote or {}).get("source") or "")

    fail_closed = bool(fail_closed_override) if fail_closed_override is not None else bool(cfg_get("immediate_entry_price_guard_strict", False))
    if latest_price <= 0:
        probe_timeout = max(0.5, min(5.0, float(probe_timeout_override if probe_timeout_override is not None else (cfg_get("immediate_entry_price_probe_timeout_seconds", 2.5) or 2.5))))
        ok_probe, raw = _call_api_with_timeout(api.get_candles, args=(asset, 60, 2, time.time()), timeout=probe_timeout)
        if ok_probe:
            try:
                candles = list(raw or []) if isinstance(raw, (list, tuple)) else []
                candles.sort(key=lambda c: int((c or {}).get("from") or (c or {}).get("at") or 0))
                for candle in reversed(candles):
                    if isinstance(candle, dict) and candle.get("close") is not None:
                        latest_price = float(candle.get("close"))
                        latest_source = "probe_m1"
                        _quote_cache_set(asset, latest_price, latest_source, int(candle.get("from") or candle.get("at") or 0))
                        break
            except Exception:
                latest_price = 0.0
        if latest_price <= 0:
            info["price_guard"] = "quote/probe indisponível"
            if fail_closed:
                return False, f"não foi possível confirmar quote M1 atual em {probe_timeout:.1f}s", info
            return True, f"sinal recente ({age:.1f}s); quote M1 indisponível, seguindo para preflight", info

    info["current_price"] = latest_price
    info["current_source"] = latest_source
    age_after = max(0.0, time.time() - approved_ts)
    info["age_seconds"] = round(age_after,3)
    if age_after > max_age:
        return False, f"sinal envelheceu durante freshness: {age_after:.1f}s > {max_age}s", info

    if ref <= 0:
        info["baseline_reset"] = True
        info["reference_price"] = latest_price
        info["reference_source"] = latest_source
        info["price_guard"] = "baseline M1 estabelecida"
        return True, f"sinal {age_after:.1f}s · baseline M1 estabelecida em {latest_price:.8g}", info

    # V108.8.0 — Freshness Reference Normalizer V2.
    # O sanity antigo só pegava diferenças >8x; um outlier ~7x podia virar falso
    # "movimento de 603%". Agora qualquer deslocamento absurdo para um sinal de
    # poucos segundos exige consenso com um TERCEIRO preço M1 antes de decidir.
    ratio = max(abs(latest_price), abs(ref)) / max(1e-12, min(abs(latest_price), abs(ref)))
    sanity_ratio = max(2.0, float(cfg_get("immediate_entry_price_scale_sanity_ratio", 8.0) or 8.0))
    raw_move_pct = abs(latest_price - ref) / max(1e-12, abs(ref)) * 100.0
    normalizer_enabled = bool(cfg_get("immediate_entry_reference_normalizer_enabled", True))
    absurd_move_pct = max(1.0, float(cfg_get("immediate_entry_reference_absurd_move_pct", 5.0) or 5.0))
    consensus_tol = max(0.2, float(cfg_get("immediate_entry_reference_consensus_tolerance_pct", 1.5) or 1.5))
    suspicious = ratio > sanity_ratio or raw_move_pct > max(absurd_move_pct, move_limit * 8.0)

    if normalizer_enabled and suspicious:
        normalizer_timeout = max(0.5, min(2.5, float(cfg_get("immediate_entry_reference_probe_timeout_seconds", 1.2) or 1.2)))
        if probe_timeout_override is not None:
            normalizer_timeout = min(normalizer_timeout, max(0.5, float(probe_timeout_override)))
        probe = _freshness_direct_m1_probe(api, asset, normalizer_timeout)
        probe_price = float(probe.get("price", 0.0) or 0.0) if probe.get("ok") else 0.0
        consensus = _freshness_price_consensus_decision(
            ref, latest_price, probe_price, move_limit, sanity_ratio, absurd_move_pct, consensus_tol,
        )
        info.update({
            "normalizer_triggered": True,
            "normalizer_action": str(consensus.get("action") or "block"),
            "normalizer_reason": str(consensus.get("reason") or "")[:220],
            "normalizer_probe_price": probe_price,
            "normalizer_probe_age_seconds": float(probe.get("age_seconds", 0) or 0),
            "scale_ratio": round(float(consensus.get("ratio", ratio) or ratio), 4),
            "raw_move_pct": round(raw_move_pct, 5),
        })
        action = str(consensus.get("action") or "block")
        if action == "block":
            info["price_guard"] = "reference_inconsistent"
            return False, (
                f"referência de preço inconsistente: ref/quote divergiram {raw_move_pct:.3f}% "
                f"e o probe M1 não confirmou consenso ({consensus.get('reason')})"
            ), info
        if action == "reanchor_reference":
            ref = float(consensus.get("reference_price") or latest_price)
            latest_price = float(consensus.get("current_price") or latest_price)
            info["baseline_reset"] = True
            info["reference_price"] = ref
            info["reference_source"] = f"normalized:{latest_source or 'quote_m1'}+probe_m1"
            info["current_price"] = latest_price
            info["current_source"] = f"{latest_source or 'quote_m1'}+probe_m1"
        elif action in {"replace_current", "use_probe"}:
            latest_price = float(consensus.get("current_price") or probe_price or latest_price)
            info["current_price"] = latest_price
            info["current_source"] = "probe_m1_consensus"
            info["reference_price"] = ref
        info["price_guard"] = "normalized_consensus"

    elif suspicious and not normalizer_enabled:
        info["price_guard"] = "scale_mismatch"
        info["scale_ratio"] = round(ratio,4)
        if fail_closed:
            return False, f"quote/reference em escalas incompatíveis ou movimento absurdo ({raw_move_pct:.3f}%, razão {ratio:.2f}x)", info
        info["baseline_reset"] = True
        ref = latest_price
        info["reference_price"] = latest_price
        info["reference_source"] = latest_source

    move_pct = abs(latest_price - ref) / max(1e-12, abs(ref)) * 100.0
    info.update({"move_pct": round(move_pct,5), "price_guard": info.get("price_guard") if info.get("price_guard") == "normalized_consensus" else "ok"})
    if move_pct > move_limit:
        return False, f"preço deslocou {move_pct:.3f}% desde a referência M1 (limite {move_limit:.3f}%)", info
    if info.get("normalizer_triggered"):
        action_txt = str(info.get("normalizer_action") or "normalizado")
        return True, (
            f"sinal {age_after:.1f}s · referência normalizada por consenso M1 ({action_txt}) · "
            f"deslocamento validado {move_pct:.3f}%/{move_limit:.3f}%"
        ), info
    return True, f"sinal {age_after:.1f}s · quote {latest_source or 'M1'} · deslocamento {move_pct:.3f}%/{move_limit:.3f}%", info

def wait_until_next_candle(tf: int) -> None:
    next_ts = (int(time.time()) // tf + 1) * tf
    sleep_for = max(5, min(tf, next_ts - time.time() + 1))
    if bool(cfg_get("elite_opportunity_watcher_enabled", True)) and bool(cfg_get("scanner_enabled", True)):
        interval = max(10, int(cfg_get("elite_opportunity_interval_seconds", 25) or 25))
        next_full = float(cfg_get("next_scan_at", 0) or 0)
        until_full = max(1.0, next_full - time.time()) if next_full > 0 else float(interval)
        sleep_for = max(1.0, min(float(sleep_for), float(interval), float(until_full)))
    next_full = float(cfg_get("next_scan_at", 0) or 0)
    next_in = max(0, int(next_full-time.time())) if next_full > 0 else int(sleep_for)
    _runtime_heartbeat("bot_loop", "scheduler_wait", next_scan_in=next_in, sleep_seconds=round(float(sleep_for),1))
    stop_event.wait(sleep_for)
    _runtime_heartbeat("bot_loop", "scheduler_wake", next_scan_in=max(0, int(float(cfg_get("next_scan_at",0) or 0)-time.time())))

def wait_until_candle_open(tf: int) -> None:
    next_ts = (int(time.time()) // tf + 1) * tf
    sleep_for = max(0.5, next_ts - time.time() + 0.8)
    stop_event.wait(sleep_for)


