# ── Resultado de ordem robusto ─────────────────────────────
def _call_api_with_timeout(fn, args: tuple = (), kwargs: Optional[Dict[str, Any]] = None, timeout: float = 4.0) -> Tuple[bool, Any]:
    """Executa uma chamada potencialmente bloqueante da iqoptionapi com timeout curto."""
    kwargs = kwargs or {}
    q: "queue.Queue[Tuple[bool, Any]]" = queue.Queue(maxsize=1)

    def runner() -> None:
        try:
            q.put((True, fn(*args, **kwargs)))
        except Exception as exc:
            q.put((False, exc))

    t = threading.Thread(target=runner, daemon=True)
    t.start()
    try:
        return q.get(timeout=timeout)
    except queue.Empty:
        return False, TimeoutError(f"timeout após {timeout:.1f}s")



# ── V108.8.0 Safe Broker RPC + runtime/order watchdog ────────────────────────
_SAFE_BROKER_RPC_META_LOCK = threading.Lock()
_SAFE_BROKER_RPC_INFLIGHT: Dict[str, Dict[str, Any]] = {}
_RUNTIME_HEARTBEAT_LOCK = threading.Lock()
_RUNTIME_HEARTBEATS: Dict[str, Dict[str, Any]] = {}
_ORDER_MONITOR_LOCK = threading.Lock()
_ORDER_MONITORS: Dict[str, Dict[str, Any]] = {}
_ORDER_FINALIZED: Dict[str, float] = {}
_RUNTIME_WATCHDOG_THREAD: Optional[threading.Thread] = None
_RUNTIME_WATCHDOG_STOP = threading.Event()
_RUNTIME_WATCHDOG_LAST_ALERT: Dict[str, float] = {}
_STATE_LOCK_BUSY_STREAK = 0


def _runtime_heartbeat(component: str, detail: str = "", **extra: Any) -> None:
    now = time.time()
    row = {"component": str(component), "ts": now, "time": now_hms(), "detail": str(detail or "")[:180]}
    if extra:
        row.update({str(k): v for k, v in extra.items() if k not in {"api", "password"}})
    with _RUNTIME_HEARTBEAT_LOCK:
        _RUNTIME_HEARTBEATS[str(component)] = row


def _runtime_heartbeat_snapshot() -> Dict[str, Any]:
    now = time.time()
    with _RUNTIME_HEARTBEAT_LOCK:
        rows = {k: dict(v) for k, v in _RUNTIME_HEARTBEATS.items()}
    for row in rows.values():
        row["age_seconds"] = round(max(0.0, now - float(row.get("ts", now) or now)), 1)
    return rows


def _emergency_console(message: str) -> None:
    """Console independente de state_lock para que um deadlock ainda fique visível."""
    try:
        print(f"[{now_hms()}] [WATCHDOG] {message}", flush=True)
    except Exception:
        pass


def _safe_broker_rpc(
    name: str,
    fn: Any,
    args: tuple = (),
    kwargs: Optional[Dict[str, Any]] = None,
    timeout: Optional[float] = None,
) -> Tuple[bool, Any]:
    """RPC da IQ Option sem state_lock e sem tempestade de threads após timeout."""
    kwargs = kwargs or {}
    rpc_name = str(name or getattr(fn, "__name__", "broker_rpc"))
    timeout_s = float(timeout if timeout is not None else cfg_get("broker_rpc_timeout_seconds", 3.5) or 3.5)
    timeout_s = max(0.8, min(15.0, timeout_s))
    q: "queue.Queue[Tuple[bool, Any]]" = queue.Queue(maxsize=1)
    token = f"{time.time_ns()}-{threading.get_ident()}"

    with _SAFE_BROKER_RPC_META_LOCK:
        prev = _SAFE_BROKER_RPC_INFLIGHT.get(rpc_name)
        if isinstance(prev, dict):
            th = prev.get("thread")
            if th is not None and getattr(th, "is_alive", lambda: False)():
                age = max(0.0, time.time() - float(prev.get("started_ts", time.time()) or time.time()))
                _runtime_heartbeat(f"rpc:{rpc_name}", "busy", age_seconds=round(age, 1))
                return False, RuntimeError(f"RPC {rpc_name} ainda em andamento há {age:.1f}s")
            _SAFE_BROKER_RPC_INFLIGHT.pop(rpc_name, None)

    def runner() -> None:
        _runtime_heartbeat(f"rpc:{rpc_name}", "started")
        try:
            value = fn(*args, **kwargs)
            try: q.put_nowait((True, value))
            except Exception: pass
        except Exception as exc:
            try: q.put_nowait((False, exc))
            except Exception: pass
        finally:
            _runtime_heartbeat(f"rpc:{rpc_name}", "finished")
            with _SAFE_BROKER_RPC_META_LOCK:
                cur = _SAFE_BROKER_RPC_INFLIGHT.get(rpc_name)
                if isinstance(cur, dict) and cur.get("token") == token:
                    _SAFE_BROKER_RPC_INFLIGHT.pop(rpc_name, None)

    t = threading.Thread(target=runner, daemon=True, name=f"broker-rpc-{rpc_name[:24]}")
    with _SAFE_BROKER_RPC_META_LOCK:
        _SAFE_BROKER_RPC_INFLIGHT[rpc_name] = {"token": token, "thread": t, "started_ts": time.time()}
    t.start()
    try:
        ok, value = q.get(timeout=timeout_s)
        _runtime_heartbeat(f"rpc:{rpc_name}", "ok" if ok else "error")
        return ok, value
    except queue.Empty:
        _runtime_heartbeat(f"rpc:{rpc_name}", "timeout", timeout_seconds=timeout_s)
        return False, TimeoutError(f"RPC {rpc_name} excedeu {timeout_s:.1f}s")


def _safe_get_balance(api: Any, timeout: Optional[float] = None) -> Tuple[Optional[float], str]:
    if api is None:
        return None, "sessão ausente"
    timeout_s = float(timeout if timeout is not None else cfg_get("broker_balance_timeout_seconds", 3.0) or 3.0)
    ok, value = _safe_broker_rpc("get_balance", api.get_balance, timeout=timeout_s)
    if not ok:
        return None, str(value)
    try:
        return float(value), "ok"
    except Exception as exc:
        return None, f"saldo inválido: {exc}"


def _update_balance_nonblocking(api: Any, reason: str = "") -> Optional[float]:
    """Atualiza state.balance sem chamar IQ Option dentro do state_lock."""
    balance, detail = _safe_get_balance(api)
    if balance is None:
        _runtime_heartbeat("balance_refresh", "failed", reason=reason, error=str(detail)[:120])
        return None
    acquired = state_lock.acquire(timeout=0.25)
    if not acquired:
        _runtime_heartbeat("balance_refresh", "state_lock_busy", reason=reason)
        return balance
    try:
        state["balance"] = float(balance)
    finally:
        state_lock.release()
    _runtime_heartbeat("balance_refresh", "updated", reason=reason, balance=round(balance, 2))
    return balance


def _order_monitor_register(order_id: Any, asset: str, direction: str, args: tuple, trade_context: Dict[str, Any]) -> None:
    key = str(order_id)
    now = time.time()
    with _ORDER_MONITOR_LOCK:
        prev = dict(_ORDER_MONITORS.get(key) or {})
        recovery_count = int(prev.get("recovery_count", 0) or 0)
        _ORDER_MONITORS[key] = {
            **prev, "order_id": key, "asset": str(asset), "direction": str(direction),
            "started_ts": float(prev.get("started_ts", now) or now),
            "heartbeat_ts": now, "heartbeat": now_hms(), "phase": "starting",
            "recovery_count": recovery_count, "status": "active", "_recovery_args": args,
        }
    _runtime_heartbeat(f"order:{key}", "starting", asset=asset, direction=direction)


def _order_monitor_beat(order_id: Any, phase: str, **extra: Any) -> None:
    key = str(order_id)
    now = time.time()
    with _ORDER_MONITOR_LOCK:
        row = dict(_ORDER_MONITORS.get(key) or {"order_id": key, "started_ts": now, "recovery_count": 0})
        row.update({"heartbeat_ts": now, "heartbeat": now_hms(), "phase": str(phase or "")[:100], "status": "active"})
        for k, v in extra.items():
            if k != "_recovery_args":
                row[str(k)] = v
        _ORDER_MONITORS[key] = row
    _runtime_heartbeat(f"order:{key}", phase, **extra)


def _order_monitor_done(order_id: Any, status: str = "done") -> None:
    key = str(order_id)
    now = time.time()
    with _ORDER_MONITOR_LOCK:
        row = dict(_ORDER_MONITORS.get(key) or {"order_id": key, "started_ts": now})
        row.update({"heartbeat_ts": now, "heartbeat": now_hms(), "phase": status, "status": status, "finished_ts": now})
        row.pop("_recovery_args", None)
        _ORDER_MONITORS[key] = row
        for old_key in list(_ORDER_MONITORS):
            old = _ORDER_MONITORS.get(old_key) or {}
            if old.get("finished_ts") and now - float(old.get("finished_ts", now) or now) > 3600:
                _ORDER_MONITORS.pop(old_key, None)
        for old_key in list(_ORDER_FINALIZED):
            if now - float(_ORDER_FINALIZED.get(old_key, now) or now) > 86400:
                _ORDER_FINALIZED.pop(old_key, None)
    _runtime_heartbeat(f"order:{key}", status)


def _order_monitor_snapshot() -> Dict[str, Any]:
    now = time.time()
    with _ORDER_MONITOR_LOCK:
        rows = {k: {kk: vv for kk, vv in v.items() if kk != "_recovery_args"} for k, v in _ORDER_MONITORS.items()}
    for row in rows.values():
        row["heartbeat_age_seconds"] = round(max(0.0, now - float(row.get("heartbeat_ts", now) or now)), 1)
        row["age_seconds"] = round(max(0.0, now - float(row.get("started_ts", now) or now)), 1)
    return rows


def _claim_order_finalization(order_id: Any) -> bool:
    key = str(order_id)
    with _ORDER_MONITOR_LOCK:
        if key in _ORDER_FINALIZED:
            return False
        _ORDER_FINALIZED[key] = time.time()
        row = dict(_ORDER_MONITORS.get(key) or {})
        row["status"] = "finalizing"
        row["phase"] = "finalizing"
        row["heartbeat_ts"] = time.time()
        _ORDER_MONITORS[key] = row
        return True


def _runtime_watchdog_snapshot() -> Dict[str, Any]:
    with _SAFE_BROKER_RPC_META_LOCK:
        inflight = {
            k: {"age_seconds": round(max(0.0, time.time()-float(v.get("started_ts", time.time()) or time.time())), 1)}
            for k, v in _SAFE_BROKER_RPC_INFLIGHT.items()
        }
    try:
        state_lock_meta = state_lock.snapshot()
    except Exception:
        state_lock_meta = {"locked": False, "owner_thread": "", "owner_site": "", "held_seconds": 0.0}
    try:
        result_pipeline = _result_pipeline_snapshot()
    except Exception:
        result_pipeline = {"commit_stage": "initializing", "learning_stage": "initializing"}
    return {
        "heartbeats": _runtime_heartbeat_snapshot(),
        "order_monitors": _order_monitor_snapshot(),
        "rpc_inflight": inflight,
        "state_lock_busy_streak": int(_STATE_LOCK_BUSY_STREAK),
        "state_lock": state_lock_meta,
        "result_pipeline": result_pipeline,
        "updated_at": now_hms(),
    }


def _runtime_watchdog_alert_once(key: str, message: str, every: float = 30.0) -> None:
    now = time.time()
    last = float(_RUNTIME_WATCHDOG_LAST_ALERT.get(key, 0) or 0)
    if now - last < every:
        return
    _RUNTIME_WATCHDOG_LAST_ALERT[key] = now
    _emergency_console(message)
    acquired = state_lock.acquire(timeout=0.10)
    if acquired:
        state_lock.release()
        try: log(message, "warn")
        except Exception: pass


def _recover_stale_order_monitors() -> None:
    if not bool(cfg_get("order_monitor_watchdog_enabled", True)):
        return
    stale_s = max(8, int(cfg_get("order_monitor_stale_seconds", 15) or 15))
    max_recoveries = max(0, int(cfg_get("order_monitor_max_recoveries", 1) or 1))
    can_recover = bool(cfg_get("order_monitor_recovery_enabled", True)) and max_recoveries > 0
    now = time.time()
    rescues = []
    alerts = []
    with _ORDER_MONITOR_LOCK:
        for key, row0 in list(_ORDER_MONITORS.items()):
            row = dict(row0 or {})
            if str(row.get("status") or "") not in {"active", "starting"}:
                continue
            age_hb = now - float(row.get("heartbeat_ts", now) or now)
            if age_hb <= stale_s:
                continue
            alerts.append((key, age_hb, row.get("phase","?")))
            rc = int(row.get("recovery_count", 0) or 0)
            if can_recover and rc < max_recoveries and isinstance(row.get("_recovery_args"), tuple):
                row["recovery_count"] = rc + 1
                row["heartbeat_ts"] = now
                row["phase"] = "watchdog_recovery"
                _ORDER_MONITORS[key] = row
                rescues.append((key, tuple(row["_recovery_args"])))
    for key, age_hb, phase in alerts:
        _runtime_watchdog_alert_once(f"order-stale-{key}", f"🫀 ORDER WATCHDOG V108.8.0 | ordem {key} sem heartbeat há {age_hb:.0f}s · fase={phase}.")
    for key, args in rescues:
        try:
            args_list = list(args)
            if len(args_list) >= 11:
                ctx = dict(args_list[10] or {})
                ctx["_watchdog_recovery"] = True
                args_list[10] = ctx
            threading.Thread(target=monitor_open_order_result, args=tuple(args_list), daemon=True, name=f"order-recovery-{key[-8:]}").start()
            _runtime_watchdog_alert_once(f"order-rescue-{key}", f"🔄 ORDER WATCHDOG | monitor da ordem {key} reiniciado em modo seguro.", every=5)
        except Exception as exc:
            _runtime_watchdog_alert_once(f"order-rescue-fail-{key}", f"⚠ ORDER WATCHDOG | falha ao reiniciar {key}: {str(exc)[:120]}", every=5)


def _runtime_watchdog_loop() -> None:
    global _STATE_LOCK_BUSY_STREAK
    while not _RUNTIME_WATCHDOG_STOP.wait(max(2, int(cfg_get("runtime_watchdog_interval_seconds", 5) or 5))):
        if not bool(cfg_get("runtime_watchdog_enabled", True)):
            continue
        _runtime_heartbeat("runtime_watchdog", "tick")
        acquired = state_lock.acquire(timeout=0.45)
        lock_busy = not acquired
        if lock_busy:
            _STATE_LOCK_BUSY_STREAK += 1
            owner = state_lock.snapshot()
            _runtime_heartbeat(
                "state_lock", "busy", streak=int(_STATE_LOCK_BUSY_STREAK),
                owner_thread=str(owner.get("owner_thread") or "?"), owner_site=str(owner.get("owner_site") or "?"),
                held_seconds=float(owner.get("held_seconds", 0) or 0),
            )
            if _STATE_LOCK_BUSY_STREAK >= 3:
                _runtime_watchdog_alert_once(
                    "state-lock-busy",
                    f"🚨 DEADLOCK GUARD V108.8.0 | state_lock ocupado por {_STATE_LOCK_BUSY_STREAK} verificações · "
                    f"owner={owner.get('owner_thread') or '?'} @ {owner.get('owner_site') or '?'} · "
                    f"preso há {float(owner.get('held_seconds',0) or 0):.1f}s.",
                    every=max(10, int(cfg_get("state_lock_watchdog_seconds", 5) or 5)),
                )
            running = bool(dict.get(state, "running", False))
        else:
            _STATE_LOCK_BUSY_STREAK = 0
            try:
                running = bool(state.get("running"))
            finally:
                state_lock.release()

        # V108.8.0: watchdog continua verificando heartbeats mesmo quando state_lock está ocupado.
        # Antes o `continue` escondia o verdadeiro ponto do stall e disparava tempestade de reconnect.
        if running:
            snap = _runtime_heartbeat_snapshot()
            bot_hb = dict(snap.get("bot_loop") or {})
            if bot_hb:
                age = float(bot_hb.get("age_seconds", 0) or 0)
                stall_s = max(20, int(cfg_get("runtime_watchdog_stall_seconds", 60) or 60))
                if age > stall_s:
                    owner = state_lock.snapshot()
                    bot_detail = str(bot_hb.get("detail") or "")
                    full_progress = dict(snap.get("full_scan_progress") or {})
                    elite_progress = dict(snap.get("elite_scan_progress") or {})
                    scan_progress = elite_progress if bot_detail == "elite_scan" else full_progress
                    progress_age = float(scan_progress.get("age_seconds", 999999) or 999999)
                    progress_grace = max(5, int(cfg_get("full_scan_progress_grace_seconds", 15) or 15))
                    in_full_scan = bot_detail == "full_scan"
                    in_elite_scan = bot_detail == "elite_scan"
                    next_full_at = float(dict.get(state, "next_scan_at", 0) or 0)
                    scheduler_idle = bot_detail in {"scheduler_wait", "scheduler_wake", "full_scan_done", "elite_scan_done", "loop_top"} and str(full_progress.get("detail") or "") in {"done", "deadline", ""} and (next_full_at <= 0 or next_full_at > time.time()-2)
                    if scheduler_idle:
                        continue
                    progressing = bool((in_full_scan or in_elite_scan) and scan_progress and progress_age <= progress_grace)
                    if progressing:
                        _runtime_watchdog_alert_once(
                            "bot-loop-slow-progress",
                            f"🟡 FULL SCAN lento porém vivo V108.8.0 | fase={scan_progress.get('detail','?')} · ativo={scan_progress.get('asset') or '-'} · "
                            f"progresso={int(scan_progress.get('current',0) or 0)}/{int(scan_progress.get('total',0) or 0)} · último avanço há {progress_age:.1f}s · NÃO reconectando Market Data.",
                            every=30,
                        )
                    else:
                        _runtime_watchdog_alert_once(
                            "bot-loop-stale",
                            f"🚨 BOT WATCHDOG V108.8.0 | loop principal sem heartbeat há {age:.0f}s · último={bot_hb.get('detail','?')} · "
                            f"scan_fase={scan_progress.get('detail','-')} · progresso_age={progress_age:.1f}s · state_lock owner={owner.get('owner_thread') or '-'} @ {owner.get('owner_site') or '-' }.",
                        )
                        phase_now = str(scan_progress.get("detail") or "")
                        market_related_stall = bool((in_full_scan or in_elite_scan) and phase_now in {"universe_snapshot", "candles", "technical"})
                        if not lock_busy and market_related_stall:
                            global _MARKET_DATA_WATCHDOG_LAST_RECONNECT
                            cooldown = max(10, int(cfg_get("market_data_watchdog_reconnect_cooldown_seconds", 30) or 30))
                            now_reconnect = time.time()
                            if now_reconnect - float(_MARKET_DATA_WATCHDOG_LAST_RECONNECT or 0) >= cooldown:
                                _MARKET_DATA_WATCHDOG_LAST_RECONNECT = now_reconnect
                                try:
                                    _market_api_invalidate(f"watchdog: FULL scan sem progresso em {phase_now}")
                                    _kick_market_data_connect(True)
                                except Exception:
                                    pass

        try:
            rp = _result_pipeline_snapshot()
            if float(rp.get("commit_age_seconds", 0) or 0) > 20:
                _runtime_watchdog_alert_once(
                    "result-commit-stall",
                    f"🚨 RESULT COMMIT STALLED V108.8.0 | order={rp.get('commit_active_order') or '-'} · "
                    f"stage={rp.get('commit_stage') or '-'} · {float(rp.get('commit_age_seconds',0) or 0):.0f}s · ledger já é canônico.",
                    every=20,
                )
            if float(rp.get("learning_age_seconds", 0) or 0) > 45:
                _runtime_watchdog_alert_once(
                    "result-learning-slow",
                    f"⚠ RESULT LEARNING lento V108.8.0 | order={rp.get('learning_active_order') or '-'} · "
                    f"stage={rp.get('learning_stage') or '-'} · {float(rp.get('learning_age_seconds',0) or 0):.0f}s · trader NÃO bloqueado.",
                    every=30,
                )
        except Exception:
            pass
        _recover_stale_order_monitors()

def _ensure_runtime_watchdog_thread() -> None:
    global _RUNTIME_WATCHDOG_THREAD
    if not bool(cfg_get("runtime_watchdog_enabled", True)):
        return
    if _RUNTIME_WATCHDOG_THREAD is not None and _RUNTIME_WATCHDOG_THREAD.is_alive():
        return
    _RUNTIME_WATCHDOG_STOP.clear()
    _RUNTIME_WATCHDOG_THREAD = threading.Thread(target=_runtime_watchdog_loop, daemon=True, name="runtime-watchdog")
    _RUNTIME_WATCHDOG_THREAD.start()
    _runtime_heartbeat("runtime_watchdog", "started")

def _normalize_profit_result(value: Any) -> Optional[float]:
    """Normaliza possíveis retornos de check_win_* para lucro/prejuízo líquido."""
    if value is None or value is False:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, (list, tuple)):
        # Algumas versões retornam (status, lucro) ou estruturas parecidas.
        nums = [v for v in value if isinstance(v, (int, float))]
        if nums:
            return float(nums[-1])
    if isinstance(value, dict):
        for key in ("profit", "win", "result", "amount", "value"):
            if isinstance(value.get(key), (int, float)):
                return float(value[key])
    return None


def wait_order_result_robust(
    api: Any,
    order_id: Any,
    amount: float,
    duration_seconds: int,
    balance_before: Optional[float],
    stop_event_obj: threading.Event,
) -> Tuple[Optional[float], str]:
    """Aguarda o resultado da ordem sem travar o painel.

    Estratégia:
    1. Espera a duração da operação expirar.
    2. Tenta medir resultado pelo saldo antes/depois, que é o método mais estável em conta PRACTICE.
    3. Se o saldo ainda não atualizou, tenta métodos check_win_* com timeout curto.
    4. Retorna None se nada confirmar dentro do prazo, evitando operação aberta fantasma.
    """
    try:
        duration_seconds = int(duration_seconds or 60)
    except Exception:
        duration_seconds = 60
    timeout_extra = int(cfg_get("result_timeout_seconds", CONFIG_DEFAULTS.get("result_timeout_seconds", 120)) or 120)
    start = time.time()
    expiry_at = start + max(5, duration_seconds) + 3
    deadline = expiry_at + max(20, timeout_extra)

    # Aguarda a vela/operação terminar, mas continua responsivo ao botão Parar.
    _order_monitor_beat(order_id, "waiting_expiry", expiry_at=round(expiry_at, 1))
    while time.time() < expiry_at:
        _order_monitor_beat(order_id, "waiting_expiry", remaining_seconds=max(0, int(expiry_at-time.time())))
        if stop_event_obj.wait(0.5):
            return None, "bot parado antes do resultado"

    last_error = "aguardando resultado"
    while time.time() < deadline:
        if stop_event_obj.is_set():
            return None, "bot parado antes do resultado"

        _order_monitor_beat(order_id, "polling_result")
        # 1) Fallback mais confiável para binária: diferença de saldo.
        if balance_before is not None:
            ok_bal, bal_value = _safe_broker_rpc("get_balance", api.get_balance, timeout=float(cfg_get("broker_balance_timeout_seconds",3.0) or 3.0))
            if ok_bal:
                try:
                    balance_after = float(bal_value)
                    diff = round(balance_after - float(balance_before), 2)
                    # Diferença positiva = WIN; negativa = LOSS. Ignora variação zero enquanto a API atualiza.
                    if abs(diff) >= 0.01:
                        return diff, "saldo antes/depois"
                except Exception as exc:
                    last_error = f"saldo inválido: {exc}"
            else:
                last_error = f"get_balance falhou: {bal_value}"

        # 2) Métodos da iqoptionapi, com timeout para não congelar o loop.
        for method_name in ("check_win_v4", "check_win_v3", "check_win_digital_v2", "check_win"):
            method = getattr(api, method_name, None)
            if not callable(method):
                continue
            _order_monitor_beat(order_id, f"rpc_{method_name}")
            ok, value = _safe_broker_rpc(f"result_{method_name}", method, args=(order_id,), timeout=float(cfg_get("broker_rpc_timeout_seconds",3.5) or 3.5))
            if not ok:
                last_error = f"{method_name}: {value}"
                continue
            profit = _normalize_profit_result(value)
            if profit is not None and abs(float(profit)) >= 0.01:
                return round(float(profit), 2), method_name

        stop_event_obj.wait(2.0)

    return None, f"timeout aguardando resultado; último detalhe: {last_error}"

def persist_closed_trade_result(
    trade_payload: Dict[str, Any], order_id: Any, signal_id: str, result: str, profit: float, result_source: str,
    signal_row: Optional[Dict[str, Any]] = None,
) -> Dict[str, bool]:
    """V99: persiste resultado executado em ledger + diário + Laboratório e recalibra já."""
    payload = dict(trade_payload or {})
    payload["order_id"] = str(order_id or "")
    payload["signal_id"] = str(signal_id or "")
    payload["result"] = str(result or "").upper()
    payload["profit"] = round(float(profit or 0), 2)
    payload["result_source"] = str(result_source or "")[:220]
    payload.setdefault("account_type", str(cfg_get("account_type") or "PRACTICE").upper())
    payload.setdefault("timestamp", datetime.now().isoformat(timespec="seconds"))

    ledger_ok = trade_ledger_finalize(
        order_id, signal_id, payload["result"], payload["profit"], result_source,
        {"asset": payload.get("asset"), "direction": payload.get("direction"), "account_type": payload.get("account_type"), "payout": payload.get("payout", 0),
         "amount": payload.get("amount", 0), "strategy": payload.get("strategy", "all_strategies"), "strategy_used": payload.get("strategy_used", ""),
         "strategy_used_key": payload.get("strategy_used_key", ""), "strategy_used_source": payload.get("strategy_used_source", "capturada"),
         "strategy_influences": list(payload.get("strategy_influences") or [])[:6], "regime_label": payload.get("regime_label", ""),
         **({"closed_at": payload.get("closed_at"), "closed_ts": payload.get("closed_ts")} if payload.get("closed_at") and payload.get("closed_ts") else {})},
    )
    daily_ok = True
    try:
        append_daily_trade(payload)
    except Exception as exc:
        daily_ok = False
        _append_trade_recovery_event({"event": "DAILY_HISTORY_RECOVERY", **payload, "error": str(exc)[:180]})
        log(f"Histórico diário: falha ao salvar {payload['result']}; resultado preservado no ledger/recovery journal: {str(exc)[:120]}", "warn")

    lab_ok = False
    try:
        lab_ok = signal_lab_mark_actual_result(order_id, payload["result"], payload["profit"], signal_id=signal_id, result_source=result_source, refresh_calibration=False)
        if not lab_ok:
            # Recupera o vínculo se uma versão anterior não capturou o sinal da rodada.
            linked_sid = signal_lab_mark_operated(
                str(payload.get("asset") or ""), str(payload.get("direction") or ""), order_id, signal_id=signal_id, row=signal_row or payload,
            )
            lab_ok = signal_lab_mark_actual_result(order_id, payload["result"], payload["profit"], signal_id=linked_sid, result_source=result_source, refresh_calibration=False)
        if lab_ok:
            _mark_adaptive_calibration_dirty()
            refresh_adaptive_calibration(True)
    except Exception as exc:
        _append_trade_recovery_event({"event": "SIGNAL_LAB_RECOVERY", **payload, "error": str(exc)[:180]})
        log(f"Adaptive Calibration: falha ao vincular resultado {payload['result']} ao sinal {signal_id or '-'}: {str(exc)[:120]}", "warn")

    if str(payload.get("account_type") or "").upper() == "REAL":
        log(
            f"💾 Resultado REAL persistido | order_id={str(order_id)} | signal_id={signal_id or '-'} | "
            f"ledger={'OK' if ledger_ok else 'RECOVERY'} · diário={'OK' if daily_ok else 'RECOVERY'} · laboratório={'OK' if lab_ok else 'PENDENTE'}.",
            "info" if ledger_ok and daily_ok and lab_ok else "warn",
        )
    return {"ledger": ledger_ok, "daily": daily_ok, "lab": lab_ok}



def _result_pipeline_meta_update(**patch: Any) -> None:
    with _RESULT_PIPELINE_META_LOCK:
        _RESULT_PIPELINE_META.update(patch)


def _result_pipeline_snapshot() -> Dict[str, Any]:
    now_ts = time.time()
    with _RESULT_PIPELINE_META_LOCK:
        snap = dict(_RESULT_PIPELINE_META)
    snap["commit_queue"] = int(_RESULT_COMMIT_QUEUE.qsize())
    snap["learning_queue"] = int(_RESULT_LEARNING_QUEUE.qsize())
    cts = float(snap.get("commit_started_ts", 0) or 0)
    lts = float(snap.get("learning_started_ts", 0) or 0)
    snap["commit_age_seconds"] = round(max(0.0, now_ts-cts), 1) if cts else 0.0
    snap["learning_age_seconds"] = round(max(0.0, now_ts-lts), 1) if lts else 0.0
    snap["threads"] = {
        "commit_alive": bool(_RESULT_COMMIT_THREAD is not None and _RESULT_COMMIT_THREAD.is_alive()),
        "learning_alive": bool(_RESULT_LEARNING_THREAD is not None and _RESULT_LEARNING_THREAD.is_alive()),
    }
    return snap


def _result_ledger_finalize_only(job: Dict[str, Any]) -> bool:
    payload = dict(job.get("trade_payload") or {})
    order_id = job.get("order_id")
    signal_id = str(job.get("signal_id") or "")
    result = str(job.get("result") or payload.get("result") or "").upper()
    profit = float(job.get("profit", payload.get("profit", 0)) or 0)
    source = str(job.get("result_source") or payload.get("result_source") or "")
    extra = {
        "asset": payload.get("asset"), "direction": payload.get("direction"),
        "account_type": payload.get("account_type"), "payout": payload.get("payout", 0),
        "amount": payload.get("amount", 0), "strategy": payload.get("strategy", "all_strategies"),
        "strategy_used": payload.get("strategy_used", ""), "strategy_used_key": payload.get("strategy_used_key", ""),
        "strategy_used_source": payload.get("strategy_used_source", "capturada"),
        "strategy_influences": list(payload.get("strategy_influences") or [])[:6],
        "regime_label": payload.get("regime_label", ""),
    }
    return trade_ledger_finalize(order_id, signal_id, result, profit, source, extra)


def _enqueue_result_learning(job: Dict[str, Any]) -> None:
    try:
        _RESULT_LEARNING_QUEUE.put_nowait(dict(job))
    except queue.Full:
        _append_trade_recovery_event({
            "event": "RESULT_LEARNING_QUEUE_FULL", "order_id": str(job.get("order_id") or ""),
            "result": str(job.get("result") or ""), "profit": float(job.get("profit", 0) or 0),
        })
        _emergency_console(f"⚠ RESULT LEARNING QUEUE cheia · #{job.get('order_id')} · aprendizado adiado; ledger preservado.")


def _process_result_commit_job(job: Dict[str, Any]) -> None:
    oid = str(job.get("order_id") or "")
    payload = dict(job.get("trade_payload") or {})
    result = str(job.get("result") or payload.get("result") or "").upper()
    profit = float(job.get("profit", payload.get("profit", 0)) or 0)
    signal_id = str(job.get("signal_id") or "")
    result_source = str(job.get("result_source") or "")
    signal_row = dict(job.get("signal_row") or {})
    ctx = dict(job.get("ctx") or {})

    _result_pipeline_meta_update(commit_active_order=oid, commit_stage="daily", commit_started_ts=time.time())
    daily_ok = True
    daily_summary = None
    try:
        daily_summary = append_daily_trade(payload, update_state=False)
    except Exception as exc:
        daily_ok = False
        _append_trade_recovery_event({"event": "DAILY_HISTORY_RECOVERY", **payload, "error": str(exc)[:180]})
        log(f"Histórico diário: falha ao salvar {result}; ledger já preservou #{oid}: {str(exc)[:120]}", "warn")
    if isinstance(daily_summary, dict):
        acquired = state_lock.acquire(timeout=0.08)
        if acquired:
            try:
                state["daily_summary"] = daily_summary
            finally:
                state_lock.release()

    _result_pipeline_meta_update(commit_stage="signal_lab")
    lab_ok = False
    def _commit_signal_lab() -> tuple:
        local_signal_id = signal_id
        ok_lab = signal_lab_mark_actual_result(
            oid, result, profit, signal_id=local_signal_id, result_source=result_source, refresh_calibration=False,
        )
        if not ok_lab:
            linked_sid = signal_lab_mark_operated(
                str(payload.get("asset") or ""), str(payload.get("direction") or ""), oid,
                signal_id=local_signal_id, row=signal_row or payload,
            )
            local_signal_id = linked_sid or local_signal_id
            ok_lab = signal_lab_mark_actual_result(
                oid, result, profit, signal_id=local_signal_id, result_source=result_source, refresh_calibration=False,
            )
        return bool(ok_lab), str(local_signal_id or "")
    try:
        lab_timeout = max(2.0, min(15.0, float(cfg_get("signal_lab_commit_timeout_seconds", 6.0) or 6.0)))
        lab_call_ok, lab_payload, lab_err = _call_daemon_timeout(_commit_signal_lab, lab_timeout)
        if lab_call_ok and isinstance(lab_payload, tuple):
            lab_ok, resolved_sid = bool(lab_payload[0]), str(lab_payload[1] or "")
            if resolved_sid:
                signal_id = resolved_sid
                job["signal_id"] = signal_id
                payload["signal_id"] = signal_id
        else:
            raise TimeoutError(f"Signal Lab excedeu {lab_timeout:.1f}s ({lab_err or 'timeout'})")
    except Exception as exc:
        _append_trade_recovery_event({"event": "SIGNAL_LAB_RECOVERY", **payload, "error": str(exc)[:180]})
        log(f"Signal Lab V108.8.0: resultado #{oid} adiado sem bloquear a fila: {str(exc)[:120]}", "warn")

    if lab_ok:
        _mark_adaptive_calibration_dirty()
        _kick_signal_lab_resolved_cache_refresh()

    # Martingale é estado operacional, mas só roda DEPOIS de ledger/diário/Lab e não chama broker/Ollama.
    mg_msg = ""
    if result == "LOSS" and str(payload.get("account_type") or "").upper() == "REAL" and bool(cfg_get("intelligent_martingale_enabled", False)):
        _result_pipeline_meta_update(commit_stage="martingale_state")
        try:
            armed, arm_reason = _arm_intelligent_martingale_after_loss(
                oid, str(payload.get("asset") or ""), str(payload.get("direction") or ""),
                float(payload.get("amount", 0) or 0), int(payload.get("payout", 0) or 0),
                int(payload.get("timeframe", 300) or 300), ctx,
            )
            mg_msg = ("🧠 Martingale Inteligente: " + arm_reason) if armed else ("🛡 Martingale Inteligente NÃO armado: " + arm_reason)
        except Exception as exc:
            mg_msg = f"🛡 Martingale Inteligente: falha isolada ao armar recuperação: {str(exc)[:120]}"
            log(mg_msg, "warn")
    job["mg_msg"] = mg_msg

    _result_pipeline_meta_update(commit_stage="learning_queue")
    _enqueue_result_learning(job)
    committed = int(_RESULT_PIPELINE_META.get("committed", 0) or 0) + 1
    _result_pipeline_meta_update(
        committed=committed, commit_active_order="", commit_stage="idle", commit_started_ts=0.0,
        last_completed_order=oid, last_completed_at=now_hms(),
    )
    if str(payload.get("account_type") or "").upper() == "REAL":
        log(
            f"💾 Resultado REAL persistido V108.8.0 | order_id={oid} | signal_id={signal_id or '-'} | "
            f"ledger={'OK' if bool(job.get('ledger_ok')) else 'RECOVERY'} · diário={'OK' if daily_ok else 'RECOVERY'} · "
            f"laboratório={'OK' if lab_ok else 'PENDENTE'} · aprendizado=ASSÍNCRONO.",
            "info" if bool(job.get("ledger_ok")) and daily_ok and lab_ok else "warn",
        )


def _result_commit_worker() -> None:
    _runtime_heartbeat("result_commit", "started")
    while not _RESULT_PIPELINE_STOP.is_set():
        try:
            job = _RESULT_COMMIT_QUEUE.get(timeout=0.5)
        except queue.Empty:
            _runtime_heartbeat("result_commit", "idle", queue=int(_RESULT_COMMIT_QUEUE.qsize()))
            continue
        try:
            _runtime_heartbeat("result_commit", "processing", order_id=str(job.get("order_id") or ""))
            _process_result_commit_job(job)
        except Exception as exc:
            with _RESULT_PIPELINE_META_LOCK:
                _RESULT_PIPELINE_META["failures"] = int(_RESULT_PIPELINE_META.get("failures", 0) or 0) + 1
                _RESULT_PIPELINE_META["last_error"] = str(exc)[:240]
                _RESULT_PIPELINE_META["commit_active_order"] = ""
                _RESULT_PIPELINE_META["commit_stage"] = "idle"
                _RESULT_PIPELINE_META["commit_started_ts"] = 0.0
            _append_trade_recovery_event({
                "event": "RESULT_COMMIT_WORKER_ERROR", "order_id": str(job.get("order_id") or ""),
                "result": str(job.get("result") or ""), "profit": float(job.get("profit", 0) or 0), "error": str(exc)[:220],
            })
            _emergency_console(f"🚨 RESULT COMMIT isolado falhou #{job.get('order_id')}: {str(exc)[:180]}")
        finally:
            _RESULT_COMMIT_QUEUE.task_done()


def _process_result_learning_job(job: Dict[str, Any]) -> None:
    oid = str(job.get("order_id") or "")
    payload = dict(job.get("trade_payload") or {})
    result = str(job.get("result") or payload.get("result") or "").upper()
    asset = str(payload.get("asset") or "")
    direction = str(payload.get("direction") or "")
    amount = float(payload.get("amount", 0) or 0)
    confidence = int(payload.get("confidence", 0) or 0)
    payout = int(payload.get("payout", 0) or 0)
    signals = dict(job.get("signals") or {})
    closed = list(job.get("closed") or [])
    result_source = str(job.get("result_source") or "")
    duration_seconds = int(payload.get("timeframe", 300) or 300)
    ctx = dict(job.get("ctx") or {})

    _result_pipeline_meta_update(learning_active_order=oid, learning_stage="memory", learning_started_ts=time.time())
    try:
        if result == "WIN":
            record_win_pattern(asset, direction, amount, confidence, payout, signals, closed, result_source, duration_seconds, schedule_factory=False)
        elif result == "LOSS":
            record_loss_pattern(asset, direction, amount, confidence, payout, signals, closed, result_source, duration_seconds)
    except Exception as exc:
        log(f"{result} Memory: falha isolada no aprendizado de #{oid}: {str(exc)[:120]}", "warn")

    _result_pipeline_meta_update(learning_stage="strategy_stats")
    try:
        record_strategy_usage(
            {"primary_strategy_key": ctx.get("strategy_used_key"), "primary_strategy_name": ctx.get("strategy_used")},
            asset, direction, "win" if result == "WIN" else "loss", force_save=True,
        )
    except Exception:
        pass

    _result_pipeline_meta_update(learning_stage="adaptive_calibration")
    try:
        _mark_adaptive_calibration_dirty()
        refresh_adaptive_calibration(True)
    except Exception as exc:
        log(f"Adaptive Calibration assíncrona: falha após #{oid}: {str(exc)[:120]}", "warn")

    _result_pipeline_meta_update(learning_stage="context_loss_intelligence")
    try:
        refresh_adaptive_loss_intelligence_cache(True)
        ctx_now = adaptive_loss_context_for_row({"asset":asset,"direction":direction,"technical_confidence":confidence,"strategy_used_key":ctx.get("strategy_used_key"),"strategy_used":ctx.get("strategy_used"),"regime_label":ctx.get("regime_label"),"signals":signals}, {"confidence":int(ctx.get("lumi_confidence",0) or 0)})
        if int(ctx_now.get("samples",0) or 0) > 0:
            log(f"🧠 Adaptive Loss Intelligence 2.5 V109.2 | {ctx_now.get('reason')} · ajuste {int(ctx_now.get('adjustment',0)):+d} · próximo tech +{int(ctx_now.get('tech_extra',0))}pp · Lumi +{int(ctx_now.get('lumi_extra',0))}pp.", "warn" if float(ctx_now.get("edge_pp",0) or 0)<0 else "info")
    except Exception as exc:
        log(f"Adaptive Loss Intelligence: falha isolada após #{oid}: {str(exc)[:120]}", "warn")

    _result_pipeline_meta_update(learning_stage="wallstreet_learning")
    try:
        learning_now = wallstreet_recent_learning_context()
        if result == "WIN":
            log(f"🧠 Autoaprendizado REAL: {learning_now.get('recent_wins',0)}W/{learning_now.get('recent_losses',0)}L recentes · edge {float(learning_now.get('edge',0)):+.1f}pp · sequência LOSS={learning_now.get('loss_streak',0)}.", "info")
        else:
            log(f"🛡 Autoaprendizado REAL 2.0 após LOSS: técnica +{learning_now.get('tech_boost',0)}pp · Lumi +{learning_now.get('lumi_boost',0)}pp · edge {float(learning_now.get('edge',0)):+.1f}pp · streak={learning_now.get('loss_streak',0)} · modo={learning_now.get('recovery_mode','normal')} · paralelismo efetivo={get_max_concurrent_open_orders()}.", "warn")
    except Exception:
        pass

    # Factory é uma terceira thread já existente; aqui apenas agendamos após o commit/aprendizado.
    if result == "WIN":
        _result_pipeline_meta_update(learning_stage="factory_schedule")
        try:
            kick_ai_strategy_factory(False)
        except Exception as exc:
            log(f"Strategy Factory: falha ao agendar após WIN #{oid}: {str(exc)[:100]}", "warn")

    learned = int(_RESULT_PIPELINE_META.get("learning_completed", 0) or 0) + 1
    _result_pipeline_meta_update(
        learning_completed=learned, learning_active_order="", learning_stage="idle", learning_started_ts=0.0,
    )


def _result_learning_worker() -> None:
    _runtime_heartbeat("result_learning", "started")
    while not _RESULT_PIPELINE_STOP.is_set():
        try:
            job = _RESULT_LEARNING_QUEUE.get(timeout=0.5)
        except queue.Empty:
            _runtime_heartbeat("result_learning", "idle", queue=int(_RESULT_LEARNING_QUEUE.qsize()))
            continue
        try:
            _runtime_heartbeat("result_learning", "processing", order_id=str(job.get("order_id") or ""))
            _process_result_learning_job(job)
        except Exception as exc:
            with _RESULT_PIPELINE_META_LOCK:
                _RESULT_PIPELINE_META["failures"] = int(_RESULT_PIPELINE_META.get("failures", 0) or 0) + 1
                _RESULT_PIPELINE_META["last_error"] = str(exc)[:240]
                _RESULT_PIPELINE_META["learning_active_order"] = ""
                _RESULT_PIPELINE_META["learning_stage"] = "idle"
                _RESULT_PIPELINE_META["learning_started_ts"] = 0.0
            _emergency_console(f"⚠ RESULT LEARNING isolado falhou #{job.get('order_id')}: {str(exc)[:180]}")
        finally:
            _RESULT_LEARNING_QUEUE.task_done()


def _ensure_result_pipeline_threads() -> None:
    global _RESULT_COMMIT_THREAD, _RESULT_LEARNING_THREAD
    _RESULT_PIPELINE_STOP.clear()
    if _RESULT_COMMIT_THREAD is None or not _RESULT_COMMIT_THREAD.is_alive():
        _RESULT_COMMIT_THREAD = threading.Thread(target=_result_commit_worker, daemon=True, name="result-commit-worker")
        _RESULT_COMMIT_THREAD.start()
    if _RESULT_LEARNING_THREAD is None or not _RESULT_LEARNING_THREAD.is_alive():
        _RESULT_LEARNING_THREAD = threading.Thread(target=_result_learning_worker, daemon=True, name="result-learning-worker")
        _RESULT_LEARNING_THREAD.start()


def _enqueue_result_commit(job: Dict[str, Any]) -> bool:
    _ensure_result_pipeline_threads()
    try:
        _RESULT_COMMIT_QUEUE.put_nowait(dict(job))
        with _RESULT_PIPELINE_META_LOCK:
            _RESULT_PIPELINE_META["queued"] = int(_RESULT_PIPELINE_META.get("queued", 0) or 0) + 1
        _runtime_heartbeat("result_commit", "queued", order_id=str(job.get("order_id") or ""), queue=int(_RESULT_COMMIT_QUEUE.qsize()))
        return True
    except queue.Full:
        _append_trade_recovery_event({
            "event": "RESULT_COMMIT_QUEUE_FULL", "order_id": str(job.get("order_id") or ""),
            "result": str(job.get("result") or ""), "profit": float(job.get("profit", 0) or 0),
        })
        _emergency_console(f"🚨 RESULT COMMIT QUEUE cheia · #{job.get('order_id')} · ledger preservado; recovery journal criado.")
        return False

def monitor_open_order_result(
    api: Any, order_id: Any, asset: str, direction: str, amount: float, confidence: int,
    signals: Dict[str, Any], closed: Optional[List[Tuple[int, float]]], duration_seconds: int, balance_before: Optional[float],
    trade_context: Optional[Dict[str, Any]] = None,
) -> None:
    """V108.8.0: monitor captura o resultado; persistência/aprendizado nunca bloqueiam a ordem.

    Ordem de segurança:
      1) captura WIN/LOSS e reivindica finalização única;
      2) remove open_order e atualiza contadores em um state_lock curtíssimo;
      3) finaliza o LEDGER fora do state_lock;
      4) enfileira diário/Lab e aprendizado em workers independentes.
    """
    ctx = dict(trade_context or {})
    signal_id = str(ctx.get("signal_id") or "")
    account_type_at_open = str(ctx.get("account_type") or cfg_get("account_type") or "PRACTICE").upper()
    payout_at_open = int(ctx.get("payout", 0) or 0)
    signal_row = ctx.get("signal_row") if isinstance(ctx.get("signal_row"), dict) else {}
    recovery_args = (api, order_id, asset, direction, amount, confidence, dict(signals or {}), list(closed or []), duration_seconds, balance_before, dict(ctx))
    _order_monitor_register(order_id, asset, direction, recovery_args, ctx)
    result, result_source = wait_order_result_robust(api, order_id, amount, duration_seconds, balance_before, stop_event)
    _order_monitor_beat(order_id, "result_returned", source=str(result_source)[:80], result=result)
    if result is not None and not _claim_order_finalization(order_id):
        _order_monitor_done(order_id, "duplicate_finalizer_ignored")
        return

    acquired = state_lock.acquire(timeout=0.50)
    if acquired:
        try:
            state["open_orders"] = [o for o in list(dict.get(state, "open_orders", []) or []) if o.get("id") != order_id]
        finally:
            state_lock.release()
    else:
        _emergency_console(f"⚠ RESULT #{order_id}: state_lock ocupado ao remover open_order; monitor seguirá e watchdog reconciliará UI.")

    if stop_event.is_set() and result is None:
        _order_monitor_done(order_id, "stopped")
        return
    if result is None:
        update_decision_diagnostic("resultado_pendente", asset, direction, "Resultado da ordem não confirmado pela API.", f"A ordem foi aberta, mas a iqoptionapi não confirmou WIN/LOSS no prazo. Motivo: {result_source}.", "aguardar próxima varredura", 30, [make_step("Ordem aberta", True, str(order_id)), make_step("Resultado", False, str(result_source))])
        trade_ledger_mark_pending(order_id, signal_id, str(result_source))
        log(f"Resultado da ordem não confirmado no prazo. ID: {order_id} | Motivo: {result_source}", "error")
        telegram_notify_async(f"⚠️ <b>Resultado não confirmado</b>\n\nID: <code>{telegram_html_escape(order_id)}</code>\nAtivo: <b>{telegram_html_escape(asset)}</b>\nMotivo: <code>{telegram_html_escape(result_source)}</code>", "errors")
        _update_balance_nonblocking(api, "resultado não confirmado")
        _order_monitor_done(order_id, "pending_unconfirmed")
        return

    is_win = float(result) > 0
    result_label = "WIN" if is_win else "LOSS"
    profit = round(float(result), 2) if is_win else -round(abs(float(amount or 0)), 2)
    trade_payload = {
        "result": result_label, "profit": profit, "amount": amount, "asset": asset, "time": now_hms(),
        "timestamp": datetime.now().isoformat(timespec="seconds"), "confidence": confidence,
        "loss_memory": not is_win, "direction": direction, "order_id": str(order_id), "signal_id": signal_id,
        "account_type": account_type_at_open, "payout": payout_at_open, "result_source": str(result_source),
        "timeframe": int(duration_seconds), "strategy": str(ctx.get("strategy") or cfg_get("strategy") or "all_strategies"),
        "strategy_used": str(ctx.get("strategy_used") or ""), "strategy_used_key": str(ctx.get("strategy_used_key") or ""),
        "strategy_used_source": str(ctx.get("strategy_used_source") or "capturada"),
        "strategy_influences": list(ctx.get("strategy_influences") or [])[:6], "regime_label": str(ctx.get("regime_label") or ""),
        "adaptive_premium_override": bool(ctx.get("adaptive_premium_override")),
        "adaptive_premium_gap_pp": int(ctx.get("adaptive_premium_gap_pp", 0) or 0),
        "adaptive_premium_reason": str(ctx.get("adaptive_premium_reason") or "")[:320],
    }

    pnl_now = 0.0
    acquired = state_lock.acquire(timeout=0.75)
    if acquired:
        try:
            state["trade_count"] = int(dict.get(state, "trade_count", 0) or 0) + 1
            if is_win:
                state["wins"] = int(dict.get(state, "wins", 0) or 0) + 1
                state["loss_streak"] = 0
                state["pnl"] = float(dict.get(state, "pnl", 0) or 0) + profit
                state["current_amount"] = float(dict.get(state, "amount", amount) or amount)
                if bool(ctx.get("martingale_intelligent")):
                    state["martingale_count"] = 0
                    state["martingale_pending"] = False
                    state["martingale_pending_context"] = {}
                    state["martingale_last_decision"] = {"decision": "win_reset", "reason": "WIN da recuperação encerrou somente este ciclo", "time": now_hms()}
            else:
                state["losses"] = int(dict.get(state, "losses", 0) or 0) + 1
                state["loss_streak"] = int(dict.get(state, "loss_streak", 0) or 0) + 1
                state["pnl"] = float(dict.get(state, "pnl", 0) or 0) + profit
            pnl_now = float(dict.get(state, "pnl", 0) or 0)
            hist = list(dict.get(state, "history", []) or [])
            hist.insert(0, trade_payload)
            state["history"] = hist[:50]
        finally:
            state_lock.release()
    else:
        # Ledger é a fonte canônica. Falha de UI/contador não pode impedir a persistência do dinheiro REAL.
        _emergency_console(f"🚨 RESULT #{order_id}: state_lock ocupado; ledger será finalizado sem esperar contador/UI.")

    job = {
        "order_id": str(order_id), "signal_id": signal_id, "result": result_label, "profit": profit,
        "result_source": str(result_source), "trade_payload": trade_payload, "signal_row": dict(signal_row or {}),
        "ctx": dict(ctx), "signals": dict(signals or {}), "closed": list(closed or []),
    }
    _order_monitor_beat(order_id, "ledger_commit")
    ledger_ok = _result_ledger_finalize_only(job)
    job["ledger_ok"] = bool(ledger_ok)
    if account_type_at_open == "REAL" and ledger_ok:
        # V108.9: a LOSS/WIN entra no cérebro temporal imediatamente após o ledger canônico,
        # sem esperar a próxima rodada completa nem a virada do worker de calibração.
        schedule_adaptive_loss_intelligence_refresh("real_result_captured")
    if not ledger_ok:
        _append_trade_recovery_event({"event": result_label, **trade_payload, "error": "ledger finalize retornou False"})
    queued = _enqueue_result_commit(job)
    log(
        f"🧾 RESULT CAPTURED V108.8.0 | #{order_id} {asset} {direction.upper()} → {result_label} {profit:+.2f} · "
        f"ledger={'OK' if ledger_ok else 'RECOVERY'} · commit={'QUEUE' if queued else 'RECOVERY'} · monitor liberado.",
        "win" if is_win else "loss",
    )

    if is_win:
        log(f"✅ WIN | {asset} {direction.upper()} | +${profit:.2f} | Estratégia: {ctx.get('strategy_used') or 'ALL_STRATEGIES'} | P&L sessão: ${pnl_now:.2f}", "win")
        telegram_notify_async(f"✅ <b>WIN</b>\n\nAtivo: <b>{telegram_html_escape(asset)}</b>\nDireção: <b>{direction.upper()}</b>\nLucro: <b>+${profit:.2f}</b>\nP&L sessão: <b>${pnl_now:+.2f}</b>", "results")
    else:
        log(f"❌ LOSS | {asset} {direction.upper()} | -${abs(profit):.2f} | Estratégia: {ctx.get('strategy_used') or 'ALL_STRATEGIES'} | P&L sessão: ${pnl_now:.2f}", "loss")
        telegram_notify_async(f"❌ <b>LOSS</b>\n\nAtivo: <b>{telegram_html_escape(asset)}</b>\nDireção: <b>{direction.upper()}</b>\nPerda: <b>-${abs(profit):.2f}</b>\nP&L sessão: <b>${pnl_now:+.2f}</b>", "results")

    _update_balance_nonblocking(api, "ordem encerrada")
    _order_monitor_done(order_id, "commit_queued" if queued else "ledger_finalized_recovery")
    try:
        _martingale_promote_next_queued("ordem encerrada")
    except Exception:
        pass

def bot_loop(run_token: int) -> None:
    api = state["api"]
    pnl_session = 0.0
    _ensure_runtime_watchdog_thread()
    _ensure_result_pipeline_threads()
    _runtime_heartbeat("bot_loop", "starting", run_token=int(run_token))
    # Ativa modo agente financeiro full no start
    with state_lock:
        state["scanner_enabled"] = True
        if str(cfg_get("strategy") or "").lower() not in VALID_STRATEGIES:
            state["strategy"] = "all_strategies"
        # Preferência do agente full: varrer o book inteiro
        if not cfg_get("strategy") or cfg_get("strategy") in {"combined", "rsi", "ema", "macd", "bb"}:
            state["strategy"] = "all_strategies"
        state["lumi_enabled"] = True
        # V104: Loss/Win Memory e aprendizado adaptativo ficam ativos no agente full.
        state["loss_memory_enabled"] = True
        state["win_memory_enabled"] = True
        state["wallstreet_adaptive_enabled"] = True
        # Fallback permanece disponível se a Lumi cair, porém em REAL só passa como
        # fallback FORTE (técnica elevada + payout + EV + filtros anti-extremo).
        state["technical_fallback_enabled"] = True
        state["technical_fallback_allow_real"] = True
        state["real_requires_lumi_or_strong_fallback"] = True
        # No modo agente FULL, HOLD da Lumi é uma abstenção, não um veto absoluto.
        # A técnica forte só passa pelo fallback se payout e filtros anti-extremo também aprovarem.
        state["lumi_hold_can_override_strong_tech"] = False
        is_real_full = str(cfg_get("account_type", "PRACTICE")).upper() == "REAL"
        if is_real_full:
            # Pisos profissionais V104 em REAL: UI/agente podem endurecer, nunca afrouxar.
            state["min_technical_confidence"] = max(58, int(cfg_get("min_technical_confidence", 58) or 58))
            state["lumi_min_confidence"] = max(62, int(cfg_get("lumi_min_confidence", 62) or 62))
            state["min_payout"] = max(70, int(cfg_get("min_payout", 70) or 70))
            # V105: Martingale simples continua proibido em REAL. O modo Inteligente
            # é separado e só aumenta stake após gate Laboratório + Lumi + risco.
            state["martingale"] = False
            state["martingale_count"] = 0
            state["martingale_pending"] = False
            state["martingale_pending_context"] = {}
            state["current_amount"] = state["amount"]
        fallback_policy_floor = max(REAL_HARD_TECH_FLOOR if is_real_full else 60, int(cfg_get("min_technical_confidence", 55) or 55))
        # V104: fallback sem confirmação da Lumi precisa ser significativamente mais forte.
        state["technical_fallback_min_confidence"] = fallback_policy_floor
        state["technical_fallback_min_confidence_real"] = max(REAL_HARD_TECH_FLOOR, fallback_policy_floor)
        state["technical_fallback_min_confidence_demo"] = max(60, min(fallback_policy_floor, 68))
        if int(cfg_get("technical_fallback_min_payout_real", 0) or 0) <= 0:
            state["technical_fallback_min_payout_real"] = 70
        if int(cfg_get("technical_fallback_min_payout_demo", 0) or 0) <= 0:
            state["technical_fallback_min_payout_demo"] = 70
        if int(cfg_get("technical_fallback_max_session_real", 0) or 0) < 50:
            state["technical_fallback_max_session_real"] = 500
        if int(cfg_get("technical_fallback_max_session_demo", 0) or 0) < 50:
            state["technical_fallback_max_session_demo"] = 1000
        # HOLD block curto para não travar o scanner quando IA falha
        if int(cfg_get("lumi_hold_block_candles", 3) or 3) > 2:
            state["lumi_hold_block_candles"] = 1
        agent = dict(cfg_get("lumi_agent") or _default_lumi_agent_state())
        agent["enabled"] = True
        agent["autonomous"] = True
        agent["phase"] = "monitoring"
        agent["status"] = "Agente financeiro FULL V108 online · WIN/LOSS + Shadow recalibram seletividade; MG Inteligente exige IA + Laboratório + risco."
        agent["active_strategy"] = str(cfg_get("strategy") or "all_strategies")
        state["lumi_agent"] = agent
        # Força uma varredura completa ao iniciar; depois o Elite Watcher ocupa os intervalos.
        state["next_scan_at"] = 0
        state["next_scan_in_seconds"] = 0
        state["elite_watcher"] = {"enabled": bool(cfg_get("elite_opportunity_watcher_enabled", True)), "status": "aguardando primeira varredura completa", "updated_at": now_hms(), "last_poll_ts": time.time(), "selected": 0, "eligible": 0, "assets": []}

    log(f"Bot iniciado | Ativo: {state['asset']} | Playbook: {str(state['strategy']).upper()}", "info")
    log("⚡ LUMI WALL STREET V108.8.0 · MARKET INTELLIGENCE 2.0 + AGENTE FINANCEIRO: técnica + MTF + Lumi + EV + Anti-Chase + WIN/LOSS Memory + Shadow com guardrails.", "info")
