@app.route("/api/health", methods=["GET"])
def integrated_lumi_health():
    try:
        url = _ollama_api_url("tags")
        req = urllib.request.Request(url, headers={"Accept": "application/json"}, method="GET")
        with urllib.request.urlopen(req, timeout=3) as resp:
            data = json.loads(resp.read().decode("utf-8", errors="replace"))
        names = [str((m or {}).get("name") or "") for m in (data.get("models") or []) if isinstance(m, dict)]
        return jsonify({
            "ok": True, "integrated": True, "server": "iqbot_server.py", "port": 5001,
            "ollama_url": _ollama_url_normalized(), "trader_model": str(cfg_get("ollama_model") or OLLAMA_DEFAULT_MODEL),
            "trader_model_available": str(cfg_get("ollama_model") or OLLAMA_DEFAULT_MODEL) in names,
            "analyst_model": LUMI_ANALYST_MODEL, "analyst_model_available": LUMI_ANALYST_MODEL in names,
            "models": names[:80],
        })
    except Exception as exc:
        return jsonify({"ok": False, "integrated": True, "error": short_lumi_error(exc), "ollama_url": _ollama_url_normalized()}), 503


