@app.route("/api/analisar-sinal", methods=["POST", "OPTIONS"])
def integrated_lumi_signal_api():
    """Endpoint compatível no mesmo :5001; o scanner interno NÃO usa HTTP para chamá-lo."""
    if request.method == "OPTIONS":
        return ("", 204)
    data = request.get_json(silent=True) or {}
    contexto = data.get("contexto") if isinstance(data.get("contexto"), dict) else None
    if contexto is None:
        raw = str(data.get("mensagem") or "").strip()
        if raw:
            try:
                obj = json.loads(raw)
                contexto = obj if isinstance(obj, dict) else {"mensagem": raw}
            except Exception:
                contexto = {"mensagem": raw}
        else:
            contexto = data
    if not isinstance(contexto, dict) or not contexto:
        return jsonify({"ok": False, "error": "Contexto vazio."}), 400
    try:
        result = call_ollama_lumi(json.dumps(contexto, ensure_ascii=False, separators=(",", ":")), float(cfg_get("ollama_timeout_seconds", 12.5) or 12.5))
        return jsonify({"ok": True, "provider": "ollama_integrado", "model": result.get("model"), "resposta": result})
    except Exception as exc:
        return jsonify({"ok": False, "provider": "ollama_integrado", "error": short_lumi_error(exc), "detail": str(exc)[:500]}), 504 if "timeout" in short_lumi_error(exc).lower() else 500


