@app.route("/api/candle-intelligence")
def candle_intelligence_route():
    try:
        asset = normalize_asset_name(request.args.get("asset") or cfg_get("signal_panel_asset") or cfg_get("asset") or "EURUSD")
        try: tf = int(request.args.get("tf") or cfg_get("timeframe",300) or 300)
        except Exception: tf = 300
        if tf not in {60,300,900}: tf = 300
        count=max(30,min(120,int(cfg_get("candle_chart_candles",60) or 60)))
        trade_api=cfg_get("api")
        api=get_market_data_api(trade_api) if trade_api is not None else cfg_get("market_api")
        if api is None:
            return jsonify({"ok":False,"error":"sessão de mercado indisponível"}),503
        bundle=get_candle_bundle_cached(api,asset,tf,max(64,count))
        ohlc=list(bundle.get("ohlc") or [])[-count:]
        if len(ohlc)<12:
            return jsonify({"ok":False,"error":"candles insuficientes","asset":asset,"tf":tf}),404
        closes=[float(c.get("close",0)) for c in ohlc]
        decision=analyze_closes(closes,str(cfg_get("strategy","combined")))
        intel=build_candle_intelligence(ohlc,decision.signals,decision.direction)
        # Marcações do laboratório/REAL sobre o gráfico sem nova consulta externa.
        with signal_lab_lock:
            records=list((_signal_lab_store().get("records") or []))
        min_ts=int(ohlc[0].get("ts",0) or 0); max_ts=int(ohlc[-1].get("ts",0) or 0)+tf
        marks=[]
        for r in records:
            if normalize_asset_name(r.get("asset",""))!=asset: continue
            rtf=int(r.get("timeframe_seconds") or r.get("shadow_horizon_seconds") or tf)
            if rtf!=tf: continue
            ts=int(r.get("signal_candle_ts") or r.get("created_ts") or 0)
            if ts>10_000_000_000: ts=int(ts/1000)
            if ts<min_ts or ts>max_ts: continue
            actual=str(r.get("actual_result") or "").upper()
            shadow=str(r.get("result") or "").upper()
            marks.append({"ts":ts,"direction":normalize_lumi_action(r.get("direction") or "hold"),"kind":"REAL" if r.get("operated") else "SHADOW","result":actual or shadow,"technical":int(r.get("technical_confidence",0) or 0),"candle_score":int(r.get("candle_score",0) or 0),"shadow_class":str(r.get("shadow_class") or "")})
        # Série EMA para o canvas local.
        def ema_series(values,period):
            alpha=2.0/(period+1.0); out=[]; e=None
            for v in values:
                e=v if e is None else alpha*v+(1-alpha)*e; out.append(e)
            return out
        ema9=ema_series(closes,9); ema21=ema_series(closes,21)
        candles=[]
        for i,c in enumerate(ohlc):
            candles.append({"ts":int(c.get("ts",0)),"open":float(c.get("open",0)),"high":float(c.get("high",0)),"low":float(c.get("low",0)),"close":float(c.get("close",0)),"ema9":round(ema9[i],8),"ema21":round(ema21[i],8)})
        return jsonify({"ok":True,"asset":asset,"tf":tf,"cache_hit":bool(bundle.get("cache_hit")),"direction":decision.direction or "hold","technical":decision.confidence,"signals":decision.signals,"intelligence":intel,"candles":candles,"marks":marks,"updated_at":now_hms()})
    except Exception as e:
        return jsonify({"ok":False,"error":str(e)[:240]}),500


