def _lumi_decision_explanation(rec: Dict[str, Any]) -> str:
    """V109.4: explicação auditável da decisão, incluindo fallback técnico sem atribuí-lo à Lumi."""
    raw = int(rec.get("lumi_confidence", 0) or 0)
    eff = int(rec.get("lumi_effective_confidence", raw) or raw)
    req = int(rec.get("lumi_required", 0) or 0)
    action = str(rec.get("lumi_action") or "HOLD").upper()
    lumi_source = str(rec.get("lumi_source") or rec.get("source") or "").lower()
    technical_fallback = "technical_fallback" in lumi_source or str(rec.get("decision_stage") or "").lower() == "fallback_tecnico"
    operated = bool(rec.get("operated"))
    sup = rec.get("trader_supervisor") if isinstance(rec.get("trader_supervisor"), dict) else {}
    sup_action = str(rec.get("trader_supervisor_action") or sup.get("action") or ("TRADE" if operated else "REJECT")).upper()
    floors = list(sup.get("floors") or [])
    parts: List[str] = []
    if technical_fallback:
        tech = int(rec.get("technical_confidence", 0) or 0)
        parts.append(f"A Lumi 4B não concluiu a análise; o sistema usou fallback técnico {action} com {tech or raw}% de confiança técnica.")
        parts.append("Esse valor não é confiança da Lumi e não deve ser interpretado como opinião do modelo.")
    elif raw > 0 and eff > 0 and raw != eff:
        parts.append(f"A Lumi indicou {action} com {raw}% bruto, mas a calibração histórica reduziu a confiança efetiva para {eff}%.")
    elif raw > 0:
        parts.append(f"A Lumi indicou {action} com {raw}% de confiança.")
    if not technical_fallback and req > 0 and eff < req:
        parts.append(f"Para a entrada atual eram necessários {req}% efetivos; faltaram {req-eff} p.p.")
    if floors:
        pretty = {"Lumi absoluta":"Lumi efetiva abaixo do piso", "gap Lumi":"gap da Lumi", "tech absoluto":"técnica abaixo do piso", "gap tech":"gap técnico", "qualidade":"qualidade", "candle":"Candle", "price action":"Price Action", "MTF":"MTF"}
        parts.append("O Supervisor encontrou: " + ", ".join(pretty.get(str(x), str(x)) for x in floors) + ".")
    blocker = str(rec.get("block_reason") or rec.get("counterfactual_blocker") or "").strip()
    if operated:
        parts.append("A decisão chegou à execução e existe order_id vinculado.")
    elif sup_action == "TRADE":
        parts.append("O Supervisor marcou TRADE, mas nenhuma ordem foi registrada; a oportunidade não concluiu a etapa final de execução/preflight.")
    elif sup_action == "WATCH":
        parts.append("O Supervisor preferiu observar em Shadow, sem usar dinheiro REAL.")
    else:
        parts.append("A decisão final foi não entrar.")
    if blocker and blocker.lower() not in " ".join(parts).lower():
        parts.append(f"Motivo registrado: {blocker[:180]}.")
    return " ".join(parts)[:700]


def _lumi_decision_row(rec: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    raw = int(rec.get("lumi_confidence", 0) or 0)
    action = str(rec.get("lumi_action") or "").lower()
    if raw <= 0 and action not in {"call", "put", "hold"}:
        return None
    sup = rec.get("trader_supervisor") if isinstance(rec.get("trader_supervisor"), dict) else {}
    operated = bool(rec.get("operated"))
    actual = str(rec.get("actual_result") or "").upper()
    shadow = str(rec.get("result") or "").upper()
    if operated:
        display_result = actual if actual in {"WIN","LOSS"} else "PENDING"
        result_source = "REAL" if actual in {"WIN","LOSS"} else "REAL_PENDING"
    else:
        display_result = shadow if shadow in {"WIN","LOSS","DRAW"} else "PENDING"
        result_source = "SHADOW" if display_result in {"WIN","LOSS","DRAW"} else "SHADOW_PENDING"
    sup_action = str(rec.get("trader_supervisor_action") or sup.get("action") or ("TRADE" if operated else "REJECT")).upper()
    floors = list(sup.get("floors") or [])
    return {
        "id": str(rec.get("signal_id") or rec.get("id") or ""),
        "created_at": str(rec.get("created_at") or ""),
        "asset": normalize_asset_name(rec.get("asset", "")),
        "direction": str(rec.get("direction") or "HOLD").upper(),
        "strategy": str(rec.get("strategy_used") or rec.get("strategy") or "Não identificada"),
        "regime": str(rec.get("regime_label") or rec.get("regime") or ""),
        "technical": int(rec.get("technical_confidence", 0) or 0),
        "technical_required": int(rec.get("technical_required", 0) or 0),
        "payout": int(rec.get("payout", 0) or 0),
        "lumi_action": str(rec.get("lumi_action") or "HOLD").upper(),
        "lumi_raw": raw,
        "lumi_effective": int(rec.get("lumi_effective_confidence", raw) or raw),
        "lumi_required": int(rec.get("lumi_required", 0) or 0),
        "lumi_reason": str(rec.get("lumi_reason") or "")[:260],
        "supervisor_action": sup_action,
        "supervisor_score": float(rec.get("trader_supervisor_score", sup.get("score", 0)) or 0),
        "supervisor_required": float(sup.get("required_score", 0) or 0),
        "supervisor_floors": floors,
        "quality": int(sup.get("quality", 0) or 0),
        "candle": int(sup.get("candle", rec.get("candle_score", 0)) or 0),
        "price_action": int(sup.get("price_action", (rec.get("candle_intelligence") or {}).get("price_action_score", 0)) or 0),
        "mtf": float(sup.get("mtf", rec.get("mtf_alignment", 0)) or 0),
        "counterfactual_adjustment": float(sup.get("counterfactual_adjustment", 0) or 0),
        "entered": operated,
        "order_id": str(rec.get("order_id") or ""),
        "approved": bool(rec.get("approved")),
        "block_reason": str(rec.get("block_reason") or "")[:260],
        "blocker": str(rec.get("counterfactual_blocker") or "")[:80],
        "result": display_result,
        "result_source": result_source,
        "shadow_result": shadow if shadow in {"WIN","LOSS","DRAW"} else "",
        "actual_result": actual if actual in {"WIN","LOSS"} else "",
        "actual_profit": round(float(rec.get("actual_profit", 0) or 0), 2),
        "explanation": _lumi_decision_explanation(rec),
    }


def build_lumi_decision_history(limit: int = 500) -> Dict[str, Any]:
    with signal_lab_lock:
        records = list(_signal_lab_store().get("records") or [])
    rows = []
    for rec in records:
        item = _lumi_decision_row(rec)
        if item is not None:
            rows.append(item)
    rows.sort(key=lambda r: str(r.get("created_at") or ""), reverse=True)
    total = len(rows)
    entered_rows = [r for r in rows if r.get("entered")]
    not_entered = [r for r in rows if not r.get("entered")]
    entered_resolved = [r for r in entered_rows if r.get("result") in {"WIN","LOSS"}]
    entered_wins = sum(1 for r in entered_resolved if r.get("result") == "WIN")
    missed_wins = sum(1 for r in not_entered if r.get("result_source") == "SHADOW" and r.get("result") == "WIN")
    protected_losses = sum(1 for r in not_entered if r.get("result_source") == "SHADOW" and r.get("result") == "LOSS")
    actions = {a: sum(1 for r in rows if r.get("supervisor_action") == a) for a in ("TRADE","WATCH","REJECT")}
    bands=[]
    for lo,hi,label in ((0,69,"<70"),(70,79,"70–79"),(80,89,"80–89"),(90,100,"90–100")):
        rr=[]
        for r in rows:
            raw=int(r.get("lumi_raw",0) or 0)
            if not (lo <= raw <= hi): continue
            if r.get("entered") and r.get("actual_result") in {"WIN","LOSS"}: rr.append(r)
            elif (not r.get("entered")) and r.get("result_source") == "SHADOW" and r.get("result") in {"WIN","LOSS"}: rr.append(r)
        if not rr: continue
        wins=sum(1 for r in rr if (r.get("actual_result") if r.get("entered") else r.get("result")) == "WIN")
        avg_payout=sum(float(r.get("payout",0) or 0) for r in rr)/max(1,len(rr))
        wr=wins/max(1,len(rr))*100.0
        be=100.0/(1.0+avg_payout/100.0) if avg_payout>0 else 100.0
        bands.append({"band":label,"samples":len(rr),"wins":wins,"losses":len(rr)-wins,"winrate":round(wr,1),"break_even":round(be,1),"edge_pp":round(wr-be,1),"avg_payout":round(avg_payout,1)})
    return {
        "enabled": bool(cfg_get("lumi_decision_history_enabled", True)),
        "version": "V109.4",
        "total": total,
        "rows": rows[:max(1, min(int(limit or 500), 2000))],
        "stats": {
            "entered": len(entered_rows), "not_entered": len(not_entered),
            "trade": actions.get("TRADE",0), "watch": actions.get("WATCH",0), "reject": actions.get("REJECT",0),
            "entered_resolved": len(entered_resolved), "entered_wins": entered_wins, "entered_losses": len(entered_resolved)-entered_wins,
            "entered_winrate": round(entered_wins/max(1,len(entered_resolved))*100.0,1) if entered_resolved else 0.0,
            "missed_wins": missed_wins, "protected_losses": protected_losses,
        },
        "raw_bands": bands,
        "updated_at": now_hms(),
        "note": "Histórico auditável das decisões realmente consultadas pela Lumi. Percentuais raw são opinião do modelo; efetiva é a confiança calibrada usada no REAL.",
    }


