def real_history_reconciliation() -> Dict[str, Any]:
    day=datetime.now().strftime("%Y-%m-%d")
    daily=dict(cfg_get("daily_summary") or load_daily_summary() or {})
    ledger_rows=[]
    try:
        with trade_ledger_lock: trades=list((_trade_ledger_load_locked().get("trades") or []))
        for t in trades:
            result=str(t.get("result") or t.get("status") or "").upper()
            closed=str(t.get("closed_at") or "")
            if result in {"WIN","LOSS"} and str(t.get("account_type") or "REAL").upper()=="REAL" and (not closed or closed[:10]==day): ledger_rows.append(t)
    except Exception: pass
    lab_rows=[]
    try:
        with signal_lab_lock: recs=list(_signal_lab_store().get("records") or [])
        lab_rows=[r for r in recs if str(r.get("actual_result") or "").upper() in {"WIN","LOSS"}
                  and str(r.get("operated_account_type") or r.get("account_type") or "REAL").upper()=="REAL"]
    except Exception: pass
    def wl(rows,key):
        w=sum(1 for r in rows if str(r.get(key) or r.get("result") or r.get("status") or "").upper()=="WIN")
        return w,len(rows)-w
    lw,ll=wl(ledger_rows,"result"); bw=int(daily.get("wins",0) or 0); bl=int(daily.get("losses",0) or 0); sw,sl=wl(lab_rows,"actual_result")
    unlinked=sum(1 for r in lab_rows if not str(r.get("signal_id") or "").strip())
    lab_total=sw+sl
    lab_linked=max(0,lab_total-unlinked)
    lab_pnl=round(sum(float(r.get("actual_profit",0) or 0) for r in lab_rows),2)
    lab_winrate=round((sw/lab_total*100.0) if lab_total else 0.0,1)
    return {"daily_wins":bw,"daily_losses":bl,"ledger_wins":lw,"ledger_losses":ll,"lab_wins":sw,"lab_losses":sl,"lab_total":lab_total,"lab_linked":lab_linked,"lab_unlinked":unlinked,"lab_pnl":lab_pnl,"lab_winrate":lab_winrate,"risk_source":"ledger+daily","data_dir":PERSISTENT_DATA_DIR}


def log_real_history_reconciliation() -> None:
    r=real_history_reconciliation()
    with state_lock:
        state["real_history_reconciliation"] = dict(r)
    level="warn" if (r["daily_wins"],r["daily_losses"])!=(r["ledger_wins"],r["ledger_losses"]) and (r["ledger_wins"]+r["ledger_losses"])>0 else "info"
    log(f"🧾 REAL Reconcile V109.4: diário={r['daily_wins']}W/{r['daily_losses']}L · ledger={r['ledger_wins']}W/{r['ledger_losses']}L · Lab histórico={r['lab_wins']}W/{r['lab_losses']}L · WR={r['lab_winrate']:.1f}% · P&L={r['lab_pnl']:+.2f} (sem vínculo={r['lab_unlinked']}) · risco temporal usa ledger+Lab REAL deduplicados; Shadow permanece separado.",level)


